    "Mapo Eggplant": RecipeDetail(
        ingredients: [
            "1 lb Chinese eggplants (about 2 small) (, cut into bite-sized pieces(*Footnote 1))",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "2 teaspoons Sichuan peppercorns",
            "8 oz ground chicken ((*Footnote 2))",
            "1 1/2 to 2 tablespoons doubanjiang ((*Footnote 3))",
            "4 green onions (, sliced with some green part reserved for garnish)",
            "2 cloves garlic (, minced)",
            "1 ” ginger (, minced)",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1 cup chicken stock ((or water))",
            "1 tablespoon homemade chili oil",
            "2 teaspoons soy sauce",
            "2 teaspoons sugar",
            "1 tablespoon cornstarch",
            "2 tablespoons water",
        ],
        steps: [
            "Add the oil and sichuan peppercorns to a large skillet and cook over medium heat. Let the peppercorns cook until they are fragrant and turn brown, about 5 minutes. Remove the peppercorns using a spatula without removing the oil, and transfer them into a small bowl. (*Footnote 4)",
            "Add the ground chicken and spread it across the pan. Top with the doubanjiang. Let the chicken cook for 30 seconds to 1 minute until the bottom turns golden. Stir with the doubanjiang and cook until the chicken is almost cooked through, 1 to 2 minutes.",
            "Add the green onions, ginger, and garlic. Continue cooking for another 30 seconds to a minute to release the fragrance.",
            "Pour in the Shaoxing wine. Immediately use your spatula to scrape off any browned bits from the pan.",
            "Add the eggplant, stock, chili oil, soy sauce, and sugar. Stir gently to incorporate everything. Bring to a boil, then cover. Simmer over medium-low heat until the eggplant is cooked through, about 7 minutes. Carefully taste one piece of eggplant to make sure it reaches your desired texture. Let cook a bit longer if needed.",
            "Mix together the cornstarch and water together in a small bowl and stir until fully dissolved. Drizzle over the sauce and turn the heat back to medium. Stir constantly and cook until the sauce has thickened. Transfer everything to a serving plate. Garnish with the reserved green onion, if using.",
            "Enjoy hot as a main dish over steamed rice or boiled noodles.",
        ]
    ),
    "Yu Xiang Eggplant": RecipeDetail(
        ingredients: [
            "2 Chinese eggplant (, cut to bite-sized pieces (or regular eggplant) (*Footnote 1))",
            "1 teaspoon salt",
            "2 teaspoons cornstarch ((to coat the eggplant))",
            "2 tablespoons Chinkiang vinegar",
            "1 1/2 tablespoons light soy sauce ((or soy sauce))",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "2 tablespoons sugar",
            "1/4 cup chicken stock ((or vegetable stock))",
            "2 teaspoons cornstarch",
            "3 tablespoons peanut oil ((or vegetable oil))",
            "4 oz ground pork ((or chicken) (*Footnote 2) (Optional))",
            "2 green onions (, sliced)",
            "2 cloves garlic (, minced)",
            "1 tablespoon ginger (, minced)",
            "8 to 10 dried Chinese chili peppers",
            "2 teaspoons doubanjiang",
            "1/4 teaspoon ground Sichuan peppercorn ((Optional))",
        ],
        steps: [
            "Place eggplant in a large bowl and add water to cover. Add 1 teaspoon salt, mix well. Place a plate on top so the eggplant pieces are submerged in the water. Let sit for 10 to 15 minutes while preparing the other ingredients. Once done, drain and pat dry with paper towels.",
            "Add all the sauce ingredients into a bowl. Stir to mix well.",
            "Sprinkle eggplant with cornstarch and mix by hand, until eggplant is evenly coated.",
            "Add 2 tablespoons of the oil to a large skillet and heat over medium-high heat until hot. Spread eggplant across the bottom of the skillet without overlapping. Cook the eggplant, stirring occasionally, until the edge of the eggplant is lightly charred and the texture just starts to soften, 5 minutes or so. Transfer to a plate. If the skillet gets too hot and starts to smoke, turn to medium heat.",
            "Add the remaining 1 tablespoon of oil and the ground meat. Cook and chop the pork into smaller pieces, until fully cooked.",
            "Add green onion, garlic, ginger and chili pepper. Stir a few times to release fragrance.",
            "Add the doubanjiang and Sichuan peppercorns. Stir and cook until the pork is evenly coated.",
            "Stir the sauce again to completely dissolve the cornstarch, then pour into the pan. Stir until the sauce thickens. Return the eggplant to the pan and quickly stir to mix everything well. Serve hot as a main dish or side dish.",
        ]
    ),
    "Dry-Fried Green Beans": RecipeDetail(
        ingredients: [
            "1 lb green beans (, tough ends removed)",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "4 oz ground pork ((Optional but highly recommended) (*Footnote 1))",
            "2 tablespoons Sichuan pickled mustard greens (Sui Mi Ya Cai) ((*Footnote 2) (Optional))",
            "1/4 teaspoon ground Sichuan peppercorn",
            "3 dried chili peppers ((*Footnote 3))",
            "3 cloves garlic (, minced)",
            "1 teaspoon minced ginger",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 teaspoon sugar",
            "Salt to taste",
        ],
        steps: [
            "Pat the green beans dry with paper towels to prevent them from splattering.",
            "Heat 2 tablespoons vegetable oil in a large nonstick skillet over medium-high heat until hot. Add the green beans and a pinch of salt. Stir to coat well with oil. Spread the beans to prevent them from overlapping, as much as possible. Flip every 15 seconds or so. Cook and stir until some of the surface is brown and withered, and the green beans just start to turn soft, 6 to 8 minutes. If you prefer a softer texture, wait until most of the surfaces have charred, 10 to 12 minutes. Turn to medium heat if the pan starts to smoke too much. Transfer the green beans to a plate and set aside.",
            "Add the remaining 1 tablespoon oil, ground pork, pickled mustard greens, and the ground Sichuan peppercorns. Cook and chop the pork to separate it into small pieces, while mixing with the rest of the ingredients.",
            "When the surface of the pork has cooked, add the dried chili pepper, garlic, and ginger. Stir a few seconds to release the fragrance. Add back the green beans. Swirl in the Shaoxing wine, light soy sauce, and sugar. Cook and stir until the sauce is mostly absorbed, about 1 to 2 minutes.",
            "Turn to low heat and carefully taste a green bean with some pork. Adjust seasoning by adding more salt, if needed. Transfer everything to a plate. Serve hot as a side dish or one of the main dishes of a multi-course meal.",
        ]
    ),
    "Saliva Chicken (口水鸡)": RecipeDetail(
        ingredients: [
            "2 (1 to 1.5 lbs in total) bone-in skin-on chicken legs ((*Footnote 1))",
            "1 thumb ginger (, sliced)",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "1/2 teaspoon salt",
            "1 1/2 tablespoons light soy sauce",
            "1 teaspoon Chinkiang vinegar",
            "1 teaspoon Chinese sesame paste ((or unsweetened natural peanut butter))",
            "1 teaspoon sesame oil",
            "1 teaspoon sugar",
            "1 green onion (, white part minced, green part sliced for garnish)",
            "2 cloves garlic (, grated)",
            "1 teaspoon grated ginger",
            "1/4 teaspoon ground Sichuan peppercorn",
            "3 tablespoons juice from cooking the chicken",
            "4 tablespoons chili oil ((3 tablespoons oil + 1 tablespoon chili flake))",
            "2 tablespoons roasted peanuts (, chopped)",
        ],
        steps: [
            "Prepare a plate large enough to fit the chicken and small enough to fit into your steamer basket. Evenly spread the ginger slices evenly onto the meat side of the chicken. Then place the chicken onto the prepared plate, skin side up. Pour the Shaoxing wine over the chicken and sprinkle evenly with the salt.",
            "Prepare the steamer by heating 2” (5 cm) water in the pot to a boil. Then place the plate with the chicken onto the steamer basket, and place the basket onto the steamer. Steam covered over medium-high heat until the chicken is just cooked through, 30 minutes or so. You can test the doneness by inserting a knife into the thickest part and checking whether the juice runs clear. If it’s clear, the chicken is cooked. Transfer the plate onto your kitchen counter to let the chicken cool off. Reserve the juice from cooking the chicken.",
            "Mix the light soy sauce, Chinkiang vinegar, sesame paste, sesame oil, sugar, white part of the green onion, garlic, ginger and ground Sichuan peppercorn in a medium bowl that you plan to serve the chicken. Mix well until the sesame paste is evenly distributed. Add 3 tablespoons of the broth from cooking the chicken, and 1 tablespoon of the chili flake residue from the chili oil. Stir to mix well.",
            "When the chicken is cooled, transfer the chicken onto a cutting board. Remove the bones using a paring knife, then slice chicken into 1/2” (1-cm) pieces. Transfer chicken into the bowl with the sauce ingredients.",
            "Pour the chili oil over the chicken, and garnish with peanuts and green onion. Serve at room temperature as an appetizer. Stir gently to mix the chicken with the sauce and the chili oil when eating.",
        ]
    ),
    "Fu Qi Fei Pian": RecipeDetail(
        ingredients: [
            "3 to 3.5 lbs (1.3 to 1.5 kg) beef brisket (, chuck, tongue, and/or tripe (I used a mixture of brisket and tongue) (*Footnote 1))",
            "1/4 cup light soy sauce ((or soy sauce))",
            "1/4 cup Shaoxing wine ((or dry sherry))",
            "1 tablespoon sugar",
            "4 dried chili peppers",
            "3 green onions (, halved lengthwise)",
            "2 large slices ginger",
            "1/2 cinnamon stick",
            "1 bay leaf",
            "1 teaspoon Sichuan peppercorns",
            "1 teaspoon salt",
            "1/4 teaspoon nutmeg powder",
            "4 tablespoons homemade chili oil ( with 2 tablespoons chili flake residue (or to taste))",
            "3 tablespoons braising liquid ((*Footnote 2))",
            "2 tablespoons homemade flavored sweet soy sauce ((*Footnote 3))",
            "2 teaspoons Chinkiang vinegar",
            "1/4 teaspoon salt",
            "1/4 teaspoon ground toasted Sichuan peppercorns ((or to taste))",
            "3 cloves garlic (, grated)",
            "2 green onions (, chopped)",
            "1 teaspoon ginger (, grated)",
            "Chopped cilantro (, toasted sesame seeds, and/or chopped toasted peanuts for garnish)",
        ],
        steps: [
            "(Option 1 - stovetop) Place the beef in a big pot and add water to cover by 1 inch. Cook over medium-high heat until boiling. Turn to medium heat and boil for 10 minutes. Skim the surface using a fine mesh strainer and discard the foam until the broth turns clear. Add all the braising ingredients. Turn to medium-low heat. Simmer, covered, until the beef turns tender but not tender enough to fall apart, 2 hours or so.",
            "(Option 2) Place the beef in a pressure cooker or Instant Pot. Add all the braising ingredients and 1 cup water. Close and seal the lid. If using a pressure cooker, cook over medium heat until the pressure is achieved, then turn to medium-low heat. Cook at high pressure for 35 minutes. Use natural release once done.",
            "Once the beef is done, transfer to a plate to cool enough to handle. Slice the beef against the grain into 1/8-inch (4-cm) pieces. (*Footnote 4) Now you can serve the beef or store it in an airtight container in the fridge for 3 to 4 days before serving.",
            "Mix all the sauce ingredients in a bowl. For an even better result, mix the sauce in advance and let sit for a couple hours before serving.",
            "Cut the beef into thin slices. Transfer to a deep plate. Drizzle with plenty of sauce, top with cilantro, sesame seeds, and peanuts.",
            "Serve at room temperature as an appetizer or a main dish. (*Footnote 5)",
        ]
    ),
    "Chongqing Noodles": RecipeDetail(
        ingredients: [
            "1 tablespoon peanut oil",
            "1 teaspoon minced ginger",
            "1/2 tablespoon doubanjiang ((or soy sauce for a less spicy dish))",
            "4 oz (225 g) ground pork",
            "1 teaspoon Shaoxing wine",
            "1/2 teaspoon sugar",
            "1 tablespoon Chinese sesame paste ((or natural peanut butter))",
            "2 to 4 tablespoons homemade chili oil ((chili crisp and oil) (*Footnote 1))",
            "4 teaspoons light soy sauce",
            "2 teaspoons sesame oil",
            "1 teaspoon Chinkiang vinegar",
            "1 clove garlic (, grated)",
            "2 teaspoons ginger (, grated)",
            "1/8 teaspoon Sichuan peppercorns ((Footnote 2))",
            "1 teaspoon chicken bouillon powder ((or 1/2 teaspoon salt, or to taste))",
            "7 oz (200 g) dried alkaline noodles ((or 300 g fresh alkaline noodles))",
            "1 cup noodle boiling water ((or chicken broth) (*Footnote 3))",
            "4 heads Chinese leafy greens ((gai lan, yu choy, baby bok choy, etc))",
            "2 tablespoons Chinese pickled mustard tube ((zha cai))",
            "2 tablespoons roasted peanuts (, chopped)",
            "1 green onion (, sliced)",
        ],
        steps: [
            "Optional Pork Topping: Heat the oil over medium heat until hot. Add the ginger and doubanjiang. Stir and cook over medium heat until the oil is red, 1 minute. Add the pork. Stir and chop the pork into small pieces until the pork is browned. Add the wine and sugar and continue to fry for another minute. Transfer everything to a small bowl and set aside.",
            "Bring a large pot of water to a full boil. Blanch the leafy greens of your choice (1 minute for softer greens, 3 minutes for firmer) and set aside. Boil the noodles according to package instructions. Transfer the noodles from the boiling water into a colander. Drain, quickly rinse with cold tap water to stop cooking, then drain thoroughly again. Reserve the noodles’ boiling water.",
            "Mix the Chinese sesame paste with 1 tablespoon of warm water. Stir to mix until it forms a smooth paste.",
            "Divide the soup base ingredients into two medium bowls: add 1 to 2 tablespoons chili oil, half of the sesame paste, 1 teaspoon soy sauce, 1 teaspoon sesame oil, 1/2 teaspoon Chinkiang vinegar, half of the grated garlic, 1/2 teaspoon grated ginger, a pinch of Sichuan peppercorn powder, and 1/2 teaspoon chicken bouillon powder (if using). Stir to mix the seasonings.",
            "Divide the noodles into each bowl. Add 1/2 cup (up to 1 cup) noodle boiling water. Top the noodles with the blanched vegetables, a tablespoon of pickled vegetables of your choice, crushed roasted peanuts, green onions, and ground pork if using. Serve as a main dish.",
        ]
    ),
    "Ma La Xiang Guo": RecipeDetail(
        ingredients: [
            "1/2 packet spicy Sichuan hot pot base (1/2 cup, 110 g)",
            "1 tablespoon doubanjiang ((or black bean sauce for a milder taste))",
            "1 tablespoon homemade black bean sauce ((or store-bought))",
            "6 oz Chinese cauliflower (or regular cauliflower) (, cut into florets (yield 2 cups))",
            "2 oz lotus root (, sliced (*Footnote 1) (yield 1/2 cup))",
            "4 oz baby bok choy ((about 6 heads))",
            "4 oz enoki mushrooms ((about 1 cup))",
            "1/8 cup dried wood ear mushrooms ((yield 1/2 cup after rehydrating))",
            "1/2 cup fried tofu (, cut to bite size pieces)",
            "4 oz strip or ribeye steak (, thinly sliced (*Footnote 2))",
            "4 oz shrimp (, peeled and deveined (*Footnote 2))",
            "2 oz quail eggs (, boiled and peeled (about 1/2 cup))",
            "2 tablespoons peanut oil",
            "4 cloves garlic (, sliced)",
            "1 tablespoon ginger (, minced)",
            "6 whole dried chili peppers ((or halved for a spicier taste))",
            "1 cup cilantro (, chopped)",
        ],
        steps: [
            "Prepare ingredients that need rehydrating: To rehydrate the wood ear mushrooms, add the dried mushrooms to a medium sized bowl and cover with 1 cup hot water. Soak for 15 to 20 minutes, or until the mushrooms are tender throughout. Drain, remove tough ends if needed, and cut into bite-sized pieces.",
            "For the sauce: Combine the sauce ingredients and set aside.",
            "To prepare the dry pot ingredients: Bring a pot of water to a boil for blanching non-meat ingredients (*Footnote 3). Set up a large strainer over a bowl. Blanch the ingredients in groups by timing or one ingredient at a time. Once done, transfer the blanched ingredients from the water and place in the strainer. First blanch the lotus root and cauliflower for 2 to 3 minutes, until al dente. Then blanch the bok choy, enoki mushrooms and wood ear mushrooms for 30 seconds to 1 minute, until just starting to turn soft.",
            "To cook the mala dry pot: Heat 1 tablespoon of the oil in a large skillet over medium heat. Spread the thinly sliced steak without overlapping. Cook for 30 seconds or until the bottom turns light golden. Flip and sear on the other side until just cooked through and the inside of the meat is still slightly pink. Transfer the meat to a plate.",
            "Add the shrimp to the pan. Cook for 1 to 2 minutes, until the surface turns pink-ish white. Flip and cook on the other side for another 1 to 2 minutes until the shrimp has fully curled up. Transfer to a plate with the steak.",
            "Add the remaining 1 tablespoon oil to the pan and the garlic, ginger, and chili peppers. Fry until fragrant, about 30 seconds.",
            "Pour in the sauce. Cook for another 30 seconds, or until the hot pot base is fully melted.",
            "Add the blanched ingredients. Toss a few times to coat well. Add the stir fried steak and shrimp. Toss until everything is evenly coated. Add the cilantro and give it one more toss. Immediately transfer everything to a large bowl or plate.",
            "Serve hot family-style as a main dish with steamed rice.",
        ]
    ),
    "Sichuan Boiled Beef": RecipeDetail(
        ingredients: [
            "1 lb beef flank steak",
            "1 tablespoon Shaoxing wine",
            "2 teaspoons soy sauce",
            "1/2 teaspoon salt",
            "1/4 teaspoon white pepper",
            "1 tablespoon cornstarch",
            "1/4 cup + 2 tablespoons canola oil (, divided (or other neutral oil))",
            "1/2 cup Chinese dried chili peppers (, halved (seeds removed for a less spicy dish))",
            "1 tablespoon Sichuan peppercorns",
            "6 cloves garlic (, grated)",
            "1 scallion (, sliced)",
            "4 cloves garlic (, smashed)",
            "1 &quot; ginger (, sliced)",
            "3 scallions (, cut into 1&quot; (2.5 cm) pieces)",
            "3 tablespoons Doubanjiang",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "2 cups chicken stock",
            "1 tablespoon sugar",
            "1 teaspoon soy sauce",
            "1/2 teaspoon chicken bouillon ((or to taste) (Optional))",
            "6 to 8 heads Chinese broccoli (, sliced to large bite-size pieces (or bok choy, yu choy, or other vegetables you prefer))",
            "1/2 teaspoon cornstarch",
            "1 teaspoon water",
        ],
        steps: [
            "Cut the beef flank steak along the grain into two pieces. Then slice against the grain by tilting your knife to 45° and slicing the beef into 1/4\" (1/2 cm) thick pieces. Transfer to a medium-sized bowl.",
            "Add the marinade ingredients except the cornstarch. Gently use your hand to mix the beef until the ingredients are absorbed. Then add the cornstarch and mix again until the beef is evenly coated. Set aside to marinate for 15 minutes while preparing the rest of the ingredients.",
            "Heat a medium-sized wok over medium heat with 2 tablespoons of oil until hot. Add the dried chilis and Sichuan peppercorns, turn to medium-low heat. Cook and stir until fragrant and darker, about 2 minutes. Transfer the spices to a plate to cool slightly, reserving the oil in the pan. Turn off the heat.",
            "Add the fried spices into a small food processor or blender. Pulse until coarsely chopped. Set aside.",
            "Reheat the same wok over medium heat until hot. Add the garlic, ginger, and scallions. Cook and stir until fragrant, 1 minute or so.",
            "Add the doubanjiang. Stir for another 2 to 3 minutes. Turn to low heat if the paste starts to stick to the pan too much. You can also pour a bit of water into the pan to release the paste.",
            "Pour in the Shaoxing wine and use a spatula to lift as much of the brown bits from the bottom as possible. Add the chicken stock and keep scraping the bottom.",
            "Add the sugar and soy sauce. Cook over medium-high heat until brought to a boil. Reduce to a simmer and cook for 2 to 3 minutes. Use a mesh strainer to remove the solid spices and discard them. Taste the broth. It should be slightly salty by itself. Add chicken bouillon to adjust flavor if needed.",
            "Prepare a large heat-proof bowl, enough to hold most of the broth, the vegetables, and the beef. (*Footnote 1)",
            "Add the Chinese broccoli to the broth and blanch until cooked to your desired texture, about 2 minutes. Remove it from the broth and place it on the bottom of the big bowl.",
            "Bring the broth back to a simmer. Cook the beef slices in two batches if needed so they don’t crowd the pan. Add the beef and immediately use a pair of chopsticks or tongs to stir and separate the pieces. Poach for a minute, or until the beef is just cooked through. Transfer the beef into the big serving bowl, on top of the Chinese broccoli.",
            "Bring the broth to a boil again. Stir to fully dissolve the cornstarch slurry and pour it into the broth, stirring constantly. Cook for 1 minute, until the broth is slightly thickened. Then pour the broth into the serving bowl, until the beef slices are mostly covered. Set aside the remaining broth if there is any left. (*Footnote 1)",
            "Spread the prepared topping spices - the fried and ground up chili peppers and Sichuan peppercorn, over the broth. Spread out the sliced scallions and the grated garlic.",
            "Heat the remaining 1/4 cup oil over medium heat in a small pot or saucepan until just smoking. Carefully drizzle the spices over the serving dish. The oil will spatter a bit but shouldn’t cause a mess. Serve hot as a main dish.",
        ]
    ),
    "Sichuan Crispy Beef": RecipeDetail(
        ingredients: [
            "1 lb beef flank steak (, sliced into 1/4” (5 mm) pieces again the grain)",
            "3/4 teaspoon salt",
            "1/2 teaspoon baking soda",
            "1 tablespoon vegetable oil",
            "4 to 6 tablespoons cornstarch",
            "3 to 4 tablespoons vegetable oil",
            "1/4 cup Lao Gan Ma Spicy Chili Crisp",
            "4 scallions (, sliced on the bias into 1” (2.5 cm) pieces)",
        ],
        steps: [
            "Combine the beef, salt, baking soda and oil in a medium bowl. Gently mix by hand until all the beef slices are coated with oil. Marinate for 30 minutes.",
            "When ready to cook, add cornstarch one tablespoon at a time. Mix to coat the beef until all surfaces are coated.",
            "Heat 2 tablespoons of oil in a large skillet over medium-high heat until shimmering. Cook in batches, spread the beef slices without overlapping. Cook until the bottom turns golden and crispy, 2 to 3 minutes. Flip the slices to fry the other side, until golden brown and crispy, another 1 to 2 minutes. (*Footnote 1) Transfer beef to a large plate. Cook the rest of the batches. Add more oil if the pan gets dry, and turn to medium heat if the pan starts to smoke too much.",
            "Once all the beef is cooked, add it back to the pan and turn to medium-high heat. Add the chili crisp and the scallion. Stir and cook until the beef is evenly coated with the chili oil and the scallion starts to wilt, 1 to 2 minutes. Transfer everything to a large plate. Serve hot as a main dish.",
        ]
    ),
    "Guai Wei Chicken": RecipeDetail(
        ingredients: [
            "700 grams bone-in skin-on chicken thigh ((*see footnote 1))",
            "2 tablespoons Shaoxing wine",
            "1 teaspoon Sichuan peppercorn",
            "2 green onion (, chopped)",
            "2 pieces ginger",
            "2 green onion",
            "1/4 teaspoon salt",
            "3 tablespoons soy sauce",
            "2 teaspoons black rice vinegar",
            "2 teaspoons sugar",
            "1 tablespoon Chinese sesame paste ((or natural peanut butter))",
            "2 tablespoons homemade chili oil with 1 to 2 tablespoons of its “sediment”",
            "1 teaspoon sesame oil",
            "1 clove garlic (, minced)",
            "1/2 teaspoon ginger (, minced)",
            "1/4 teaspoon Sichuan peppercorn (, freshly grated roasted (*see footnote 2))",
            "1 cucumber, sliced into thin strips ((Optional))",
            "1 tablespoon roasted sesame seeds for garnish ((Optional))",
        ],
        steps: [
            "Bring a large pot of water to a boil. Turn to medium heat.",
            "Halve green onion. Chop some of the green parts and use them to garnish the dish later.",
            "Add Shaoxing wine, Sichuan peppercorn, white part of green onion, and ginger to the boiling water. Mix well. Add chicken. Cook until bringing to a simmer. Turn to low heat. Continue cooking at a very gentle simmer until the chicken is cooked through, 20 to 30 minutes.",
            "While cooking the chicken, prepare a large bowl of ice water.",
            "(Very important) When the chicken is just cooked, immediately transfer it to the ice bath. Add more ice if necessary. Set aside and let cool completely. This step tightens the chicken skin and firms up the texture.",
            "Combine soy sauce, black rice vinegar, and sugar in a bowl. Mix well until the sugar dissolves.",
            "Add sesame paste to another bowl. Gradually blend in the sauce from last step and mix with a spoon, until the sesame paste is evenly blended and no lumps remain.",
            "Add chili oil, sesame oil, garlic, ginger, and Sichuan peppercorn. Mix well.",
            "Right before serving, combine chicken and spicy sesame sauce. Toss to mix well. Spread cucumber over a deep plate. Transfer chicken on top of cucumber and garnish with sesame seeds and green onion, if using. (*see footnote 3)",
            "Serve as a cold appetizer, or as a main over noodles or rice.",
        ]
    ),
    "Shui Zhu Yu": RecipeDetail(
        ingredients: [
            "1 whole fish (a 2 to 3 lbs / 1 to 1.3 kg fish) (, or 2 white fish fillets (branzino, sea bass, snapper, or catfish))",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1 teaspoon salt",
            "1 teaspoon white pepper",
            "1 egg white",
            "2 teaspoons cornstarch",
            "1/2 cup Chinese dried chili peppers (and extra for garnish)",
            "2 tablespoons Sichuan peppercorns (, a combo of red and green if possible (*Footnote 1))",
            "1/3 canola oil (, separated (or other neutral oil))",
            "4 cloves garlic (, smashed)",
            "1 &quot; ginger (, sliced)",
            "3 green onions (, cut into 1&quot; (2.5 cm) pieces)",
            "5 Chinese dried chili peppers (, sliced)",
            "3 tablespoons Doubanjiang",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1 tablespoon sugar",
            "1 teaspoon soy sauce",
            "1/2 teaspoon mushroom powder ((or chicken powder) (optional))",
            "1/4 teaspoon white pepper",
            "2 cups bean sprouts",
            "1 cup chopped Chinese celery ((or regular celery) (cut into 1&quot; / 2.5 cm sticks))",
            "1/2 teaspoon cornstarch",
            "1 teaspoon water",
        ],
        steps: [
            "Check to see if there are any residual fish scales. If yes, run your knife gently from the tail to the head to remove the scales.",
            "Starting at the top of the head, slice along the collarbone.",
            "Using mainly the tip of your knife, run the blade along one side of the spine to make a 1/2” (1 cm) shallow cut through the skin.",
            "Make a small slice near the tail, which will be the base of the fillet.",
            "In smooth motions, use your knife gently to slice the flesh while pressing against the bone and the other hand holding the flesh. Slice the flesh away from the spine until it reaches the rib cage.",
            "Carefully angle the blade of the knife downward so that you can carve around the bone. It’s OK if some of the bones are attached with the fillet, which you can remove later.",
            "Once the flesh is released from the rib cage, keep slicing it until the fillet is fully detached from the bone.",
            "Flip the fish over and repeat on the other side, this time from the tail, until you get two pieces of fish fillets.",
            "Trim the thin white belly from both sides and discard the pieces (depending on the type of the fish they might taste quite oily, but you can reserve them as well).",
            "Using a heavy knife or a cleaver, remove the head and tail by pressing the knife against the bone and use one strong motion to cut through it. Chop the spine into 4 pieces.",
            "Starting at the bottom of the fillet, tilt your knife to 45° and slice the fish into 1/4\" (1/2 cm) thick pieces.",
            "Add the cut fillets, bones, and head (if using) to a medium-sized bowl. Keep the bones and the head on one side of the bowl. Add the marinade ingredients. Gently use your hand to mix the sliced fish until the ingredients are evenly coated. Then gently rub the rest of the seasonings onto the bones and fish head. Be careful not to poke your finger on the fish bones. Set aside to marinate for 15 minutes.",
            "Cut the dried chili peppers in half.",
            "Heat a medium-sized pot over medium-low heat with 2 tablespoons oil. Add the dried chilis, and Sichuan peppercorns. Cook and stir until fragrant but not browned, about 2 minutes. Transfer the spices to a plate to cool slightly, reserving the oil in the pan.",
            "Add the fried spices into a small food processor or blender. Pulse until coarsely chopped. Set aside.",
            "Reheat the same pot over medium heat and add the garlic, ginger, green onion whites, and dried chilis. Cook and stir until fragrant, 1 minute or so.",
            "Add the doubanjiang. Stir for another 2 to 3 minutes. Turn to low heat if the paste starts to stick to the pan too much. You can also pour a bit of water into the pan to release the paste.",
            "Pour in the Shaoxing wine and use a spatula to lift as much of the brown bits from the bottom as possible.",
            "Add 5 cups of water and keep scraping the bottom.",
            "Add the sugar, soy sauce, white pepper, and mushroom/chicken powder (if using). Cook over medium-high heat until bringing to a boil. Reduce to a simmer and cook for another 5 minutes. Use a mesh strainer to remove the solid spices and discard them.",
            "Prepare a large heat-proof bowl, large enough to hold all the broth, the vegetables, and the fish.",
            "Add the vegetables to the broth and blanch for 1 minute. Remove them from the broth and place them on the bottom of the big bowl.",
            "Bring the broth back to a simmer. Add the fish bones and head. Cook for 2 minutes, or until the fish head is cooked through. Add the fish bones to the big bowl. (You can add the fish head as well if the bowl is big enough and if you plan to serve the fish head).",
            "Bring the broth back to a simmer. Add the fillet slices using your hand, a few pieces at a time, and separate them during the process. Poach for 30 second to a minute, or until the fish is just cooked through. Transfer the fish into the big serving bowl.",
            "Bring the broth to a boil again. Stir to fully dissolve the cornstarch slurry and pour it into the broth, stirring constantly. Cook for 1 minute. Then pour the broth into the serving bowl, until the fish slices are mostly covered. Set aside the remaining broth if there is any left. (*Footnote 2)",
            "Spread the prepared topping spices over the broth. You can add a few pieces of dried chili peppers for garnish (optional, and they won’t add too much heat).",
            "Heat the remaining 1/4 cup oil over medium heat in a small pot or saucepan until just smoking. Carefully drizzle the spices over the serving dish. The oil will spatter a bit but shouldn’t cause a mess.",
            "Serve immediately as a main dish with steamed rice.",
        ]
    ),
    "Chili Oil": RecipeDetail(
        ingredients: [
            "4 tablespoons Chinese chili flakes ((*footnote 1))",
            "2 teaspoons five spice powder",
            "3 tablespoons toasted sesame seeds",
            "1 teaspoon ground Sichuan peppercorn",
            "1 whole star anise ((Optional))",
            "2 bay leaves",
            "1 cup vegetable oil ((or grapeseed oil))",
            "1 piece thinly sliced ginger ((Optional))",
        ],
        steps: [
            "Combine chili flakes, five spice powder, sesame seeds, star anise, Sichuan peppercorns, and bay leaves in a heatproof ceramic bowl that can hold at least 2 cups liquid. Place the bowl on a heat resistant coaster.",
            "Heat oil in a wok (or a skillet) over medium-high heat. Add ginger. When the ginger starts to wither and turns golden brown, immediately turn off the heat. The oil should reach 370 degrees F (190 C) and no higher than 400 F (200 C) if read with an instant thermometer.",
            "Carefully pour oil or use a ladle to transfer oil into the bowl of mixed spices. The oil will bubble for a few seconds and cook the spices. While the the oil is bubbling, use a metal spoon to stir gently to mix the spices, so they’ll cook thoroughly.",
            "When the oil cools down a bit, scoop out and discard the star anise and bay leaf.",
            "The oil is now ready to use! Its flavor will mature if you let it rest for a day, allowing the spices to infuse into the oil.",
            "The oil can be stored covered at room temperature for two weeks, or up to six months in the fridge in an airtight container.",
        ]
    ),
    "Sichuan Hot Pot Base": RecipeDetail(
        ingredients: [
            "1/3 cup Sichuan peppercorns",
            "1/2 cup dried chili peppers",
            "2 cinnamon sticks",
            "4 bay leaves",
            "2 pods star anise",
            "1 teaspoon cumin seeds",
            "1 teaspoon fennel seeds",
            "1/2 teaspoon cloves",
            "2 1/2 cups rapeseed oil ((or other neutral oil) (*Footnote 1))",
            "6 cloves garlic (, chopped)",
            "4 ” (10 cm) ginger (, chopped)",
            "4 to 6 green onions (, chopped)",
            "1/2 cup Doubanjiang",
            "3 tablespoons fermented black beans ((or black bean paste/sauce))",
            "1 teaspoon rock sugar ((or white sugar))",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "3 tablespoons mushroom bouillon powder ((or chicken bouillon powder))",
            "12 dried chili peppers ((for garnish) (*Footnote 2))",
            "2 tablespoons Sichuan peppercorns (, crushed (for garnish))",
        ],
        steps: [
            "Combine all the spices in a blender or food processor. Mix until the spices turn into small flakes but not powdered.",
            "Heat the oil in a medium-sized pot or 9” deep pan over low heat until medium hot (if you add a small piece of garlic it should sizzle gently and not bubble furiously). Add the garlic, ginger, and green onion. Cook and stir until fragrant but not browned, about 2 minutes.",
            "Carefully add the doubanjiang and fermented black beans to the oil. Cook and stir for another minute.",
            "Add the blended spices. Cook, stirring frequently, for about 10 minutes. The oil should reach a vibrant orange-red color when it’s ready.",
            "Add the sugar, Shaoxing wine, and mushroom powder. Stir until dissolved.",
            "Remove the pan from the heat and let cool for 10 to 20 minutes (or longer if you have a non-heat proof blender).",
            "Add the cooled hot pot base mixture to the blender. Make sure the lid’s air vent is open. Start from a low speed, gradually raising to medium-high speed, blending until the oil is emulsified, about 1 minute. The mixture will look cloudy once blended.",
            "Carefully pour the hot pot soup base into a large heat proof tupperware. Top the whole dried chilis and crushed peppercorns evenly over the base for garnish. Cover the container and freeze overnight.",
            "Once frozen, you can divide the base into individual portions by slicing it into 4 pieces. Then you can store each piece in a ziplock bag in the freezer for up to 6 months. Each block is good for a small hot pot, or one side of a hot pot with a divider.",
            "To use the hot pot base, add it to the hot pot and pour in 4 to 5 cups of broth (chicken or vegetable broth). Heat over medium-high heat and stir to dissolve the soup base. You’re ready to cook when the soup is boiling. Refer to my Ultimate Hot Pot Guide for more information on how to put together a hot pot dinner.",
        ]
    ),
    "Chili Oil Wontons": RecipeDetail(
        ingredients: [
            "1 pack wonton wrappers (, thawed if using frozen)",
            "2 tablespoons boiling water",
            "1/4 teaspoon salt",
            "2 green onions (, sliced)",
            "1 tablespoon minced ginger",
            "1 teaspoon Sichuan peppercorns",
            "1/2 lb ground pork",
            "1 large egg",
            "2 teaspoons cornstarch",
            "1/8 teaspoon white pepper powder",
            "8 tablespoons homemade chili oil ((including the chili crisp))",
            "4 tablespoons seasoned sweet soy sauce ((*Footnote 1))",
            "1 1/2 tablespoons Chinkiang vinegar",
            "2 teaspoons grated garlic",
            "2 green onions (, sliced)",
            "Chopped cilantro, toasted ground Sichuan peppercorn flakes, and toasted sesame seeds for garnish ((Optional ))",
        ],
        steps: [
            "Combine all the ingredients for the aromatic water in a small bowl. Stir to mix well and let infuse for 15 minutes while you prepare the other ingredients. Strain and discard all the solid ingredients.",
            "Combine the chili oil, sweet soy sauce, vinegar, garlic, and white part of the green onion in a medium-sized bowl. Stir to mix well.",
            "Add the minced pork into a medium-sized bowl. Add the aromatic water, egg, cornstarch, and white pepper powder. Mix until it forms a smooth and sticky paste.",
            "Work on the wontons one at a time. Place about half a teaspoon of filling (or 1 teaspoon for bigger wontons) on the lower third of the wrapper. Fold the bottom side over the filling, then roll the filling all the way across to the other side of the wrapper. Brush a thin layer of egg white on one end of the wonton wrapper. Bind both ends and press them together to lock the filling inside the wrapper. Place on a big plate, a finger’s width apart.",
            "When you’ve finished 10 to 15 wontons, cover them with a wet paper towel to prevent them from drying out.",
            "Bring a large pot of water to boil. Add the wontons, 20 at a time. Stir gently with a spatula constantly, to prevent them from sticking to the bottom. Cook until the wontons are floating on top, about 2 to 3 minutes. Transfer 7 to 8 wontons into each bowl. Pour 2 tablespoons of the sauce, and 1 to 2 tablespoons of the hot broth used to boil the wontons, garnish with the green part of the green onion, and serve.",
            "Mix the wontons well to coat them with sauce. Enjoy!",
            "If you are not going to cook and serve the wontons immediately, you can store them in the fridge for a day, or freeze them for up to a month. Seal the tray of wontons with plastic wrap and place it in the freezer. When the wontons are completely frozen, you can transfer them to an airtight ziplock bag to free up freezer space.",
            "Bring a large pot of water to a boil over high heat. Add wontons. Stir gently to prevent it from sticking. Cook until the water reaches a boil again. Turn to medium-low heat. Cover the pot with a small gap on one side, to prevent it from boiling over. Continue boiling for 2 minutes (3 minutes for larger wontons). Stand beside the pot the entire time and monitor the broth. If the broth starts to boil over, uncover and stir, then replace the cover. Uncover, continue cooking for another minute, or until the wontons are cooked through.",
        ]
    ),
    "Suan Cai Yu": RecipeDetail(
        ingredients: [
            "1 lb (450 g) catfish filets ((*Footnote 1))",
            "1 egg white",
            "1/2 teaspoon sea salt",
            "1 tablespoon cornstarch",
            "1/4 teaspoon white pepper",
            "1/3 cup dried chili pepper",
            "4 green onions (, white part sliced into 1/2” (1 cm) pieces, green part thinly sliced for topping)",
            "6 cloves garlic (, minced)",
            "1 thumb ginger (, minced)",
            "1 pack (10.5oz / 300 g) Sichuan pickled mustard greens (, rinsed with running tap water, drained and sliced into bite-sized pieces)",
            "1/2 cup Chinese pickled peppers (, sliced (or keep them whole for a less spicy dish))",
            "2 tablespoons Shaoxing wine",
            "4 cups chicken broth",
            "1 teaspoon sugar",
            "1/4 teaspoon salt ((or to taste))",
            "1/4 teaspoon white pepper",
            "5 to 10 fresh chili peppers (, sliced (for garnish, very optional, use this only if you like the dish to be very spicy))",
            "1/4 teaspoon ground Sichuan peppercorns",
            "2 to 3 tablespoons peanut oil",
            "1 teaspoon green Sichuan peppercorn oil ((Optional))",
        ],
        steps: [
            "To slice the catfish, tilt the knife so it’s at 45 degrees against the cutting board. Slice fish into 1/2” (1 cm) thick slices.",
            "Combine fish, white pepper, salt, egg white, and potato starch in a bowl. Gently mix the ingredients by hand, until the fish is evenly coated. Let marinate for 10 to 20 minutes while preparing other ingredients.",
            "Heat the oil in a deep large skillet (or a wok) over medium heat until hot. Turn to medium heat. Add green onion, garlic, ginger, and chili pepper. Cook and stir until very fragrant and the peppers just start to turn darker, 1 minute or so.",
            "Add Sichuan pickles and pickled peppers. Cook and stir for 1 to 2 minutes. Add Shaoxing wine to deglaze the pan. Quickly stir a few times.",
            "Add chicken stock and sugar. Cook over medium heat until boiling. Turn to medium heat and let the broth simmer for 3 to 5 minutes. Turn to low heat and taste the broth. Adjust seasoning by adding salt and white pepper, if needed. The broth should be slightly salty. Use a slotted ladle to transfer the pickles to a big serving bowl.",
            "Turn to medium-high heat to bring the broth to a simmer. Add the fish slices, using chopsticks or a pair of tongs to gently separate the slices. Cook the fish in two batches if your pan is not big enough to spread all the fish slices into a single layer. Cook until the fish is just cooked through, 1 to 2 minutes. Using a slotted ladle to transfer the fish to the serving bowl on top of the pickles. Once the fish is cooked, turn to medium-high heat to bring the broth back to a boil.",
            "While the broth is cooking, sprinkle the green part of the green onions, sliced chili peppers (if using), and ground Sichuan peppercorn on top of the fish.",
            "Heat the oil in another small saucepan until hot and just starting to smoke. Turn off the heat. Immediately drizzle the hot oil over the aromatics on top of the fish. You should see the hot oil bubbling. Drizzle a bit of green Sichuan peppercorn oil if using. Serve hot by itself or over rice as a main dish.",
        ]
    ),
    "Dry Pot Cauliflower": RecipeDetail(
        ingredients: [
            "1 head (1 lb / 450 g) Chinese cauliflower (, cut into bite-size florets )",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "4 slices bacon (, cut to bite-size pieces)",
            "4 Chinese dried chili peppers (, cut in half)",
            "2 green onions (, cut into 2” (5 cm) pieces)",
            "1 tablespoon minced ginger",
            "4 cloves garlic (, sliced)",
            "1 long red Asian pepper (or Thai bird eye chile, jalapeno, or anaheim pepper) (, sliced)",
            "1/3 cup chicken broth",
            "2 teaspoon soy sauce",
            "1/2 teaspoon salt",
            "1/2 teaspoon sugar",
            "1/4 teaspoon freshly ground Sichuan peppercorns ((Optional but highly recommended))",
        ],
        steps: [
            "Add the oil to the pan and heat over medium heat. Add the bacon. Cook, stirring occasionally, until the bacon turns golden. Transfer the bacon to a plate and leave the oil in the pan.",
            "Add the dried chili peppers, green onion, garlic, and ginger. Stir a few times to release fragrance.",
            "Add the cauliflower. Turn to medium-high heat. Stir and cook for 1 minute to coat the cauliflower evenly with oil.",
            "Pour in the sauce. Keep stirring to mix everything together, 1 minute or so. Cook covered for another 1 to 2 minutes, until the cauliflower just starts to soften. Add the pepper and the cooked bacon back, stir to mix everything together and cook until the sauce is mostly absorbed, 1 minute or so. Carefully taste the cauliflower. Cook a bit longer and adjust seasoning by adding more salt, if needed.",
            "Transfer everything to a big plate. Serve hot as a side or main dish.",
        ]
    ),
    "Suan La Fen": RecipeDetail(
        ingredients: [
            "1 teaspoon peanut oil",
            "4 oz (125 g) ground pork",
            "2 teaspoons Shaoxing wine ((or dry sherry))",
            "1 teaspoon dark soy sauce ((use 2 teaspoons if not using Sui Mi Ya Cai))",
            "2 teaspoons Sui Mi Ya Cai ((Optional) (Footnote 1))",
            "2 green onions (, sliced)",
            "2 cloves garlic (, grated)",
            "2 tablespoons homemade chili oil",
            "2 tablespoons Chinkiang vinegar",
            "2 tablespoons light soy sauce",
            "1 teaspoon dark soy sauce",
            "1/2 teaspoon sugar",
            "1/8 teaspoon ground Sichuan peppercorns ((Optional))",
            "2 cups chicken broth ((*Footnote 3))",
            "7 oz (200 g) fresh sweet potato noodles ( (or 4 oz./ 120 g dried sweet potato noodles))",
            "Roasted peanuts ((*Footnote 4))",
            "Chopped cilantro ((or green onions))",
            "Pickled mustard tube ((or other Chinese pickles) (Optional))",
        ],
        steps: [
            "Heat oil in a medium skillet over medium-high heat until hot. Add the pork and spread it out. Let cook until the bottom is browned. Break apart the pork and flip to cook the other side until just cooked through.",
            "Pour in the Shaoxing wine, soy sauce and add the Sui Mi Ya Cai, if using. Stir and cook until the sauce is fully absorbed and mixed well. Transfer the pork to a plate and set aside.",
            "Divide all the ingredients evenly (except the chicken broth) and add them into two medium-sized bowls. Or add everything into one big bowl. (*Footnote 2)",
            "Add the chicken broth to a small saucepan and bring to a full boil over medium-high heat. When the broth comes to a boil, turn to low heat to keep the broth hot.",
            "While heating up the broth, prepare the noodles according to the package instructions. Boil the noodles until al dente, then rinse a few times with cold tap water to stop cooking. Drain and set aside.",
            "When everything is ready and you’re ready to serve, pour 1 cup of the broth into each bowl with all the broth ingredients.",
            "Divide and transfer the noodles into the bowls with the broth. Add the pork topping if using. Garnish with roasted peanuts, chopped cilantro or green onions, and pickled mustard tube. Serve hot.",
        ]
    ),
    "Huang Fei Hong Peanuts": RecipeDetail(
        ingredients: [
            "1 cup raw peanuts",
            "1/2 cup vegetable oil ((or enough to cover the peanuts))",
            "dried chili peppers and 1 teaspoon Sichuan peppercorn for garnish ((Optional))",
            "1 teaspoon chili flakes",
            "1 teaspoon sugar",
            "1 teaspoon sea salt",
            "1 teaspoon Sichuan peppercorn powder (, toasted (*See footnote 1))",
            "1/4 teaspoon white pepper powder",
            "1/4 teaspoon five spice powder",
        ],
        steps: [
            "Cover peanuts with warm water. Let soak for 30 minutes to 4 hours. Peel and discard the skin. Drain and pat dry peanuts with paper towel.",
            "Combine all the ingredients for the spice mix in a small bowl.",
            "Add peanuts into a wok and oil to cover. Turn on medium heat. Cook until the peanuts start to sizzle. Turn to medium low heat. Cook and stir occasionally until the surface turns pale yellow. Transfer peanuts using a colander onto a plate layered with paper towels. Remove extra oil from the wok and reserve just 1 teaspoon.",
            "(Optional) Add chili peppers and Sichuan peppercorns into the same wok. Cook and stir until fragrant.",
            "Return peanuts to wok. Add the spice mix. Stir to mix well so the peanuts are evenly covered with spices. Transfer peanuts onto a big plate to cool. Don’t worry if the peanuts are not crispy enough when they’re still warm. They’ll crisp up and become crunchy once completely cooled.",
            "Serve immediately as a snack or store in an air-tight container.",
        ]
    ),
    "Tiger Skin Peppers": RecipeDetail(
        ingredients: [
            "3 tablespoons soy sauce",
            "3 tablespoons black rice vinegar",
            "1 tablespoon sugar",
            "1 and 1/2 tablespoons peanut oil ((or vegetable oil))",
            "4 cloves garlic",
            "10 500 grams hatch peppers ((or anaheim peppers))",
        ],
        steps: [
            "Combine soy sauce, black rice vinegar and sugar in a small bowl. Mix well.",
            "Cut peppers from the top to the end. Remove stem and seeds with a knife or spoon (*see footnote).",
            "Add 1 tablespoon oil to a large nonstick skillet (or a wok). Heat over medium heat until warm.",
            "Add peppers. Cook and stir until the peppers turn tender and the color turns yellowish green, and the skin is blistered nicely, about 15 minutes. Turn to low heat if the skillet starts to smoke. Transfer to a plate.",
            "Add the remaining 1/2 tablespoon oil and garlic. Turn to medium high heat. Stir a few times until fragrant.",
            "Add peppers back to the skillet. Stir a few time.",
            "Pour the sauce onto the peppers. Cook and stir until the sauce thickens, 1 minute.",
            "Serve warm or cold, over steamed rice or by itself as a side.",
        ]
    ),
    "Sichuan Roast Chicken": RecipeDetail(
        ingredients: [
            "1 (3.5 to 5 lbs / 1.5 to 2 kg) whole chicken",
            "1 1/2 tablespoon salt",
            "1 tablespoon black tea",
            "2 teaspoons Sichuan peppercorns",
            "1 teaspoon granulated garlic ((or garlic powder))",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "1 tablespoon sesame oil (more to drizzle)",
            "4 green onions (, sliced into 2” (5 cm) pieces)",
            "15 slices ginger (, 2 in)",
            "1 head garlic (, top removed)",
            "1 cup (250 ml) ice",
            "2 pieces ginger (, sliced)",
            "Pan drippings (+ water needed for adequate rice cooking liquid)",
            "1 green onion (, thinly sliced)",
            "Pinch of salt",
        ],
        steps: [
            "Add the salt, tea, and peppercorns to a pan. Heat over medium-low heat, stirring regularly, until smoking.",
            "Remove the pan from the heat and add the granulated garlic. Transfer everything into a spice grinder or a small food processor. Grind until everything turns into a granulated spice mix.",
            "Combine the shaoxing wine and sesame oil in a small bowl. Stir well.",
            "Transfer the chicken into a large bowl. Rub the chicken with the sesame oil mixture on the inside and outside until well coated.",
            "Sprinkle the Sichuan peppercorn salt mixture onto the inside and outside of the chicken. Gently pat and rub with your hands until evenly coated.",
            "Stuff the cavity with green onions and ginger. Seal with the garlic, with the cut side facing the inside of the chicken. Secure the stuffing by stitching together the cavity with a toothpick (skip this if you don’t have a toothpick). Tuck the wing tips underneath the breasts to prevent burning.",
            "Place the chicken breast-side-down in the same large bowl. Cover with plastic wrap. Let it marinate overnight in the fridge. Rotate once halfway through marinating (it’s OK if you forget the rotating).",
            "Adjust the oven rack, so the chicken will be positioned in the middle of the oven. Preheat the oven to 450 °F (232 °C). Line a roasting pan with foil for easy cleaning. Pour in a cup of water to prevent the drippings from burning. Place a roasting rack into the pan.",
            "Drizzle the extra marinating liquid onto the chicken. Roast the chicken at 450 °F (232 °C) for 30 minutes.",
            "Take the chicken out of the oven. Turn the oven to 350 °F (176 °C). Drizzle additional sesame oil onto the chicken. Add more water to the pan if needed.",
            "Return the chicken back to the oven. Roast at 350 °F (176 °C) for another 30 minutes, or until the juices run clear.",
            "If you happen to have an adjustable roasting rack, you can use this method to get extra crispy thighs. Start the roasting by shaping the roasting rack into a “V” shape. Grease the rack with a thin layer of oil to prevent sticking. Place the chicken on its side, so the thigh and the wing are facing up. Drizzle a few teaspoons of the marinating liquid onto the chicken. Roast at 450 °F (232 °C) for 15 to 20 minutes, until the top of the thigh turns golden brown.",
            "Take the chicken out of the oven. Wearing a pair of oven mitts and holding both ends of the chicken, flip it so the other thigh and wing face up. Drizzle the rest of the marinating liquid onto the chicken. Continue to roast at 450 °F (232 °C) for 10 to 15 minutes, until the top of the thigh turns golden brown.",
            "Take the chicken out of the oven. Turn the oven to 350 °F (176 °C). Drizzle additional sesame oil onto the chicken. Add more water to the pan if needed.",
            "Return the chicken to the oven. Roast at 350 °F (176 °C) for another 30 minutes, or until the juices run clear.",
            "For a smaller chicken (under 4 lbs / 1.8 kg), I would test the chicken at the 20-minute mark, just in case, to avoid overcooking. For a bigger chicken, you might need 10 minutes or more of additional roasting time at 350 °F (176 °C) to finish.",
            "For a more accurate reading, use an instant-read thermometer, inserted into the thickest part of the thigh and breast. The thigh should read at least 160 °F (71 °C) and the breast at least 155 °F (68 °C). While resting, the temperature of the dark meat will continue to go up and should reach 165 °F (74 °C), the safe temperature recommended by the FDA. Note, I prefer to cook chicken breast slightly under 165 °F (74 °C), which yields super juicy and tender results.",
            "Let the chicken rest for at least 10 minutes before serving. It will stay pretty hot for about 30 minutes.",
            "Collect the pan drippings in a measuring cup. Add water to the drippings to reach the needed amount of liquid, depending on the type of rice you’ll make. You will need 1 3/4 cup of liquid for jasmine rice, or 1 1/4 cup of rice for medium or long grain rice. Check out my rice cooking guide for more information.",
            "Add the rice into a small saucepan. Add water to cover. Rinse in a circular motion with your fingers a few times. Drain the water and repeat the process one more time. Drain the water thoroughly.",
            "Add the pan dripping water mixture, ginger, and a pinch of salt.",
            "Cook over medium heat until the water comes to a full boil. Cover the pan and turn to low heat immediately. Steam 15 minutes for jasmine and long grain rice, and 18 minutes for medium grain rice. Do not uncover the pot during steaming.",
            "Once the rice is done cooking, remove the pan from the stove. Let sit, covered, for another 10 minutes.",
            "After resting the rice, use a fork or spatula to fluff it. Taste the rice. Add more salt and mix again, if needed.",
            "Once rested, carve the chicken and top it onto the rice. Garnish with green onion. Serve hot as a main dish.",
        ]
    ),
    "Zhong Shui Jiao": RecipeDetail(
        ingredients: [
            "1/2 cup soy sauce",
            "2 scallions (, cut into 1” pieces)",
            "1 slice ginger",
            "1 bay leaf",
            "1/4 cup brown sugar",
            "1/8 teaspoon five spice powder",
            "1/2 teaspoon cornstarch",
            "1 tablespoon grated ginger",
            "1 teaspoon Sichuan peppercorn",
            "3 tablespoons hot water",
            "8 oz pork",
            "2 teaspoons Shaoxing wine",
            "2 teaspoons light soy sauce",
            "1/4 teaspoon salt",
            "1/4 teaspoon sugar",
            "1 teaspoon sesame oil",
            "24 homemade dumpling wrappers ((or packaged wrappers) (*Footnote 2))",
            "4 tablespoons homemade chili oil ((or store bought chili oil, oil &amp; chili flakes 1:1))",
            "2 cloves garlic (, grated)",
            "Sichuan peppercorns (, grated (for garnish) (Optional))",
        ],
        steps: [
            "Combine the soy sauce, scallion, ginger and bay leaf in a small sauce pan. Cook over medium heat until simmering. Lower the heat and simmer for 5 minutes. Remove the ginger and scallion pieces using a slotted spoon and discard them. Add the brown sugar and five spice powder into the sauce. Stir and cook until dissolved. Combine the cornstarch with 1 tablespoon cold water and stir to dissolve completely, then pour it into the soy sauce mixture. Stir and cook until the sauce thickens enough to coat the back of a spoon. Transfer to a small bowl and set aside.",
            "Combine the ginger and Sichuan peppercorn in a small bowl and pour the hot water over them. Stir a few times. Let sit for 10 minutes. Then strain the mixture through a fine sieve. Discard the ginger and Sichuan pepper.",
            "Add the pork into a medium-sized bowl. Add the ginger peppercorn water, Shaoxing wine, soy sauce, salt, sugar and sesame oil. Stir in one circular direction until all the ingredients are absorbed and the pork becomes sticky.",
            "Make the dumplings by adding about 1 tablespoon of filling into the center of a dumpling wrapper. Fold the wrapper into a half-moon shape and press to seal the edges, or fold the dumpling pleats using the method in the blog post (refer to the photos and video above). Place the folded dumplings onto a tray and cover with damp paper towels to prevent them from drying out.",
            "While folding the dumplings, bring a large pot of water to a boil. Cook the dumplings in two batches (*Footnote 3). Carefully lower the dumplings into the water. Cover and cook until the water starts to boil again. Adjust the heat so the water keeps a low boil without spilling. Cover and cook for 3 minutes (up to 5 minutes for bigger dumplings, or frozen dumplings). Uncover pot. Continue to cook for about 1 minute (up to 2 minutes for bigger dumplings), until cooked through. Transfer to a plate immediately using a spider strainer.",
            "To assemble the dumpling bowls, add 2 teaspoons of seasoned soy sauce, 1 tablespoon chili oil, and about 1/4 teaspoon grated garlic into each individual bowl. Portion the dumplings into each bowl and stir to mix well. Garnish with extra ground Sichuan peppercorn if preferred. Serve immediately as an appetizer. Add more sauce if desired.",
        ]
    ),
    "Sichuan Shrimp": RecipeDetail(
        ingredients: [
            "1 lb shrimp (, peeled and deveined)",
            "1/2 teaspoon light soy sauce",
            "1/2 teaspoon Shaoxing wine ((or dry sherry))",
            "2 tablespoons cornstarch",
            "1 cup dried Chinese chili peppers ((*Footnote 1))",
            "1/3 cup vegetable oil ((or enough to cover the shrimp halfway ) (*Footnote 2))",
            "3 cloves garlic (, minced)",
            "1/2 ” ginger (, minced)",
            "1 green onion (, whites minced, greens sliced for garnish)",
            "2 teaspoons Doubanjiang",
            "1 tablespoon Sichuan peppercorns",
            "2 tablespoons roasted peanuts",
        ],
        steps: [
            "Pat the shrimp dry with paper towels and transfer them to a medium-sized bowl. Add the light soy sauce, Shaoxing wine, and cornstarch. Toss to coat well. Marinate for 15 minutes.",
            "Cut the chilis into 1/2” pieces and place in a colander that has holes big enough to have the chili seeds fall through. Shimmy the colander above a big plate to separate some of the seeds from the chilis. Set aside the deseeded chilis for the cooking and discard the seeds.",
            "Heat the oil in a large skillet over medium-high heat until hot. Add the shrimp. Let cook without moving for 1 to 2 minutes, until the bottom turns golden. Flip to cook the other side for another 1 to 2 minutes, until turning golden and the shrimp are fully curled up. Transfer the shrimp to a big plate and set aside.",
            "Turn to low heat. Remove all but 2 tablespoons of oil from the pan by pouring the oil into a bowl, or use a few layers of paper towels held in a pair of tongs to wipe the pan.",
            "Turn to medium-low heat. Add the garlic, ginger, and green onion. Cook and stir until fragrant, about 30 seconds.",
            "Add the doubanjiang. Stir and cook for a minute.",
            "Add the dried chilis, sichuan peppercorns, and peanuts. Continue to cook and stir for another minute, or until the chilis turn dark brown but are not burned.",
            "Add back the shrimp. Toss thoroughly to coat well. Immediately transfer everything to a serving plate.",
            "Serve hot over steamed rice as a main dish. (*Footnote 3)",
        ]
    ),
    "Chili Garlic Shrimp": RecipeDetail(
        ingredients: [
            "1 lb raw shrimp (, peeled &amp; deveined (*Footnote 1))",
            "1 teaspoon Shaoxing wine ((Optional))",
            "1/2 teaspoon salt",
            "1 1/2 tablespoons cornstarch",
            "1 tablespoon all-purpose flour",
            "1/4 cup chili garlic sauce",
            "2 tablespoons brown sugar",
            "2 teaspoons light soy sauce ((or soy sauce))",
            "4 1/2 tablespoons peanut oil ((or vegetable oil))",
            "1 tablespoon minced ginger",
        ],
        steps: [
            "Combine the shrimp and Shaoxing wine in a medium-sized bowl. Sprinkle evenly with salt. Mix until the salt is evenly dispersed. Set aside while preparing the rest of the ingredients.",
            "Combine all the sauce ingredients in a bowl and stir until the brown sugar is dissolved. Set aside.",
            "Heat 4 tablespoons of oil (or just enough to cover the bottom of the pan) in a medium-sized skillet until hot. Meanwhile, add the cornstarch and all-purpose flour to the bowl with the shrimp. Toss until the shrimp are fully coated.",
            "Shake the extra flour off the shrimp and add them to the pan. You might need to cook them in two batches. Let the shrimp cook without touching them, until the bottom turns golden, 2 to 3 minutes. Flip to brown the other side, another 2 to 3 minutes. Once done, transfer the shrimp to a large plate without overlapping and keep cooking the rest.",
            "Once you’re done cooking the shrimp, turn off the stove and use paper towels to wipe the pan to remove any residue.",
            "Add the remaining 1/2 tablespoon of oil to the pan and heat over medium heat. Add the ginger and stir until fragrant, about 1 minute.",
            "Add the sauce to the pan. Cook and stir until the sauce becomes thick and glossy, 20 to 30 seconds.",
            "Turn the heat off and return the shrimp into the pan, tossing to coat thoroughly. Serve hot as a main dish.",
        ]
    ),
    "Hunan Beef": RecipeDetail(
        ingredients: [
            "1 lb (450 g) flank steak",
            "1 tablespoon light soy sauce",
            "2 teaspoons Shaoxing wine",
            "1/4 teaspoon baking soda",
            "1/4 teaspoon white pepper",
            "1/2 teaspoon cornstarch",
            "2 tablespoons chicken broth",
            "1 tablespoon light soy sauce",
            "1 tablespoon Shaoxing wine",
            "1/2 teaspoon cornstarch",
            "1/2 teaspoon chicken bouillon",
            "1/4 teaspoon white pepper",
            "1/4 teaspoon sugar",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "6 cloves garlic (, sliced)",
            "1 thumb ginger (, julienned)",
            "4 dried Chinese chili pepper (, cut into small pieces)",
            "1/4 teaspoon ground Sichuan peppercorn",
            "2 to 4 hot chili peppers (, sliced into circles (*Footnote))",
        ],
        steps: [
            "Split the flank steak along the grain into two long pieces, then slice each piece against the grain into 1/8” (3 mm) thin pieces. Transfer to a medium bowl. Add the light soy sauce, baking soda and white pepper. Mix thoroughly with your hands to evenly coat the beef. Add the cornstarch and mix again. If the cornstarch does not distribute evenly, add 1 to 2 teaspoons of water and mix again. Set aside to marinate for 15 minutes while preparing the other ingredients.",
            "Mix the sauce in a medium bowl and set aside.",
            "Heat the oil in a large skillet over medium heat until hot. Spread the beef into the pan without overlapping. You might want to cook in batches if your pan is not big enough. Sear without moving until the bottom turns golden brown, 1 minute or so. Flip the beef to cook the other side, until lightly seared and the inside is still slightly pink. Transfer the beef to a big plate and set aside.",
            "Add the remaining oil, garlic, ginger, dried chili pepper and ground Sichuan peppercorn. Cook and stir until the garlic turns slightly golden, 1 minute or so.",
            "Add the pepper. Stir and cook for 1 minute. Then add back the cooked beef.",
            "Stir the sauce again to dissolve the cornstarch completely. Pour into the skillet and stir immediately. Cook until the sauce is evenly coated. Turn off the heat and transfer everything to a large plate. Serve over steamed rice as a main dish.",
        ]
    ),
    "Hunan Chicken": RecipeDetail(
        ingredients: [
            "1 lb boneless skinless chicken thigh (, cut into 1” (2.5 cm) pieces (or breast))",
            "1 tablespoon Shaoxing wine",
            "1/4 teaspoon salt",
            "2 teaspoons cornstarch",
            "1 tablespoon oyster sauce",
            "1 tablespoon Shaoxing wine",
            "1 tablespoon soy sauce",
            "1 teaspoon dark soy sauce",
            "2 teaspoons sugar",
            "1/2 teaspoon cornstarch",
            "2 tablespoon peanut oil ((or vegetable oil))",
            "6 scallions (, sliced into 1” (2.5) pieces, white and green parts separated)",
            "5 garlic cloves (, smashed and sliced)",
            "1/2 ” ginger (, julienned)",
            "2 tablespoons fermented black beans",
            "2 stalks celery (, sliced on bias into 1/2” thick pieces)",
            "2 hot chili peppers (, thinly sliced on the bias (anaheim, or Fresno etc))",
        ],
        steps: [
            "Combine chicken, Shaoxing wine, salt, and cornstarch in a medium-sized bowl. Mix well with your hands, so the chicken is evenly covered with a thin slurry.",
            "Mix all the sauce ingredients together in a small bowl.",
            "Heat 1 tablespoon of oil in a large skillet over high heat until hot. Add the chicken pieces and spread into a layer without overlapping. Let sear until the bottom turns golden brown, 2 minutes or so. Flip to cook the other side until the chicken is cooked through, 1 to 2 minutes. Transfer the chicken to a big plate.",
            "Add the remaining 1 tablespoon oil, scallion whites, garlic, ginger and fermented black beans. Cook and stir over medium heat for 1 minute to release fragrance.",
            "Add the chili pepper, celery and scallion greens. Stir and cook for 2 minutes, until just starting to turn tender.",
            "Add back the chicken pieces and pour in the sauce. Cook and stir until the sauce has reduced and coats everything. Transfer everything to a big plate. Serve hot with steamed rice as a main dish.",
        ]
    ),
    "La Zi Ji": RecipeDetail(
        ingredients: [
            "1 lb boneless skinless chicken thigh (or breast) (, cut into 1” (2.5 cm) cubes )",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 tablespoon toasted sesame seeds (, and more to garnish)",
            "1 to 3 cups whole dried red Sichuan chilies ((*Footnote 1))",
            "2 tablespoons Sichuan chili flakes",
            "1 teaspoon sugar",
            "1/4 cup cornstarch",
            "1 teaspoon cayenne powder ((*Footnote 2))",
            "1 teaspoon ground Sichuan peppercorns ((*Footnote 3))",
            "3/4 teaspoon salt",
            "1/4 to 1/3 cup peanut oil ((or vegetable oil))",
            "2 teaspoons Sichuan peppercorns",
            "5 garlic cloves (, thinly sliced)",
            "1 thumb ginger (, minced)",
            "4 green onions (, sliced)",
            "1 cup chopped cilantro (, and more for garnish)",
        ],
        steps: [
            "To marinate the chicken: Combine chicken pieces, Shaoxing wine, and soy sauce in a medium-sized bowl. Mix well and marinate for 10 to 15 minutes.",
            "For the spice mix: Combine all the spice mix ingredients in a big bowl.",
            "For the chicken coating: Mix cornstarch, cayenne powder, ground Sichuan peppercorns and salt in a large ziplock bag. Shake to mix well",
            "When you’re ready to cook, drain the chicken pieces and discard the marinating liquid. Transfer the chicken pieces into the bag with the cornstarch mixture. Shake the bag to coat the chicken, then use your hands to massage the bag so the spice is evenly mixed in. There should be little / no dried ingredients left in the bag. Massage the bag more if you still see a lot of uncoated cornstarch. On the other hand, if the chicken pieces look wet, sprinkle on a bit more cornstarch.",
            "To cook the stir fry: Heat a large skillet (or a wok) over medium-high heat until wisps of smoke start to rise. Add oil. (Or add oil in the pan and heat together if using a nonstick skillet.) When oil is hot, spread out the chicken pieces without overlapping them. Use a pair of tongs or chopsticks to separate the chicken pieces as much as possible, then leave the chicken undisturbed until the bottom turns golden brown. Flip to cook the other side until golden and the inside of the chicken is no longer pink. Stir a few times to make sure the surface of the chicken is evenly cooked. Turn to medium-low heat. Transfer the cooked chicken to a large plate.",
            "You should still have some oil in the pan. If not, add 2 tablespoons of oil. Add the Sichuan peppercorns. Cook and stir until the color turns dark brown. Remove them from the pan. (*Footnote 3)",
            "Add the garlic, ginger and green onions. Stir a few times to release the fragrance.",
            "Add the bowl of spice mix with the peppers. Quickly stir until the peppers just turn a bit darker without turning black.",
            "Return the cooked chicken into the pan. Cook and stir until well mixed. Add the cilantro and mix a few times. Turn off heat. Transfer everything to a plate with chili peppers prominently displayed. Top with more cilantro for garnish, if needed.",
            "Serve hot (and ‘hot’!) over steamed white rice as a main.",
        ]
    ),
    "Xinjiang Cumin Lamb": RecipeDetail(
        ingredients: [
            "1 lb lamb leg (, cut to 2/3&quot; (1.5-cm) cubes)",
            "1 tablespoon soy sauce",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1/2 teaspoon salt",
            "1/4 cup cornstarch",
            "2 tablespoons cumin powder",
            "2 teaspoons Sichuan chili flakes ((or Korean chili flakes))",
            "1/2 teaspoon sugar",
            "1/4 teaspoon freshly ground Sichuan peppercorns ((Optional))",
            "4 tablespoons peanut oil ((or vegetable oil))",
            "1/2 cup dried Chinese chili peppers",
            "1 small white onion (, large diced)",
            "1 thumb ginger (, minced)",
            "5 cloves garlic (, sliced)",
            "1 cup cilantro (, chopped)",
            "Toasted sesame seeds for garnish ((Optional))",
        ],
        steps: [
            "Combine lamb, soy sauce, Shaoxing wine, and salt in a big bowl. Mix well. Let marinate for 20 minutes at room temperature, or in the fridge up to overnight.",
            "Combine the ingredients for the spice mix in a small bowl.",
            "When you’re ready to cook, drain the extra liquid from the bowl of lamb. Add the cornstarch, a few tablespoons at a time, and mix, until all the lamb pieces are coated.",
            "Heat 3 tablespoons of oil in a large skillet over medium-high heat until hot. Add the lamb pieces and spread them out with a pair of tongs or chopsticks, so they don’t overlap. Let cook without touching until the bottom side turns golden, 1 minute or so. Flip the lamb and cook the other side until slightly golden, while the inside is still a bit pink, 30 to 40 seconds. Transfer the lamb to a big plate.",
            "Add the remaining 1 tablespoon oil, the dried Chinese chili peppers, ginger, and garlic. Stir a few times to release the fragrance. Add the onion. Stir and cook for about 1 minute, until the onion just starts to turn tender. Add back the lamb and sprinkle the spice mix all over. Stir immediately to coat the lamb with spice. Remove the pan from the stove and carefully try one piece of lamb. Sprinkle a bit more salt on it, if needed.",
            "Add the cilantro and give it a final stir. Transfer everything to a big plate immediately. Serve hot as a main dish.",
        ]
    ),
    "Cantonese Roast Chicken": RecipeDetail(
        ingredients: [
            "1 (4 to 5 pound / 2 kg) whole chicken",
            "4 big cloves garlic (, sliced)",
            "1 thumb ginger (, sliced)",
            "1/2 cup soy sauce",
            "1/4 cup oyster sauce",
            "2 tablespoons Japanese sake ((or Shaoxing win, or dry sherry))",
            "2 tablespoons sugar",
            "1/2 teaspoon salt",
            "1/8 teaspoon freshly grounded black pepper",
        ],
        steps: [
            "Rinse chicken with tap water and pat dry with a paper towel.",
            "Combine all the ingredients in a bowl and mix well.",
            "Transfer the chicken to a gallon-sized Ziplock bag, legs up. Add half the marinade into the cavity of the chicken. Pour the rest of the marinade onto the chicken skin. Seal the bag halfway across. Try to squeeze out as much air as possible. Seal the bag. Rub chicken through the bag to make sure the marinade and herbs are evenly dispersed.",
            "Place chicken in fridge for 24 to 48 hours (*footnote). Flip once during marinating.",
            "On the day of cooking, place a cooling/roasting rack over a baking sheet.",
            "Transfer the chicken from the bag to a large plate. Discard marinating liquid and all the herbs. Make sure the cavity of the chicken isn’t holding any liquid. Place the chicken onto the roasting rack, breast side up.",
            "Place the baking sheet near an AC vent or in front of a fan. Let the bird air dry completely. It will take at least 4 hours if you don’t use a fan. To speed up the process, I sometimes use a hair dryer to dry the chicken. You can also place the chicken in the fridge to dry, but it takes longer.",
            "The surface of the chicken must be completely dry in order to yield crispy skin after baking. When the chicken is ready to bake, the surface won’t be shiny, with almost a leathery feel when touched.",
            "Preheat oven to 400 degrees F (200 C).",
            "Line the baking sheet with aluminum foil to catch the chicken grease. Place the roasting rack on top. Spray a thin layer of oil onto the roasting rack. (*see footnote 2)",
            "Tie chicken legs together with kitchen twine. Spray a thin layer of oil onto another sheet of aluminum foil. Cut foil into small squares and wrap around the end of the chicken legs and wings tips. (*see footnote 3)",
            "Bake on the lowest rack in the oven for 30 minutes. Rotate chicken (don’t flip). Bake for another 30 minutes. Rotate again. Continue baking until the thermometer reads 165 F (74C) when probing into the thickest part of the leg. It takes me 1 hour and 30 minutes in total to roast a chicken from Costco (about 5 pounds).",
            "During the final hour of baking, check on the chicken every 10 to 20 minutes. When you notice that any part of the chicken is already browned, cover that part with aluminum foil to prevent it from burning. If you think this is too much trouble, you can simply cover the whole chicken with a large piece of foil when most parts are nicely browned.",
            "When the chicken is cooked through, let cool for 15 minutes before slicing.",
            "Serve chicken by itself as a main. Or you can serve it with sriracha, plum sauce, or soy sauce.",
            "To reheat leftover chicken, my favorite way is to cook it with a bit of oil on the stove top. The chicken will get nicely charred and heat up in a few minutes without drying out (which happens if you reheat it in the oven).",
        ]
    ),
    "Cumin Beef": RecipeDetail(
        ingredients: [
            "1 lb beef flank steak",
            "1/4 teaspoon salt",
            "1/2 teaspoon baking soda",
            "1 tablespoon vegetable oil",
            "2 tablespoons cumin powder",
            "2 teaspoons Sichuan chili flakes ((or Korean chili flakes))",
            "1/2 teaspoon sugar",
            "1/4 teaspoon freshly ground Sichuan peppercorns ((or black pepper))",
            "1/4 teaspoon salt",
            "1/4 cup cornstarch",
            "3 tablespoons peanut oil ((or vegetable oil))",
            "8 dried Chinese chili peppers (, halved crosswise and seeds removed)",
            "1 small red onion (, sliced into 1/2” (1 cm) thick pieces)",
            "1 tablespoon ginger (, minced)",
            "5 cloves garlic (, sliced)",
            "1 tablespoon toasted white sesame seeds ((for garnish))",
            "1/4 cup loosely packed cilantro ((Optional, for garnish))",
        ],
        steps: [
            "Cut the flank steak along the grain into two even pieces, then slice it against the grain into pieces that are around 1/4” (5 mm) thick.",
            "Combine beef, salt, baking soda and vegetable oil in a big bowl. Mix well. Let marinate for 30 minutes at room temperature.",
            "Combine the ingredients for the spice mix in a small bowl.",
            "When you’re ready to cook, drain the extra liquid from the bowl of beef. Add the cornstarch, a few tablespoons at a time, and mix, until all pieces are coated.",
            "Heat 2 tablespoons of oil in a wok or large skillet over medium-high heat until hot. Cook in batches, spreading the beef slices without overlapping. Cook until the bottom turns golden and crispy, 2 to 3 minutes. Flip the slices to fry the other side, until golden brown and crispy, another 1 to 2 minutes. (*Footnote 1) Transfer the beef to a large plate. Cook the rest of the batches. Add more oil if the pan gets dry, and turn to medium heat if the pan starts to smoke too much.",
            "Add the remaining 1 tablespoon oil, the dried Chinese chili peppers, ginger, and garlic. Stir a few times to release the fragrance. Add the onion. Stir and cook for about 1 minute, until the onion just starts to turn tender. Add back the beef and sprinkle the spice mix all over. Stir immediately to coat the meat with spice. Remove the pan from the stove and carefully taste a piece of beef. Sprinkle a bit more salt on it, if needed. Turn off the heat. Add the sesame seeds and cilantro. Stir again. Transfer everything to a big plate immediately. Serve hot as a main dish.",
        ]
    ),
    "White Cut Chicken": RecipeDetail(
        ingredients: [
            "1 whole chicken ((under 3 lbs) (*Footnote 1))",
            "2 teaspoons sea salt",
            "1/4 cup Shaoxing wine",
            "6 scallions (, halved)",
            "3 ” ginger (, sliced)",
            "8 cloves garlic",
            "1 tablespoon toasted sesame oil",
            "4 scallions (, sliced)",
            "3 tablespoons minced ginger",
            "1/2 teaspoon chicken bouillon",
            "1 tablespoon light soy sauce",
            "1/8 teaspoon sugar",
            "4 tablespoons peanut oil",
        ],
        steps: [
            "Remove any giblets from the chicken cavity. Dry the chicken with paper towels. Sprinkle the salt evenly over the outside and inside of the chicken. Place the salted chicken in the fridge for at least 30 minutes, up to half a day, so the salt penetrates the meat.",
            "Add 10 cups of water into a large pot that can hold the chicken. Add the Shaoxing wine, scallion, ginger slices, and garlic. Heat over high heat until boiling.",
            "Holding the chicken by the end of its legs, gently dunk the bird into the hot water three times. This is to ensure water enters the cavity, which allows the chicken to poach evenly.",
            "Gently drop the chicken into the water, breast side up. Bring the pot to a very low simmer, cover the pot, and cook over low heat. Poach for 7 minutes per pound of meat. Flip the chicken once in the middle. The pot should be kept at a very low simmer, barely bubbling at all. Cook until the thickest part of the thigh registers 165°F (74°C). If you don’t have a thermometer, pierce the thickest part of the chicken and the liquid that comes out should be clear. If the chicken is not cooked but the temperature is close, turn off the heat and let the chicken poach, covered for an additional 7 minutes.",
            "While poaching the chicken, prepare the ginger scallion sauce by mixing the scallion, ginger, chicken bouillon, light soy sauce, sugar and peanut oil. Stir to mix well.",
            "Prepare a big bowl of ice water. Once the chicken is done, remove the chicken from the pot using a spider strainer, and place it in the bowl of prepared ice water. (*Footnote 2) Once the chicken has cooled off enough to handle, drain the chicken thoroughly.",
            "Place the chicken on a cutting board. Rub the chicken skin with sesame oil.",
            "Break the chicken down into bone-in bite-size pieces using a cleaver. If you don’t have a cleaver, you can also cut off the breasts and legs, remove the bones, then slice the chicken. Serve with ginger scallion sauce as a main dish.",
        ]
    ),
    "Siu Yuk": RecipeDetail(
        ingredients: [
            "3 to 4 lbs (1.4 to 1.8 kg) whole slab of skin-on pork belly ((*Footnote 1))",
            "1/2 to 1 teaspoon salt (depending on the size of the pork belly (*Footnote 2))",
            "1/2 cup light soy sauce ((or soy sauce, or tamari for gluten-free))",
            "1/4 cup oyster sauce ((*Footnote 3))",
            "1/4 cup Shaoxing wine ((or dry sherry for gluten-free))",
            "2 cloves garlic (, minced)",
            "1 tablespoon sugar",
            "1/2 teaspoon coarsely ground black pepper powder",
            "1/2 teaspoon five-spice powder",
            "Mustard (, Sriracha hot sauce (or other hot sauce), or plum sauce)",
        ],
        steps: [
            "Choose a shallow dish large enough to hold the pork belly (I used a baking dish). Add all the marinating ingredients and stir to mix well.",
            "Pat the skin of the pork belly with a paper towel to dry completely. Score the skin into a crosshatch pattern using a sharp knife. Try to cut through the skin without piercing the fat.",
            "Carefully transfer the pork into the shallow dish with the marinade. The marinade should come up to the sides of the pork but not touch the skin. Let it marinate in the fridge uncovered overnight or for up to a day.",
            "Preheat oven to 400 degrees F (200 C). Line a baking sheet with aluminum foil for easy cleaning. Place a wire rack on top and then place the pork on the rack.",
            "Evenly spread a layer of salt to cover the pork skin entirely.",
            "Cook at 400 F (200 C) for 30 minutes. Then lower the oven temperature to 300 F (150 C). Bake for another 2 hours.",
            "Raise the oven temperature to 450 F (230 C) and roast for another 30 to 45 minutes, until the skin completely crisps up.",
            "Move the pork onto the kitchen counter and loosely cover with aluminum foil. Slash a cross on top of the foil to let out steam so the crackling will remain crispy. Rest for 10 to 15 minutes before serving. Alternatively, you can place the pork in the oven on the lowest setting if you won’t serve it immediately.",
            "Serve the pork hot or warm with preferred dipping sauce (*Footnote 4).",
            "Store the leftover pork in fridge for 3 to 4 days.",
            "To reheat, preheat the oven to 400 F (200C). Separate the skin from the meat. Place the skin in a baking dish without overlapping, in the middle or upper section of the oven. Wrap the meat with aluminum foil and place in the lower part of the oven. Bake for 10 to 15 minutes, or until the skin is bubbling and starts to turn dark.",
        ]
    ),
    "Char Siu": RecipeDetail(
        ingredients: [
            "2 to 2.5 lbs pork tenderloin ((or pork loin))",
            "1/4 cup soy sauce",
            "1/4 cup Shaoxing wine ((or dry sherry))",
            "1/4 cup hoisin sauce",
            "1/4 cup oyster sauce",
            "1/4 cup sugar",
            "2 tablespoons molasses",
            "2 teaspoon garlic (, grated)",
            "1 teaspoon five spice powder",
            "3/4 teaspoon salt",
            "10 drops red food coloring ((Optional))",
            "2 tablespoons maltose ((or honey))",
        ],
        steps: [
            "(Optional) If you’re using pork loin, cut the pork along the grain, into 2 strips about 2” (6 cm) wide and 1”(3 cm) thick. Skip this step if using tenderloin.",
            "Prepare the marinade and the glaze the day before you cook.",
            "In a large bowl combine the soy sauce, hoisin sauce, oyster sauce, Shaoxing wine, sugar, molasses, garlic, five spice powder, salt, and food coloring (if using). Stir to mix well.",
            "Transfer the pork into a large ziplock bag. Pour 1/2 cup of the mixed sauce into the bag. Squeeze out as much air as possible and seal the bag. Massage the bag a few times so the pork pieces are covered evenly with the sauce. Transfer to the fridge and marinate overnight (highly recommended), or for at least 6 hours.",
            "Microwave the maltose for 20 seconds or so, until the top loosens. Do NOT touch the maltose with your fingers. It’s very hot once it’s heated. Grease your tablespoon with a thin layer of oil. Transfer 2 tablespoons of maltose into a small saucepan. The oil coating on the spoon will help the maltose to fall into the pan without stuck on the spoon.",
            "Add the rest mixed sauce into the same pan. Heat over medium heat and stir frequently to melt the maltose, until brought to a simmer. Turn to medium low heat. Cook for 5 minutes to thicken the sauce slightly.",
            "Once done, let the sauce cool for at least 10 minutes. Carefully transfer the sauce into a heat-proof mason jar or container. Let cool for another 10 to 15 minutes. Cover and transfer into the fridge. The sauce will continue to thicken once chilled.",
            "When the pork is marinated and the glaze is chilled, you’re ready to cook.",
            "Preheat the oven to 450 degrees F (230 C). Line a large baking tray with aluminum foil and add 1/4 inch (1/2 cm) water. Place a grilling rack on top. (Alternatively, you can grill the pork as well)",
            "Transfer the pork onto the grilling track. Drizzle a few tablespoons marinating liquid onto the pork. Bake for 10 minutes.",
            "Baste the pork, using a brush to dab the glaze onto the top side. Turn to the other side and dab glaze on top. Bake for 5 minutes.",
            "Baste the top of the pork, and bake for another 5 minutes. Once done, you can check the doneness by inserting a thermometer into the thickest part of the pork. It should read at least 145 F (63 C). Return the pork to the oven to bake for another 5 minutes or so if needed.",
            "Turn on the broiler. Broil for 3 minutes. Flip the pork to baste the other side. Broil for another 3 minutes. The pork should look glossy, lightly charred, and cooked through.",
            "Once the pork is done, brush it with the rest of the glaze. Cover loosely with aluminum foil. Let rest for 10 to 15 minutes before serving.",
            "You can serve the pork hot over rice as a main dish, or at room temperature as a cold appetizer. It’s super delicious either way.",
            "You can use the char siu drippings and meat to make char siu gravy (served with homemade scallion biscuits).",
            "You can use leftover char siu to make char siu fried noodles, char siu fried rice, and char siu buns (recipes coming soon!)",
            "To store the char siu, place it in a sealed container or bag and store it in the fridge for up to 4 days, or in the freezer for up to 1 month.",
        ]
    ),
    "Wonton Soup": RecipeDetail(
        ingredients: [
            "1 pack wonton wrappers ((80 wrappers))",
            "1/2 lb ground lean pork",
            "1/2 lb peeled shrimp, chopped into small pieces",
            "1 tablespoon finely minced ginger",
            "2 green onions (, finely chopped)",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "1/2 teaspoon salt",
            "2 tablespoons sesame oil",
            "8 cups chicken stock",
            "8 teaspoons light soy sauce ((or soy sauce))",
            "8 teaspoons minced ginger",
            "4 teaspoons sesame oil",
            "Salt (, to taste)",
            "8 cups hot broth from the wonton boiling water",
            "8 tablespoons papery dried shrimp (, or to taste)",
            "8 big pieces of dried seaweed for soup (, prepared according to instruction (*Footnote 1))",
            "4 teaspoons chicken bouillon",
            "8 teaspoons light soy sauce (, or to taste)",
            "8 teaspoons sesame oil",
            "4 green onions (, chopped)",
            "4 stalks baby bok choy (, cut to bite-size (or 4 cups baby spinach))",
            "1 batch cilantro, chopped ((Optional))",
            "Homemade chili oil (, to taste (Optional))",
        ],
        steps: [
            "Without a food processor: Combine ground pork, shrimp, ginger, green onion, soy sauce, Shaoxing wine, salt and sesame oil in a big bowl. Mix well with a fork until everything combines well together and the mixture feels a bit sticky.",
            "With a food processor or a blender: coarsely chop the ginger and green onion. Add all the filling ingredients except the shrimp. Mix until it forms a silky paste. Add the shrimp and blend again, until the shrimp are finely chopped but don’t become a paste.",
            "To make wontons, place a wonton wrapper in one hand, scoop a teaspoon of wonton filling and place it near the narrow side of the wonton wrapper (you can add more filling to the wonton if you like, as long as you can still wrap it). Fold the narrow side over the filling, then roll the filling all the way through the other side of the wrapper. Bind both ends and press together to lock the filling inside the wrapper. Brush a thin layer of water onto the wonton wrapper and press the ends together.",
            "Make one wonton at a time, and line up all the wontons on a big wooden cutting board. If you aren’t going to boil the wontons immediately, use a damp paper towel (or cheesecloth) to cover the wontons to prevent them from drying out.",
            "If you aren’t going to boil the wontons the same day, place them in an airtight container with several layers of wet paper towels on the bottom. This way, they can be stored in the fridge for up to 2 days.",
            "Combine the chicken stock, ginger, and soy sauce in a pot. Bring to a boil. Let boil for 10 minutes. Turn to lowest heat to keep warm and start cooking wontons (see below).",
            "Prepare 8 medium-sized bowls. Pour in 1 cup hot broth into each bowl. Add the cooked wontons and bok choy. Top with green onion and 1/2 teaspoon sesame oil into each bowl. Garnish with cilantro and chili oil, if using. Add a bit more soy sauce or salt to adjust seasoning if needed. Serve hot.",
            "To prepare 1 serving of wonton soup base, add a big spoon of cilantro, 1 tablespoon papery dried shrimps, a generous piece of dried seaweed, 1/4 teaspoon chicken bouillon, and some baby bok choy into a big bowl. Repeat the process to prepare the rest of the soup base in the other serving bowls. Cook wontons (see below).",
            "To make 1 serving of wonton soup, use a ladle to transfer cooked wontons, bok choy, and the hot soup into a serving bowl with all the ingredients from the previous step. Drizzle 1 teaspoon soy sauce and 1 teaspoon sesame oil into the bowl and give it a gentle stir. The soup should be amber-colored. Add extra soy sauce or salt if the soup is not salty enough. Scatter green onion on top. Garnish with cilantro and chili oil, if using. Serve hot.",
            "To boil the wontons, heat a big pot of water until boiling. Add 10 to 20 wontons at a time and boil over medium heat until wontons are floating on the surface of the water. Continue to boil until the wrappers are swollen, around 1 to 2 minutes for small wontons and 2 to 3 minutes for bigger ones. Take a wonton out with a slotted spoon and split it with a chopstick or fork. If the wonton is cooked through, stop heat immediately and transfer the wontons to individual serving bowls. If not, continue to boil until cooked through.",
            "Once you’ve cooked the wontons, add the bok choy. Let cook until tender. Remove from the pot, drain well, and set aside.",
            "Bring a large pot of water to a boil over high heat. Add wontons. Stir gently to prevent from sticking. Cook until bringing the water to a boil again. Turn to medium-low heat. Cover the pot with a small gap on one side, to prevent spilling. Continue boiling for 2 minutes (3 minutes for larger wontons). Stand beside the pot the whole time to monitor the broth. If the broth starts to spill, uncover and stir, and replace the cover. Uncover and continue cooking for another minute, or until the wontons are cooked through.",
        ]
    ),
    "Steamed Fish in Black Bean Sauce": RecipeDetail(
        ingredients: [
            "1 tablespoon fermented black beans",
            "2 teaspoons Shaoxing wine",
            "1 tablespoon oyster sauce",
            "2 teaspoons light soy sauce",
            "1 tablespoon minced ginger",
            "2 teaspoons sugar",
            "1/4 teaspoon salt",
            "2 teaspoons cornstarch",
            "2 flounder fillets ((or other white fish such as branzino, cod, or halibut) (*Footnote 1))",
            "1 thumb ginger (, julienned)",
            "2 scallions (, julienned)",
            "2 tablespoons vegetable oil",
        ],
        steps: [
            "Combine the fermented black beans, Shaoxing wine, oyster sauce, light soy sauce, ginger, sugar, salt and cornstarch. Stir to combine.",
            "Select a plate that can hold the fish and can fit into your steamer (or wok, if using a wok in your steamer setup). Place the fish fillets into the plate with minimal overlap. Spread the black bean sauce evenly over the fish. Set up your steamer and bring the water to a boil. Place the plate into the steamer and steam covered for 5 minutes (*Footnote 2), or until the fish is cooked through.",
            "Once cooked, transfer the fish onto a serving platter. Spread the ginger and scallion over the fish.",
            "Heat vegetable oil in a small saucepan until it shimmers. Test the oil by poking a piece of scallion into it, it should sizzle and small bubbles rapidly rise up. Immediately pour the oil onto the fish fillets to cook the ginger and scallion. You should hear a vibrant sizzle. Serve hot.",
        ]
    ),
    "Wonton Noodle Soup": RecipeDetail(
        ingredients: [
            "1 pack wonton wrappers (, thawed if using frozen)",
            "1/2 lb ground pork",
            "4 oz raw peeled and deveined shrimp (, chopped into small pieces)",
            "1/2 tablespoon light soy sauce",
            "1 tablespoon sesame oil",
            "1 egg white",
            "2 teaspoons ginger (, finely minced)",
            "3/4 teaspoon sea salt",
            "1/2 teaspoon sugar",
            "1/4 teaspoon white pepper",
            "1 pack Hong Kong style wonton noodles",
            "8 cups homemade chicken stock ((Footnote 1))",
            "2 teaspoons sea salt ((or to taste))",
            "4 green onions (white part, sliced)",
            "1 ” ginger (, large sliced)",
            "green onion greens for garnish (, sliced)",
            "8 heads choy sum ((or baby bok choy))",
            "Fried shallots",
        ],
        steps: [
            "Prepare wonton filling: In a large bowl, combine all the ingredients for the wonton filling. Mix well with a spatula in a circular motion until it forms a sticky paste.",
            "Prepare a large tray or a plate. Spray a thin layer of oil or sprinkle some flour onto it to prevent sticking.",
            "Wrap the wontons: Work on the wontons one at a time. Make a loose fist with one hand and place a wonton wrapper over your thumb and index finger. Place about a teaspoon of filling in the center of the wrapper. Slowly close your thumb and index finger to gather the wrapper while using a small spoon to push down the filling, until the wrapper comes together. Pinch the wrapper right above the filling so it seals tightly. (See the blog post above for the detailed wrapping steps in the pictures). Place the wrapped wontons onto the prepared tray, a finger’s width apart. (Now you can store the wontons if not used immediately. See footnote 2 for storage tips)",
            "Make sure to use a wet paper towel or clean wet kitchen towel to cover the wonton wrappers and the wrapped wontons, to prevent them from drying out.",
            "Prepare a big pot for cooking the wontons and noodles. Add about 1 gallon (4 liters) of water and bring it to a boil.",
            "Add homemade chicken stock, salt, ginger and green onion (white part) to another medium-sized pot. Heat over medium heat until simmering. Then cover and turn to lowest heat to keep warm while cooking the wontons and noodles. Taste the soup. It should be slightly salty. You can always adjust the seasoning by adding more salt later.",
            "Prepare 4 large bowls. Add noodles into the large pot with the boiling water. Cook according to package instructions. Once done, divide noodles into 4 equal portions and transfer into each serving bowl.",
            "Cook the wontons in two batches if you plan to use them all. When the big pot of water comes to a boil again, add half of the wontons into the large pot. Stir gently with a spatula constantly to prevent them from sticking to the bottom. Cook until the wontons are floating on top, then continue cooking for another minute. Transfer the wontons into each of the serving bowls.",
            "Pour 2 cups of hot chicken soup into each serving bowl.",
            "(Optional) Blanch the greens in the large pot. Transfer onto the wonton bowls to garnish. Garnish with a spoonful of fried shallot and a pinch of green onions. Serve hot and enjoy!",
        ]
    ),
    "Steamed Fish": RecipeDetail(
        ingredients: [
            "1 small (about 1.1 lb / 500 g) head-on sea bass",
            "1 1/2 pieces (thumb-sized) ginger (, 1 thumb sliced, 1/2 thumb julienned)",
            "3 green onions (, sliced into 2.5” (6 cm) long pieces)",
            "2 tablespoons Shaoxing wine",
            "1 1/2 tablespoons peanut oil ((or vegetable oil))",
            "2 dried Chinese chili peppers",
            "1/8 teaspoon ground Sichuan peppercorn ((Optional but highly recommended))",
            "2 tablespoons seasoned soy sauce for seafood",
        ],
        steps: [
            "Before cooking, check if the fish is fully scaled by running your fingers from the tail of the fish to the head. Use kitchen shears to descale if needed. Wash the fish thoroughly with cold tap water and drain. Dry the fish with paper towels. Score the fish 3 to 4 times, 1” (2.5 cm) apart.",
            "Place a quarter of the green onions on a plate large enough to hold the entire fish. The green onions will hold the fish so it won’t stick to the plate when cooked.",
            "Stuff ginger slices and a quarter of the green onions (white part) into the cavity of the fish. Stuff the ginger slices into the scored parts. Pour the Shaoxing wine over the fish. Season very lightly with salt. Cover the fish with another quarter of the green onions. Let marinate for 10 minutes at room temperature while preparing the other ingredients, or in the fridge for half a day, until you’re ready to cook.",
            "In a large, deep skillet (or steamer or wok), add 1” (2.5 cm) of water and place a steaming track in the middle (Footnote 2). Place the plate of fish over the rack. Cover and bring water to a boil over high heat. When the steam starts to come out, cook, covered, over high heat for 5 to 8 minutes (*Footnote 3), until you can easily pull the flesh from the bone with a fork. Turn off the heat immediately.",
            "Carefully transfer the plate of the fish onto the kitchen counter. Use a pair of chopsticks to remove and discard the ginger and green onion from the top of the fish.",
            "Spread the remaining julienned ginger strips and green onions on top of the fish and set aside. Make sure the seasoned soy sauce is ready beside the fish.",
            "In a small skillet or saucepan, heat oil over medium-high heat. When the oil is warm, break chili peppers into 3 to 4 pieces and add them, with the ground Sichuan peppercorns, into the oil. Stir with a spatula until fragrant and the peppers are sizzling, about 30 seconds. Drizzle the hot oil over the fish. You should hear the sizzling of the oil when it touches the fish. Immediately pour the seasoned soy sauce onto the fish.",
            "Serve immediately. The fish won’t hold sauce very well, so make sure you dip the fish meat into the sauce from the plate as you eat. (see footnote 4).",
        ]
    ),
    "Shu Mai": RecipeDetail(
        ingredients: [
            "30 Hong Kong Style dumpling wrappers (, thawed if using frozen wrappers)",
            "Frozen peas (, for garnish (Optional))",
            "1 large carrot (, sliced thinly into rounds (Optional))",
            "1/2 lb shelled and deveined raw shrimp",
            "10 oz ground pork ((20% fat))",
            "2 eggs",
            "2 teaspoons cornstarch",
            "2 teaspoons Shaoxing wine ((or dry sherry))",
            "1 tablespoon oyster sauce",
            "1 teaspoon light soy sauce ((or regular soy sauce))",
            "1 teaspoon grated ginger",
            "1/2 teaspoon sugar",
            "1/4 teaspoon salt",
            "1/4 teaspoon white pepper powder",
            "1 tablespoon toasted sesame oil",
            "3 tablespoons Chinkiang vinegar",
            "1/2 thumb ginger (, thinly sliced)",
        ],
        steps: [
            "Reserve 3 to 4 shrimp, and chop them into small pieces. Mince the rest of the shrimp as finely as possible.",
            "Combine the shrimp, pork, egg and cornstarch. Beat the mixture with a pair of chopsticks or a wooden spatula until the mixture is very sticky.",
            "Add the rest of the filling ingredients and the reserved shrimp pieces. Mix very well, until smooth and sticky.",
            "Reserve 3 to 4 shrimp, and chop them into small pieces. Add the rest of the shrimp into the food processor. Pulse the food processor until the shrimp are coarsely chopped.",
            "Add the rest of the filling ingredients. Mix until everything is evenly chopped into a fine paste and becomes very sticky.",
            "Transfer the paste into a big bowl and add the reserved shrimp pieces. Stir to mix well.",
            "Work on the shumai one by one. Place a dumpling wrapper on a clean work surface. Wet the edge lightly with water. Place 1 tablespoon of filling in the center of the wrapper. Bring the edges up around the filling, pinching and pleating, leaving the top open. Then use your thumb and index finger to lightly press the top without closing it, while using the other hand to hold the bottom to pack the filling in. Garnish with a green pea. Place a slice of carrot on the bottom, if using. Repeat with the remaining wrappers.",
            "Line your steamer with a clean, wet cheesecloth or steaming parchment (you can skip this if using the carrot liner). Transfer the shumai into the steamer basket, one finger’s width apart.",
            "Heat a large pot of water over medium-high heat until boiling. Cover the steamer basket and place it over the pot. Steam over boiling water for 7 to 8 minutes, until cooked through.",
            "Serve by itself or with a Chinkiang vinegar and ginger dipping sauce.",
            "Place the uncooked shumai on a lightly greased baking sheet, one finger’s width apart. Cover the sheet with plastic wrap. Freeze the shumai until completely frozen. Then you can transfer them to bags or containers to save freezer space.",
            "Steam the frozen shumai without defrosting or thawing. After bringing the water to a boil, steam until completely cooked through, 15 minutes or so.",
        ]
    ),
    "Turnip Cake (Lo Bak Go)": RecipeDetail(
        ingredients: [
            "4 shiitake mushrooms",
            "2 tablespoons dried shrimp ((or dried scallops))",
            "2 lbs daikon radish (, peeled and grated coarsely, yields 1 lb 4 oz (560 g) grated (*Footnote 1))",
            "3 Chinese sausages (, small diced into 1/3” pieces (*Footnote 2))",
            "1 teaspoon sugar",
            "3/4 teaspoon salt",
            "1/2 teaspoon white pepper",
            "1 1/4 cups rice flour",
            "Sliced scallion for garnish ((Optional))",
            "Soy sauce (, for serving (Optional))",
            "Chili garlic sauce ((or Chinese chili crisp), for serving (Optional))",
        ],
        steps: [
            "Soak dried ingredients: Rinse the shiitake mushrooms and dried shrimp separately with tap water and gently rub them to remove any dirt. Place each ingredient into a different bowl. Add warm water to cover. Soak for 15 minutes, or until the ingredients turn soft. Drain thoroughly. Dice mushroom cap into 1/4” pieces and mince the shrimp.",
            "Cook the filling: Add the Chinese sausage into a large nonstick skillet and heat it over medium heat. Cook from a cold pan and turn to medium-low heat once the sausage starts to sizzle. Cook until the sausage is lightly browned and some oil is rendered off, 5 minutes or so. Transfer the sausage to a bowl and reserve the rendered fat. Add the shiitake mushrooms and dried shrimp. Cook and stir until lightly charred. Transfer to the same bowl with the sausage.",
            "Cook the daikon: Add the daikon radish and 1 cup of water into the same skillet. Cook over medium-high heat until simmering. Cover, simmer over medium-low heat until the daikon is soft and translucent, 8 to 10 minutes.",
            "Create the batter: Strain the cooked radish over a colander, pressing out as much liquid as you can into a big bowl or measuring cup. Measure out 1 cup of liquid, pour into a large bowl. Add rice flour, sugar, salt and white pepper. Stir to mix well until forming a very runny batter. Add back the radish and mix again.",
            "Cook the batter: Transfer the radish mixture to a large, clean nonstick skillet. Cook over medium-low heat and stir constantly, until the mixture has slightly thickened. When you stir the mixture, the radish should be able to form a clump without looking too runny. Stir in the cooked filling.",
            "Assemble: Prepare 1 to 2 glass tupperware or baking dishes that can fit into your steamer. You can use two 4.5” x 4.5” (11cm x 11 cm) tupperware dishes to cook two batches. If you have a large wok or steamer, you might be able to fit a 5” x 9” (13cm x 23cm) loaf pan or 7”x7” (20cm x 20cm) baking pan (*Footnote 3). You’ll only need to cook one batch in this case. If you’ll be cooking in two batches, cover the uncooked batter with plastic wrap to prevent it from drying out. Grease the glass tupperware with oil. Transfer the mixture into the tupperware.",
            "Steam: Set up your steamer by adding plenty of water and bringing it to a boil (*Footnote 4). Add the steaming rack with the turnip cake container. Steam over medium-high heat for 50 to 60 minutes until the turnip cake is cooked through. Test the doneness by inserting a knife into the cake and it should come out clean.",
            "Rest: Remove the steamed turnip cake and set it aside to cool. Once the container is no longer hot, transfer it to the fridge. Let the turnip cake set until it has cooled completely. (*Footnote 5)",
            "Release: Use a knife to loosen the edges from the container, then turn the container upside down. The turnip cake should come out in one piece.",
            "Serve: Cut the turnip cake into 1/4” (1 cm) thick pieces. Heat a skillet coated with a thin layer of oil, cook both sides over medium or medium low heat until heated through and the surface turns golden. Garnish with sliced green onion if using. Serve with soy sauce and chili garlic sauce, if desired.",
            "Store: Transfer the steamed turnip cakes (without pan-frying) into an airtight container and store them in the fridge for 2 to 3 days, or in the freezer for up to 1 month. To reheat, thaw the frozen turnip cakes first, and pan fry them before serving.",
        ]
    ),
    "Clay Pot Chicken Rice": RecipeDetail(
        ingredients: [
            "1 cup (230 grams) raw white rice ((short round) (*see footnote 1))",
            "350 milliliters water ((about 1 and 1/2 cup))",
            "2 teaspoons vegetable oil",
            "15 (20 grams / 0.5 ounces) dried shiitake mushrooms ((or 2 cups fresh shiitake mushrooms))",
            "2 (500 grams / 1 pound) bone-in chicken leg-and-thigh portions (, chopped (*see footnote 2) or 4 boneless chicken thighs)",
            "1 tablespoon light soy sauce",
            "1 tablespoon Shaoxing wine ((or Japanese sake))",
            "1 teaspoon ginger (, minced)",
            "1 teaspoon sugar",
            "1/2 teaspoon salt",
            "1 tablespoon cornstarch",
            "3 cloves garlic (, crushed)",
            "4 tablespoons oyster sauce",
            "2 teaspoons sugar",
            "2 cups Chinese broccoli, baby bok choy or chopped broccoli ((Optional))",
        ],
        steps: [
            "Rinse rice a few times and drain. Add water and mix. Let the rice soak for 30 minutes.",
            "Rinse shiitake mushrooms. Place dried shiitake mushrooms in a medium sized bowl and add warm water to cover. Mix a few times so that the mushrooms are coated with water. Set aside and allow to rehydrate for about 20 minutes. (Slice fresh mushroom if you use it instead.)",
            "Combine chicken, light soy sauce, Shaoxing wine, ginger, sugar, and salt in a large bowl. Mix well. Blend in cornstarch and mix well by hand until chicken is evenly coated. Marinate at room temperature.",
            "When the shiitake mushrooms turn soft, carefully rinse mushrooms to remove any dirt. Drain and set aside.",
            "Drain rice and add into a medium sized dutch oven (or clay pot). Add 350 milliliters water. Add Heat over medium high heat. Add 1 teaspoon oil and mix well. Bring to a boil while stirring regularly, just like cooking risotto. Turn to medium heat. Continue to cook and stir, until the water is almost absorbed by the rice, about 5 minutes. Cover and simmer over lowest heat for 10 minutes.",
            "While simmering the rice, cook the chicken and mushrooms. Add the remaining 1 teaspoon of oil into a nonstick skillet over medium high heat until warm. Add chicken and let it cook for 1 minute without stirring. Place the chicken so that you cook the skin side first, until golden brown. Flip and cook the other side until golden brown, and the chicken is half cooked through. Turn to lowest heat. Transfer the chicken to a plate.",
            "(Optional) Use a spoon to transfer the extra oil to a small bowl, until just a thin layer of oil remains in the skillet. If you use skinless chicken, skip this step.",
            "Turn back to medium high heat and add shiitake mushrooms. Stir and cook for 2 minutes. Transfer to a plate and set aside.",
            "When the rice is ready (the water should be fully absorbed by now), arrange chicken, mushrooms, and Chinese broccoli on top of the rice. Cover and continue to simmer for 18-20 minutes (the longer you simmer, the more crispy the rice on the bottom will be). Be careful - you should move as quickly as you can, so the temperature of the rice won’t drop too much.",
            "While the rice is cooking, mix the oyster sauce with the sugar and garlic in a small bowl.",
            "When the rice is done, remove from heat and uncover. Drizzle oyster sauce on top immediately, while the rice is hot, and mix everything well with a spatula. I suggest you scrape the rice from the bottom while the pot is still warm. Otherwise, it will be a bit difficult to scoop out.",
            "Serve hot as a main dish/",
        ]
    ),
    "Century Egg Congee": RecipeDetail(
        ingredients: [
            "1/2 cup (120 ml) uncooked short grain white rice ((or medium grain))",
            "4 cups chicken broth ((*Footnote 1))",
            "2 (about 10 oz. / 300 g) chicken thighs (, frozen cuts work, too, if using Instant Pot )",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "2 teaspoons ginger (, finely minced)",
            "2 century eggs (, diced)",
            "2 green onions (, thinly sliced)",
            "1/4 teaspoon salt (, or to taste)",
            "1 teaspoon toasted sesame oil",
            "Fried wonton wrapper (, for topping (*Footnote 2) (Optional))",
        ],
        steps: [
            "Add the rice into a medium-sized bowl and water to cover. Gently rinse the rice a few times with your fingers and drain. Repeat one to two more times. Drain well.",
            "Combine the rice, stock, chicken, Shaoxing wine, and ginger in your Instant Pot. Set it to cook at high pressure for 15 minutes. If using a pressure cooker, cook over medium heat until pressure is added, then cook at low heat for 15 minutes. Once done, release the pressure naturally for at least 10 minutes before releasing it quickly. Note, do not use fast release right after cooking, because the congee is starchy and might cause the valve to clog.",
            "Once the pressure is released, uncover the pot, remove the chicken and place it onto a plate. Shred it with two forks.",
            "Add the century eggs, green onion, sesame oil (if using), and the shredded chicken to the pot. Stir to mix well. Taste the congee and add salt if needed.",
            "Combine the rice, stock, Shaoxing wine, ginger, and 2 cups of water in a big pot.",
            "Cook over medium-high heat until brought to a simmer. Turn to low heat. Cover the pot and leave a finger-wide gap between the lid and the edge of the pot, to allow more steam to escape and prevent the congee from spilling or boiling over. Simmer for 25 minutes.",
            "Add the chicken. Cook for another 15 minutes. Remove the chicken breast and place it onto a plate.",
            "If the congee has reached the desired texture when the chicken is done, turn off the heat. Transfer the chicken to a plate and shred it with two forks. If you want a stickier and thicker congee, remove the chicken first, then keep cooking the congee for another 15 to 20 minutes. Note, the congee will get quite thick and sticky towards the end. Stay near the pot and stir frequently.",
            "When the congee reaches the desired texture, add back the shredded chicken. Add the century eggs, green onion, and sesame oil (if using) to the pot. Stir to mix well. Taste the congee and add salt to taste if needed.",
            "Transfer the congee into small bowls. Top it with a spoonful of fried wonton wrapper chips, if using. Serve hot.",
        ]
    ),
    "Steamed Egg with Minced Pork": RecipeDetail(
        ingredients: [
            "1 tablespoon oyster sauce",
            "1 teaspoon light soy sauce ((or soy sauce) (*Footnote 1))",
            "1/4 teaspoon sugar",
            "1/2 teaspoon cornstarch",
            "2 tablespoons water",
            "3 large eggs",
            "1/8 teaspoon salt",
            "1 cup warm water",
            "1/2 tablespoon peanut oil ((or vegetable oil))",
            "4 oz (120 g) ground pork ((or ground chicken))",
            "1 green onion (, sliced (reserve some for garnish))",
        ],
        steps: [
            "Combine the oyster sauce, light soy sauce, dark soy sauce (if using) and sugar in a small bowl. Stir to mix well.",
            "Mix the cornstarch with water. Stir thoroughly until the cornstarch is fully dissolved.",
            "Add the eggs and the salt into a large bowl that can fit into your steamer. Pour in warm water. Beat well. Use a fine colander to skim the foam from the top and discard them, so the eggs will result in a very smooth texture.",
            "Prepare the steamer by adding 2” (5 cm) water and bringing it to a boil. Place the bowl of eggs onto the steamer rack and place the steamer rack over the boiling water. (*Footnote 2) Steam covered for 10 to 12 minutes (*Footnote 3). Check on the eggs. If the eggs are not fully set yet, cook for another 2 to 3 minutes, or until the eggs are fully set.",
            "While the eggs are cooking, heat the oil in a medium sized skillet until hot. Add the green onion. Stir a few times to release fragrance. Add the pork. Stir and cut the pork into smaller pieces until the surface is cooked, 2 to 3 minutes.",
            "Pour in the mixed sauce. Stir a few times to mix well.",
            "Stir the cornstarch slurry again to fully dissolve, then pour it onto the pork. Stir a few times until it thickens.",
            "Once the eggs are cooked, top the pork onto the eggs and garnish with reserved green onions. Serve hot.",
        ]
    ),
    "Steamed Ribs in Black Bean Sauce": RecipeDetail(
        ingredients: [
            "1 lb pork baby back ribs (, divided crosswise into 2” long ribs (*Footnote 1), then sliced into single riblet)",
            "1 green onion (, sliced)",
            "1 heaping tablespoon fermented black beans",
            "1 tablespoon minced ginger",
            "3 cloves garlic (, minced)",
            "2 tablespoons vegetable oil",
            "2 teaspoons Shaoxing wine",
            "1 tablespoon oyster sauce",
            "2 teaspoon light soy sauce",
            "2 teaspoons sugar",
            "1/4 teaspoon salt",
            "1 tablespoon cornstarch",
        ],
        steps: [
            "Add the pork ribs into a big bowl and add cold tap water to cover. Soak for 1 hour before cooking, to get rid of any impurities. Once done, rinse the ribs with cold running tap water, drain and pat dry. Transfer to a big bowl. (*Footnote 2)",
            "Combine the fermented black beans, ginger and garlic in a medium-sized heat proof bowl. Heat oil over medium heat in a small skillet until it shimmers. Immediately pour onto the black beans and aromatics. Stir to mix well. Add the Shaoxing wine, oyster sauce, soy sauce, sugar, and salt. Stir to combine.",
            "Combine ribs with the sauce. Add the cornstarch and mix again to coat well. Marinate at room temperature for a minimum of 30 minutes, or in the fridge, up to overnight.",
            "To set up the steamer, use a large plate that has some depth (to hold the sauce) that can fit in your steamer. You will also need to use a wok or a skillet to hold the steamer. In the case of a skillet, you might need a rack to elevate the steamer, so the water underneath doesn’t touch the bottom of the steamer.",
            "Spread the ribs onto the plate with minimum overlap, along with the marinade, and place the plate into the steamer.",
            "Add plenty of water to the wok (or skillet) but not so deep it touches the bottom of the steamer. Bring to a boil over high heat.",
            "Place the steaming rack, covered, onto the wok. You should see steam rising from the top of the steamer. Cook over medium-high heat until the ribs are just cooked through, 20 minutes or so. Test the ribs by cutting through one. The juice should run clear. Cook, covered, checking at 5 minute increments to see if the ribs are done.",
            "Garnish with green onion. Serve hot.",
        ]
    ),
    "Clams in Black Bean Sauce": RecipeDetail(
        ingredients: [
            "2 lbs manila clams",
            "Salt (, for soaking the clams)",
            "2 tablespoons vegetable oil",
            "2 tablespoons Shaoxing Wine",
            "1 tablespoon Oyster Sauce",
            "2 shallots red onion (, thinly sliced)",
            "3 scallions (or 1/2 red onion) (, sliced to 1” (2.5 cm) pieces, white and green parts separated)",
            "1 ” ginger (, julienned)",
            "1 1/2 tablespoon fermented black beans (, rinsed)",
            "2 fresno chilis (or other hot peppers, or 1/2 red pepper) (, seeds removed and minced (*Footnote 1))",
            "Small handful Cilantro (, chopped)",
        ],
        steps: [
            "Place the clams in a large bowl. Add 8 cups cold tap water and 2 tablespoons of salt. Stir to mix well. Soak for 30 minutes to 1 hour before cooking. This process purges the clams of extra grit by mimicking the clams’ natural environment. Right before cooking, transfer the clams to a large colander to drain well.",
            "Mix the Shaoxing wine and oyster sauce in a small bowl. Set aside.",
            "Heat oil in a large pan or wok over medium-high heat until shimmering Add the shallot, scallion whites, ginger and fermented black beans. Stir and cook for 1 minute, until fragrant.",
            "Add the clams and pour the sauce over. Toss to cover the clams in the sauce and aromatics. Cover the pan, and cook until the clams start to open, 1 minute. Uncover the pan. Keep cooking until the clams fully open and the sauce has reduced, 4 to 5 minutes.",
            "Add the scallion greens, chili pepper, and the cilantro. Mix again. Discard any clams that have not opened. Serve as an appetizer or main dish.",
        ]
    ),
    "Crab Roe Tofu": RecipeDetail(
        ingredients: [
            "4 cooked salted duck egg yolks (, smashed)",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "1 tablespoon minced ginger",
            "1/2 cup imitation crab legs (, sliced (optional))",
            "1 cup chicken broth",
            "1 pack soft tofu (, sliced to 1/2” (1 cm) squares)",
            "1/4 cup green peas (, thawed if using frozen)",
            "1/4 teaspoon salt ((or to taste))",
            "2 teaspoons cornstarch",
        ],
        steps: [
            "(Optional) If using uncooked duck egg yolks, bake them first. Heat oven to 300 F (150 C). Line a baking tray with parchment paper. Place the salted duck yolks onto the tray and bake for 10 minutes. Once done, smash the yolks into small pieces.",
            "Heat oil in a medium skillet over medium-high heat until hot. Turn to medium heat. Add the ginger and mashed egg yolks. Stir and cook until bubbling.",
            "Add the crab sticks. Stir and cook for 1 minute.",
            "Pour in the chicken broth, add the tofu, and green peas. Braise over medium-low heat for 2 to 3 minutes. Add the salt. Taste the broth and adjust seasoning by adding more salt if needed.",
            "Meanwhile, mix the cornstarch with 2 tablespoons of water in a small bowl until fully dissolved. Pour into the pan. Stir immediately until the sauce thickens. Transfer to a deep plate and serve hot as a main.",
        ]
    ),
    "Shrimp Toast": RecipeDetail(
        ingredients: [
            "1 lb shrimp (, raw and deveined)",
            "1 large egg white",
            "2 teaspoons ginger (, grated)",
            "1 teaspoon garlic (, grated)",
            "1 teaspoon light soy sauce",
            "1 teaspoon sugar",
            "1/2 teaspoon salt",
            "1/2 teaspoon sesame oil",
            "1/2 teaspoon white pepper",
            "8 slices of white bread",
            "2 tablespoons sesame seeds",
            "6 tablespoons vegetable oil ((if pan frying))",
            "1 green onion (, sliced (for garnish))",
            "6 lemon wedges ((1 lemon’s worth))",
            "Kewpie mayonnaise ((Optional but highly recommended))",
        ],
        steps: [
            "(Option 1) Chop and mix by hand: Take half the shrimp, and cut them into 1 cm long pieces. Mince the other half until it forms a fine paste. Add both into a large bowl. Add the egg white, ginger, garlic, soy, sugar, salt, sesame oil and white pepper to the bowl. Mix forcefully with your hands, occasionally slapping the shrimp mixture down into the bowl. Continue mixing and slapping until the mix takes on a firm texture. (Footnote 1)",
            "(Option 2) Use a blender: Alternatively, you can cut half of the shrimp to 1/2” (6 mm) long pieces, then blend the rest of the shrimp and all the seasonings together in a food processor. Transfer the minced shrimp to a big plate, and mix it with the chopped shrimp.",
            "Cut the crust off the slices of bread. Separate the shrimp mix equally between the bread slices, and spread the shrimp mix evenly over each slice. Sprinkle the shrimp mix very generously with sesame seeds",
            "Use a small pan that can just fit one toast, add 1 to 2 tablespoons of oil, enough to coat the pan. Heat the oil over medium heat until hot, but not smoking hot. Turn to medium-low heat. To add the toast, gently flip the toast onto a spatula, then slowly lower into the pan shrimp side down. Cook for 2 to 3 minutes, until the shrimp side is cooked through. You can tell by observing the edge of the shrimp, it should turn a white-ish pink all the way through.. Flip the toasts and lightly cook the bottom until golden crispy, 1 minute or so. Immediately transfer the toast onto a big plate. Continue cooking the rest of the toasts, adding more oil if needed.",
            "If using an airfryer: Preheat for 5 minutes at 300°F (150°C). Spray the shrimp side of toast with vegetable oil, place into the air fryer tray shrimp side up. Cook for 5 to 6 minutes, until the shrimp is cooked through. Then transfer the toast onto a plate.",
            "If using an oven: Preheat the oven to 350°F (176°C). Spray the shrimp side of toast with vegetable oil, place onto a baking tray shrimp side up. Bake for 6 to 8 minutes, until the shrimp is cooked through.",
            "Once the toasts have cooled enough to handle, cut each toast diagonally. Garnish with scallions. Serve hot or at room temperature with lemon wedges and mayonnaise as an appetizer.",
        ]
    ),
    "Cheung Fun with Shrimp": RecipeDetail(
        ingredients: [
            "1 cup rice flour",
            "1/2 cup wheat starch",
            "1/2 teaspoon salt",
            "3 cups water",
            "1/2 lb shrimp (, peeled and deveined)",
            "2 scallions (, sliced (greens only))",
            "1/2 tablespoon cornstarch",
            "1/2 tablespoon water",
            "1/4 teaspoon salt",
            "1/4 teaspoon sugar",
            "1/4 teaspoon toasted sesame oil",
            "Pinch of white pepper",
            "1 teaspoon vegetable oil",
            "2 scallions (, sliced into 2” (5-cm) pieces (white part only))",
            "2 garlic cloves",
            "5 tablespoons water",
            "2 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "2 tablespoons sugar",
            "1 tablespoon oyster sauce",
            "2 dried shiitake mushrooms",
            "Pinch of white paper",
            "Large wok ((or large deep skillet with cover))",
            "Stainless steel tray (, that can fit into your wok or skillet)",
            "Steaming rack",
            "Bench scraper",
            "Brush",
        ],
        steps: [
            "To make the batter: Combine the rice flour, wheat starch and salt in a large bowl. Mix with a whisk. Pour in the water. Mix until the flour is fully incorporated. Let the flour hydrate while preparing the rest of the ingredients.",
            "To make the filling: Slice the shrimp across the center lengthwise in half, then slice across vertically into 2/3” (1.5 cm) pieces. (*Footnote 1) Transfer the shrimp into a medium bowl, add the scallion greens, cornstarch, water, salt, sugar, sesame oil and white pepper. Mix well and set aside to marinate.",
            "To make the sauce: Heat the oil over medium heat in a small pot until hot. Add the scallions. Let cook until the surface turns lightly golden, 1 to 2 minutes. Then add the garlic. Cook for another minute, until the garlic turns golden brown. Add the water, light and dark soy sauce, sugar, oyster and shiitake mushrooms. Stir to mix. Keep cooking until the sauce is boiling and the sugar has melted. Remove the pot from the stove. Leave with the aromatics in the pot to infuse the flavor, until the sauce has fully cooled. Strain the sauce into a small bowl.",
            "Set up the steamer: In a large wok, place a steaming rack in the center, and place a rectangular stainless steel tray onto the rack, the short side facing you. Make sure the wok lid can cover the wok properly. (Footnote 2) Keep the tray as leveled as you can. Fill the wok with water until just below the rectangular tray. Heat over high heat until the water is boiling. Keep the wok covered to heat up the stainless tray for at least 5 minutes, until very hot.",
            "To make cheung fun: Brush a thin layer of vegetable oil across the tray. Stir the batter before using every time, so the rice flour is fully incorporated. Pour 1/3 cup of batter onto the tray. (*Footnote 3) Use the cup to disperse the batter to cover the tray. You can also use a dish towel to hold the tray, and tilt the tray to evenly spread out the batter. Pour in a little more batter to fully cover the tray, if needed. (*Footnote 4) Cover and cook for 1 minute, until the batter just sets but is not fully cooked.",
            "Add the filling: Place approximately 2 tablespoons worth of filling in a tight row on the cheung fun batter, about a third of the way up, across the short side of the pan facing you. Cover again and steam for an additional two minutes, until the shrimp is fully cooked and the cheung fun is set.",
            "Roll the cheung fun: Use a dish towel to transfer the steaming tray from the wok onto a clean work surface. Keep the wok covered. Using a bench scraper, first gently separate the cheung fun from the tray’s sides. Then use the bench scraper to roll the cheung fun, starting with the side that the shrimp are closest to. Gently lift the cheung fun from the tray’s edge, and roll until a cylinder is formed. (*Footnote 5) If the cheung fun is having trouble lifting off the tray once rolled, gently tip the tray over a plate, so the roll comes off the tray in one piece.",
            "To make the rest cheung fun: Place the stainless tray back into the wok. Reheat for a few minutes until hot before using. Repeat the process until all the batter and shrimp are used up.",
            "To serve: Pour a few spoonfuls of the seasoned soy sauce over the cheung fun. Serve warm as an appetizer or a snack.",
            "Store and reheat: You can keep the cheung fun in an airtight container in the fridge for 1 to 2 days, or in the freezer for a month. Steam to reheat until heated through.",
        ]
    ),
    "Coconut Cocktail Buns": RecipeDetail(
        ingredients: [
            "260 ml (1 cup + 1 tablespoon) milk (, heated to 110°F / 43°C)",
            "1 1/2 teaspoons (6 g) active dry yeast",
            "400 g (2 3/4 cups) bread flour",
            "50 g (1/4 cup) sugar",
            "1 g (1/4 teaspoon) salt",
            "40 g (3 tablespoons) butter (, melted)",
            "1 large egg",
            "40 g (2/3 cup) unsweetened shredded coconut",
            "85 g (6 tablespoons) butter (, melted)",
            "30 g (1/4 cup) dry milk powder",
            "50 g (1/4 cup) sugar",
            "20 g (2 tablespoons) all-purpose flour",
            "1 g (1/4 teaspoon) salt",
            "21 g (1 1/2 tablespoons) unsalted butter (, melt)",
            "18 g (2 tablespoons) all-purpose flour",
            "10 g (1 tablespoon) confectioner’s sugar",
            "1 large egg",
            "1 tablespoon heavy cream ((or milk))",
            "Toasted sesame seeds for garnish ((Optional))",
        ],
        steps: [
            "Combine the warm milk, a pinch of sugar (from the sugar you plan to use in the dough), and dry yeast in a small bowl. Set aside for 5 minutes for the yeast to activate. When it’s ready, the yeast should be bubbly.",
            "Add the flour, sugar, and salt to the bowl of a stand mixer and create a well in the center. Pour the activated yeast, melted butter, and egg to the well. Attach the dough hook. Mix on low until a shaggy dough begins to form. During mixing, stop the mixer and scrape the flour from the wall of the bowl if needed.",
            "Turn the speed to medium (setting 4) and knead for 15 to 20 minutes, until smooth and elastic. Observe the dough during the process. If the dough is too wet and cannot be gathered by the dough hook, sprinkle some flour, 1 teaspoon at a time, until the dough comes together. If it’s too dry, you can add a bit more milk. This is a wet dough. And it’s normal to have a small amount of dough stick to the bottom of the mixing bowl the whole time.",
            "Spray or grease a large bowl with a thin layer of oil (or butter).",
            "Once the dough is ready, gather it into a ball and place in the oiled bowl. Cover with plastic wrap. Rest until doubled, about an hour or so (It can take anywhere from 45 to 90 minutes depending on heat and humidity).",
            "Add all the filling ingredients into a medium-size bowl. Mix with a spatula until crumbly. You should be able to lift and shape the filling using your hands. If it’s too crumbly and dry to form, add a bit of melted butter. Set aside. (*Footnote 1)",
            "Punch the fully risen dough down to deflate it. Transfer it to a clean working surface and knead briefly, until it returns to its original size.",
            "Cut the dough into 12 or 16 even pieces (*Footnote 2). You can use a scale to weigh each piece of dough so the buns will come out perfectly evenly sized. For 12 buns, it’s 65 g per piece or 49 g per piece if making 16 buns. Immediately cover all the dough with plastic wrap to prevent it from drying out.",
            "One piece at a time, pull and pinch the dough together at the top until the dough is rounded. Flip the piece so that the pinched part of the dough faces down on the working surface. Place your palm and fingers over the ball forming a domed cage. Roll the dough in small circular motions while applying light pressure to the dough. Set aside and cover again. Once all the dough is formed, let rest for 10 minutes before assembling.",
            "Line a 9” x 13” baking dish (*Footnote 3) with parchment paper.",
            "Flatten a piece of dough. Roll with a rolling pin into a 3”x5” (7cm x 12cm) oval shape, with thinner sides and a thick center. Scoop 1 heaping tablespoon of filling (if making 12 buns, use 1 scant tablespoon if making 16 buns). Place it in the middle of the dough (*Footnote 4). Bring up all the edges of the dough to gather in the center, around the filling. Pinch all the dough together to seal the bun, forming an oval-shaped bun. Place on a parchment-lined baking tray and cover with plastic, repeat with the remaining buns.",
            "Once all the buns are formed, let rest for another 30 to 40 minutes. While the buns rise, preheat the oven to 350°F (176°C) and prepare the topping.",
            "Combine the topping ingredients in a small bowl. Mix until it forms a smooth paste. Transfer it to a small ziplock bag and press it towards one corner and squeeze out as much air as possible. Seal the bag, and cut 1/4” (6mm) of the tip off.",
            "Make the egg wash just before baking by combining the egg and heavy cream in a small bowl. Stir to mix well.",
            "Once the buns have finished their second rise, brush gently with the egg wash. Pipe two strips across the short ends of the buns. Sprinkle with the sesame seeds if using. Bake for 20 minutes, or until golden brown. Transfer the dish to a wire rack to cool.",
            "Serve the buns warm or at room temperature.",
            "Once the buns have cooled off completely, place them in a ziplock bag or airtight container. Store in the refrigerator for up to 3 days, or in the freezer for up to 3 months.",
            "To reheat the buns, you can either microwave them or bake them in a 300°F (148°C) oven until warmed throughout, 5 minutes for refrigerated buns or 10 to 15 minutes for frozen ones.",
        ]
    ),
    "Hong Kong Egg Tart": RecipeDetail(
        ingredients: [
            "1 1/2 cups all-purpose flour",
            "7 tablespoons chilled unsalted butter (, cubed)",
            "4 tablespoons sugar",
            "1/4 teaspoon salt",
            "1 large egg",
            "1/4 cup ice water",
            "1 cup all-purpose flour",
            "1/3 cup shortening",
            "3 tablespoons unsalted butter (, softened)",
            "5/6 cup hot water",
            "1/4 cup sugar",
            "4 large eggs",
            "Pinch of salt",
            "1/2 cup evaporated milk",
            "4 1/2 ” Fluted pastry cutter ((not required but highly recommended) (*Footnote 1))",
            "Egg tart mold ((Scantily over 2′′ on the base, 3′′ top for the inner edge, and 3.3′′ top for the outer edge))",
        ],
        steps: [
            "Combine the flour and chilled butter in the bowl of a stand mixer. Break the butter into the flour using your fingers until it resembles wet sand.",
            "Add the sugar, salt, egg, and water. Keep mixing together the ingredients with your hand until a wet dough paste comes together.",
            "Knead with the dough hook attachment on setting 4 for 15 minutes, or until the dough is smooth and elastic. (*Footnote 2) Carefully pinch the dough with your fingers and it should form a thin semi-transparent sheet.",
            "Cover the dough with plastic wrap and rest for 15 minutes.",
            "Add the ingredients for the oil dough into a medium-sized bowl.",
            "With a spatula or by hand, mix until a smooth dry paste is formed.",
            "Transfer to a clean working surface. Press into a 6” x 6” (15cm x 15cm) square. Cover with plastic wrap and rest for 10 minutes.",
            "Once both doughs are rested, dust the work surface with flour. Gently knead the water dough for a few times until it forms a 6” (15 cm) smooth round ball.",
            "Use a rolling pin to flatten the dough into four directions about 4” (10 cm), forming a cross shape, leaving the center thicker and shaped like a 6” (15 cm) square. Once done, it should create a 4-sided cross shape. Gently roll the square center a few times to smooth it out.",
            "Place the oil dough in the center aligned with the square. Fold the four sides over the oil dough, one side at a time, so they are overlapping, while using your palm to press the dough gently to press out as many air bubbles as you can. Gently smooth out and pinch the dough together to seal.",
            "Dust the working surface again. Flip the dough over. Gently roll into a 8” x 18” (20cm x 45cm) rectangle.",
            "Fold the short sides of the rectangle inward, leaving about one finger’s width in the middle. Fold the dough in half again along the short side, as if closing a book..",
            "Dust the dough with flour again. Place the short side of the folded dough towards you. Repeat the rolling and folding from the step above.",
            "Cover the folded dough with plastic wrap. Let rest for 15 to 30 minutes at room temperature, or in the refrigerator if the dough feels soggy or loose.",
            "At this stage, the dough can be stored in the refrigerator for a few days for later use. Just make sure it is well wrapped and sealed (you can store the wrapped dough in a ziplock bag or a container).",
            "While the dough is resting, make the filling: Combine the hot water and sugar in a medium-sized bowl. Stir until the sugar is dissolved. Set aside to cool.",
            "Add the eggs to a medium-sized bowl with a pinch of salt. Beat the eggs gently with a fork until it is consistent but not frothy.",
            "Add the evaporated milk to the cooled sugar syrup. Stir to mix well.",
            "Then pour the syrup mixture into the eggs. Gently mix again until everything is well combined.",
            "Strain the egg mixture through a fine mesh strainer (or a regular mesh strainer lined with cheese cloth) into a container or measuring cut that’s convenient for pouring.",
            "Preheat the oven to 325°F (162°C).",
            "Cut the dough into two equal pieces. Wrap the half not in use with plastic wrap and store it in the fridge.",
            "Roll the other half of the dough into a 1/8” (3 mm) thick rectangle.",
            "Using a large, round pastry cutter (5 3/8”, fluted if possible) cut out 8 circles of dough.",
            "Work on one piece of dough at a time. Carefully lift each circle and place it into a pastry cup. Gently drop and tap the cup to help the dough fall into place. Once the dough is mostly in place, gently press the bottom and sides into the cup, until the edges are slightly over the top of the pastry cup. Don’t press the sides too hard as it can damage the layers. Aim to have a small lip over the side of the cup, since the dough shrinks as it cooks.",
            "If you plan to make the full batch, repeat the shaping method to work on the second half of the dough. Meanwhile, cover the assembled pastry cups with plastic wrap to prevent them from drying out.",
            "Right before baking, place the assembled tart shells on a baking tray. Fill each cup with the filling, leaving a 1/4” (0.5 cm) space at the top, about 2 1/2 tablespoons.",
            "Bake the tarts at 325°F(162°C) for 25 to 35 minutes, until the custard is set and does not jiggle when moved.",
            "Let the egg tart cool off a bit before serving. You should serve them as fresh as you can.",
            "Once the egg tarts have cooled completely, you can store them in an airtight container in the fridge for 2 to 3 days. Their taste will diminish the longer you store them, but mine tasted quite nice the next day. During the first two days, the crust will keep quite crispy in the fridge and the filling moist.",
        ]
    ),
    "Pineapple Buns (Bolo Bao)": RecipeDetail(
        ingredients: [
            "60 g butter",
            "2 teaspoons whole milk",
            "1 egg yolk",
            "1/2 teaspoon vanilla extract",
            "140 g sugar",
            "150 g all-purpose flour",
            "1/2 teaspoon baking powder",
            "1/2 teaspoon baking soda",
            "Pinch of salt",
            "180 g whole milk",
            "70 g sugar",
            "7 g active dry yeast",
            "160 g heavy cream",
            "1 large egg",
            "300 g bread flour",
            "225 g all-purpose flour",
            "5 g salt",
            "50 g butter (, softened)",
            "2 egg yolks",
            "2 teaspoons whole milk",
            "1/2 teaspoon sugar",
        ],
        steps: [
            "Heat the butter in the microwave until it melts completely. Once the melted butter is slightly cooled, add the milk, egg yolk, vanila, and sugar. Mix with a spatula until smooth.",
            "Combine the flour, baking powder, and baking soda in another medium-sized bowl. Stir to mix a few times, then transfer it to the bowl with the wet ingredients.",
            "Mix with a spoon or fork until a dough forms. The dough should be very crumbly. Use your hand to press the crumbs together until a thick dough log is formed (see picture in the blog post).",
            "Transfer the dough onto a large piece of plastic wrap and wrap the dough. Continue shaping the dough once wrapped, so it forms a thick cylindrical log, about 2” (5 cm) in diameter.",
            "Transfer the dough to the fridge until ready to use.",
            "Add the milk into a small bowl and warm it to approximately 100-110°F (38°C), about 30 seconds in the microwave. The milk should be warm, just a bit above body temperature. Pour it into the KitchenAid mixing bowl. Add the sugar and yeast. Stir it slightly and let it sit for 5 minutes to activate the yeast. You can tell the yeast has activated when there are bubbles forming in the liquid and a strong yeasty smell.",
            "Add the heavy cream, egg, bread flour, all-purpose flour, and salt into the bowl (add the salt at the end to prevent it from directly touching the yeast).",
            "Install the dough hook on your KitchenAid. Mix at setting 2, until a dough forms, about 2 minutes.",
            "Turn off the mixer. Add the butter to the dough. Use a spatula to smear the butter into the dough to prevent it from splashing. Turn the mixer to setting 6. Knead for another 14 minutes, until the dough is smooth and stretchable. During mixing, turn off the mixer and scrape the sides as needed to make sure all the butter is incorporated. Test the dough by pulling a piece of it using both of your hands. It should stretch into a very thin and translucent sheet.",
            "Form the dough into a tight ball by pulling its sides to the bottom, then place back in the mixing bowl. Cover the top of the bowl loosely with plastic wrap and place it in a warm and humid part of your home. Allow to rise until it double in size, about 1 hour.",
            "Line a large baking sheet with parchment paper.",
            "Once the dough is rested, punch the dough softly to push the air out. Place the dough onto an unfloured working surface and knead it a few times. Use a bench scraper or a knife to cut the dough in half, then halve it again into four pieces, and cut each piece into four even pieces, so you get 16 pieces in total. For a more accurate result, you can weigh the dough so each piece is 62 to 63 g (2.1 to 2.2 oz).",
            "Loosely cover all the dough pieces with plastic wrap and work on the dough pieces one at a time.",
            "Pinch the ends of a dough ball into its bottom and place the pinched side down. Place your hand over the ball, forming a cage with your fingers and working the ball in a circular motion, applying light pressure with all of your fingers, until the ball is well rounded.",
            "Place the dough ball onto the lined baking sheet. Repeat with the rest of the dough balls. Make sure there is 2” (5 cm) of space between each ball. Cover the dough balls with plastic wrap while you form the rest, to prevent the dough from drying out.",
            "Once done, make sure the whole tray is loosely covered with plastic wrap. Place it in a warm and humid place. Let it rise for another 30 to 45 minutes, until the size doubles again.",
            "Make the egg wash by combining the yolk, milk, and sugar in a small bowl. Whisk together until everything is combined.",
            "Cover with plastic and place in the fridge. Chilling the egg wash will make it slightly thicker so it will stick better when brushed on the dough.",
            "Once the topping is chilled, unwrap it. Use a knife to slice off the uneven ends and discard them. Carve marks on the dough so you can slice the log into 16 even pieces (see the blog post for instructional pictures). Then slice the dough accordingly. If the dough is too hard to slice, rest it on the kitchen counter for 10 to 15 minutes to let it soften before cutting.",
            "Place each piece between two pieces of plastic wrap. Use a rolling pin to flatten the dough without cracking it, until it forms a round disk that is about 2.5” (6 cm) in diameter and 1/4” (5 mm) thick. The dough will be very crumbly and the ends might crack a bit (it’s totally OK!). If you find the dough too difficult to roll out without cracking, you can use your hand to lightly flatten it instead of rolling it. (*Footnote 1)",
            "Place the rolled/pressed topping disks onto a large sheet of plastic wrap using a thin spatula (you can also stack them together by placing plastic wrap or parchment paper between each piece of dough). Cover with plastic wrap until you’re ready to assemble the buns. (*Footnote 2)",
            "Preheat the oven to 350° F (176° C).",
            "Once the bread dough has risen again, remove the plastic wrap. Gently place the topping dough disks onto the bread dough rolls.",
            "Brush all the buns with egg wash. Allow the egg to dry slightly. Then brush them again for a second time to get the beautiful yellow color.",
            "Bake for 15 to 17 minutes, until the top is golden yellow and the bottom is slightly browned.",
            "Let the buns rest in the pan for 5 minutes, then transfer them onto a cooling rack.",
            "Serve warm or at room temperature.",
        ]
    ),
    "Bird's Nest": RecipeDetail(
        ingredients: [
            "4 pieces bird nest (1 oz. / 28 grams)",
            "8 Asian pears",
            "4 tablespoons goji berries",
            "8 pieces small rock sugar (or syrup)",
            "1 papaya (cubed)",
            "Syrup to taste",
        ],
        steps: [
            "Add bird nest to a large bowl and 8 cups water to cover. Soak for a minimum of 6 hours or up to overnight. Gently rinse the nest with your fingers during the soaking and change the water once. If you see small feathers attached to the bird nest, carefully remove them with tweezers and discard them.",
            "Once the nest is soaked, gently tear it into smaller long pieces along the threads.",
            "Cut each Asian pear into two pieces by cutting through the core about 1/3 of the way from the top. Use the larger piece as a bowl and the smaller piece as the lid. Use a spoon or melon scoop to scoop out the inner part of the bigger piece and make the pear into a small bowl. You can cut a zig-zag pattern if you like. It won’t affect the cooking.",
            "Divide up the bird nest and fill 2/3 of each pear with the nest. Add filtered water to cover, a few pieces of goji berries, and 1 piece rock sugar. Cover the pear with the lid you cut off earlier.",
            "Place the pear in a small bowl and transfer the bowl into a big skillet. Add water until it reaches halfway up the bowl.",
            "Cover the skillet and cook over medium high heat, until water reaches a boil and steam comes from the skillet. Turn to medium heat and let braise for 40 minutes.",
            "Once the bird nests are cooked, transfer the small bowls onto the kitchen counter with your oven mitts on. Let cool until it can be handled by hand.",
            "You can further sweeten it with syrup or honey, if needed. Serve the bird nest warm or at room temperature as a dessert.",
            "Add cubed papaya into 4 medium-sized bowls, about 1/2 cup papaya per bowl. Divide bird nest into 4 portions and add into the bowls on top of the papaya. Add filtered water to cover. Place a small plate on top of each bowl as a cover.",
            "Transfer the bowls into a big skillet and add water until it reaches halfway up the bowls.",
            "Cover the skillet and cook over medium high heat, until water reaches a boil and steam comes from the skillet. Turn to medium heat and let braise for 40 minutes.",
            "Once the bird nests are cooked, transfer the small bowls onto the kitchen counter with your oven mitts on.",
            "Once completely cooled, transfer the bird nest into serving bowls and discard the papaya and the liquid. Add coconut milk into bird nest and sweeten with syrup according to your taste. Serve at room temperature as a dessert.",
        ]
    ),
    "Wife’s Cake": RecipeDetail(
        ingredients: [
            "75 g glutinous rice flour",
            "25 g unsweetened shredded coconut ((or desiccated coconut))",
            "25 g toasted sesame seeds",
            "1 wedge winter melon ((yields 150 g puree))",
            "36 g water",
            "30 g unrefined coconut oil",
            "75 g sugar",
            "1/4 teaspoon sea salt",
            "1/2 teaspoon ground ginger",
            "90 g all-purpose flour",
            "1 tablespoon powdered sugar",
            "1/4 teaspoon salt",
            "35 g unsalted butter (, softened)",
            "40 ml ice water",
            "110 g cake flour",
            "55 g lard ((or shortening))",
            "2 egg yolks",
            "Toasted sesame seeds ((for garnish))",
        ],
        steps: [
            "Add the glutinous rice flour into a cold pan and heat over medium heat. Stir and cook the flour until the color turns off-white and you can smell some nuttiness coming from the flour, 5 minutes or so.",
            "Add the shredded coconut and sesame seeds into a grinder or using a mortar and pestle, coarsely grind both.",
            "Peel the winter melon by removing the tough skin by 1/4” (4mm) using a knife, until no green skin is visible on the flesh. Remove the seeds using a knife by cutting off the soft part between the seeds and the flesh. Chop the melon into 1” (2.5 cm) pieces to yield slightly over 150g, then puree in a blender until smooth.",
            "Weigh 150g of the purée into a medium saucepan and add the 36 g water, 30 g coconut oil, 75 g sugar, and 1/4 teaspoon salt. Bring to a simmer over medium heat, stirring frequently, about 5 minutes, or until slightly thickened.",
            "Add the shredded coconut and sesame seed mixture and ground ginger, and continue to cook until most of the liquid has evaporated.",
            "Turn to low heat. Add in toasted glutinous rice flour in several rounds, stirring very thoroughly by scraping the pan between additions. Cook and stir for another 1 to 2 minutes until the mixture is very thick and translucent. Transfer to a bowl, cover with plastic wrap pressed directly on the surface to prevent skin from forming, let cool completely.",
            "Once cool, divide filling into 8 equal portions, rolling paste into balls. Cover and set aside.",
            "Sift the 90 g all-purpose flour, powdered sugar, and salt into the bowl of a stand mixer. Add the butter and ice water. Mix with a spatula until a rough dough forms. Place the bowl in the mixer with the dough hook attachment. Drape a piece of the dough over the hook. Turn the mixer to setting 4 and knead until smooth and elastic, about 10 minutes. Depending on the size of your mixer, it may be necessary to stop the kneading occasionally and lift the dough over the hook (*Footnote 1). You can also hand knead the dough. To test the dough, stretch it into a thin semi transparent sheet and it should hold well. Knead a bit longer, if needed. Once done, cover the dough and rest for 10 minutes.",
            "Combine the 110 g cake flour and shortening in a medium-sized bowl. Mix and press it together using your hands, until the dough forms. Further shape and knead it on a working surface until uniform and smooth. Cover and rest for 5 minutes.",
            "Divide the water dough into 8 even pieces. Work on one dough at a time, use your hands to pull the dough towards the center, until it forms a ball. Pinch to seal the end and set aside. Always cover the dough with plastic wrap.",
            "Divide the oil dough into 8 even pieces. Form each piece into a dough ball using your hands, covering them as you go.",
            "Flatten a ball of water dough with your palm and spread it with your fingers so that the center is thicker than the edges, about 3 1/4” (8 cm) wide. Place a ball of oil dough in the center. Lift the edges of the water dough over the oil dough to wrap it and pinch at the top to seal it. Shape the ball to smooth it out. Set it aside and cover it. Repeat with all pieces of dough.",
            "Preheat the oven to 350°F (176°C).",
            "Take a formed ball, sealed-side down, and flatten it with your palm. Gently roll it into a 5” (12.5 cm) long strip. Flip it over so it’s seam-side up. Starting from the short side, roll it into a thick jelly roll. Turn the roll 90° and flatten it with your hand. Again roll it into a 5”(12.5 cm) strip and then into a jelly roll. Cover and set aside. Repeat with the remaining balls.",
            "Beginning with the first roll you made, take a roll and press into the middle so the swirled ends are pressed out. Then fold the swirled ends into the center and press them down so that a flat disc is formed. Roll this disc out so that it is 4” (10 cm) in diameter. Place the filling in the center. Lift and stretch the dough over the paste ball to cover completely, and pinch to seal. Roll between your palms to smooth it out. Flatten gently with your palm. Then roll into a flat disk that is about 3 1/4” (8 cm) in diameter. Repeat with all the dough and cover all the dough pieces with plastic wrap as you do so. (*Footnote 5)",
            "Line a baking tray with parchment paper. Place the pastries on it, at least 1” (2.5) apart. Gently slice two slits on the top.",
            "Lightly beat the yolk. Brush a thin layer of the egg wash onto the tops of the pastries. Wait 5 minutes and brush with a second layer of yolk.",
            "Wet your fingertip with water and dip it into the sesame seeds so the seeds stick to your finger. Tap the top of each pastry to decorate.",
            "Bake at 350°F (176°C) for 15 to 20 minutes, until the egg wash turns golden and the pastries are cooked through and flaky. Once done, remove the baking sheet from the oven and let cool for 15 minutes before serving.",
            "After completely cooling, you can store the baked cakes in an airtight container at room temperature for up to 2 days, in the fridge for up to 2 weeks, or in the freezer for 3 months.",
        ]
    ),
    "Braised Beef Tongue": RecipeDetail(
        ingredients: [
            "1 beef tongue",
            "1/2 big onion (, sliced (White or Yellow))",
            "5 to 8 cloves of garlic",
            "1-2 bay leaves",
            "Sea salt to taste",
        ],
        steps: [
            "Put beef tongue, onion, garlic and bay leaves in a slow cooker and add enough water to cover tongue. Cook overnight on low. You can also gently boil it on the stovetop for 2 hours to 3 hours, until the beef tongue turns very tender.",
            "When tongue is cool enough to handle, peel off and discard rough tongue skin.",
            "Cut tongue in 1/2-inch slices across grain then into 1/2-inch cubes. It can also be shredded or sliced, depend on the dish you cook. If you won’t serve the tongue soon, store in an airtight container or ziplock bag in the fridge up to 5 days.",
            "When ready to serve, heat oil in a large nonstick or cast iron skillet set over medium-high heat until shimmering. Add tongue pieces and cook, stirring occasionally, until tongue is well browned on all sides, 2 to 3 minutes total. Season to taste with salt and pepper.",
        ]
    ),
    "Pork Lettuce Wrap": RecipeDetail(
        ingredients: [
            "2 tablespoons oyster sauce",
            "1 tablespoon hoisin sauce",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 teaspoon dark soy sauce ((or soy sauce))",
            "1/4 teaspoon black pepper",
            "1 1/2 tablespoon peanut oil",
            "1 lb (450 g) ground pork",
            "1 white onion (, minced)",
            "2 cloves garlic (, minced)",
            "1 tablespoon miced ginger (, minced)",
            "1 can (100g / 3.5oz) water chestnuts (, small diced)",
            "1 red pepper (, small diced)",
            "10 to 12 lettuce leaves ((Iceberg, Bibb, Butterhead, or Romaine))",
            "1/4 cup roasted peanuts (, chopped)",
            "green onions (, thinly sliced)",
            "Chili garlic sauce ((or your favorite hot sauce))",
        ],
        steps: [
            "For the sauce: Add all the sauce ingredients into a small bowl and stir to mix well.",
            "To make the filling: Heat 1 tablespoon of oil in a large skillet over medium-high heat until hot. Add the ground pork and spread into an even layer. Cook without touching until the bottom is browned, 2 to 3 minutes. Flip the pork and chop into smaller pieces. Cook until the other side turns golden. Move the pork to one side of the pan.",
            "Add the remaining 1/2 tablespoon of oil, onion, garlic and ginger to the other side of the pan. Stir and cook for 2 minutes. Then mix everything together.",
            "Add the water chestnut and the red pepper. Stir and cook for another 2 minutes, until the vegetables soften. Transfer everything to a large bowl.",
            "To serve and eat: Add a spoonful of the pork filling onto a lettuce leaf. Add some roasted peanuts and green onions. Drizzle a bit of chili garlic sauce or your favorite hot sauce for a spicy taste, if desired. Enjoy as an appetizer.",
        ]
    ),
    "XO Sauce": RecipeDetail(
        ingredients: [
            "2 oz dried scallops",
            "2 oz dried shrimp",
            "1/2 cup + 2 tablespoons Shaoxing wine ((or dry sherry))",
            "1.5 oz dry cured ham (, minced (Jinhua or Yunnan style if possible, or prosciutto) (*Footnote 1))",
            "2 large shallots (, minced)",
            "8 cloves garlic (, minced)",
            "2 Thai bird’s eye chilis (, minced)",
            "1 1/4 cups canola oil ((*Footnote 2))",
            "1 tablespoon sugar",
            "1 1/2 tablespoons oyster sauce",
            "1 teaspoon chicken bouillon powder",
            "1 tablespoon Chinese chili flakes",
        ],
        steps: [
            "Rinse the scallops and shrimp with running water to remove any dust. Place them in separate heatproof bowls. Add a tablespoon of Shaoxing wine and 1/2 cup warm water to each bowl. Let soak for at least 1 hour or overnight in the fridge. (*Footnote 3)",
            "Drain the soaked seafood, reserving the shrimp soaking liquid. Remove the hard feet on the side of the scallops (adductor muscle) (*Footnote 4). Add the scallops and shrimp into a small food processor and pulse until the scallops are shredded and the shrimp are minced. (*Footnote 5)",
            "Prepare a large heatproof bowl (enough to hold 2 cups of oil) and layer it with a strainer.",
            "Heat a heavy-bottomed pot or high-walled pan (*Footnote 5) over medium heat and add the oil.",
            "Once the oil has reached 200 to 250°F (94 to 120°C), add the shallots and garlic. Cook, stirring frequently, until they just start to show color, about 12 minutes.",
            "Add the minced chilis. Fry for another 5 minutes, or until the aromatics turn golden and crispy. (*Footnote 6)",
            "Strain the aromatics using the prepared bowl with the strainer. Pour the oil back into the pot and set aside the cooked aromatics.",
            "Heat the oil again to 200 to 250°F (94 to 120°C). Add the shredded scallops. Cook, stirring constantly, for about 10 minutes, until they just start to brown.",
            "Add the minced shrimp and continue to fry for 5 minutes.",
            "Add the minced ham. Cook and stir until everything turns a deep golden brown, 10 more minutes or so.",
            "Return the fried aromatics to the pot and stir to mix well.",
            "Pour in the Shaoxing wine. Add 2 tablespoons of the shrimp soaking liquid along with the sugar, oyster sauce, chicken powder, and chili flakes. Cook for another 5 minutes, or until the ingredients turn a dark brown color and the scallops are withered.",
            "Remove the skillet from the stove. Transfer everything to a heat-proof container.",
            "Once the sauce has cooled completely, you can store it in an airtight container or a jar in the fridge for about a month, or 3 months in the freezer.",
        ]
    ),
    "XO Fried Rice": RecipeDetail(
        ingredients: [
            "1 1/2 tablespoons peanut oil ((or vegetable oil))",
            "1 yellow onion (, diced)",
            "2 cups char siu pork (, diced (about 1 lb / 450 g))",
            "4 green onions (, sliced, whites &amp; greens separated)",
            "1 ” ginger (, minced)",
            "2 cloves garlic (, minced)",
            "4 cups leftover rice",
            "4 tablespoons homemade XO sauce ((or store-bought XO sauce))",
            "4 eggs (, beaten with a pinch of salt)",
        ],
        steps: [
            "Heat 1 tablespoon of oil in a large skillet over high heat until hot. Add the onion and char siu. Cook and stir until they both begin to caramelize, 1 to 2 minutes.",
            "Add the white part of the green onion, ginger, and garlic. Stir for another 30 seconds.",
            "Add the rice. Cook, stirring occasionally, until the rice begins to crackle, 2 minutes or so.",
            "Pour in the XO sauce. Stir until everything is coated and the XO sauce is fully absorbed.",
            "Move everything to one side of the pan and add the remaining 1/2 tablespoon of oil to the other side. Add the egg to the oil. Wait until the bottom is set, then scramble for 20 to 30 seconds, so that the eggs are mostly cooked through, but there is some remaining runny egg. Chop the egg into the fried rice using a spatula.",
            "Add the remaining green onion. Stir everything together and cook for another 30 seconds. Taste the rice carefully and adjust the seasoning by adding a pinch of salt, if needed.",
            "Serve hot as a main or side dish.",
        ]
    ),
    "XO Noodles": RecipeDetail(
        ingredients: [
            "12 oz (340 g) shrimp (, peeled and deveined)",
            "1/2 teaspoon Shaoxing wine ((or dry sherry))",
            "1/4 teaspoon salt",
            "1/8 teaspoon ground white pepper",
            "1/2 teaspoon cornstarch",
            "2 tablespoons XO sauce",
            "1 tablespoon dark soy sauce",
            "2 teaspoons light soy sauce",
            "1/8 teaspoon ground white pepper",
            "8 oz (225 g) fresh Hong Kong Pan Fry noodles ((or thin egg noodles))",
            "2 tablespoons vegetable oil",
            "2 cloves garlic (, sliced)",
            "4 yu choy (or baby bok choy) (, greens and stems separated and sliced on the bias)",
            "1 carrot (, thinly sliced to strips)",
        ],
        steps: [
            "Combine the shrimp and the marinade ingredients in a medium-sized bowl. Stir to mix well. Set aside for 10 minutes.",
            "Mix the sauce ingredients together in a small bowl and set aside.",
            "In a large nonstick skillet bring an inch of water to a boil over medium-high heat. Add the noodles and cook for 30 seconds (or according to the packaging). Drain and rinse the noodles with cold water to stop cooking. Add a drizzle of oil, toss, and set aside.",
            "In the same pan, add 1 tablespoon of oil and heat over medium-high heat. Once the oil is hot, add the garlic. Cook until the garlic is fragrant, 30 seconds or so.",
            "Add the shrimp and brown both sides, about 1 minute per side, or until the shrimp curl up. Transfer the shrimp to a large plate and set aside.",
            "Add the yu choy stems and carrots. Let everything cook without stirring for 30 seconds, then stir and cook for another minute.",
            "Add the noodles and yu choy greens to the pan along with another tablespoon of oil. Toss the noodles with a pair of tongs to incorporate all the ingredients, 1 to 2 minutes.",
            "Pour in the sauce and add back the cooked shrimp. Stir and toss to coat everything evenly. The veggies should be tender but still a bit crunchy. Carefully taste the noodles and cook for another minute if needed. You can adjust the seasoning by adding a bit more XO sauce.",
            "Transfer everything to serving plates. Serve hot as a main dish or a side dish.",
        ]
    ),
    "Yangzhou Fried Rice": RecipeDetail(
        ingredients: [
            "2 1/2 tablespoons peanut oil ((or vegetable oil))",
            "4 oz char siu pork (, diced (or ham, or sausage))",
            "6 oz shrimp (, peeled and deveined (*Footnote 1))",
            "1/2 cup frozen vegetable mix (, thawed (I used frozen green peas))",
            "4 cups leftover cooked white rice ((*Footnote 2))",
            "1 tablespoon light soy sauce",
            "2 large eggs (, beaten)",
            "1/2 teaspoon salt ((or to taste))",
            "1/4 teaspoon ground white pepper",
            "4 green onions (, chopped)",
        ],
        steps: [
            "Heat 1/2 tablespoon of oil in a wok or a nonstick skillet over medium-high heat until hot. Swirl to coat the bottom of the pan with the oil. Add the ham and shrimp. Cook for 30 seconds without disturbing. Stir and cook until the shrimp turn white. Immediately transfer the ham and shrimp to a separate plate.",
            "Add 1 tablespoon of oil and the rice. Stir and cook for 1 minute to coat the rice with oil. Pour in the soy sauce. Stir and cook until the soy sauce is evenly distributed. And the grains are separated.",
            "Move the rice to one side of the pan and add oil and the beaten eggs to the other side. Let cook for 30 seconds until the bottom is just set. Stir gently to scramble the eggs, then mix the rice with the eggs. Stir and cook until the eggs are separated into small pieces, 1 to 2 minutes.",
            "Add the vegetable mix and green onion. Sprinkle salt and white pepper. Stir and cook for another minute.",
            "Return the cooked shrimp and char siu. Give it a final mix. Turn to low heat, carefully taste the rice and adjust seasoning if necessary. Transfer to serving bowls and serve hot as a side dish, or a light main dish.",
        ]
    ),
    "Soy Sauce Eggs": RecipeDetail(
        ingredients: [
            "6 to 12 large Pete and Gerry’s Organic Eggs ((*Footnote 1))",
            "3/4 cup soy sauce",
            "2 tablespoons brown sugar ((or white sugar))",
            "1 tablespoon rice vinegar",
            "4 dried chilis ((or 2 jalapeno peppers) (*Footnote 2))",
            "2 star anise pods",
            "3 to 4 cups water ((*Footnote 3))",
        ],
        steps: [
            "Combine all the marinade ingredients in a small pot. Bring it to a boil, then simmer for 5 minutes. Remove the pot from the stove and let it cool.",
            "Prepare a pot that is large enough to hold all the eggs without overlapping them. Add just enough water to cover the eggs. Heat over medium-high heat until boiling. Lower the heat to medium.",
            "Transfer the eggs to a ladle or a colander. Slowly lower the eggs into the water to prevent them from cracking. Adjust the heat so the water maintains a slow boil.",
            "Bring a small pot with just enough water to cover your 6 eggs to a boil.",
            "(Optional) If you wish to keep the egg yolks in the center of the eggs, stir the water in a consistent circle for the first minute of cooking.",
            "Cook for 6 minutes for runny yolks, 8 minutes for semi-firm, or 11 minutes for hard boiled.",
            "While the eggs are boiling, prepare an ice bath (or a big bowl of cold water if you don’t have ice).",
            "When the eggs are done cooking, run cold water over them for 30 seconds. Add the eggs to the ice bath and let them cool completely, about 10 minutes.",
            "Once the marinade is cooled until no longer hot to touch, transfer it into a tall container that is large enough to hold 8 cups of water (*Footnote 4).",
            "Carefully crack the egg shells by tapping them with the back of a spoon or by gently rolling them on the counter. Starting from the bottom, begin peeling each egg, dipping it back into the water as needed to help loosen the shell. Make sure to peel off the egg membrane completely, so the egg will marinate evenly. Once peeled, place the eggs into the marinade container.",
            "Marinate the eggs in the fridge for a minimum of 6 hours before serving. If you want to serve the eggs sooner, simply drizzle some extra marinade onto the cut eggs. Store the eggs in the marinade in the fridge for up to a week.",
            "You can serve the eggs over steamed rice or boiled noodles, drizzled with extra marinade and some homemade chili oil (if you wish). You can also make noodle soup by combining some marinade with hot noodle boiling water. Enjoy!",
        ]
    ),
    "Chinese BBQ Ribs": RecipeDetail(
        ingredients: [
            "1 rack pork ribs (2.5 to 4 lbs) ((the one I used was about 3 lbs / 1.4 kg))",
            "1/2 tablespoon salt",
            "1 1/2 teaspoon gochugaru ((or chile powder) (*Footnote 1))",
            "1/2 teaspoon white pepper",
            "1/2 teaspoon five spice powder",
            "3 tablespoons brown sugar",
            "2 tablespoons oyster sauce",
            "2 tablespoons hoisin sauce",
            "2 tablespoons honey",
            "1 tablespoon soy sauce",
            "1 teaspoon salt",
            "2 teaspoons rice vinegar",
            "2 teaspoons Shaoxing wine ((or dry sherry))",
            "1 teaspoon grated ginger",
            "1 clove garlic (, grated)",
            "1/2 teaspoon 5 spice powder",
            "6 to 10 drops red food coloring ((optional))",
        ],
        steps: [
            "(Optional) Remove the membrane from the back of the ribs by loosening one end with a knife, and then tearing it away.",
            "Prepare a large piece of foil (at least 2” / 5 cm bigger than the ribs on all sides) to layer over a baking sheet. Place the ribs back side up onto the foil.",
            "Combine the dry rub ingredients in a small bowl and mix well. Sprinkle evenly over the back of the ribs and rub in. Flip the ribs and sprinkle on the top side, rub in the spice again. Set aside to marinate briefly while preheating the oven to 275°F (135°C).",
            "Combine the sauce ingredients in a medium-sized bowl. Mix well.",
            "Once the oven is heated, brush a thin layer of sauce all over the ribs.",
            "Place another piece of foil over the top. Crimp the bottom foil over the top foil and fold a few times to create a sealed parcel.",
            "Place the ribs in the oven and bake for 2 to 3 hours depending on their size (*Footnote 2). Once done, you can use a thermometer or a fork to poke through the foil to test the doneness. The meat should feel very tender or read at least 160°F/71°C.",
            "While cooking, prepare a baking tray lined with foil (or parchment paper) and a rack on top.",
            "Remove the ribs from the oven and turn the heat up to 450°F (230°C).",
            "Carefully open the parcel and move the ribs to the prepared baking tray. You might need to use 2 spatulas to help with this step because the ribs are extremely tender and might fall apart.",
            "Generously brush the top and back of the ribs with the sauce, leaving a few tablespoons for after cooking.",
            "Return the ribs to the oven and bake until beginning to char, 10 to 15 minutes. Check on the ribs every 5 minutes to prevent them from burning.",
            "Remove the ribs from the oven and brush with a thin layer of sauce. Let cool for 10 minutes then slice the ribs and serve hot with the remaining sauce.",
        ]
    ),
    "Sheng Jian Bao": RecipeDetail(
        ingredients: [
            "1 1/2 tablespoons ginger (, minced)",
            "1/4 cup hot water",
            "250 g (1 2/3 cup) all-purpose flour",
            "50 g (1/3 cup + 1 tablespoon) cornstarch",
            "4 g (3/4 teaspoon) instant yeast",
            "5 g (1 teaspoon) sugar",
            "150 g (2/3 cup) warm water ((*Footnote 1))",
            "15 g (1 tablespoon) vegetable oil",
            "8 oz (227 g) ground pork ((*Footnote 2))",
            "1 1/2 teaspoons light soy sauce",
            "1/2 teaspoon dark soy sauce ((or soy sauce) (*Footnote 3))",
            "2 teaspoons Shaoxing wine",
            "1/2 teaspoon salt",
            "1/4 teaspoon sugar",
            "1/4 teaspoon ground white pepper",
            "4 green onions (, sliced)",
            "1 tablespoon toasted sesame oil",
            "4 tablespoons vegetable oil",
            "1/2 cup hot water (, separated)",
            "Chopped green onions (, for garnish (Optional))",
            "Roasted sesame seeds (, for garnish (Optional))",
        ],
        steps: [
            "Combine the minced ginger and hot water in a small bowl. Stir to mix well and set aside.",
            "In a large tall plate or a big bowl, combine the all-purpose flour, cornstarch, instant yeast and sugar. Stir to mix well.",
            "Slowly pour in the warm water, a few tablespoons at a time, and mix with a pair of chopsticks (or a fork). Once all the water has been added, keep mixing and scrape off the dry flour on the side of the bowl, until it forms many small dough flakes.",
            "Pour in the vegetable oil. Keep mixing with the chopsticks until the oil is absorbed.",
            "Start kneading by hand while further incorporating the dry flour, until there’s no dry flour left in the bowl.",
            "Transfer the dough onto a working surface. Knead for 15 to 20 minutes, until the dough is quite smooth and elastic and there’s no dry flour left in the bowl. It’s OK if there’s some unevenness in the dough, which will smooth out after resting. The dough should be quite tough and not sticky to the touch. Cover and seal the bowl with plastic wrap. Let rest until it doubles in size, 1 hour or so.",
            "Add the ginger water, light and dark soy sauce, Shaoxing wine, salt, sugar, and white pepper to the ground pork in a large bowl. Beat with a pair of chopsticks or a wooden spatula in a circular motion, until all the liquid is absorbed and the meat is sticky. This process might take a few minutes. (*Footnote 4)",
            "Add the green onions and sesame oil. Mix until they are incorporated. Cover the bowl with plastic wrap. Store in the fridge until ready to use.",
            "When the dough has rested, transfer to a work surface and punch it down. Knead for 1 minute to deflate the air out completely, then form it back into a ball.",
            "Cut the dough in half. Wrap half of the dough in plastic wrap and store in the fridge while working on the other half.",
            "Poke a hole in the center of the dough you’re working with. Stretch the dough into a large oval by running your fingers along the inside of the hole in a circular motion. Once the diameter of the dough is about 1” (2.5 cm), tear apart the ring so it creates a long, thin strip.",
            "Cut the dough strip into 12 even pieces by cutting it in half, then further cut each half into 6 pieces. Gently use a circular motion to round up each dough piece then flatten it with your palm. Cover them with plastic wrap to prevent drying out.",
            "Work on one piece of dough at a time - take one dough piece and place in front of you. Roll it with a rolling pin in one hand, using the other hand to rotate the dough while rolling, until the diameter reaches 5” (13 cm). You should keep the edges thinner than the center, so the wrapper of the bun will be even once you make the pleats.",
            "Place the rolled dough in your palm and add 1 tablespoon of filling in the center.",
            "Start wrapping the bun by folding and pinching the edge over itself, in one direction, until it is almost sealed. Then rotate and pinch the top of the pleats to fully seal the bun. (View my video for more details)",
            "Repeat with the remaining dough pieces to wrap all the buns. Keep the wrapped buns under a piece of plastic wrap to prevent drying out. Once done wrapping, let rest for 10 minutes. Once rested, you should cook the buns immediately. You can store the wrapped buns in a sealed container in the fridge for up to 1 hour before cooking.",
            "Repeat the wrapping steps to wrap the other half of the dough.",
            "Add 2 tablespoons of oil and carefully place 12 wrapped buns into a 9” or 10” skillet. Heat over medium-high heat until hot. Turn to medium heat. Cook, uncovered, for 3 minutes, until the bottoms are lightly browned.",
            "Pour about 1/4 cup hot water into the pan, just enough to cover the buns halfway up. Cover the pan and cook over medium heat for about 8 minutes, until the water is completely evaporated.",
            "Turn the heat to medium-low and cook for another 2 to 3 minutes. Turn the heat off and remove the pan from the stove. Let the buns rest with the lid on for an additional 2 minutes. Remove the lid and transfer to a plate. Repeat the steps to cook the rest of the buns.",
            "Serve hot immediately. (*Footnote 5) Or you can store the cooked buns in an airtight container in the fridge for up to 4 days or in the freezer for up to 3 months.",
        ]
    ),
    "Steamed Chicken": RecipeDetail(
        ingredients: [
            "2 (about 12 oz / 350 g) chicken thighs (, cut to bite-size pieces (*Footnote 1))",
            "1 tablespoon oyster sauce",
            "2 teaspoons Shaoxing wine",
            "1 teaspoon light soy sauce",
            "1/2 thumb ginger (, julienned)",
            "1 teaspoon peanut oil ((vegetable oil, or sesame oil) (*Footnote 2))",
            "2 teaspoons cornstarch",
            "1/4 teaspoon salt",
            "1/4 cup dried lily flowers (, soaked and drained)",
            "2 tablespoons dried wood ear mushrooms (, soaked and drained)",
            "1/2 tablespoon goji berries",
            "green onions (, sliced)",
        ],
        steps: [
            "Add all the marinating ingredients in a large bowl. Mix thoroughly with your hands. Let marinate for a minimum of 30 minutes at room temperature, up to overnight in the fridge.",
            "(Optional) If you will be using dried lily flowers and / or wood ear mushrooms, soak them while marinating the chicken. Once done, cut the mushrooms into small bite-size pieces. Dry both ingredients with paper towels (very important, otherwise it will dilute the sauce).",
            "Prepare a plate that can fit into your steamer. Add the chicken onto the plate along with the marinating liquid, and arrange the soaked lily flowers and wood ear mushrooms with the chicken. Add the goji berries. Avoid overlapping the chicken if possible, because it will result in a longer cooking time and the chicken might not be cooked evenly.",
            "Add 2” (5 cm) water to the steamer and place the plate of chicken onto the steamer rack. Cover and turn to medium-high heat. When the steam starts to come out of the steamer, set the timer for 8 minutes.",
            "Once done, remove the cover and carefully check the chicken to make sure it’s fully cooked. Steam for a bit longer if needed. Turn off the heat. Carefully remove the plate from the steamer. Serve hot as an appetizer, or over steamed rice as a main dish.",
        ]
    ),
    "Lion’s Head Meatballs": RecipeDetail(
        ingredients: [
            "1 lb ground pork",
            "4 tablespoons Shaoxing wine ((or dry sherry))",
            "3 tablespoons light soy sauce ((or soy sauce))",
            "1 teaspoon dark soy sauce",
            "1 1/4 teaspoons salt ((*Footnote 1))",
            "2 teaspoons sugar",
            "2 teaspoons grated ginger",
            "4 green onions (, minced)",
            "1 tablespoon cornstarch",
            "12 water chestnuts (one 8-oz / 227-g can) (, finely chopped)",
            "3 eggs",
            "1 cup panko ((Japanese breadcrumbs))",
            "2 tablespoons sesame oil",
            "1 tablespoon peanut oil ((or vegetable oil))",
        ],
        steps: [
            "Add ground pork into a large bowl. Add 4 tablespoons of water. Mix well with a spatula until water is fully incorporated.",
            "Add Shaoxing wine, light soy sauce, dark soy sauce, salt, sugar, grated ginger, cornstarch, and scallion. Mix well.",
            "Add water chestnuts and eggs. Mix a few times. Then add panko. Mix well.",
            "At the end, add sesame oil. Mix until it forms a soft paste.",
            "Heat the oil in a medium-sized skillet over medium-high heat until hot. Turn to medium heat.",
            "Brown the meatballs in batches. Scoop 1/3 cup of the ground meat mixture and shape it into a meatball. The meatball will be quite soft, barely able to hold its shape (so the finished meatballs will be tender and juicy). If the meatballs are too hard to handle and cannot hold their shape, add a bit more panko and mix again.",
            "Carefully place 3 to 4 meatballs in the skillet and make sure to leave enough space to flip them. When the bottom side turns golden brown, carefully roll the ball with a spatula to cook the other sides. Continue to do this until at least two sides are set and browned (*see footnote 2). Transfer to a deep plate or a bowl that can fit into your steamer rack. Continue to brown the rest of the meatballs.",
            "Steam the browned meatballs in batches. Heat water in a steamer until boiling. Place the plate of meatballs on the steaming rack and place the steaming rack onto the steamer. Cook covered until the meatballs are cooked through, 30 minutes or so.",
            "Cook the rest of the batches using the same method. After cooking the first batch, check the water level and add more if it runs too low. Serve hot as a main.",
            "Store the meatballs in an airtight container in the fridge for 3 days or in the freezer for up to 2 months. After steaming, the meatballs will render some fat and liquid. Drizzle it onto the meatballs before storage, to keep them tender and moist.",
            "The best way to reheat the meatballs is by steaming, the same method used to cook them. The meatballs will be heated evenly and still be moist inside. Alternatively, you can use the microwave. Make sure the container has some liquid (leftover grease or 1 teaspoon water) in it. Place a loose lid on top and heat it up in the microwave.",
        ]
    ),
    "Xiao Long Bao": RecipeDetail(
        ingredients: [
            "2.5 to 3 lbs chicken backs and necks",
            "1 tablespoon vegetable oil",
            "2 ” ginger (, sliced)",
            "4 green onions (, chopped into 3” (8 cm) pieces)",
            "120 g all purpose flour ((2/3 cup plus 2 tablespoons))",
            "Pinch of salt",
            "35 g hot water ((2 tablespoons plus 1 teaspoon))",
            "25 to 30 g cold water ((about 2 tablespoons))",
            "1 tablespoon grated ginger",
            "8 oz fatty ground pork ((*Footnote 1))",
            "1 tablespoon light soy sauce",
            "4 teaspoons Shaoxing wine ((or dry sherry))",
            "1/4 teaspoon salt",
            "1/4 teaspoon sugar",
            "1/8 teaspoon white pepper",
            "4 green onions (, finely minced)",
            "Chinkiang vinegar",
            "ginger (, very thinly sliced)",
            "Small Chinese rolling pin ((*Footnote 2))",
        ],
        steps: [
            "Preheat the oven to 400°F (200°C).",
            "Prepare a medium-sized (about 4 qt) dutch oven with a lid or a roasting pan that can be securely sealed with a lid or foil. Add the oil to the pan and place it in the oven to heat up, 5 to 10 minutes.",
            "Once heated, carefully transfer the pan onto a trivet. Place the chicken back in the pan and spread the ginger and green onions on top of it. Add 1/4 cup water. Cover with the lid and return to the oven. Roast until you’ve collected a good amount of chicken broth in the bottom of the pot, 50 minutes or so.",
            "Remove the pan from the oven and let cool for 5 minutes. Use a pair of tongs to remove and discard the chicken backs.",
            "Lay a mesh strainer over a heat-proof bowl. Strain the chicken broth. Once cooled completely, transfer the chicken broth into a sealed container and refrigerate overnight.",
            "Combine the flour and salt in a large bowl. Slowly drizzle the hot water over the flour while stirring with a pair of chopsticks (or a fork). Mix until the hot water is fully absorbed.",
            "Then slowly drizzle 25 g of cold water over the dry flour while mixing. Once the water is fully absorbed and the flour turns into dough flakes, start pressing with your hand to gather the dough together while mixing in as much dry flour as you can. If the dough is almost formed but there’s still dry flour left in the bowl, add the remaining 5 g water and keep kneading. Once done, it should form a semi-soft dough and no flour is left in the bowl.",
            "Transfer the dough onto a clean working surface and knead for 15 to 20 minutes, until the surface is smooth and the texture elastic. The dough should feel soft to the touch and not stick to your hands.",
            "Wrap the dough with plastic wrap and let it rest for 45 minutes.",
            "Storage: You can store the dough at this point if you decide to assemble the dumpling later. The dough can be stored in a sealed container in the fridge overnight.",
            "Add the grated ginger into a small bowl and pour in 1/4 cup hot water. Let sit while preparing other ingredients.",
            "The chicken broth you made the day before should have become congealed with a layer of fat on top. Scrape off the fat and reserve it in a small bowl.",
            "Slice the chicken gelatin into thin strips, then further into small cubes. Coarsely mince it into bits.",
            "Measure the chopped gelatin. If it’s less than 4.4 oz (120 g), add a few spoonfuls of the chicken fat until it reaches 4.4 oz (120 g). You can discard or reserve the remaining chicken fat for future use. Store the gelatin in the fridge while not using.",
            "Add the ground pork into a medium-sized bowl. Add the ginger water, light soy sauce, Shaoxing wine, salt, sugar and white pepper. Beat with a spatula until the liquid is fully absorbed and the filling becomes sticky and bouncy, 5 minutes or so.",
            "Add the chopped chicken jelly and green onions. Mix until incorporated.",
            "Cover the bowl with plastic wrap and store in the fridge until ready to use. The filling can be stored in the fridge for a couple of hours, but I do not recommend storing it for too much longer, because the liquid will start to seep out.",
            "Line a steamer rack with napa cabbage leaves or prepare some square parchment paper for steaming the dumplings.",
            "Place the rested dough onto a clean working surface. Roll it into a long log, about 1” (2.5 cm) in diameter. Cut the log in half, wrap one half with plastic wrap and place it in the fridge while working on the other half.",
            "Roll out the log a bit more. Divide it into two equal pieces, then further cut them into 10 pieces in total. Cover them with a few layers of wet paper towels to prevent drying out.",
            "Work on the buns one at a time. Shape one piece of dough with your fingers so it is a round piece, then flatten it with your palm. Use a small rolling pin to roll out the wrapper, spinning the dough after rolling a few times. Roll until the wrapper is very thin, about 4 1/2” (11 cm) in diameter. (*Footnote 3)",
            "Place 22 g (about 1 tablespoon) of the filling onto the center of the wrapper. Fold and pinch the edges of the wrapper to create pleats (see the wrapping process in action in my cooking video). When you are about to seal the pleats, leave a small opening on the top of the dumplings (very important - *Footnote 4).",
            "Place the wrapped dumplings onto the napa cabbage or parchment paper. Cover loosely with a few layers of wet paper towels to prevent drying out. Work on the rest of the dumplings until you can fill the steamer rack - you should leave at least 2” (5 cm) between the dumplings.",
            "Prepare the dipping sauce by adding 1 tablespoon of Chinese vinegar and a few strips of ginger to each small sauce plate.",
            "Bring a pot of water to a boil over medium-high heat. Cover the steamer rack with a lid and place it over the boiling water. Steam over medium-high heat for 8 to 10 minutes, depending on the number of dumplings you cook at a time.",
            "Once done cooking, serve immediately with the dipping sauce.",
            "To eat the soup dumplings, hold a pair of chopsticks in one hand and a big spoon in the other. Carefully use the chopsticks to pick up the soup dumpling and place it into the spoon. If you’re skillful with chopsticks, you can also dip the dumpling into the dipping sauce. Otherwise, drizzle a tiny amount of sauce over the dumpling. Have a small bite of the dumplings to let the steam out and allow the soup to pool in the spoon. If you don’t mind hot food (it’s very hot!), you can also let the soup stay in the dumpling and eat it all in one bite (I do not recommend this method if you’re not familiar with soup dumplings).",
        ]
    ),
    "West Lake Beef Soup": RecipeDetail(
        ingredients: [
            "1/2 lb ground beef",
            "1/2 teaspoon salt",
            "2 teaspoons Shaoxing wine",
            "2 teaspoons cornstarch",
            "6 cups chicken broth",
            "2 slices ginger",
            "1/4 block soft tofu (, diced)",
            "4 oz white or brown mushrooms (, diced)",
            "1/4 cup cornstarch",
            "3 egg whites (, beaten thoroughly)",
            "1 scallion (, thinly sliced)",
            "1 teaspoon salt",
            "1/4 teaspoon white pepper",
        ],
        steps: [
            "Combine the ground beef, 1/2 teaspoon salt, Shaoxing wine and 1 teaspoon cornstarch in a small bowl. Mix well and marinate while preparing the rest of the ingredients.",
            "Bring a small pot of water to a boil. Add the ground beef and turn to lowest heat. Break apart the beef as much as you can, until the beef has just turned a pale color, 1 to 2 minutes. Drain the beef and discard the boiling water. Break apart any large beef pieces as needed.",
            "Heat the chicken broth and ginger in a medium pot over high heat until bringing to a boil. Add the mushroom and tofu. Simmer for 3 minutes, until the mushrooms are cooked.",
            "Combine the 1/4 cup of cornstarch with 1/4 cup water in a small bowl, stir to dissolve completely. Pour the slurry into the pot. Stir immediately to mix well to thicken the soup.",
            "Turn to low heat. Slowly pour in the egg white so it goes into the pot in a very thin stream. Once you’ve added all the egg whites, stir gently to break apart the eggs into thin ribbons. Add the cooked beef into the soup and stir to mix well. Turn off the heat. Add the scallion, salt and white pepper. Stir to mix well. Serve hot.",
        ]
    ),
    "Drunken Chicken": RecipeDetail(
        ingredients: [
            "2 bone-in skin-on chicken leg quarters ((includes thighs) (*Footnote 1))",
            "1 1/2 teaspoons salt",
            "1/4 teaspoon ground Sichuan peppercorns",
            "2 teaspoons Shaoxing wine",
            "1 green onion (, smashed)",
            "3 slices ginger",
            "2 cups water",
            "1 “ ginger (, sliced)",
            "1 green onion (, coarsely chopped)",
            "1 star anise",
            "3 dried jujubes ((Optional))",
            "15 goji berries ((Optional))",
            "1 teaspoon salt",
            "1 teaspoon sugar",
            "1/2 cup Shaoxing wine",
            "Chopped green onion for garnish",
        ],
        steps: [
            "Combine the salt and Sichuan peppercorns in a small pan. Toast over medium-low heat, shaking the pan occasionally, until fragrant, about 5 minutes. Transfer to a small plate to cool.",
            "Debone the chicken legs (see the step-by-step guide above in the blog post), setting the bones aside for the stock. Using the back of the knife to pound the thick part of the meat so that it is an even thickness.",
            "Sprinkle the toasted salt and Sichuan peppercorns over the chicken legs. Top with the Shaoxing wine, green onion, and ginger. Use your hand to gently massage the seasonings in and set aside for 15 minutes.",
            "Use a cleaver or strong knife to chop the leg bones in half (Optional, to release more flavor). Add them to a small pot with the water, ginger, green onion, star anise, and jujubes.",
            "Heat over medium-high heat until bringing to a boil, then reduce to medium-low heat. Simmer for 30 minutes, skimming the foam from the top occasionally. Transfer the stock to a heat proof container once done.",
            "Add the goji berries, salt, sugar, and Shaoxing wine. Stir until the sugar and salt are fully dissolved. Place the stock in the fridge to cool down completely.",
            "After the chicken has marinated, roll each leg into a tight log, skin side out.",
            "Place the rolled chicken leg on a piece of aluminum foil. Wrap the leg with the foil to seal it completely.",
            "Set up a steamer by adding water to the pot and bringing to a boil over medium-high heat.",
            "Place the chicken rolls on the steaming rack and steam over medium-high heat for 15 to 20 minutes, depending on the size of the chicken legs. At the 15-minute mark, check the doneness by inserting a toothpick through the center of the chicken and the juices run clear. Let cook for another 5 minutes if needed.",
            "Prepare an ice bath by adding ice and water to a big bowl. Place the cooked chicken rolls into it and let cool completely.",
            "Once the chicken rolls and brine are completely cooled, remove the chicken legs from the foil and transfer into a deep container, collecting the juices from the rolls as well.",
            "Lay a mesh colander over the container, then strain and pour the brine over the chicken. Add the goji berries back to the chicken, discarding the rest of the solid ingredients. Seal the container and let marinate in the fridge overnight.",
            "To serve, slice the chicken into 1/2” (1 cm) pieces, drizzle a small amount of the brine, and garnish with green onions and goji berries. Serve cold or at room temperature as an appetizer.",
        ]
    ),
    "Hong Shao Rou": RecipeDetail(
        ingredients: [
            "1.5 to 2 lbs pork belly (, cut into 1” (2.5 cm) cubes)",
            "2 green onions (, cut into 2” (5 cm) pieces)",
            "1/2&quot; ginger (, sliced)",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "3 tablespoons sugar",
            "1/3 cup Shaoxing wine ((or dry sherry))",
            "2 cups reserved blanching liquid",
            "3 tablespoons light soy sauce ((or soy sauce))",
            "1 1/2 tablespoons dark soy sauce",
            "1&quot; ginger (, sliced)",
            "3 green onions (, cut into 2” (5 cm) pieces)",
            "2 whole star anise pods",
        ],
        steps: [
            "In a medium-sized pot add the pork belly and enough water to cover it completely. Make sure there is some space between the water level and the lip of the pot to avoid boiling over and to make skimming easier.",
            "Add the green onions and ginger. Cook over high heat until the water reaches a full boil. Boil for 5 minutes, using a fine mesh strainer (or a ladle) to skim and discard the brown foam from the top, until the liquid is clear.",
            "Strain the pork and reserve the blanching liquid. Rinse the pork with running tap water to stop the cooking and rinse away any scum that may have stuck to it.",
            "In a separate medium-sized dutch oven or pot (make sure it is completely dry to avoid the oil and sugar splattering), add the sugar and oil. Heat over low heat until the sugar is melted and begins to brown; look for an amber color. Try to avoid stirring the sugar while melting it. Instead, swirl the whole pot.",
            "Once the caramel is a light amber color, carefully add the pork chunks by gently placing them into the caramel to minimize splashing or splattering. Depending on the size of your pot, you might need to add the pork in two batches.",
            "Turn the heat up to medium-low and brown the pork in the caramel, about 1 minute on each side. Be careful not to burn the sugar.",
            "Add the cooking wine and scrape with a wooden spatula to release any brown bits from the bottom of the pan. Add the reserved blanching liquid, light soy sauce, dark soy sauce, ginger, green onions, and star anise.",
            "Turn to medium-high heat until the broth comes to a boil. Turn to medium-low or low heat so the broth reduces to a simmer. Cover the pot, leaving a finger-width gap to allow the steam to escape. Simmer for 1 hour and 30 minutes. Stir 2 to 3 times during the simmering.",
            "If the pork has turned tender but the sauce isn’t fully reduced, remove the lid and bring the heat up to medium. Cook for another 10 or 15 minutes, until the liquid is reduced to a glaze consistency. Keep an eye on the pot during the process and stir to prevent burning on the bottom.",
            "Serve the pork with the glaze over steamed rice as a main course.",
            "You can store the leftovers in a sealed container in the fridge for 4 to 5 days or in the freezer for a month. To reheat the frozen pork, thaw it in the fridge overnight, then steam it until fully heated through, 15 to 20 minutes. If you want to reheat the pork in the microwave, cover the bowl with a plate to prevent oil splatter.",
        ]
    ),
    "Zha Jiang Mian": RecipeDetail(
        ingredients: [
            "12 oz ground pork ((*Footnote 1))",
            "1 tablespoon minced ginger",
            "2 tablespoons Shaoxing wine",
            "3/4 cup sweet bean paste ((Tian Mian Jiang))",
            "1 1/2 cup water",
            "4 tablespoons peanut oil ((or vegetable oil))",
            "1 white onion (, diced)",
            "12 oz fresh wheat noodles ( (or 9 oz / 240 g dried wheat noodles) (*Footnote 2))",
            "1 cucumber (, julienned)",
            "cilantro (, chopped (or onion) for garnish)",
            "Stir fried tomato and egg (, Optional (*Footnote 3))",
        ],
        steps: [
            "Add sweet bean sauce to a large bowl. Slowly blend in water and stir constantly, until water is fully incorporated.",
            "Heat a large skillet or a wok over medium-high heat until hot. Add the oil and the ginger. Stir a few times to release the fragrance.",
            "Add the pork. Cook, stir and chop, until the pork turns to small pieces and has browned. Pour in the Shaoxing wine. Stir and cook for 1 minute.",
            "Add the sweet bean sauce and turn to medium heat. Stir constantly, until the sauce thickens and turns darker, about 10 mins. If the sauce thickens too quickly and starts to feel like it's sticking to the bottom of the pan, turn to medium-low heat and slowly blend in more warm water, 2 tablespoons at a time. Reduce the heat if the pan gets too smoky.",
            "Add the onion. Cook and stir for 3 to 5 minutes, until the onion has softened but remains crispy. Turn off heat and transfer the sauce to a large bowl.",
            "While cooking the noodle sauce, bring a large pot of water to a boil and cook noodles according to instructions. Once done, drain the noodles immediately and rinse with cold tap water to stop cooking. Drain again.",
            "Add noodles to individual serving bowls. Top noodles with sauce, cucumber, and stir fried tomato and egg if using. Garnish with cilantro or green onions. Serve as a main dish.",
        ]
    ),
    "Scallion Oil Noodles": RecipeDetail(
        ingredients: [
            "6 to 8 scallions ((*Footnote 1))",
            "1/4 cup vegetable oil ((or any neutral oil))",
            "3 tablespoons light soy sauce",
            "2 cloves garlic (, coarsely chopped)",
            "2 1/2 tablespoons dark soy sauce",
            "2 teaspoons sugar",
            "1 lb fresh thin wheat noodles (, or 12 oz (340 g) dried thin wheat noodles (*footnote 2))",
        ],
        steps: [
            "Cut the scallions into 2” (5 cm) long pieces, then julienne into thin strips. If using very thin scallions, you can also quarter them lengthwise if it’s easier. Dry the green onions thoroughly before cooking to prevent oil splatter.",
            "Add oil to a frying pan and heat over medium heat until hot, but not smoking. Add the scallions and spread them out as much as you can. Cook over medium heat, stirring constantly until the green onions turn golden brown. Turn to medium-low heat if the scallions brown too quickly and start to burn. Some scallion pieces might brown faster than others. Transfer the browned green onions with a pair of tongs or chopsticks and place in a bowl, until all the scallion pieces are cooked. Save the cooked scallions for later.",
            "Add the minced garlic to the oil. Cook and stir until turning lightly golden.",
            "Pour in the light soy sauce, dark soy sauce and sugar. Simmer and stir for 1 minute or so. Turn off the heat and set the sauce aside.",
            "Bring a large pot of water to a boil. Cook noodles according to instructions. Once cooked, drain noodles and transfer to serving plates.",
            "Portion the noodles into serving bowls, add a few spoonfuls of the noodle sauce into each bowl and garnish with fried green onions. Serve the noodle with the rest of the sauce on the side. Mix the noodles with sauce before eating. Add more sauce if needed.",
        ]
    ),
    "Shanghai Fried Noodles": RecipeDetail(
        ingredients: [
            "4 dried shiitake mushrooms",
            "8 oz pork tenderloin (, julienned)",
            "1 tablespoon Shaoxing wine",
            "2 teaspoons light soy sauce",
            "1 tablespoon cornstarch",
            "2 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "1 tablespoon Shaoxing wine",
            "1 teaspoon sugar",
            "1/4 teaspoon white pepper",
            "10 oz Shanghai thick noodles ((or Japanese udon noodles) (*Footnote 1))",
            "2 tablespoons vegetable oil",
            "12 oz baby bok choy (, whites sliced into 1/2” pieces, greens sliced into 1” pieces)",
            "3 scallions (, sliced into 2” pieces, white part halved lengthwise, white and green parts separated)",
        ],
        steps: [
            "Add the shiitake mushrooms into a medium bowl and pour hot water to cover. Soak until turning tender throughout, 15 minutes or so. Drain and slice the mushrooms into strips.",
            "Combine the pork with Shaoxing wine, light soy sauce and cornstarch in a small bowl. Mix well.",
            "Combine all the sauce ingredients in a small bowl.",
            "Boil the noodles until al dente, 1 minute less than the package instructions call for. Drain, rinse with cold water to stop cooking, drain again and set aside.",
            "Heat 1/2 tablespoon of oil in a large skillet over medium-high heat until shimmering. Spread the pork without overlapping. Cook for 1 minute until the bottom side is cooked, then stir a few times until turning white throughout. Transfer to a plate.",
            "Add the remaining 1 1/2 tablespoons oil to the skillet, the scallion whites and shiitake mushrooms. Stir for 1 minute to release fragrance. Add the noodles. Toss with a pair of tongs to coat with oil. Pour in the sauce and toss again until the sauce coats the noodles evenly.",
            "Add the bok choy whites. Stir to mix well. Cover the pan and let steam for 2 minutes. Add the bok choy greens, scallion greens and the cooked pork. Toss to mix well. Cover the pan and cook for another 1 to 2 minutes, until the bok choy has fully softened. Lower the heat and taste the noodles carefully. Adjust seasoning by adding a pinch of salt if needed. Transfer everything to a large platter and serve hot.",
        ]
    ),
    "Sticky Rice Cake": RecipeDetail(
        ingredients: [
            "250 grams (9 ounces) glutinous rice flour and extra flour to dust working surface",
            "1 1/2 cups red bean paste",
            "1 tablespoon vegetable oil",
            "1/2 cup white roasted sesame seeds",
        ],
        steps: [
            "Add sweet rice flour into a large bowl. Measure out 1 cup of water (You will use slightly less than a cup). Slowly add water into the flour in 4 to 5 pours, and stir with a fork until the water is fully incorporated with the flour. There should be no dry flour left, and the flour should start to have the texture of dough - soft but not runny. If the dough gets too soft and becomes difficult to shape, add more rice flour, a tablespoon at a time. Use your hand to press and knead the dough a few times, until the texture becomes consistent (* see footnote). The dough should be soft and easy to shape. When you lift the dough from the bowl, it should slightly stick to the bottom of the bowl.",
            "Dust a working surface with rice flour and transfer the dough onto it. Divide the dough in half. Roll the dough with both hands to shape it into a long, even rod. Divide the dough equally into 6 pieces. Shape each piece into a round ball and set aside.",
            "To make the cake, place one rice dough ball in your palm and use the other hand to gently press it into a round, flat piece (it’s very easy to shape, so you won’t need a rolling pin), about 6 centimeters (2.5 inches) in diameter, 6 millimeters (1/4 inch) in thickness.",
            "Scoop about 2 tablespoons of red bean paste and shape the paste into a ball. Place the ball of bean paste in the center of the round dough. Pinch the edges of the dough together to completely enclose the bean paste. When the cake is shaped like a ball, gently use your palm to press it, until it is shaped like a pancake, about 6 centimeters (2.5 inches) in diameter and 1.2 centimeters (1/2 inches) in thickness. Spread 1 tablespoon of sesame seeds onto the working surface, place the cake on top of them, and gently press. Shake off the extra sesame seeds, flip the cake, and press the other side onto the seeds. Craft the rest of the cakes in the same manner.",
            "Heat 1 teaspoon of vegetable oil a non-stick skillet over medium heat. When the oil is hot, turn to medium low heat and place 4 cakes into the skillet. Cook until the bottom of the cake turns golden brown, after 2 to 3 minutes. Flip and cook the other side. Transfer the cakes to a large plate to cool. Cook the rest of the cakes in the same manner.",
            "Serve the rice cakes warm.",
        ]
    ),
    "Eight Treasure Rice": RecipeDetail(
        ingredients: [
            "1 1/2 cups (360 ml) glutinous rice",
            "2 tablespoons coconut oil ((or shortening))",
            "1 tablespoon sugar",
            "4 tablespoons red bean paste",
            "3 jujubes",
            "1 tablespoon golden raisins",
            "1 tablespoon pumpkin seeds",
            "1/2 tablespoon goji berries",
            "1 walnut half",
            "1 cup water",
            "2 tablespoons sugar",
            "1 heaping tablespoon dried chrysanthemum buds",
            "1 teaspoon cornstarch",
        ],
        steps: [
            "Cover the glutinous rice with 2” (5cm) cold water and soak it for a minimum of 3 hours, preferably overnight.",
            "Once soaked, drain off the water and rinse the rice a few times.",
            "Prepare your steamer by bringing the water to a boil.",
            "Add the soaked rice into a heat-proof bowl and place it on the steamer rack. Steam, covered, for 30 minutes for overnight-soaked rice, or for 45 minutes for 3-hour-soaked rice. Once done, the rice should be edible, but still quite tough.",
            "While steaming the rice, arrange the rice toppings in the base of a wide heat-proof bowl. (*Footnote 2)",
            "Once the rice is steamed, add the coconut oil and sugar. Stir thoroughly until the sugar melts and the rice is evenly coated with oil.",
            "Press the seasoned rice into the bowl with the toppings. Be careful not to disturb the pattern you’ve created. Fill two thirds of the bowl with rice while creating a dent in the middle for the red bean paste.",
            "Add the red bean paste in the middle and use the back of a spoon to flatten it into a thin layer.",
            "Add the rest of the rice and use a spoon to flatten it.",
            "At this stage, you can store the rice, covered with plastic wrap, in the fridge for 1 to 2 days. Follow the rest of the instructions prior to serving.",
            "Place the assembled rice back to the steamer and steam it for an additional 30 minutes.",
            "Prepare the syrup while steaming the assembled rice. Combine the water, sugar, and chrysanthemum buds in a small saucepan and heat it over medium heat until boiling. Turn to medium-low heat. Simmer for 10 minutes.",
            "Mix the cornstarch with 1 teaspoon of water until the cornstarch has dissolved completely.",
            "When the chrysanthemum mixture is cooked, pour in the cornstarch slurry. Keep cooking and stirring constantly, until the syrup slightly thickens. Pour the syrup over a strainer into a bowl and discard the chrysanthemum buds.",
            "When the treasure rice is done steaming, drizzle a few spoons of syrup onto the rice. Let it sit for 10 minutes.",
            "To plate the rice, put a plate over the bowl and flip it in one swift motion. Remove the bowl and pour the remaining syrup over top of it. Serve warm.",
            "The cooked treasure rice can be stored in an airtight container in the fridge for up to 2 days. You can reheat it in the microwave.",
        ]
    ),
    "Chinese Roast Duck": RecipeDetail(
        ingredients: [
            "1 whole duck (,preferably Pekin duck, 3.5-4.5 lbs (1.6-2 kg) (*Footnote 1))",
            "1 teaspoon sea salt",
            "1 teaspoon five spice powder",
            "1 teaspoon sugar",
            "4 cubes red fermented tofu",
            "2 tablespoons Shaoxing wine",
            "1 tablespoon hoisin sauce",
            "1 teaspoon oyster sauce",
            "1 star anise",
            "1 green onion (, cut into 4” (6 cm) long pieces)",
            "1 ” ginger (, cut into large slices)",
            "8 cups water",
            "1/2 cup Shaoxing wine",
            "1/2 cup honey ((or brown sugar syrup, or maltose) (*Footnote 2))",
            "1/2 cup Chinese red vinegar ((or cider vinegar, malt vinegar))",
            "Plum sauce",
            "Ginger scallion sauce",
            "2 skewers ((metal or wooden))",
            "Kitchen twine",
            "Pump with a fine tip (, electric or hand pump (*Footnote 3))",
        ],
        steps: [
            "To prepare the duck: First remove any giblets and neck pieces from the cavity, and tear off the excess fat found inside the bird. Next, remove the wings by cutting through the joints, but keep the drumettes on the bird. Remove any remaining pieces of feather with kitchen tweezers.",
            "Have the skewers ready within reach. Cut off two pieces of 2’ (60 cm)-long kitchen twine, and place them within reach.",
            "Seal the front of the duck: Threading a skewer through both layers of skin. Seal the top by tying twine under the skewer. The top must be sealed before adding the marinade.",
            "Add the marinade: Combine the wet seasonings in a small bowl and mash the fermented tofu to mix well. Add the dry seasonings into the duck cavity, using your hands to rub the cavity a few times. Add all of the seasonings, ensuring they are snug within the cavity. Carefully pour the wet seasonings into the cavity, making sure that they do not leak out of the duck.",
            "Seal the tail of the duck: To close the duck’s cavity, carefully thread a skewer through both layers of the skin, and tie twine under the skewer to seal the bird. It is best to hold the duck at an angle, so the wet seasonings do not escape the cavity.",
            "Pump the air under the duck skin: After the duck has been closed, place the duck breast side up. Insert an air pump with a fine tip where the leg meets the breast of the duck. Begin pumping air into the bird, and ensure that the skin is separated from the meat as much as possible. Switch to the opposite side to guarantee all the skin has lifted up from the meat. Then insert the tip from the top of the breast pointing to the leg direction, and pump again to lift the breast skin. Do the same with the opposite side. (*Footnote 4)",
            "To blanch the duck: Prepare a tray that can fit into your fridge. Line it with a wire rack. Add all the blanching ingredients into a big wok, dutch oven or a large pot. Bring all the blanching ingredients to a boil over medium-high heat. Turn to medium heat. Carefully lower the duck into the seasoned water. Ladle hot water and pour over the duck until the skin becomes tight and smooth, about 30 seconds.(*Footnote 5) Use a spider strainer to lift the duck and transfer it to the lined tray. If the duck is too heavy, you can also use a spatula to lift the tail end, then use your hands to lift the leg bones (they won’t be too hot).",
            "Rest overnight: Once the duck has cooled off slightly, transfer it into the fridge. Allow to marinate and air dry in your fridge for at least 24 hours before roasting. (*Footnote 7)",
            "To roast the duck: Preheat your oven to 450°F (232°C). (*Footnote 8) If your oven has convection, roast at 425°F (218°C) with convection instead. This helps the duck cook more evenly. Wipe the duck skin with a paper towel, to remove any oil on the surface.",
            "Roast at high temperature: Transfer the duck to the oven. Roast at 450°F (232°C) for a total of 20 minutes. After 10 minutes, rotate the duck around (180 degrees, don’t flip it), and cook for 10 minutes more.",
            "Roast at a lower temperature: Lower the temperature to 350°F (176°C) or 325°F (163°C) convection, and rotate the duck again. Roast for another 30 minutes in total if using a 3.5-4 lb (1.6-1.8 kg) duck. Rotate after 15 minutes. If your duck is bigger, add 10 to 15 minutes of cooking time for a 4-5.5 lb (2-2.5 kg) duck, or add 20 to 25 minutes for a 6-6.5 lb (2.7-2.9kg) duck. Rotate every 15 minutes to ensure even cooking. (*Footnote 9)",
            "Test the doneness: The duck should have developed a nice golden brown color. Make an incision with a paring knife poking through the thickest part of the breast meat, then press the skin. If the juice runs clear, it is cooked. (*Footnote 10) If the juice is red, keep cooking for another 10 to 15 minutes.",
            "Rest the duck: Once the duck is cooked, transfer the duck to your kitchen counter. Let rest for at least 40 minutes.",
            "Drain the duck: Once the duck has cooled enough to handle, prepare a big bowl. Untie the tail end and remove the skewer. Use a sharp knife to cut through the skin and remove the part where you sealed the duck, exposing the cavity. Very carefully lift the duck over the bowl to drain the liquid from the cavity, then remove any solid aromatics. The inside of the duck will be very hot and you should handle it very carefully. Then remove the twine and skewer from the neck area.",
            "Carve the duck: Carve the duck by cutting through the part where the leg meets the breast. Find the joint of the thigh bone and cut through it to remove the duck leg. Then find the joint of the drumstick and the thigh, cut through it. Then cut down the center of the breast to remove both breasts.",
            "Reheat the duck (Optional): If you’re not serving the duck immediately, or you accidentally get the duck skin wet when draining and carving the duck, I highly recommend this step. Heat your oven to 450°F (232°C). Place all the carved duck pieces onto a baking sheet lined with a wire rack, skin side up. Heat in the oven for 5 to 10 minutes, until the skin is crispy again. Slice the breast into 1/2” (6 mm) thick pieces, and place them on a platter with the legs and thighs.",
            "How to serve: Serve hot or warm with plum sauce or ginger scallion sauce.",
        ]
    ),
    "Eight Treasure Congee": RecipeDetail(
        ingredients: [
            "1/2 cup (120 ml) glutinous rice",
            "2 tablespoons forbidden rice",
            "2 tablespoons barley ((or brown rice))",
            "2 tablespoons dry red beans ((or mung beans))",
            "1/8 cup (30 ml) raw cashews ((or peanuts, or lotus seeds) (*Footnote 1))",
            "1/8 cup (30 ml) coarsely chopped raw pecans ((or walnuts, or chestnuts))",
            "6 to 10 dried Chinese jujubes ((or dried Longan, rinsed) (*Footnote 2))",
            "2 tablespoons raisins",
            "8 to 10 cups of water",
            "1/4 cup rock sugar (, or to taste (or any other type of sweetener you prefer) (Optional))",
        ],
        steps: [
            "Add all the dry ingredients except the sugar, and 8 cups water into the Instant Pot. Set to cook at high pressure for 25 minutes. Once done, release the pressure naturally. (*Footnote 3) Once the pressure is released, stir the congee thoroughly so the texture becomes consistent.",
            "(Optional) Add the sugar according to your taste. Stir so that it dissolves completely. If the rock sugar doesn’t dissolve, turn on the saute function and let it cook until the sugar melts, 2 minutes or less.",
            "Serve hot as a side.",
            "Combine the glutinous rice, black rice, peanuts, walnuts, barley, red beans in a big bowl. Pour in 2”(5cm) tap water to cover. Soak overnight. Discard the soaking water and drain thoroughly before cooking.",
            "Combine the soaked rice blend, red dates, and raisins in a big pot. Add 10 cups water.",
            "Cook over medium-high heat until bringing to a simmer. Turn to low heat. Cover the pot and leave a finger-wide a gap between the lid and the edge of the pot, to allow more steam to escape and prevent the congee from spilling or boiling over. Simmer until the congee reaches the desired texture, 40 minutes for a thin texture, or up to 60 minutes for a stickier and thicker texture.",
            "(Optional) At the end of the cooking, add the sugar and stir to dissolve it completely.",
            "Serve hot as a side.",
        ]
    ),
    "Mom’s best duck pancakes": RecipeDetail(
        ingredients: [
            "2 cups (300 grams) all-purpose flour ((please read how to convert grams to cups properly), and extra to dust the working surface)",
            "3/4 cup (180 milliliters) boiling water",
            "90 milliliters 1/4 cup + 2 tablespoons cool water ((room temperature))",
            "2 tablespoons vegetable oil for brushing",
        ],
        steps: [
            "Bring a small pot of water to a boil. Dust a working surface with plenty of flour.",
            "Add 150 grams (1 cup) flour into a large bowl. Slowly add boiling water into the first bowl. Whisk with a pair of chopsticks (or a spatula), until the water is fully absorbed. It will form a soft, sticky mass. Use a spatula to scrape the dough onto the working surface.",
            "Add the remaining 150 grams (1 cup) flour into the same bowl. Slowly add cool water and whisk until the water is fully absorbed. It will form a soft mass, but should not be too sticky. Scrape dough onto the first dough on the working surface.",
            "Dust both hands with flour. Knead and press the two doughs together. Dust with more flour if needed. Knead the dough by hand until texture turns consistent, about 5 minutes. You should feel that the dough is slightly sticky while kneading, but it shouldn’t stick to your hands. Be careful not to dust the working surface with too much flour. The dough will become less tender as you blend in more dry flour.",
            "Dust the dough with flour. Cover with plastic wrap and let rest for 30 minutes.",
            "Dust working surface with flour again. Knead the dough a few times until smooth. Do not over-knead it.",
            "(Optional) The dough might still be springy and a bit difficult to roll. Dust the dough with flour and cover with plastic wrap again. Let rest for another 10 to 20 minutes.",
            "Shape the dough into a log and divide it into two equal pieces. Wrap one piece with plastic wrap (to prevent the dough from drying out) and work on the other piece.",
            "Pull and roll the dough log back and forth until it turns into a long roll, about 36 cm (18 inches) in length. Cut into 2-cm (1-inch) pieces. You should get 18 pieces of dough. Dust both cut sides of each dough piece with flour and let stand on one of the cut sides.",
            "Work on the dough pieces two at a time. Cover the rest of the dough pieces loosely with plastic wrap (or a clean, damp towel), to prevent drying out.",
            "Add oil into a small bowl. Prepare a small brush.",
            "Shape two doughs into a cylinder shape and press them as much as you can into two small, round discs.",
            "Brush oil thoroughly onto the top of one dough disc. Make sure the oil covers the entire surface, otherwise the two pancakes will be difficult to separate later. This process of doubling up the pancakes cuts rolling and cooking time in half.",
            "Place the other one onto it, to form a two-layer pancake. Press the two doughs again, into a flat disc.",
            "Dust the working surface with flour. Use a rolling pin to roll the double pancake into a thin round disc, about 13 to 15 cm (5 to 6 inches) in diameter. Turn the dough a few times during rolling, to ensure both pancakes are evenly rolled out. The pancakes will be very thin and might stick to the working surface when rolled. Dust with more flour if needed.",
            "Dust both sides of the double pancake with flour again and place it aside, keeping them in a single stack. Cover with a damp towel (or damp paper towel) to prevent the pancakes from drying out.",
            "When you finish working on the first batch of dough pieces, you should have 9 double-pancake doughs. You should cook them before rolling out the rest of the dough pieces. Because the pancake dough is very moist and tender, the pancakes will stick together if let sit for too long. On the other hand, if you’re cooking with your family or friends, you can have someone else help you cook the pancakes while you work on the rest of the dough.",
            "Prepare two plates beside the stove.",
            "Heat a heavy skillet over medium high heat until hot. Turn to medium low heat. Place a pancake in the center and let cook until the surface puffs up and the bottom side shows small light-brown spots, about 30 to 40 seconds.",
            "Flip and cook the other side. The whole process should take 1 minute or less. The finished pancake should be tender, springy, and slightly crispy on the surface. It should not feel dry.",
            "If the pan is too hot, the pancakes will burn too quickly before they puff up. If the pan is not hot enough, the pancakes will dry out due to the long cooking time. Adjust the heat of the pan and keep the total cooking time for each double pancake under 1 minute.",
            "Transfer the cooked pancakes to a plate to cool. Place another raw double pancake into the skillet. While cooking that pancake, split the just-finished double pancake in two by peeling off the top layer. If the pancake is too hot to touch, you can wait a bit longer and cook other pancakes first. Since we brushed oil between the pancakes, it should be very easy to separate them. Place the separated pancakes on top of each other on the other plate. Repeat the process until you’ve finished 30 pancakes. Cover the pancakes with a damp paper towel to keep them moist.",
            "If you will be serving the pancakes immediately after cooking, you can serve them directly. They will be very tasty, even after they’ve cooled off.",
            "You can make the pancakes ahead of time and reheat them when you’re ready to serve the meal.",
            "To serve them the next day or within the next few hours, let the pancakes stay covered, and wait until they’ve cooled off. Transfer them to an air-tight container and store them at room temperature for up to half a day, or in the fridge overnight.",
            "To serve the pancakes, place them onto a heatproof plate or a bamboo steaming rack. Steam until hot, 3 to 5 minutes. Serve immediately.",
            "If you will serve the pancakes a few days later, you can freeze them. Let the pancakes cool off completely. Wrap tightly with plastic wrap and seal in a ziplock bag. Store in the freezer for up to a month.",
            "To serve the pancakes, reheat them by steaming until hot and tender, 10 to 15 minutes. You don’t need to thaw the pancakes before steaming.",
            "(Option 1) Serve with duck - you can cook pan-seared duck breast according to this recipe (minus the sauce). Serve the duck breast, hoisin sauce, green onions, and sliced cucumber with the pancakes. If you prepare the pancakes ahead of time, you can easily serve a Peking duck dinner for four in just 30 minutes.",
            "(Option 2) Serve with moo shu vegetables or other stir-fried veggies (vegetarian meal - refer to the blog post above this recipe). If you’re cooking other stir-fried veggies, try to select veggies with lower moisture content (such as root vegetables).",
            "(Option 3) Serve with scrambled eggs, green onion, and hoisin sauce - this is the easiest way to enjoy these fresh pancakes.",
            "(Option 4) Serve with crispy chicken - Use this recipe to cook crispy chicken without deep-frying. Serve with hoisin sauce, green onion, and sliced carrot (or cucumber).",
        ]
    ),
    "Hand-Pulled Noodles": RecipeDetail(
        ingredients: [
            "2 2/3 cup all-purpose flour ((*Footnote 1))",
            "1/2 teaspoon salt",
            "1 cup water (, room temperature)",
            "Vegetable oil to coat the dough",
        ],
        steps: [
            "Combine the water and salt in a small bowl. Stir to dissolve the salt.",
            "Add the flour into a large bowl. Bit by bit, pour the water into the flour, mixing with a pair of chopsticks or a spatula as you go.",
            "Once all the water is added, the dough should be in shaggy threads with little/no dry flour in the bowl. Begin pressing the dough together. If you find the dough is too dry and there’s still dry flour that’s hard to incorporate into the dough, drizzle more water onto the dry flour and mix it again, until there’s no dry flour left. Knead the dough until a rough, firm ball is formed, about 2 minutes.",
            "Cover the bowl with plastic wrap and let it rest for 20 minutes.",
            "Once the dough is rested, knead it again until it becomes smooth, 1 to 2 minutes.",
            "Mix the flour and salt in the bowl of the KitchenAid mixer and add the dough hook. Turn it to the mix setting. Slowly drizzle the water down the side, all along the bowl. This should take about 1 minute. Once the water is incorporated, turn to setting 2 and knead until a rough dough ball is formed, another 2 to 3 minutes.",
            "Cover the dough with plastic wrap and let it rest for 20 minutes.",
            "Either knead in the machine on setting 4 for 30 seconds or by hand for 1 to 2 minutes. Then shape the dough.",
            "(Optional) If you plan to store/freeze the dough, coat the dough with oil and store it in a sealed plastic bag. Refrigerate for up to 2 days or freeze for up to 3 months.",
            "FOR THIN NOODLES: Divide the dough to halves and roll each dough into a 1/2” (1 cm) thick oval.",
            "FOR FLAT NOODLES: Divide the dough to halves and roll each and roll each dough into a 1/4” (1/2 cm) thick oval.",
            "FOR WIDE NOODLES: Cut the dough into 8 pieces. Roll each piece into approximately 3”x5” (8x13 cm) ovals, 1/4” (1/2 cm) high.",
            "Coat the dough(s) generously with oil and cover with plastic. Let rest for 2 hours.",
            "Bring a medium-sized pot of water to a boil.",
            "FOR THIN NOODLES: Cut long the longer side of the oval, slicing the dough into 1/2” (1 cm) wide strips and rolling each piece slightly to the side with each cut to prevent them from sticking together. Cover the cut pieces with the plastic again to prevent them from drying out. Starting with the first strip you cut off, pick it up on both ends. (*Footnote 2) In one swift motion, tug the noodle about an arm’s length and gently bounce it on the working surface once or twice until it forms a long, thin noodle. Rest the noodle on your working surface as you fold it over, so that both ends are in one hand. Hook the other side with your thumb. Give it a couple light tugs and bounces until the noodles get longer and reach the desired thin shape. Then pull off the thick ends collected in one hand and lay the noodle out on the working surface. Repeat with the rest of your noodles.",
            "FOR FLAT NOODLES: Cut along the longer side of the oval, slicing the dough into 1 1/2” (3 cm) wide strips. Cover the cut pieces with the plastic again to prevent from drying out. Starting with the first strip you cut off, pick it up on both ends. (*Footnote 2) In one swift motion, tug the noodle to about an arm’s length and gently bounce it on the working surface once or twice. Rest the noodle on your working surface for 10-20 seconds, then give it a couple extra-light tugs and bounces until it forms a flat long noodle. Then pull off the thick ends and lay the noodle out. Repeat with the rest of your noodles. Drop the noodles into the boiling water, a few at a time, and cook for 1 to 1.5 minutes.",
            "FOR WIDE NOODLES: One at a time, grip the short ends of a strip (*Footnote 2) and pull it apart in one swift motion until the dough feels taut. It should be between 1 to 2 feet. Bounce it on the table a couple times. Pull off the thick ends and lay the noodle out, covering it with plastic to prevent drying out.",
            "Drop the noodles, a few pieces at a time, into the boiling water and cook for 1 to 1.5 minutes, until tender but still with a chewy texture. Do not cook too many noodles at a time! It’s hard to control the texture that way and the noodles might stick together.",
            "Store the cooked noodles: If you plan on reheating, you can slightly undercook the noodles (to al dente) to create a better texture once reheated. Store the noodles in an airtight container or a ziplock bag in the fridge for up to 3 days or in the freezer for up to 3 months.",
            "For frozen/refrigerated dough; let the frozen dough thaw in the fridge overnight. Transfer the refrigerated dough to room temperature. Rest for 2 hours. The dough will become super soft and can be gently shaped, rested for another 10 minutes or so, and pulled. Cook according to the instructions above.",
            "To reheat, bring a pot of water to a boil and add the cooked noodles. Separate with a pair of chopsticks and cook until the noodles are just heated through.",
            "For a quicker and lazier reheating method (for leftovers), reheat the refrigerated noodles in the microwave until heated, then quickly rinse the noodles with tap water in a colander. Drain the water thoroughly before serving.",
            "If you plan to use the thin noodles for fried noodles, you don’t need to reheat them before using. Thaw them if frozen. Then run the noodles with tap water in a colander and separate gently with chopsticks. Drain thoroughly before using for stir fried noodles.",
        ]
    ),
    "Scallion Pancakes": RecipeDetail(
        ingredients: [
            "2 cups all-purpose flour",
            "1/2 teaspoon salt",
            "1/2 cup boiling water",
            "1/4 cup cool water",
            "1/3 cup all-purpose flour",
            "1/4 cup peanut oil ((or your favorite oil like olive oil, melted coconut oil, melted butter, or melted chicken fat etc.))",
            "3/4 teaspoon salt",
            "8 green onions (, split down the middle and chopped (yield 1 cup))",
            "Vegetable oil for pan frying",
            "1 1/2 tablespoon soy sauce",
            "1 tablespoon Chinkiang vinegar ((or rice vinegar))",
            "1/4 teaspoon sugar",
        ],
        steps: [
            "OPTION 1 - USING YOUR HANDS: Combine the flour and salt in a big bowl. Stir to mix well. Slowly drizzle in the hot water while mixing it with a pair of chopsticks (or a fork), until the water is fully absorbed. Slowly drizzle in the cool water, continuing to stir until many dough flakes form. Press the dough together, and try to combine the wet dough with the dry flour. Drizzle in a little extra water if there is any dry flour remaining. Knead until a firm ball is formed, about 5 minutes. Cover and let rest for 20 minutes.",
            "OPTION 2 - USING A MIXER: Combine the flour and salt in the mixer bowl with the dough hook attachment. Turn it to the mix setting and slowly drizzle in the hot water followed by the cool water. After a minute of mixing, drizzling in a little extra water if there is any dry flour remaining. Turn to setting 4 and knead until a ball of dough is formed, about 3 minutes. Cover and let rest for 20 minutes.",
            "While the dough is resting, combine the flour, oil, and salt in a small bowl. Mix until a smooth paste is formed.",
            "If making the dipping sauce, combine all the ingredients with 1 tablespoon of water in a small bowl and mix until the sugar is dissolved.",
            "When the dough is done resting, knead for another minute until it is smooth. Cut the dough into 6 even pieces, about 76 grams per piece. Form the dough into balls using your hands.",
            "Work on one dough ball at a time, covering the rest with plastic wrap to prevent drying out. Roll each dough ball into a thin rectangle with a rolling pin, aiming for around 6x10” (15x25 cm). Lift and turn the dough regularly as you roll it to prevent sticking. Spoon about 1 tablespoon of the filling onto the dough and spread it evenly with the back of a spoon, leaving about 1” (2.5 cm) on top and the left end without the filling. Sprinkle 2 heaping tablespoons of green onions onto the paste, concentrating most of it towards one side of the length and one side of the width, creating a loose L shape (see the blog post above for the step-by-step pictures).",
            "Begin rolling the dough from the longer side of the dough where the green onions are concentrated, until you have one long tube. Lightly flatten the tube using your hand. Pinch the side with more green onion to seal it. Take the sealed side and gently pull and roll it towards the unsealed side, using your hand to smooth out the dough to push any large air bubbles out. Tuck the loose end under the rolled bun. Gently press down on the round disk with your hand to seal the pancake.",
            "Set the formed pancake aside and cover it with plastic wrap. Repeat steps 4 and 5 until each pancake is ready.",
            "Roll each prepared pancake into a circle, about 7-8” (17-20 cm) wide. Flip and move it as you do to prevent sticking. Don’t worry if air bubbles burst through or some green onions fall out.",
            "If you plan to store the pancakes and cook them later, place each pancake onto a piece of parchment paper and stack them. Transfer the pancakes to a large ziplock bag, squeeze out as much air as possible, and seal the bag. You can freeze the pancakes for up to 3 months.",
            "Heat a 9” (23 cm) cast iron pan (or a nonstick skillet) over medium-high heat and add enough oil to fully coat the bottom. Once the oil is hot, add a pancake. Use a pair of chopsticks (or a spatula) to swirl the pancake around to spread the oil and prevent sticking, for a few seconds. Cover the pan and turn the heat down to medium. Let the pancake cook, covered, for 1 minute. Remove the lid and flip the pancake, cover, and cook for another minute. Remove the lid. Use a spatula to press the pancake, to ensure even browning. Continue to cook, flipping regularly, until both sides are crisp and browned, about 3 minutes. Turn to medium-low heat if the pan gets too hot. Transfer the pancake to a cooling rack or a cutting board to cool. Repeat to cook all the pancakes you plan to serve.",
            "Once the pancakes are slightly cooled enough to handle, cut into 6 pieces and transfer to a serving platter. Serve hot with the dipping sauce as an appetizer.",
            "Let the frozen pancakes thaw for 10 minutes then proceed from step 8.",
            "Place the leftover pancakes in a ziplock bag by stacking them together. Store in the fridge up to 3 days. To reheat, add a pancake to a pan and heat over medium heat, cook, flip occasionally until the pancakes turn warm throughout.",
        ]
    ),
    "Biang Biang Noodles": RecipeDetail(
        ingredients: [
            "1 tablespoon peanut oil ((or vegetable oil))",
            "2 tomatoes (, diced)",
            "Pinch of salt",
            "1 tablespoon tomato paste",
            "1 tablespoon light soy sauce",
            "1 tablespoon Chinkiang vinegar",
            "1/4 teaspoon dark soy sauce ((optional))",
            "1 teaspoon sugar",
            "1 teaspoon sesame oil",
            "1 green onion (, white part minced, green part sliced for garnish)",
            "3 cloves garlic (, grated)",
            "1 tablespoon Chinese chili flakes",
            "1 tablespoon toasted white sesame seeds",
            "1/4 teaspoon cumin powder",
            "1/4 teaspoon ground Sichuan peppercorn ((optional but highly recommended))",
            "3 tablespoons peanut oil ((or vegetable oil))",
            "2 bundles (150 g) dried knife shaved noodles ((or 400 g fresh wide noodles or hand pulled-noodles))",
            "4 heads baby bok choy (, tough ends removed and cut into large bite size pieces (*Footnote 1))",
            "Chopped cilantro for garnish ((Optional))",
        ],
        steps: [
            "Add 1 tablespoon of oil into a medium-sized skillet and heat over medium heat until hot. Add the tomato and a pinch of salt. Chop and stir the tomatoes until the tomato pieces break down, 4 to 5 minutes. Pour in a small splash of water if the pan becomes too dry. Add the tomato paste. Keep stirring for 1 minute until the tomato paste is evenly mixed. Transfer to a bowl and set aside.",
            "Combine the soy sauce, Chinkiang vinegar, sesame oil and sugar in a large bowl. Stir to mix until the sugar has dissolved.",
            "Bring a large pot of water to a boil. Blanch the baby bok choy for 2 minutes or so, until tender. Transfer the bok choy to a plate to cool off.",
            "In the same pot, boil the noodles according to instructions. Once the noodles are done, quickly rinse with running tap water to stop cooking. Then drain thoroughly and transfer to the bowl with the soy sauce mixture. Stir to combine.",
            "Add the white part of the green onion, garlic, chili flakes, sesame seeds, cumin powder and ground Sichuan peppercorn on top of the noodles.",
            "Heat the oil in a small saucepan over medium heat until hot. Immediately pour the hot oil over the noodles, covering as much seasoning as possible. Then stir everything together to mix well while the oil is still hot.",
            "Add the tomato sauce and mix again (if using).",
            "Garnish with baby bok choy and cilantro. Serve immediately.",
        ]
    ),
    "Lanzhou Beef Noodles": RecipeDetail(
        ingredients: [
            "2 to 3 lb beef shin bones ((*see footnote 1))",
            "2 lb untrimmed beef flank (, or brisket, or round roast (*see footnote 2), cut into 3” (7 cm) pieces)",
            "2 Chinese scallions (or 4 green onions, white part, cut to 4” (10 cm) pieces)",
            "1 thumb ginger (, sliced)",
            "5 cloves garlic",
            "5 Chinese dried chili peppers",
            "5 whole cloves",
            "2 bay leaves",
            "1 teaspoon whole Sichuan peppercorn",
            "1 teaspoon fennel seed",
            "1 whole nutmeg",
            "1 star anise",
            "1 cinnamon stick",
            "2 teaspoons salt ((or to taste))",
            "1 small daikon radish (, peeled and sliced to 1/2” (5 mm) quarters)",
            "1.3 to 2 lbs fresh Lanzhou noodles",
            "Homemade Chinese chili oil ((for serving))",
            "Extra salt ((for serving))",
            "Cilantro (, chopped (for garnish))",
            "Green onion (, sliced (for garnish))",
        ],
        steps: [
            "Add the beef bones and meat into a large pot. Add 8 cups of cold water. Heat over medium-high heat until brought to a boil. Stir occasionally to prevent the bottom from sticking. When it starts to boil, turn to medium heat. Skim the brown foam from the top and discard it. Boil and skim until the broth turns almost clear, 10 minutes or so.",
            "Transfer the meat and bones into the Instant Pot, and pour in all the broth. You can keep cooking on the stovetop if not using an Instant Pot. (*Footnote 3)",
            "(Optional) Add the cloves, Sichuan peppercorn and star anise into a tea infuser. Submerge the tea infuser in the broth.",
            "Add the scallion, ginger, garlic, dried chili pepper, bay leaves, fennel seed, nutmeg, cinnamon stick into the Instant Pot. Set the pressure on high, timer for 1 hour. Once done, let pressure release naturally. If you want to use fast release, do a natural release for at least 20 minutes first, to prevent it from spilling.",
            "Once done, remove and discard the spices, aromatics, and beef bones using a pair of tongs. You can also strain the broth if that is easier. But you need to pick out the meat separately.",
            "You might find a thick layer of oil floating on top of the soup (depending on the fattiness of the beef). Use a ladle to skim the oil off according to your preference (*footnote 4).",
            "Add salt and mix well. Taste the broth and adjust seasoning if needed. The broth should taste a bit salty by itself, so it will be perfect after adding the noodles. You can also adjust the seasoning later, after assembling the bowls.",
            "Turn on the saute function if using Instant Pot. Add the daikon radish and cook until tender, 10 minutes or so.",
            "Boil the noodles according to package instructions.",
            "Add noodles to each serving bowl, then pour in the broth. Top noodles with beef, a few pieces of daikon radish, and some cilantro. Serve immediately with chili oil and soy sauce on the side. Enjoy hot as a main dish.",
        ]
    ),
    "Chinese Beef Noodle Soup": RecipeDetail(
        ingredients: [
            "2 to 4 tablespoons vegetable oil",
            "2 pounds beef chuck roast ((or short ribs))",
            "2 green onions",
            "10 cloves garlic (, smashed)",
            "2 pieces ginger (, minced)",
            "1 teaspoon Sichuan peppercorn",
            "3 tablespoons doubanjiang (spicy fermented bean paste)",
            "3 tablespoons tomato paste",
            "1/2 cup Japanese sake",
            "2 tablespoons soy sauce",
            "2 teaspoons brown sugar ((or white sugar))",
            "1/2 teaspoon curry powder",
            "1/2 teaspoon cumin powder",
            "2 potatoes (or 1 daikon radish, or a few carrots) ((Optional))",
            "4 servings noodles",
            "4 servings Asian beef stock ((or store bought beef stock))",
            "Green salad leaves or blanched bok choy to garnish ((Optional))",
        ],
        steps: [
            "If you aren’t cooking the Asian beef stock as well, start by browning the beef. You can achieve this either in the oven or on the stove top. If you have already cooked my Asian beef stock recipe, skip ahead to step 5.",
            "To brown the beef in the oven, preheat oven to 400 degrees F (200 C). Cut beef into 1.5 to 2 inch chunks (about 4 to 5 cm). Spread the beef in a roasting pan. Spray a thin layer of oil onto the meat. Roast for 20 minutes. Take out the beef and flip. Cook until the beef turns to an even golden brown color, about 20 minutes.",
            "To brown the beef on stove top, heat a large heavy skillet with 2 tablespoons vegetable oil until hot. Add beef. Let cook without moving for a minute. Continue cooking until the bottom side turns golden. Flip to cook the other sides, until the beef is evenly browned.",
            "Transfer the cooked beef to a plate. Add 1/4 cup hot water to the baking tray (or the skillet). Scrape off the brown bits, so you can transfer them to the braising pot later.",
            "Heat a dutch oven (or a wok) with 2 tablespoons oil over medium heat until warm. Add green onion, garlic, ginger, and Sichuan peppercorn. Cook until the garlic turns a plate yellow color. Turn to medium low heat. Add doubanjiang and tomato paste. Stir and cook until the bean paste releases oil, 2 to 3 minutes.",
            "Add beef to the pot. Stir a few times to coat beef evenly with the sauce. Add back the brown bits from step 4, if any.",
            "Add 2 cups water, Japanese sake, soy sauce, brown sugar, curry powder, and cumin powder to the the pot. Stir to mix well. Turn to medium high heat. Cook until almost bringing to a simmer. Turn to low heat and cover. Let the beef cook at a very gentle boil until it starts to get tender, about 1 hour 20 minutes.",
            "Add veggies of your choice (potato, daikon radish, and/or carrot). Stir to mix well. Cover and cook until both the veggies and the beef turn tender, 20 to 30 minutes.",
            "You can cook the beef stew one day before serving, store it in an air-tight container in the fridge, and reheat right before serving.",
            "When you’re ready to serve the noodles, bring a large pot of water to a boil and cook the noodles according to the instructions.",
            "In another pot, add about 6 cups beef stock (add less stock plus water to dilute, if you’re using homemade condensed beef stock. Cook until bringing to a boil.",
            "Divide beef stock among 4 bowls for serving. Add a few spoonfuls of sauce from the braised beef. Taste the broth. It should be a bit salty and very rich. Add salt if necessary. Mix well. Add noodles, top with a few chunks of beef and veggies, and garnish with green onions and greens (if using).",
            "Serve as main immediately.",
        ]
    ),
    "Tea Eggs": RecipeDetail(
        ingredients: [
            "12 large eggs",
            "4 tablespoons light soy sauce ((or soy sauce))",
            "2 tablespoons dark soy sauce ((or soy sauce))",
            "2 bay leaves",
            "1 teaspoon Sichuan peppercorns",
            "1 star anise",
            "1 small cinnamon stick",
            "2 teaspoons sugar",
            "1 teaspoon salt",
            "2 black tea bags ((or 2 tablespoons black tea leaves))",
            "2 1/2 cups water",
        ],
        steps: [
            "Mix all the marinade ingredients in a small pot. Cook over medium heat until bringing to a boil. Turn to medium-low heat. Simmer for 10 minutes. Remove the pot from your stove and let cool completely. Once done, remove and discard the tea bags.",
            "To boil the eggs, heat a pot of water (enough to cover all the eggs) over high heat until boiling. Turn to low heat. Carefully place the eggs in the pot using a ladle, to prevent the eggs from cracking.",
            "Boil 5 minutes for soft-boiled eggs, 7 minutes for medium eggs, or 10 minutes for hard-boiled eggs.",
            "While cooking the eggs, prepare an ice bath by combining ice and tap water in a big bowl.",
            "Once the eggs are cooked, immediately transfer them to the ice bath to cool for 2 to 3 minutes. If you don’t have ice on hand, simply run cool tap water over the eggs for a couple minutes until they cool down.",
            "Gently crack the eggs using the back of a spoon. You want to make sure the egg shells are cracked enough so the marinade will reach the interior, without cracking the eggs apart (especially if you made soft boiled eggs). If you’re in a hurry, you can also peel the eggs and marinate them peeled. The eggs will be ready in 12 hours this way.",
            "Transfer the eggs to a quart-size ziplock bag, then carefully pour in the marinade along with the dry ingredients. Marinate overnight for peeled eggs, or 24 hours for cracked “marble” eggs.",
            "Peel the eggs and enjoy them cold or at room temperature!",
            "You can store the leftover eggs in the marinade for 4 to 5 days in the fridge. The marinade will help with preserving the eggs. Note, the eggs will become more flavorful and saltier over time.",
        ]
    ),
    "Braised Beef Shank": RecipeDetail(
        ingredients: [
            "2 to 3 lbs (1 to 1.4 kg) beef shank (shin) (, sliced to large bite-size pieces (*Footnote 1))",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "4 green onions (, cut into 2” (5 cm) long pieces)",
            "1 thumb ginger (, sliced)",
            "1 teaspoon Sichuan peppercorns",
            "2 tablespoons soybean paste ((or sweet bean paste) (*Footnote 2))",
            "2 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "4 Chinese dried chili peppers",
            "3 bay leaves",
            "3 cloves",
            "2 whole star anise",
            "1 cinnamon stick",
            "1 whole nutmeg ((or 1/4 teaspoon nutmeg powder))",
            "1 teaspoon fennel seeds",
            "1 black cardamom ((optional))",
            "1 tablespoon rock sugar ((or regular sugar))",
            "1 teaspoon salt",
        ],
        steps: [
            "Add the beef into a big pot (or an Instant pot or a pressure cooker). Add 4 cups of cold tap water to cover the beef. Add the green onions, ginger, and Sichuan peppercorns. Cook over medium-high heat until it reaches a boil. Stir occasionally to prevent from sticking. Turn to medium heat. Boil for 10 minutes while skimming the brown foam off the top and discarding the foam.",
            "Combine the soybean paste, light soy sauce, and dark soy sauce in a small bowl. Mix thoroughly until the soybean paste has completely dissolved into a smooth sauce.",
            "To use an Instant Pot or pressure cooker: Add the soybean sauce mixture and the rest of the braising ingredients. Seal the pot. For the Instant Pot, pressure cook on high for 35 minutes. For a pressure cooker, heat over medium heat until it reaches high pressure. Turn to low heat, then cook at high pressure for 35 minutes (*Footnote 1). Once done, release the pressure naturally by letting the pot sit for 20 minutes.",
            "To cook on stovetop: add the soybean sauce mixture and the rest of the braising ingredients to the pot. Cook over medium-high heat until it reaches a simmer. Turn to medium-low heat. Simmer, covered, until the beef turns tender but is not falling apart, 1.5 to 2 hours.",
            "The beef is cooked now. But for the best result, transfer the beef, broth, and all the spices to a large container. Once it has cooled completely, cover the container and store it in the fridge overnight before serving.",
            "To serve, slice the beef into thin pieces. Serve it by itself, in a salad, or as a noodle / rice bowl topping.",
        ]
    ),
    "Guo Kui": RecipeDetail(
        ingredients: [
            "2 tablespoons softened butter ((or shortening))",
            "1 tablespoon all-purpose flour",
            "1/4 teaspoon salt",
            "1/4 teaspoon freshly ground Sichuan peppercorn",
            "4 oz pork (, finely ground)",
            "1 teaspoon light soy sauce",
            "1 teaspoon toasted sesame oil",
            "1 teaspoon grated ginger",
            "1/2 teaspoon salt",
            "1/4 teaspoon Sichuan peppercorn (, freshly ground)",
            "1 green onion (, white part only, finely chopped)",
            "2 tablespoons warm water ((110°F))",
            "1/4 teaspoon active dry yeast",
            "Pinch sugar",
            "200 g (1 1/3 cups) all-purpose flour",
            "1/2 teaspoon salt",
            "1/2 cup boiling water",
            "1/4 cup vegetable oil ((plus extra for shaping))",
            "3 tablespoons white sesame seeds ((in a shallow bowl for dipping))",
        ],
        steps: [
            "Filling 1: Mix the butter (or shortening), flour, salt, and pepper together until smooth. Set aside.",
            "Filling 2: Combine ground pork, light soy sauce, sesame oil, ginger, salt and ground Sichuan peppercorn. Beat until the ingredients are well incorporated and the pork is streaky. Add the chopped green onion whites. Mix to evenly distribute and set aside.",
            "Dough: Combine the yeast and a pinch of sugar in a small bowl and add 2 tablespoons warm water. Stir briefly and let the yeast activate for 5 to 10 minutes.",
            "Knead the dough using a mixer: While the yeast activates, combine the flour and salt in the bowl of a stand mixer. Slowly drizzle in the 1/2 cup of boiling water while stirring to evenly distribute. Once the water is incorporated, add the dough hook to the mixer and begin kneading on setting 2. Add the yeast to the dough and continue kneading, scraping any dry flour from the bowl. Turn the setting to 4 once the water is fully incorporated and knead until the dough is sticking to itself and somewhat smooth, about 2 to 3 minutes.",
            "Knead the dough using your hands: Combine the flour and salt in a medium bowl. Slowly drizzle in the 1/2 cup of boiling water while stirring to evenly distribute. Once the water is incorporated, slowly drizzle the yeast mixture into the dry flour, mixing until the water is fully incorporated and soft dough flakes form. Start to gather the dough using your hands until a ball forms and there’s little dry flour left. Transfer the dough to a clear working surface. Knead until the dough is somewhat smooth, about 5 minutes.",
            "The dough should be a little soft but keep its shape and not be sticky at all. If your dough is too soft, sprinkle more flour onto it and knead again.",
            "First rest: Oil a bowl, add the dough, and cover. Let the dough rest for 15 minutes.",
            "Second knead and rest: Knead the dough briefly, 30 seconds to 1 minute, to smooth out the dough, then divide it into 6 even pieces. Round each piece into a ball, oil each piece, place them back into the bowl and cover, and let rest for another 5 minutes.",
            "Create layered dough: One at a time take a piece of dough and roll it out into a 3x10” (7x25cm) oval. Gently spread 1 teaspoon of “Filling 1 - butter flour paste” across it, leaving a little space along the edges and bottom. Roll the top of the oval towards yourself, occasionally lifting and tugging the dough as you go. Once fully rolled up, pinch both ends to seal well. Set aside and repeat with the remaining pieces of dough. Cover the dough with plastic wrap to prevent it from drying out.",
            "Form with meat filling: Beginning with the first piece that was rolled up, flatten it with your palm. With the roll up dough parallel to the table, roll the dough out to 3x12” (7x30cm). Take 1 1/2 tablespoons of “Filling 2 - ground pork mixture” and spread it onto the dough, concentrating it slightly more at the top than at the bottom and again leaving a small edge free along the sides. Roll it up with the same motion from step 6, taking extra care to pull and stretch as you roll to create more layers. Tuck the end of the dough into one of the swirled sides, then pinch both ends to seal. Turn the rolled dough on its side (swirls facing up and down) and press it down to make a fat disc. The dough will likely be taut at this point so don’t worry if it springs back a bit. The gluten will rest while you roll the remaining pieces. Cover the formed bread with plastic wrap. Repeat with the remaining dough.",
            "Coat with sesame seeds: Again beginning with the first piece you rolled, take the disc and dip the swirled sides into the sesame seeds. Then flatten the dough again with your palm and roll gently into a 5” (12cm) disc, trying to keep the filling sealed in without tearing the dough (*Footnote 1). Set aside, covered, and repeat with the remaining dough. Always keep the assembled bread and unused dough covered with plastic wrap to prevent it from drying out.",
            "Cooking: Preheat the oven to 325°F (160oC). Preheat a large skillet over medium heat and add 1/4 cup of oil. Prepare a baking tray lined with parchment.",
            "Once the oil is heated, add as many guokui as will fit, first placing them where the oil has concentrated in the pan then sliding them to a less oily section. Let fry for about 30 seconds then begin flipping regularly. Once both sides are crispy and evenly browned, remove from the skillet and place on the lined baking tray. Continue until all the guokui are fried, adding more oil as necessary.",
            "Bake the guokui for 15 to 20 minutes, until very crispy and evenly browned. Serve while still warm.",
        ]
    ),
    "Bing Bread": RecipeDetail(
        ingredients: [
            "500 grams / 17 ounces all-purpose flour (*see conversion to cups)",
            "1 cup boiling water",
            "1/2 cup room temperature water (*see footnote 1)",
            "4 tablespoons peanut oil (or lard or chicken grease)",
            "1 and 1/2 teaspoons salt",
        ],
        steps: [
            "Add flour into a large bowl.",
            "Slowly add boiling water and mix the flour with a pair of chopsticks (or a spatula), until water is fully absorbed.",
            "Slowly add room temperature water, continuing to mix, until water is fully absorbed and there is no dry flour on the bottom of the bowl.",
            "Dust both hands with flour and start to knead the mixture, until dough forms. The dough should be quite sticky and difficult to lift from the bowl.",
            "Dust a working surface (or a large cutting board) with flour. Transfer the dough to the working surface and knead for another 5 minutes.",
            "Dust the same big bowl with flour and transfer the dough to the bowl. Cover the dough with a wet clean kitchen towel and place a lid on the bowl. Let rest for 1 hour.",
            "Dust both hands and the working surface again with flour. Transfer the dough to the working surface.",
            "Knead the dough for another 3 minutes, until the texture becomes smooth.",
            "Divide the dough in half. Divide each half further into 4 equal pieces (*see footnote 2). Transfer half of the dough into the bowl and cover with the wet kitchen towel, to keep it from drying out.",
            "Work on the dough pieces one at a time. Use a rolling pin to roll the dough into a thin rectangular sheet, about the thickness of a dollar coin. Lift up the thin sheet once in the middle of rolling, to prevent the dough from sticking to the working surface.",
            "Brush a thin layer of oil on the dough. Evenly spread salt on top.",
            "Fold the dough accordion-style back and forth, until the dough becomes a long strip. Flip the dough to let it stand, oiled side up. Tug and roll the dough from one end like a swirl, until it’s shaped like a snail shell. Set aside.",
            "Continue to work on the rest of the dough pieces in the same way.",
            "Heat a tablespoon of oil in a nonstick skillet over medium heat until warm.",
            "Press the dough until it’s shaped like a disk, about 0.6mm (1/5 inch) thick.",
            "Place the dough in the skillet. Grill each side for about 2 minutes, until both sides turns golden brown. If the skillet starts to get too hot, turn to low heat. Transfer the bing bread to a plate. (*see footnote 3) Continue to press and cook the rest dough pieces.",
            "Serve warm as a side.",
            "Store leftovers in an airtight container in the fridge for up to 3 days, or in the freezer for up to a month.",
            "To reheat, heat a nonstick skillet over medium heat until warm. Place the bread inside. When the skillet is hot, flip the bread. Add 1 tablespoon water and cover the skillet immediately. Turn to low heat and cook until heated through.",
        ]
    ),
    "Ge Da Tang": RecipeDetail(
        ingredients: [
            "1 cup all-purpose flour",
            "1/4 cup warm water ((*Footnote 1))",
            "1 tablespoon vegetable oil",
            "1/2 lb ground pork",
            "2 scallions (, sliced, white and green parts separated)",
            "2 pieces ginger",
            "3 tomatoes (, sliced into bite-size pieces)",
            "1 1/2 tablespoons light soy sauce ((*Footnote 3))",
            "1/2 teaspoon sugar",
            "4 cups chicken stock",
            "2 heads baby bok choy (, white part sliced into 1/2” pieces and green part sliced into 1” pieces)",
            "2 eggs (, beaten)",
            "1 teaspoon chicken bouillon powder",
            "1/2 teaspoon ground white pepper",
            "1 tablespoon toasted sesame oil",
        ],
        steps: [
            "Add flour into a big bowl. Very slowly drizzle water in batches onto the dry flour, and whisk with a pair of chopsticks. Try to mix in a way that creates many small dough pieces, without them clumping together. It’s important to add a very small amount of water at a time, and stop, then mix very thoroughly. At the end, there should be little or no dry flour left, and small dough flakes ranging from pea-sized to blueberry-sized (*Footnote 2).",
            "Heat oil in a medium pot (4-qt) over medium-high heat until hot. Add the ground pork. Cook and chop the pork into small pieces until cooked through and the surface is lightly browned, 4 to 5 minutes.",
            "Add the scallion whites and ginger. Stir a few times to release fragrance. Add the tomato, light soy sauce and sugar. Cook and stir until the tomato starts to fall apart.",
            "Add the chicken stock and bring to a boil. Turn to medium heat. Add the dough flakes in by slowly pushing them into the pot, dropping them into empty space so the dough doesn’t clump together. If the dough starts to clump together, immediately use a pair of chopsticks to stir and separate the dough into small pieces. After all the dough pieces are added, keep stirring to make sure they don’t clump together. Cook for 2 to 3 minutes until the dough is cooked through.",
            "Add the baby bok choy and cook for 1 to 2 minutes, until wilted.",
            "Turn to medium-low heat. Slowly drizzle in the beaten eggs. Let the eggs sit for 30 seconds, then stir to form ribbons.",
            "Turn off the heat. Add the chicken bouillon, white pepper, sesame oil and scallion greens. Stir to mix well. Taste the soup and adjust seasoning if needed. Serve hot as a main dish.",
        ]
    ),
    "Braised Pork Trotters": RecipeDetail(
        ingredients: [
            "3 to 4 lb pork trotters (, cut into large cubes (*Footnote 1))",
            "2 thumbs ginger (, thickly sliced and divided)",
            "4 tablespoons Shaoxing wine ((or dry sherry))",
            "3 tablespoons light soy sauce",
            "2 tablespoons dark soy sauce",
            "4 green onions (, cut into 4” pieces (or 2 Chinese scallions))",
            "5 dried Chinese chili peppers",
            "2 star anise",
            "4 cloves",
            "1 heaping tablespoon rock sugar ((or regular sugar))",
            "2 teaspoons salt",
        ],
        steps: [
            "Place the pork trotters and half of the ginger slices in a large pot and add cold tap water to cover. Bring the water to a boil. Stir occasionally to prevent the bottom from sticking. Continue boiling while skimming off the brown foam from the top until the broth is mostly clear, 10 to 15 minutes. Transfer the pork to an Instant Pot (or pressure cooker). If the boiling broth is clear and doesn't have a strong smell, transfer 5 cups of broth to the pot with the trotters, or until the broth almost covers everything. If the broth looks very cloudy and smells strong, discard the broth and add 5 cups of cold tap water. (*Footnote 2)",
            "Set the pressure to high and timer to 15 minutes for fall-off-the-bone tender pork (or 12 minutes for tender pork with some texture). Press start. (*Footnote 3)",
            "Once the Instant Pot is done cooking, release pressure naturally for at least 15 minutes. Then switch the valve to fast release. Transfer pork and the broth back to the large pot.",
            "Add the rest of the ingredients into the same pot and turn to medium-high heat. After bringing the broth to a boil, reduce to medium-low heat and simmer for 40 minutes or so, until the pork has absorbed a lot of flavor. Stir pork occasionally to avoid burning on the bottom.",
            "Transfer the pork to a large bowl. Use a ladle to remove and discard the solid spices and aromatics from the broth. Turn to medium-high heat to boil the broth until it reduces to half of the volume and gets thicker, 15 minutes or so. Keep an eye on the broth so it doesn’t reduce too much. The broth will continue to thicken when it cools down a bit, so you don’t need to reduce it too much.",
            "Add the trotters back to the pot and mix everything together. Serve hot as a main dish. You can store the leftovers in the fridge for 3 to 4 days, or in the freezer for up to 3 to 4 months.",
        ]
    ),
    "Jing Jiang Rou Si": RecipeDetail(
        ingredients: [
            "12 oz (340 g) pork tenderloin (or loin) (, cut into 1/4” thick matchsticks along the grain (*Footnote 1))",
            "1 tablespoon egg white",
            "1 tablespoon Shaoxing wine",
            "1/4 teaspoon salt",
            "1 tablespoon ginger (, finely minced)",
            "2 teaspoon cornstarch",
            "3 tablespoons sweet bean sauce",
            "2 tablespoons Shaoxing wine",
            "1 tablespoon soy sauce",
            "1 tablespoon sugar",
            "1 tablespoon water",
            "1 teaspoon sesame oil",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "2 green onions (, sliced)",
            "2 ” Chinese scallions (or regular scallion) (, the white part only, julienned into thin matchsticks)",
            "1 carrot (, julienned (Optional))",
            "1/2 cucumber (, julienned (Optional))",
            "1 small batch cilantro ((Optional))",
            "Tofu sheets (, or duck pancakes (*Footnote 3) (Optional))",
            "Steamed rice ((Optional))",
        ],
        steps: [
            "Add the pork, Shaoxing wine and egg white in a medium-sized bowl. Mix with your fingers until the pork is evenly coated. Add the rest of the marinating ingredients and keep mixing, until all the liquid is absorbed and the meat is evenly coated with cornstarch. Marinate for 15 minutes while preparing the rest of the ingredients.",
            "Combine the sauce ingredients in a small bowl. Stir until the sauce becomes smooth.",
            "Heat 1 tablespoon of oil in a large nonstick skillet until hot. Add the marinated pork. Use chopsticks to separate the strips so they overlap as little as possible. Cook, stirring occasionally, until the surface of all the pieces of pork has turned white, but the inside is still a bit pink. Transfer the cooked pork to a plate.",
            "Add remaining 1 tablespoon of oil and green onion. Stir a few times to release the fragrance, 20 to 30 seconds.",
            "Turn the heat to medium-low. Pour in the sauce mixture carefully. Let simmer for 2 minutes, or until the sauce starts to thicken and turn darker.",
            "Return the cooked pork to the pan. Immediately stir to mix everything so the pork is coated with the sauce, 1 minute or so. Then transfer everything to a serving platter.",
            "Option 1: Cut the tofu sheets into 3” (8cm) squares. Place the scallion on top of the pork and lay the tofu sheets on the side of the platter. To eat, add a small amount of pork and a few slivers of scallion onto the tofu sheet. Roll up and enjoy.",
            "Option 2: Lay a large tofu sheet on a working surface. Add carrot and cucumber onto one side of the sheet, then roll up the sheet to wrap in the vegetables. Use your knife to slice the tofu roll into 1” (2.5 cm) pieces. Make a second roll using the same method. Plate the cooked pork in the center of the plate with scallions on the top. Then place the rolled up vegetables around the pork. Serve hot.",
            "Option 3: Place the scallions on top of the pork. Serve hot over steamed rice.",
            "Option 4: Place the scallions on top of the pork. Serve hot with moo shu pancakes. To eat, add some pork and a couple pieces of scallion on the pancake and make a “burrito”.",
        ]
    ),
    "Ji Dan Bing": RecipeDetail(
        ingredients: [
            "150 g (1 cup) all-purpose flour",
            "1/2 teaspoon salt",
            "255 ml (1 cup + 1 tablespoon) water",
            "3 green onions (, sliced)",
            "1 tablespoon peanut oil ((or melted butter))",
            "Oil spray (, for cooking)",
            "4 eggs",
            "Toasted black sesame seeds (, for garnish)",
            "Sweet bean sauce ((or hoisin sauce))",
            "Chili garlic sauce (, for spiciness if preferred (Optional))",
            "6 pieces green leaf ((or romaine lettuce))",
            "6 hot dogs (, pan fried (or bacon strips))",
            "Shredded carrots and cucumber",
            "Sliced green onions (, for garnish)",
        ],
        steps: [
            "Combine the all-purpose flour and salt in a medium size bowl. Stir a few times to mix well. Slowly pour in the water while mixing, until it forms a smooth, runny batter. Add the peanut oil. Mix until fully incorporated. The batter should be quite runny, but not as runny as a crepe batter.",
            "Spray (or drizzle) a very small amount of oil onto a medium-sized or small nonstick skillet. Use paper towels to wipe the pan so the oil is very thinly coated.(*Footnote 1) Heat over medium heat until just hot and not smoking hot.",
            "Add about 1/3 cup of the batter to the pan. Immediately swirl the pan so the batter will spread out evenly into a thin round shaped pancake.(*Footnote 2)",
            "When the pancake is just set, crack an egg onto the center of it. Use a spoon to break the egg and spread it over the pancake. When the egg is still runny, sprinkle it with green onion and black sesame seeds. Cook over medium-low heat until the egg is mostly set and the bottom of the pancake just turns golden on the edges. Carefully flip the pancake. Cook for 20 to 30 seconds, until the egg is fully cooked. Transfer the pancake to a plate. Keep cooking the rest of the pancakes. Note, you might need to lower the heat while making the rest of the pancakes or remove the pan from the heat occasionally when adding the batter. If the pan gets too hot, the batter will set too quickly and will be difficult to spread out into a thin pancake.",
            "Brush the pancake with a thin layer of the sweet bean sauce (or hoisin sauce). You can add some chili garlic sauce if you prefer.",
            "The pancakes can be served as is. For a more filling meal, top with other ingredients such as lettuce leaves, hot dogs, bacon, carrots and / or cucumber. Garnish with extra green onion. Roll up and enjoy!",
        ]
    ),
    "Moo Shu Pork": RecipeDetail(
        ingredients: [
            "A small pinch of dried wood ear mushrooms (black fungus (yields 1 cup after rehydration))",
            "A small handful of dried lily flowers (yields 1/2 cup after rehydration) ((Optional))",
            "4.5 ounces (130 grams) pork tenderloin ((1/4 of a whole tenderloin))",
            "2 teaspoons Shaoxing wine",
            "1/4 teaspoon sea salt",
            "1/8 teaspoon white pepper powder",
            "1/2 teaspoon cornstarch",
            "1/4 cup chicken stock",
            "1 tablespoon light soy sauce",
            "1/2 teaspoon Chinkiang vinegar",
            "1/2 teaspoon sesame oil",
            "1/4 teaspoon sea salt ((Optional) (*footnote 1))",
            "1 teaspoon cornstarch",
            "3 tablespoons peanut oil ((or vegetable oil))",
            "2 eggs (, beaten)",
            "1/4 white onion (, sliced (or 2 green onions, chopped))",
            "1/2 teaspoon ginger (, minced)",
            "1/2 seedless cucumber (, sliced into diamond shape)",
        ],
        steps: [
            "Add dried wood ear mushrooms into a small bowl and hot water to cover. Add dried lily flowers into another small bowl and hot water to cover. Rehydrate for 20 to 30 minutes, or until ingredients turn tender. Check after 10 minutes to make sure the water still covers all the ingredients. If the water gets cold, change to another batch of hot water. Gently rub with hands and rinse to remove the dirt. Remove tough ends of the mushrooms and flowers. Drain and place in a small bowl. It is OK if the ingredients are still a bit wet.",
            "Slice pork against the grain into bite-sized pieces, as thinly as possible.",
            "In a small bowl, combine pork, Shaoxing wine, salt, and white pepper. Gently mix by hand so that the seasonings coat the meat evenly without tearing the meat apart. Add cornstarch. Continue to mix with hand until the it forms a thin paste that evenly coats the pork. Marinate for 10 to 15 minutes.",
            "In another small bowl, combine chicken stock, light soy sauce, Chinkiang vinegar, salt (if using), sesame oil, and cornstarch. Mix well and set aside.",
            "Heat a wok over high heat until hot. Add 2 tablespoons oil and swirl the wok so that the oil coats the bottom (*footnote 2). When the oil just starts to smoke, spread the pork in the oil. Cook without moving for 20 to 30 seconds, until the bottom side turns golden. Flip and cook until the surface just turns white but the inside is still pink. You don’t want to stir too much here, since it might break the pork pieces. Scoop the pork with a spatula and let the oil drip back into the wok. Transfer pork to a plate.",
            "You should still have about 1 tablespoon oil in the wok. If not, add more oil.",
            "Add egg. Cook a few seconds to allow the bottom to set. Stir a few times until the eggs are just cooked. Transfer eggs to the same plate as the pork.",
            "Add a teaspoon of oil and the onion (or green onion) and ginger. Stir until the herbs become fragrant. Add rehydrated wood ear mushrooms and lily flowers. Stir to mix well with the oil. Swirl in the sauce. Cook until the sauce thickens. Return pork, egg, and cucumber to the wok. Stir to mix everything well. Turn to low heat. Carefully try a piece of pork with a piece of vegetable. Adjust seasoning by sprinkling a bit salt and stir well, if needed. Transfer to a serving plate.",
            "Serve immediately over steamed rice.",
        ]
    ),
    "You Tiao": RecipeDetail(
        ingredients: [
            "200 g (1 1/2 cups) all-purpose flour",
            "115 g (1/2 cup) water (, cool to room temperature)",
            "4 g (1 teaspoon) baking powder",
            "2 g (1/2 teaspoon) baking soda",
            "1 teaspoon kosher salt ((or 1/2 teaspoon sea salt))",
            "1 egg white",
            "Vegetable oil for deep-frying",
        ],
        steps: [
            "Prepare a large bowl with a mesh strainer on top. Sift the flour into the bowl.",
            "Combine the water, baking powder, and baking soda in a small bowl. Stir to mix well.",
            "Add the water mixture, egg white and salt into the flour. Stir with a fork until a coarse dough forms.",
            "Knead the dough for 5 minutes. Cover the dough with plastic wrap and let it rest for 30 minutes.",
            "On a clean working surface, knead the dough the second time for another 2 minutes. Cover it with plastic again and let it rest for at least 2 hours or overnight in the fridge (*See Footnote 1).",
            "While heating the oil, prepare the donut dough: Divide the dough into two even pieces. Work on them one at a time.",
            "On a lightly oiled surface, roll the dough into a long strip. You can use your hands to hold both ends of the dough and stretch it gently so it’s easier to form a long shape. Once the dough is 4” (10 cm) wide and 1/4” (0.5 cm) thick, cut off both ends so it forms a rectangle.",
            "Cut across the rectangular sheet, making 1” (2.5 cm) width 4” (10 cm) rectangles.",
            "Dip a skewer or the back of a knife into water. Press it into the center of half of the rectangles. Place the unpressed strips on top of the the pressed strips and press into the center again, so the two pieces of dough are attached to each other. (*Footnote 2)",
            "Once the donuts are formed, let them rest for another 10 minutes.",
            "Heat a tall medium-sized pot or a wok with 3” (7 cm) of oil over medium heat until it reaches 375 °F (190 °C).",
            "Line a cooling rack on top of a baking sheet.",
            "Work on the donuts one at a time. Use your fingers to pinch the two ends, and gently stretch it into a thin long strip that is about 8” (20 cm) long. Then gently lower it into the oil. You can cook 2 to 3 donuts at a time, depending on the size of your pot.",
            "Cook each side for 2 minutes or so, until it turns light golden color for a soft crispy texture, or a golden color for a crispier texture. Do not over fry, which result in chewy and tough you tiao.",
            "Use a pair of tongs to remove the donuts from the oil, gently shake off the excess oil, then transfer them onto the cooling rack.",
            "Enjoy the donuts while they’re hot or warm.",
            "To store the leftover donuts, wait until they cool down completely, then transfer them into a ziplock bag. Store them in the fridge for 2 to 3 days or in the freezer for up to a month.",
            "To reheat the donuts, preheat the oven to 400 °F (200 °C). Place the donuts on a baking tray and bake until heated through, 5 minutes for refrigerated or 8 minutes for frozen donuts.",
        ]
    ),
    "Dou Fu Nao": RecipeDetail(
        ingredients: [
            "10 g (about 25) dried lily flower buds ((yields 1/2 cup rehydrated))",
            "2.5 g (1 tablespoon) dried wood ear mushrooms ((yield 1/4 cup rehydrated))",
            "5 g (4 to 5) dried shiitake mushrooms",
            "1 1/2 tablespoon peanut oil",
            "1/2 teaspoon Sichuan peppercorns ((Optional))",
            "2 green onions (, sliced and separated)",
            "8 oz (250 g) ground pork",
            "1 tablespoon Shaoxing wine",
            "2 tablespoons light soy sauce",
            "1 teaspoon dark soy sauce",
            "1 cup water",
            "1/2 teaspoon chicken bouillon powder ((or 1/4 teaspoon salt))",
            "1 tablespoon cornstarch",
            "2 servings homemade tofu pudding ((or store-bought sundubu tofu))",
        ],
        steps: [
            "Gently rinse the dried lily flower buds, wood ear mushrooms, and shiitake mushrooms with tap water and transfer them into three bowls. Add 1/2 cup hot water to each bowl to cover. Let soak until tender throughout, 30 minutes or so. Once done, squeeze out the marinating liquid back into the bowls and gently rinse them with tap water again to remove any dust on the surface. Slice the shitake mushrooms. Cut the lily flowers in half. And chop the wood ear mushrooms into small pieces. Reserve the marinating liquid from the shiitake mushrooms and lily flowers for the gravy.",
            "Heat 1 tablespoon oil in a large skillet over medium heat. Add the Sichuan peppercorns. Cook, stirring occasionally, until you can smell a strong fragrance and the peppercorns turn darker (but not black). Scoop out the Sichuan peppercorns and discard them (*Footnote 1).",
            "Add the rehydrated lily flowers, shiitake mushrooms, and wood ear mushrooms. Cook, stirring frequently, for 1 minute or so. Be careful, the rehydrated ingredients might cause oil splatter.",
            "Add the white part of the green onion. Cook and stir for 30 seconds to release the fragrance.",
            "Move everything to one side of the pan and add the remaining 1/2 tablespoon oil to the other side. Add the ground pork on top of the oil, then use a spatula to spread it out. Let the pork cook for a minute without moving to brown the bottom, then cut it into small pieces.",
            "When the pork is cooked through, pour in the Shaoxing wine and scrape the pan to release any brown bits.",
            "Pour in the light soy sauce and dark soy sauce. Stir to coat well.",
            "Add the water and the reserved 1 cup of soaking water. And the chicken bouillon powder. Bring to a boil, stirring occasionally, and cook for 2 minutes.",
            "Meanwhile, dissolve the cornstarch in 1 tablespoon of water in a small bowl. Pour the cornstarch slurry into the pan. Stir to mix well and let cook until the sauce thickens. Taste the gravy and adjust the seasoning by adding a pinch of salt, if needed.",
            "To serve, scoop the tofu pudding using a large spoon (the larger and flatter, the better) into two serving bowls. If too much liquid is pooling in the bowl, tilt the bowl carefully to drain off the excess liquid (it’s OK to have some liquid in the bowl). Ladle the gravy on top of the tofu pudding. Serve immediately.",
        ]
    ),
    "Millet Porridge": RecipeDetail(
        ingredients: [
            "1/2 cup (120 grams) millet ((*see footnote))",
            "8 cups (2 liters) water",
            "Sugar",
            "Fermented tofu",
            "Pickled vegetables",
            "Parmesan cheese",
        ],
        steps: [
            "Rinse millet a few times with tap water and drain.",
            "Add water to a medium-sized pot and bring to a boil.",
            "Slowly add millet to the pot.",
            "Continue cooking until the water returns to a boil. Turn to low heat. Use a ladle to skim the foam from the surface, so the porridge won’t spill during cooking.",
            "Cook while keeping the porridge boiling, but not too fiercely, for 30 minutes. Stir the porridge several times after 20 minutes, so the millet won’t stick to the bottom of the pot.",
            "If you want a thicker porridge, keep cooking after 30 minutes are up, and stir the porridge constantly as it thickens, about 10 minutes.",
            "The porridge is ready when the millet is tender but still keeps its shape.",
            "(Option 1) Sweet porridge - Transfer the porridge to serving bowls and add sugar to taste.",
            "(Option 2) Savory porridge - Serve warm with pickled vegetables or fermented tofu.",
            "(Option 3) Cheesy porridge - Grate parmesan cheese into the porridge while it’s still hot.",
        ]
    ),
    "Beer Duck": RecipeDetail(
        ingredients: [
            "4 (2 lb total) duck legs ((or 1 whole duck))",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "3 green onions (, halved crosswise)",
            "1 thumb ginger (, sliced)",
            "3 cloves garlic (, smashed)",
            "2 dried Chinese chili pepper",
            "1 cinnamon stick",
            "1 star anise",
            "1 tablespoon rock sugar ((or 1 teaspoon white sugar))",
            "2 tablespoons light soy sauce ((or soy sauce))",
            "2 teaspoons dark soy sauce ((or soy sauce) (*Footnote 1))",
            "2 cans (total 24 oz / 700 ml) beer",
            "Sliced hot chili pepper for garnish ((optional))",
        ],
        steps: [
            "Use a pair of chicken shears or a large heavy knife (preferably a cleaver) to cut the duck leg into large bite-size pieces.",
            "Heat oil in a wok (or a dutch oven, or a large deep skillet) over medium-high heat until hot. Swirl the wok so the oil covers the bottom. Add the duck pieces without overlapping, skin side down. Cook in batches if needed. Let cook without moving until the bottom turns golden brown. Flip to cook the other side until golden. Then turn to medium or medium-low heat. Flip the duck occasionally as you continue to cook for 5 to 6 minutes to render the excess fat. Once done, transfer the duck pieces to a plate and set aside.",
            "(Optional) If there’s too much oil in your pan, you can carefully remove some using a ladle. Leave about 3 tablespoons of oil / rendered duck fat.",
            "Add the green onion, ginger, garlic, chili pepper, cinnamon stick, and star anise. Cook and stir to release fragrance until the aromatics are lightly charred.",
            "Pour in the beer and immediately use a wooden spatula to scrape the bottom, releasing any brown bits.",
            "Add the light soy sauce, dark soy sauce and sugar. Cook over medium-high heat until the broth comes to a boil. Then cover the wok. Turn down the heat so the broth maintains a low boil. It’s important to use enough heat so the broth is not simmering, so the fat will emulsify into the broth, creating a thick sauce at the end. Cook until the duck turns tender (but not fall-off-the-bone tender), 30 to 40 minutes. If you used larger duck pieces (unhacked thighs and drumsticks, you might need to braise a bit longer).",
            "Uncover the pan and turn to medium-high heat. Cook to reduce the broth, until it is thick enough to coat the back of a spoon, 10 to 15 minutes. You should watch closely during this step, and use a spatula to scoop the duck from the bottom, to prevent sticking and burning. You can taste the duck and the sauce during this process, and add a bit of salt if needed.",
            "(Optional) Once the sauce has reduced, add the hot chili pepper, if using.",
            "Mix everything well so the duck is evenly covered with the sauce. Transfer everything to a deep plate or bowl and serve as a main dish over steamed rice, or by itself.",
        ]
    ),
    "Beijing Hot Pot Sauce": RecipeDetail(
        ingredients: [
            "1/4 cup Chinese sesame paste ((or unsweetened natural peanut butter, or tahini) (*Footnote 1))",
            "1/4 cup water ((or warm hot pot broth) (*Footnote 2))",
            "1 block red fermented bean curd",
            "2 to 3 teaspoons Chinese fermented leek flower sauce ((Optional) (*Footnote 3))",
            "2 teaspoons soy sauce ((or to taste))",
            "1 tablespoon toasted sesame oil",
            "1 teaspoon garlic (, grated (2 cloves))",
            "2 tablespoons cilantro (, minced (or to taste) (Optional))",
        ],
        steps: [
            "Add the sesame paste into a big bowl. Add the water, one tablespoon at a time, and use a spatula or a spoon to blend the water in until it forms a smooth paste. Add more water and repeat, until it forms a smooth sauce that is slightly runny.",
            "Add the red fermented bean curd. Break it apart while mixing it into the sauce, until fully incorporated.",
            "Add the rest of the ingredients and mix, until everything is fully dissolved into the sauce. Taste it and adjust it according to your taste. If you do not use the leek flower sauce, the sauce will be milder. You can add a bit more soy sauce, sesame oil, and garlic to boost the flavor.",
        ]
    ),
    "Kao Bao Zi": RecipeDetail(
        ingredients: [
            "300 g (2 1/2 cups) all-purpose flour (, plus extra for dusting)",
            "1/2 teaspoon salt",
            "2 tablespoons vegetable oil",
            "1 egg",
            "1/2 cup warm water",
            "1 lb lamb leg meat ((or ground lamb))",
            "1 1/2 teaspoons salt",
            "1 tablespoon cumin powder",
            "1 1/2 teaspoons ground black pepper",
            "2 teaspoons toasted sesame oil",
            "1 small onion (, minced)",
            "1 egg yolk ((reserve the egg white))",
            "1 teaspoon milk ((or water))",
            "Toasted sesame seeds",
        ],
        steps: [
            "Cube lamb meat into 1/4“ (1-cm) pieces and add them into a large bowl. Add salt, cumin powder, black pepper. Mix well. Add onion and peanut oil, and mix again.",
            "Add flour and salt to a large bowl. Stir to mix well. Add the oil and egg. Use a pair of chopsticks to whisk the flour until the wet ingredients are fully absorbed. Slowly add water onto dried flour and keep stirring, until soft dough flakes form and there’s no dry flour on the bowl. If there’s still too much dry flour left in the bowl, add a bit more water. If the dough flakes are very sticky to the touch, add more flour.",
            "Dust both hands with dry flour and start gathering the dough flakes, until dough forms. Dust a working surface with flour and transfer the dough onto it. Knead the dough until the surface turns smooth, 5 to 10 minutes. The dough should be soft but should not stick to your hand.",
            "Transfer the dough to a large bowl. Cover with a damp dish towel or plastic wrap. Allow to rest at room temperature for 15 minutes.",
            "Knead the dough again until it’s very smooth, 2 to 3 minutes. Let rest for another 30 minutes.",
            "Preheat the oven to 450°F (230°C). Line a baking tray with parchment paper.",
            "Beat 1 egg yolk with the milk to make the egg wash. Reserve the white in another bowl.",
            "Dust the working surface with flour again and transfer the dough onto it (try not to add too much dry flour as long as the dough doesn’t stick to the surface too much, so it’s easier to seal later). Divide the dough into two even pieces. Roll the dough into a long log. Divide each dough log into 5 equal pieces, so you get a total of 10 dough balls (mine weighs 48g to 50g per dough). Work on one at a time, using plastic wrap to cover the rest to prevent it from drying out.",
            "Knead a piece of dough a few times to shape a ball. Press it into a round disc. Roll the dough with a rolling pin into a round disc that is slightly thicker in the center and thin on the edges, about 7” (18cm) x5” (13cm) in diameter.",
            "Pack 4 to 5 tablespoons of filling into the center of the dough disc. Fold the longer edges of the dough and pinch them together. To help with sealing, you can brush some egg white until both short ends of the wrapper. Fold the shorter ends so the dough seals the filling inside. Press gently and place onto the baking sheet. Work on the rest of the dough in the same way.",
            "Brush each bun with a thin layer of egg wash on top and sprinkle sesame seeds to garnish.",
            "Bake on the middle rack for 25 minutes, until the surface turns golden brown. Let the buns cool off for 5 to 10 minutes before serving.",
        ]
    ),
    "Da Pan Ji": RecipeDetail(
        ingredients: [
            "1 batch wide homemade pulled-noodles ((or 8 oz / 225 g dried noodles))",
            "2 tablespoons Shaoxing wine",
            "2 tablespoons light soy sauce",
            "2 teaspoons dark soy sauce",
            "1 tablespoon doubanjiang",
            "1 teaspoon sugar",
            "1 thumb ginger (, thinly sliced)",
            "6 cloves garlic (, smashed)",
            "4 scallions (, sliced into 1” pieces)",
            "1/2 red onion (, sliced into 1/2” pieces)",
            "8 dried Chinese chili peppers",
            "2 star anise pods",
            "2 bay leaves",
            "1/2 teaspoon ground Sichuan peppercorn",
            "1 cinnamon stick",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "4 boneless chicken thighs (, diced to 1” (2.5 cm) pieces)",
            "1 1/2 cups chicken stock",
            "1 russet potato (, roll cut into 1/2” pieces (*Footnote 1))",
            "1 red pepper (, cut into 1 1/2” pieces)",
            "Chopped cilantro for garnish ((Optional))",
        ],
        steps: [
            "Prepare the noodle dough if you’re planning to use homemade noodles.",
            "Mix Shaoxing wine, light and dark soy sauce, and sugar in a small bowl.",
            "Add the ginger, garlic, onion, dried chili pepper, star anise, bay leaves, Sichuan peppercorns, and cinnamon to a small plate.",
            "Boil the noodles according to instructions. Once done, drain and rinse with cold water to stop cooking. Then drain again.",
            "Heat oil in a wok until shimmering. Add the chicken. Cook, stirring occasionally, until the surface turns light golden.",
            "Add the plate of the spices to the wok. Stir and cook for 30 seconds to release fragrance. Add doubanjiang and cook until all the spices are coated. Add the Shaoxing wine mixture. Stir immediately to deglaze the wok.",
            "Pour in water and add potato. Cook over medium-high heat until bringing to a simmer. Cover and simmer over medium heat for 5 minutes (*Footnote 2).",
            "Add bell pepper. Keep simmering for another 5 minutes until the vegetables turn tender. Stir in the scallion and cook for another minute.",
            "If the broth is still too thin, turn to high heat to reduce the sauce. Stir constantly to prevent burning. Once done, transfer everything to a big bowl. Remove as much dried spices as you can and discard them.",
            "Serve the chicken, vegetables and sauce over boiled noodles. Garnish with cilantro if desired.",
        ]
    ),
    "Laghman Noodles": RecipeDetail(
        ingredients: [
            "1 lb (450 g) lamb leg or ground lamb",
            "2 teaspoon peanut oil ((or vegetable oil))",
            "1 teaspoon salt",
            "1/4 teaspoon white pepper powder",
            "2 teaspoons cornstarch",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "1 purple onion (, diced)",
            "4 cloves garlic (, sliced)",
            "2 teaspoons Chinese chili flakes",
            "5 tomato (, chopped (or 1 28-oz can diced tomatoes))",
            "2 tablespoons light soy sauce ((or soy sauce))",
            "2 tablespoons tomato paste",
            "2 tablespoons cumin powder",
            "1 teaspoon sugar",
            "1/2 teaspoon salt ((or to taste))",
            "2 anaheim pepper ((or 1 bell pepper, diced))",
            "1 to 1.3 lbs (450 to 600 g) fresh noodles ((or 12 oz / 340 g) dried thin wheat noodles)",
        ],
        steps: [
            "Cube lamb leg into 1/2” (1-cm) cubes (or just use ground lamb) and add it to a medium-sized bowl. Add the rest of the marinating ingredients. Mix well and allow to marinate at room temperature for about 15 minutes while preparing the other ingredients.",
            "Add water to a large pot and bring to a boil. Cook the noodles according to instructions. Then transfer to a colander to drain. Run the noodles with cold tap water to stop cooking. Drain again and set aside.",
            "Heat 1 tablespoon of oil in a large skillet over medium-high heat until hot. Add the lamb and spread out with minimal overlap. Cook, stirring occasionally, until the surface turns light brown but the meat is still slightly pink inside, about 2 minutes. Transfer the lamb to a plate and set aside. Save the oil in the skillet.",
            "Pour in the remaining 1 tablespoon of oil. Add the onion. Stir and cook for 2 to 3 minutes, until the onion starts to soften.",
            "Add the garlic and chili flakes. Stir and cook to release fragrance. Add the tomato. Stir and cook for 2 to 3 minutes, until the tomato starts to break down. Add the light soy sauce, tomato paste, cumin powder, sugar, and salt. Stir and cook to mix everything well, until the tomato has broken down and becomes saucy.",
            "Add the pepper. Stir and cook until just softened but still crisp, 1 minute if using anaheim pepper, 2 to 3 minutes if using bell pepper.",
            "Return the lamb back to the skillet and stir to mix well. Cook just long enough so the lamb is warmed through and not overcooked. If you’re using ground meat, you can cook it a bit longer to release more flavor and it won’t overcook.",
            "To serve the noodles, fluff the noodles again and transfer to each serving plate. Add the noodle sauce. Stir to mix well and enjoy while hot!",
        ]
    ),
    "Uyghur Lamb Pilaf": RecipeDetail(
        ingredients: [
            "2 tablespoons oil",
            "5 cloves garlic (, peeled)",
            "3 slices ginger ((about 1 tablespoon))",
            "1.2 pound (600 grams) lamb spare ribs (, cut into 1 or 2 segments (*see footnote))",
            "2 teaspoons salt",
            "1 pound (350 grams) onion (, chopped)",
            "1 pound (500 grams) carrot (, chopped)",
            "2 cups (500 grams) rice",
            "1 teaspoon sugar",
            "1 teaspoon cumin powder",
            "5 dried chili peppers (reduce to 2 to 3, for less spicy dish)",
            "1 teaspoon Sichuan peppercorn ((optional))",
        ],
        steps: [
            "Cut lamb spare ribs into 1 or 2 segments. Prepare vegetables.",
            "Heat oil in a wok over medium high heat until warm. Add garlic and ginger. Stir a few times until fragrant.",
            "Carefully add lamb ribs and let them cook without stirring for 1 minute. Stir and cook for 1 minute. Add 1 teaspoon salt. Stir and cook until the surface of ribs is cooked and turns golden brown, about 3 minutes.",
            "Add onion, stir to mix well, for 1 minute. Add carrot. Stir and cook for 2 to 3 minutes.",
            "Add 3 cups water. Cook until brought to a boil. Skim brown foam from the surface. Add sugar, cumin powder, and chili peppers. Place Sichuan peppercorn in a tea infuser and add it into the wok. Bring to a boil again, then turn to low heat and cover. Cook for 1 hour 30 minutes. During cooking, check on the lamb 3 to 4 times. After 1 hour, add the remaining 1 teaspoon salt. If the water is reducing quickly and no longer covers the lamb, carefully add just enough hot water to cover.",
            "Forty minutes before the lamb is ready, prepare the rice. Rinse rice 2 to 3 times. Cover with water and let soak for 30 minutes. Drain and set aside.",
            "When the lamb is ready, use a spatula to push the lamb to the edges of the wok and leave some room in the center. Add rice to fill the space. If the water doesn’t cover the rice completely, add more hot water, about 1/2 to 1 cup. Cover the wok and cook over medium heat for 5 minutes. Uncover, stir, and continue cooking until the water is almost absorbed, about 5 minutes.",
            "Transfer everything to a large dutch oven (or a big pot with a thick bottom). Cover and simmer over lowest heat for 25 minutes.",
            "Serve warm.",
        ]
    ),
    "Di San Xian": RecipeDetail(
        ingredients: [
            "1/4 cup water",
            "1 tablespoon light soy sauce",
            "1/2 tablespoon dark soy sauce ((*Footnote 1))",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "1/2 tablespoon sugar",
            "1/4 teaspoon salt",
            "1 teaspoon cornstarch",
            "10 oz eggplants (about 1 large Chinese eggplant or 1/2 American eggplant)",
            "2 teaspoons cornstarch",
            "1/3 cup peanut oil ((or vegetable oil))",
            "1/2 lb potato (1 small russet or 2 yukon potatoes)",
            "1 bell pepper (, chopped into bite-size pieces)",
            "2 green onions (, chopped)",
            "2 cloves garlic (, minced)",
        ],
        steps: [
            "Place eggplant into a large bowl and sprinkle with 2 teaspoons of salt. Add tap water to cover and stir to dissolve the salt. Use a small plate or a lid to cover the eggplant pieces and submerge them in the water. Soak for 15 to 20 minutes.",
            "Drain the eggplant and dry thoroughly with a paper towel. Sprinkle with cornstarch and gently mix by hand, until the eggplant pieces are lightly coated.",
            "Combine the sauce ingredients in a small bowl. Mix well and set aside.",
            "Heat a 12” pan (or a wok) with 1/3 cup oil over medium-high heat until hot. Spread the potato pieces in the pan without overlapping. Cook without moving until the bottom turns golden. Flip to cook the other side, until golden. Transfer the potatoes to a big plate.",
            "Your pan should still have plenty of oil. Place the eggplant in the pan and spread the pieces without overlapping. Cook the eggplant without moving it until the bottom turns golden brown. If the oil in the pan is fully absorbed by the eggplant before cooking through, add a bit more oil to the pan. Turn to medium heat if the pan starts to smoke. Flip the pieces to cook the other side until golden brown. Transfer to a plate with the potatoes.",
            "If your pan still has too much oil, carefully remove some of it with a folded paper towel and leave only about 1 teaspoon of oil in the pan. Add the green onion and garlic and stir a few times until fragrant.",
            "Add the peppers and stir a few times to mix well.",
            "Mix the sauce again to dissolve the cornstarch completely. Pour the sauce into the pan. Stir a few times.",
            "Return the eggplant and potato to the pan. Cook and stir until the sauce has thickened and evenly coated the vegetables. Transfer everything to a plate.",
            "Serve hot with steamed rice as a main or as a side.",
        ]
    ),
    "Hot Dry Noodles": RecipeDetail(
        ingredients: [
            "10 oz fresh alkaline noodles (, cooked or uncooked (or regular wheat noodles) (*Footnote 1))",
            "1 tablespoon sesame oil",
            "1 teaspoon vegetable oil",
            "2 green onions (, just the whites (greens reserved))",
            "2 slices ginger",
            "2 cloves garlic (, lightly smashed)",
            "1 star anise",
            "5 cloves",
            "1 cinnamon stick",
            "1/4 teaspoon Sichuan peppercorns",
            "2 tablespoons shaoxing wine ((or dry sherry))",
            "1 tablespoon light soy sauce",
            "1 teaspoon sugar",
            "2 cups beef stock ((chicken stock, or vegetable stock))",
            "2 cloves garlic (, minced)",
            "3 tablespoons hot water",
            "3 tablespoons Chinese sesame paste ((or unsweetened natural peanut butter))",
            "1 teaspoon sesame oil",
            "2 teaspoons light soy sauce",
            "1 teaspoon dark soy sauce",
            "1 1/2 teaspoons Chinkiang vinegar",
            "1 teaspoon sugar",
            "1/8 teaspoon white pepper powder",
            "1/8 teaspoon five spice powder",
            "2 to 4 tablespoons homemade chili oil ((Optional))",
            "Reserved green onion (, sliced)",
            "1/4 cup pickled radish ((or mustard greens or your favorite pickles))",
            "Cilantro leaves",
        ],
        steps: [
            "Garlic water: Combine the 2 cloves of minced garlic and 3 tablespoons of hot water in a small bowl. Set aside.",
            "Master sauce: In a small pot, heat the vegetable oil over medium heat and add the green onion, ginger, and garlic. Saute until fragrant, about 1 minute. Add the star anise, cloves, cinnamon, and fennel seeds and cook for another 30 seconds. Add the Shaoxing wine, soy sauce, sugar, and broth. Bring to a boil, then reduce to a simmer. Cook for 10 to 15 minutes. Strain and discard the aromatics and spices.",
            "Sesame sauce: Slowly incorporate the garlic water into the sesame paste until smooth. Then add the remaining sauce ingredients.",
            "Prepare noodles: Bring a pot of water to a boil. (1) If using the Cooked Noodle (You Mian), quickly rinse the noodles in the hot water to revive its texture and drain. (2) If using uncooked fresh ramen noodles, drizzle the sesame oil over the noodles and toss gently. Add the noodles to the boiling water and cook until al dente. (3) If using regular dried noodles, boil according to the instructions. Once done, drain the noodles and divide between 2 bowls.",
            "Assemble: Add 2 tablespoons of the broth, 2 tablespoons of the sesame sauce, and 1 tablespoon of chili oil (if using) to each bowl. Garnish with the green onion, preserved vegetables of your choice, and cilantro leaves.",
            "Toss everything together, then adjust the seasoning to taste by adding more sauce or broth. Enjoy hot or cold!",
            "The noodles, sauce, and broth can be prepared ahead of time and stored in the fridge separately for up to 3 days. Assemble them whenever you plan to serve.",
        ]
    ),
    "Tomato and Egg": RecipeDetail(
        ingredients: [
            "1 1/2 tablespoons peanut oil ((or vegetable oil))",
            "4 eggs (, beaten)",
            "1 lb vine-ripe tomatoes (, chopped to bite-size pieces (about 4 tomatoes))",
            "2 cloves garlic (, minced)",
            "3/4 teaspoon salt",
            "1 teaspoon sugar ((Footnote 1))",
            "green onion (, sliced (for garnish) (Optional))",
        ],
        steps: [
            "Heat 1 tablespoon of oil in a medium-sized skillet over medium-high heat. When oil is ready, add egg and cook until the bottom side is done, but the top is still raw, about 30 seconds. Scramble the eggs while chopping into bite sized pieces, until the egg is just cooked. Turn to lowest heat, transfer egg to a plate, and set aside.",
            "Add the remaining 1/2 tablespoon of oil and the garlic and turn back to medium-high heat. Stir the garlic a few times until fragrant. Add tomato and stir fry until the texture becomes soft, 1 to 2 minutes. Add egg back into skillet. Sprinkle the salt and sugar evenly over everything. Quickly mix everything together with a spatula until evenly seasoned. Taste the dish and adjust seasoning by adding a bit more sugar or salt if needed.",
            "Serve hot over steamed rice as a main dish or a side dish.",
        ]
    ),
    "Ding Ding Chao Mian": RecipeDetail(
        ingredients: [
            "300 grams all-purpose flour (convert to cups)",
            "1/8 teaspoon salt",
            "3/4 cup (180 grams) warm water ((See footnote 2))",
            "1/2 pound (200 grams) ground lamb ((or lamb leg meat, cubed) (See footnote 3))",
            "2 tablespoons Shaoxing wine",
            "1/4 teaspoon Sichuan peppercorn (, grounded (or ground black pepper))",
            "1 teaspoon salt",
            "1 teaspoon potato starch ((or cornstarch))",
            "1/2 cup tomato sauce ((*see footnote 5))",
            "2 tablespoons soy sauce ((or light soy sauce))",
            "1 teaspoon sugar",
            "1/4 teaspoon salt",
            "2 tablespoons vegetable oil",
            "1/2 onion (, chopped)",
            "4 garlic (, minced)",
            "2 pieces ginger (, minced)",
            "1 to mato (, cubed)",
            "2 anaheim peppers ((or 1 bell pepper, or 2 jalapenos, diced))",
            "2 tablespoons black vinegar",
        ],
        steps: [
            "Prepare mixer. Attach the beater blade. Combine flour and salt in the mixing bowl. Turn to low speed. Slowly add water. Let mix until it forms a dough. Change to dough hook. Turn on slow speed and let knead until the dough is very smooth, about 10 minutes. If you’re not using a KitchenAid mixer, start by mixing the flour with the water, stirring with a spatula, until the dough forms. Dust a working surface with flour and transfer the dough onto it. Knead until the surface becomes smooth, about 15 minutes.",
            "Spray a thin layer of oil onto the bottom of a large bowl. Place the dough inside. Cover with plastic wrap. Let rest at room temperature for 20 minutes.",
            "While resting the dough, marinate the lamb and chop the veggies.",
            "When the dough has rested, prepare a large cutting board (or working surface). Brush a thin layer of oil in the middle. Place the dough on top. Press it into a 1-cm (1/3-inch) sheet with your hands.",
            "Brush oil on top of the dough. Cover loosely with plastic wrap and let rest for 10 minutes.",
            "Bring a large pot of water to a boil.",
            "Make sure your working surface is covered with a thin layer of oil.",
            "Slice the dough sheet into 10 to 12 strips. Make sure you leave enough space in between them, to prevent them from sticking together.",
            "Work on the strips one by one. Use both hands to pull the strip into a 5-mm (1/4-inch) wide noodle.",
            "Brush a thin layer of oil onto the noodles to prevent them from sticking.",
            "Gather the noodles together again. Cut into 1-cm (1/3-inch) long pieces. The noodles may stick together at this point, but will separate during boiling.",
            "Add the noodles into the boiling water right after you cut them. Immediately stir with a spatula to separate the noodles. Let cook until the noodles are floating on top. Continue cooking for 2 to 3 minutes, until the noodles are almost cooked through.",
            "Drain the noodles and rinse them with tap water, to stop the cooking.",
            "Combine ground lamb (or cubed lamb leg), Shaoxing wine, salt, Sichuan peppercorn, and potato starch in a small bowl. Mix well. Let marinate for 10 to 15 minutes.",
            "Combine tomato sauce, light soy sauce, black vinegar, sugar, and salt in a small bowl. Set aside.",
            "Heat oil over medium high heat until hot. Add onion, garlic, and ginger. Cook until the onion turns slightly golden, 2 to 3 minutes.",
            "Use the spatula to move everything to one side of the pan. Add ground lamb onto the other side. Spread the lamb to let the bottom brown slightly. Stir until the surface is cooked.",
            "Mix everything together. Add the tomato sauce mixture. Stir to mix well.",
            "Pour the drained noodles into the skillet. Stir to mix well. Adjust seasoning if necessary. If the noodles are still a bit raw inside, cover and let steam for a minute or so, until cooked through.",
            "Add tomato and anaheim pepper. Stir a few times to gently cook the veggies.",
            "Transfer to plates and serve immediately.",
            "(Optional) Pour a spoonful of black vinegar onto your noodles before eating, just like real Xinjiang people do.",
        ]
    ),
    "Chinese Dumplings": RecipeDetail(
        ingredients: [
            "4 cups all-purpose flour ((*see footnote 1))",
            "265 ml water ((room temperature) (1 cup plus 2 tablespoons))",
            "Pork and napa cabbage",
            "Lamb with carrot and zucchini",
            "Pork with shiitake mushrooms",
            "Beef filling",
            "Carrot and eggs ((Vegetarian))",
            "Vegan",
            "dumpling dipping sauce",
            "Homemade chili oil",
        ],
        steps: [
            "Add flour into a large bowl. Slowly pour the water into the bowl, mixing them together with a pair of chopsticks.",
            "When the water is mixed with the flour, dust both hands with flour and start kneading to form dough. The dough will be quite tough and should easily be able to be lifted from the bowl without sticking to the bottom.",
            "When dough has formed, dust the working surface with flour and dust hands again. Transfer the dough to the working surface and continue to knead it until its surface becomes smooth, about 10 minutes.",
            "Rinse a clean dish towel with water. Dust the bottom of a large bowl with flour and transfer the dough into it. Cover bowl with the damp dish towel and a lid (or plastic wrap). Let the dough rest for 2 hours. You can let the dough rest longer, 4 to 5 hours.",
            "After resting, the dough will be softened and have a smooth texture. Dust the working surface and your hands with extra flour and transfer the dough onto the surface. Knead the dough repeatedly for another 3 to 5 minutes, until the dough hardens again. Let the dough rest for about 30 minutes (or longer).",
            "During this time, you can prepare the dumpling filling(s).",
            "Dust the working surface again and transfer the dough onto it. Slice 1/6 of the dough off and place the rest back to the big bowl. Cover it with the damp dish towel.",
            "Roll the dough into a long stick, 2.5 to 3 centimeters (1 inch) in diameter. Use a knife to cut the dough stick into about 12 small doughs, each weighing 12 to 14 grams (0.4 to 0.5 oz) (*see footnote 2).",
            "Slightly dust both sides of each small dough with flour. Work on them one at a time.",
            "Dust the working surface again. Take one dough and press it to a round disc. Roll it with a rolling pin into a round sheet (refer to the video to see how). Try to roll it so that that the edge is thinner than the center. The wrapper should be about 1 millimeter thick (i.e. almost same as the thickness of a CD), and the diameter should be about 7 centimeters. It is ok if the wrapper is not perfectly round.",
            "Starting here, you should work as quickly as you can, because the wrappers will dry out quickly. And if they do, you will find it very difficult to seal the dumplings later. If the wrappers dry out when you start to fold the dumplings, brush a bit of water over the edge so you can still seal the dough.",
            "Scoop about 1 tablespoon (or less, so you can easily fold the dumpling) of dumpling filling and place it in the center of the wrapper. Hold the dumpling with one hand and start sealing the edges with the other hand (refer to the video to see how to fold a dumpling). Be careful, when you press the edges together to seal the dumpling, do not let filling touch the sealing area (the dumpling will fall apart if you do). After folding, press edge again to seal well. You don’t need to fold beautiful dumplings here; our goal is to make the dumplings hold their shape during boiling.",
            "Place the dumplings on the working surface and work on the rest of the doughs in the same manner.",
            "Try to wrap and cook dumplings in small batches (20 to 25 dumplings at a time). If you won't cook dumplings soon after wrapping (within 30 minutes), freeze them first (refer to the session \"to store dumpling\" below). If you want to know the reason, read the session of \"Things you should take note of\" above.",
            "Bring a large pot of water to a boil.",
            "Carefully add dumplings one at a time into the water. Use a big ladle to stir the water gently and continuously, until the water starts to boil again, so the dumplings won’t stick to the bottom, for about 1 minute. Adjust the heat so the water is at boiling point, but isn’t bubbling too fiercely.",
            "When the dumplings float to the surface, continue boiling until the dumplings are filled with air and swollen, and the dough starts to become transparent, about 1 minute (*see footnote 3). Immediately transfer all the dumplings to a plate.",
            "(*) Be careful, the dumplings cook quickly and you should always stand beside the pot throughout the boiling process. When the dumplings are cooked, they will start to fall apart within seconds, so transfer them as soon as possible.",
            "Heat a tablespoon of oil in a nonstick skillet over medium high heat. When oil is hot, place potstickers in the skillet, pleat side up.",
            "Swirl 2 tablespoons water in the skillet, cover immediately, and turn the heat to medium. Cook covered until the water is evaporated and potstickers are cooked through, 3 to 4 minutes.",
            "Remove the cover and flip one potsticker to see whether the bottom side is charred. If not, turn to medium high heat and cook until the bottom side turns golden brown.",
            "Transfer the potstickers to a plate.",
            "Option 1: Serve with Chinese black vinegar and a few ginger slices.",
            "Option 2: Serve with 1 tablespoon Chinese black vinegar + 1 teaspoon light soy sauce + 1/2 teaspoon sesame oil.",
            "Option 3: Serve with Chinese black vinegar and a few drops fresh Chili oil.",
            "If you plan to store dumplings or won't serve them immediately, always freeze them uncooked. It won’t affect the texture or flavor of the dumplings.",
            "Dust the bottom of a big airtight box with a thin layer of flour. Place the dumplings, one finger’s width apart. Store in the freezer for up to 2 months.",
            "Bring a large pot of water to a boil. Add dumplings into the water. Use a big ladle to stir a few times. Cover and cook until the water starts to boil again. Adjust the heat so the water will keep boiling without spilling. Cover and cook for 3 minutes (up to 5 minutes for bigger dumplings). Uncover pot. Continue to cook for about 1 minute (up to 2 minutes for bigger dumplings), until cooked through. Transfer to a plate immediately.",
            "Store leftover boiled dumplings in airtight container in the fridge and consume as soon as possible, within 1 to 2 days.",
            "To reheat in microwave - Add dumplings into a bowl and sprinkle with a few drops of water. Cover and heat until warm.",
            "To reheat by steaming - Place dumplings in a bowl. Place a tall-rimmed plate upside down in a pot and add water to cover. Place the bowl of dumplings on top. Heat over high heat until water is boiling. Continue cooking for 5 minutes.",
            "To pan fry - Grease a nonstick skillet with a thin layer of oil and heat over medium heat. When skillet is hot, add dumplings. Swirl in a tablespoon of water, cover immediately, and cook for 2 to 3 minutes.",
        ]
    ),
    "Beef Dumplings": RecipeDetail(
        ingredients: [
            "1/2 lb ground beef ((at least 20% fat))",
            "1/4 cup chicken stock ((or beef stock, or water))",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "2 teaspoons ginger (, grated)",
            "1 teaspoon salt",
            "1/4 teaspoon ground toasted Sichuan peppercorn ((or black pepper))",
            "4 green onions (, coarsely chopped)",
            "1 large carrot (, coarsely chopped)",
            "1/2 cup frozen corn (, thawed)",
            "1/2 cup frozen green peas (, thawed)",
            "1 tablespoon sesame oil",
            "20 homemade dumpling wrappers ((or packaged dumpling wrappers))",
            "1 to 2 tablespoons vegetable oil",
        ],
        steps: [
            "To make the dumpling filling, add ground beef into a big bowl. Add chicken stock, light soy sauce, Shaoxing wine, ginger, salt, and toasted Sichuan peppercorns. Mix by using a pair of chopsticks until the liquid is fully absorbed. Cover with plastic wrap, and let marinate in the fridge while you prepare other ingredients.",
            "(Optional) You can start making dumpling dough now if you’re planning to use homemade dumpling wrappers.",
            "Add carrot into the food processor. Mix until finely chopped. Add green onions. Mix until the onions are finely cut. Transfer to a bowl.",
            "When you’re ready to make the dumplings, add minced green onion, carrot, corn, green peas and sesame oil into the ground beef mixture. Stir to mix well.",
            "Scoop about 1 to 1.5 tablespoons dumpling filling and place it in the center of the wrapper. Hold the dumpling with one hand and start sealing the edges with the other hand. After folding, press the edges again to seal well. You can use any way to fold the dumplings as long as you’re comfortable with it.",
            "Now you can freeze these dumplings if you don’t cook them immediately. Place them onto a baking tray and seal with a plastic wrapper. You can store the dumplings in the freezer for up to 1 month. Once the dumplings are completely frozen, after about a day, you can transport them to a gallon bag to save freezer space.",
            "Cook the dumplings in batches. Heat 1 tablespoon oil in a nonstick skillet over medium heat until hot. Add dumplings. Cook until the bottom side turns golden. Add 2 tablespoons water, and cover. Cook until the other side also turns golden and the dumplings are cooked through, 2 to 3 minutes.",
            "You can serve the dumplings immediately with dumpling dipping sauce (the spicy dumpling sauce works extremely well with these beef dumplings).",
        ]
    ),
    "Pork and Chive Dumplings": RecipeDetail(
        ingredients: [
            "1 pack dumpling wrappers",
            "1 lb ground pork",
            "2 tablespoons papery shrimp ((Optional))",
            "2 tablespoons light soy sauce ((or soy sauce))",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "1 teaspoon dark soy sauce",
            "1 tablespoon grated ginger",
            "1/2 teaspoon salt",
            "1/2 teaspoon sugar",
            "1/8 teaspoon ground white pepper",
            "1 tablespoon toasted sesame oil",
            "14 stalks garlic chives (, sliced into 1/4” (0.5 cm) pieces)",
            "Chinkiang vinegar",
            "Dumpling dipping sauce",
            "Homemade chili oil",
        ],
        steps: [
            "Add the pork into a medium-sized bowl and the rest of the filling ingredients except for the sesame oil and garlic chives.",
            "Beat everything together in one circular direction with a pair of chopsticks or a spatula, until all the liquid is absorbed and the pork is streaky.",
            "Add the sesame oil and Chinese chives. Mix for another minute.",
            "Prepare a small bowl of water on the side. Cover the dumpling wrappers with damp paper towels to prevent them from drying out.",
            "Wet the edge of a dumpling wrapper. Scoop about 1 heaping tablespoon of dumpling filling and place it in the center of the wrapper. Hold the dumpling with one hand and start sealing the edges with the other hand (watch the video below for the wrapping process). After folding, press the edges again to seal well. You can use any way to fold the dumplings as long as you’re comfortable with it. Cover the dumpling wrappers and wrapped dumplings with wet paper towels to prevent them from drying out.",
            "Now you can freeze the assembled dumplings if you aren’t going to cook them immediately. Place them onto a baking tray and seal with plastic wrap. You can store the dumplings in the freezer for up to 1 month. Once the dumplings are completely frozen, after about a day, you can transfer them to a gallon zipper bag to save freezer space.",
            "To boil the dumplings: Bring a large pot of water to a boil. Carefully add dumplings into the water, one at a time. Use a big ladle to stir the dumplings gently in a circular motion, until the water starts to boil again, so the dumplings won’t stick to the bottom, for about 1 minute. Adjust the heat so the water is at a gentle boil. When the dumplings float to the surface, continue boiling until the dumplings are filled with air and swollen, and the dough starts to become transparent, 2 to 3 minutes. Immediately transfer all the dumplings to a plate.",
            "To cook pan fried dumplings: Cook the dumplings in batches. Heat the 1 tablespoon of oil in a nonstick skillet over medium heat until hot. Add dumplings. Add 2 tablespoons of water and cover. Cook until the dumplings are cooked through, 2 to 3 minutes. Uncover and keep cooking until the bottom side turns golden. If using frozen dumplings, the cooking process is the same, but you will need to cook the covered dumplings for 4 minutes before uncovering the pan.",
            "Serve the dumplings hot with some Chinkiang vinegar or dumpling dipping sauce.",
        ]
    ),
    "San Xian Potstickers": RecipeDetail(
        ingredients: [
            "200 grams (7 ounces) ground pork ( (lean fat ratio 7:3))",
            "10 large (1 cup) shrimp (, peeled, deveined and chopped into corn kernel sized pieces)",
            "1 cup (30 grams / 1 ounce) shiitake mushrooms (, dried, rehydrated and finely chopped)",
            "2 tablespoons Shaoxing wine",
            "2 tablespoons light soy sauce",
            "3 and 1/2 tablespoons peanut oil",
            "1 teaspoon ginger (, minced)",
            "1 teaspoon salt",
            "1/4 teaspoon black pepper",
            "1/2 cup green onion (, chopped)",
            "2 teaspoons sesame oil",
            "40 dumpling wrappers",
            "2 tablespoons ginger slices",
            "4 tablespoons black vinegar",
        ],
        steps: [
            "In a large bowl, combine ground pork, shaoxing wine and light soy sauce. Mix well with a pair of chopsticks (or a fork). Add 4 tablespoons water to the mixture, 1 tablespoons at a time, and stir until the water is fully combined. The mixture should feel sticky and a bit runny, but still thick enough to coat a spoon. Add shrimp, shiitake, ginger, salt and black pepper, mix well.",
            "Right before you’re ready to wrap the dumplings, add green onion and sesame oil, mix well.",
            "Prepare a small bowl of water. Place a piece of parchment paper on a working surface or dust a wooden board with flour.",
            "To wrap a potsticker, scoop about 2 teaspoons of the pork mixture and place in the center of the dumpling wrapper. Gently press the mixture into a round shape, so it will be easier to wrap. Wet your finger or a pair of chopsticks with water and gently brush water onto the edge of the wrapper (this will help the wrapper stick to itself when pressed together).",
            "Fold the wrapper into a half moon shape, using fingers to pinch the middle and press the two layers together. Use your left hand to hold the dumpling and your right hand to fold 2 to 3 pleats in the outer layer towards the midpoint, and press it well to seal the filling inside.",
            "Switch so that you're holding the dumpling in your right hand, and use your left hand to form more pleats in the same manner. Press the pleats again to seal the filling tightly. If you have trouble sealing the dumplings, reduce the amount of filling inside until you can seal it easily.",
            "Place potsticker on the parchment paper. Continue forming the rest of the potstickers in the same manner. Leave about a finger’s width between any two dumplings, so they won’t stick together.",
            "In a small bowl, drizzle vinegar over ginger slices. If the dipping sauce is not salty enough to your liking, you can add soy sauce to adjust the flavor, 1 teaspoon at a time.",
            "Heat a tablespoon of oil in a nonstick skillet over medium high heat. When oil is hot, place potstickers in the skillet, pleat side up. Swirl 2 tablespoons water into the skillet, cover immediately, and turn the heat to medium.",
            "Cook covered until the water is evaporated and potstickers are cooked through, about 3 minutes. Remove the cover and flip one potsticker to see whether the bottom side is charred. If not, turn to medium high heat and cook until the bottom side turns golden brown, about 1 minute. Transfer the potstickers to a plate.",
            "Serve immediately with dipping sauce.",
            "Store the cooked potstickers in an airtight container in the fridge for 2 days.",
            "For uncooked potstickers, place them in a large airtight container, one finger’s width apart. Do not overlap dumplings. Store in freezer up to 1 month.",
            "You don’t need to thaw the potstickers before cooking. Heat a tablespoon of oil until hot and place dumplings in one at a time. Swirl in 4 tablespoons water and cover. Cook over medium heat until cooked through, about 5 minutes. Remove the cover and flip one potsticker to see whether the bottom side is charred. If not, turn to medium high heat and cook until the bottom side turns golden brown, about 1 minute.",
        ]
    ),
    "Xinjiang Lamb Skewers": RecipeDetail(
        ingredients: [
            "1 lb lamb meat ((lean fat ratio 7:3) (*See footnote 1))",
            "1/2 onion (, sliced)",
            "2 tablespoons whole cumin seeds ((Optional))",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "2 tablespoons light soy sauce ((or soy sauce, or tamari for gluten-free))",
            "2 teaspoons cornstarch",
            "2 teaspoons cumin powder and extra for grilling",
            "1/2 teaspoon chili powder and extra for grilling",
            "1/2 teaspoon salt",
            "1/4 teaspoon Sichuan peppercorn powder ((Optional))",
        ],
        steps: [
            "Combine oil, soy sauce, cornstarch, cumin powder, chili powder, and salt in a small bowl. Mix well.",
            "Trim fat from the lamb meat if necessary. Cut lean part into 1.5-cm (0.5-inch) cubes. Cut fat into thin pieces half the size of the lean pieces.",
            "Thread lamb cubes closely onto skewers, alternating between lean meat and fat cubes (*see footnote 2).",
            "Spread onion inside a 1-gallon ziploc bag. Place lamb skewers on top of the onion. Pour the marinade over the lamb. Massage the bag so the lamb is covered evenly with the marinade. Seal both sides of the bag and place upside down, the onions facing up. Let marinate for 30 minutes at room temperature or overnight in the fridge.",
            "Build a modified two zone fire, and leave some space without any coal.",
            "Transfer the lamb skewers onto the grilling grate, one finger’s width apart. Flip frequently until the lamb turns dark brown on all surfaces. Move to indirect fire. Generously sprinkle a layer cumin powder, then chili powder (or you can skip the chili powder if you don’t want the lamb to be too spicy). Flip, then sprinkle another layer of cumin powder. Sprinkle whole cumin seeds onto the lamb for extra flavor, if using. Grill until the meat is cooked through.",
            "Serve immediately. Or move to the side of the grill without coal to keep warm.",
        ]
    ),
    "Chive Pockets": RecipeDetail(
        ingredients: [
            "3 to 4 tablespoons peanut oil ((or vegetable oil, to fry the pockets))",
            "2 cups (300 g) all-purpose flour",
            "1 teaspoon salt",
            "1/2 teaspoon sugar",
            "3/4 cup (180 ml) water",
            "2 teaspoon peanut oil ((or vegetable oil))",
            "4 large eggs",
            "2 teaspoons Shaoxing wine ((or dry sherry, or chicken stock))",
            "1 teaspoon salt (, divided)",
            "1/4 cup papery dried shrimp ((Optional))",
            "2 tablespoons peanut oil (, seperated (or vegetable oil))",
            "1/2 lb (225 g) chinese chives (, cut into 1/4” (0.6 cm) pieces)",
            "2 tablespoons oyster sauce",
            "2 teaspoons sesame oil",
        ],
        steps: [
            "In a large bowl combine the all-purpose flour, salt, and sugar. Stir with a fork to mix well.",
            "Microwave the water to approximately 180 degrees F (80 C). It should be too hot to touch but not boiling.",
            "Slowly add the hot water into the flour mixture, stirring with a fork to mix the water into the flour.",
            "Once all the water is added, work the water into the flour until it forms large doughy flakes without any dry flour left. Feel the flakes with your hand. It should be quite firm and not too soft. If there’s still a lot of dry flour left, add 1 more tablespoon of water.",
            "Add the oil. Mix and knead with your hand until it forms a dough ball.",
            "Transfer the dough ball onto a clean working surface. Knead by hand for 5 to 8 minutes, until the dough becomes firm. It is OK if the surface is not smooth.",
            "Return the dough to the bowl and cover with plastic wrap. Let rest for 30 minutes.",
            "Prepare the filling while the dough rests. Combine the eggs, Shaoxing wine, and salt in a medium-sized bowl. Whisk until evenly mixed.",
            "Heat 1 tablespoon of oil in a medium-sized pan over medium heat until hot.",
            "(Optional) Add the dry shrimp. Cook and stir until it turns golden brown, 1 minute or less.",
            "Add the egg mixture. Stir with a spatula to scramble the eggs and cut them into smaller pieces. Cook until the eggs just begin to firm up. Transfer to a plate to cool.",
            "Add the chives into a large bowl. Add the remaining 1 tablespoon of peanut oil. Mix with a spatula until the chives are evenly coated with a thin layer of oil.",
            "Once the eggs are cooled, add them into the bowl with the chives. Add the oyster sauce and sesame oil. If you aren’t using the papery dried shrimp, add 1/2 teaspoon salt into the mixture.",
            "Once the dough has rested, the surface should become smoother and the texture softened. Divide the dough into two even pieces using a knife of dough cutter. Work on the dough one piece at a time. Place one piece back into the bowl and cover with plastic wrap.",
            "Roll the dough on the working surface until it forms a ball. Cut the dough in half. Roll each piece into a long log, then divide it into 3 even pieces.",
            "Add a small spoon of oil onto your working surface and use your hand to grease the surface. It prevents the dough from sticking to the surface.",
            "Work on the dough one piece at a time. Roll the dough with both of your hands until it forms a ball.",
            "Press the dough with your hand, then roll it out into a 6” (15 cm) disk.",
            "Use a measuring cup to scoop 1/4 cup of egg-chive filling, press it down with your hand, and add more filling so it fills the cup tightly (very important). Add the filling onto the center of the rough disk. Fold the dough over it to create a half moon. Gently use your hand to press the filling to even it out.",
            "Seal the edges of the dough together by gently pressing the dough and pressing out as much of the air bubbles as you can.",
            "Crimp the edges by folding the excess dough together along the edge using your hand, one finger width at a time, until it forms a pattern. Cut off any extra dough at the end and discard it. If you don’t know how to crimp the edges, you can simply press the dough together so it won’t break apart during cooking.",
            "Heat 1 to 2 tablespoons of oil in a large nonstick frying pan over medium heat until hot. Pan fry the Chinese chive pockets until the bottom turns golden brown, 2 minutes or so. Turn to the other side and fry until golden brown. If the pan starts to smoke, turn to medium-low heat. If your chive pockets are thick, you can also stand them upright in the pan to fry the edge.",
            "Once done, transfer the chive pockets to a big plate. Serve hot with Chinkiang vinegar (highly recommended) or dumpling sauce. You can add soy sauce to the vinegar if you think the pockets are not salty enough.",
            "To store the chive pockets, place in a ziplock bag, using parchment paper to separate the pockets. Squeeze out as much air as possible, and seal the bag. Freeze them for up to 2 months. To reheat frozen pockets, you don’t need to thaw them. Cook them in the pan just like if you were making fresh ones, except that you’ll need to cover the pan and add a splash of water while heating. Once heated through, open the lid and cook a bit longer to crisp up the surface.",
        ]
    ),
    "Chive and Egg Stir Fry": RecipeDetail(
        ingredients: [
            "25 stalks (120 g) Chinese chives",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "4 eggs",
            "1/2 teaspoon salt ((*Footnote 1))",
            "1/4 teaspoon white pepper",
        ],
        steps: [
            "Wash the Chinese chives thoroughly to remove any dirt. Then drain thoroughly. Cut and discard the tough ends, about 1” (2.5 cm). Cut the chives into 1/2” (1 cm) pieces.",
            "Heat 1 tablespoon of oil in a large skillet over medium-high heat until hot. Add the chives. Cook and stir until the chives turn tender, 1 to 2 minutes. Transfer to a plate to cool slightly.",
            "Beat the eggs in a large bowl with salt and white pepper. Add back the cooked chives. Mix well.",
            "Heat the remaining oil in the same skillet over medium-high heat until hot. Pour in the egg and chive mixture. Scramble the eggs lightly. Cook until the eggs reach the desired texture - you can keep the eggs a bit tender and silky, or cook until the eggs are lightly browned on the outside for a crispy texture. Transfer to a plate and serve hot as a side or main dish.",
        ]
    ),
    "Homemade Egg Noodles": RecipeDetail(
        ingredients: [
            "300 g (2 cups) all-purpose flour ((*Footnote 1))",
            "3 Pete &amp; Gerry’s large eggs",
            "2 tablespoons (30 ml) cold tap water",
            "1/4 teaspoon salt",
            "Cornstarch ((for coating the noodles))",
        ],
        steps: [
            "Add the flour and salt into a large mixing bowl. Mix well and make a well in the center. Add the eggs and the cold water into the well. Stir to mix everything together until shaggy dough flakes form. There should be little dry flour in the bowl and the dough flakes should be semi-soft without being sticky. If there is too much dry flour in the bowl, add 1 more tablespoon of cold water and stir to mix again.",
            "Press the dough flakes together with your hands until the dough is mostly formed. The dough can be slightly sticky to the hands, but still quite firm.",
            "Transfer the dough onto a clean work surface. Knead with hands until the water is evenly absorbed and a springy dough forms, 10 to 15 minutes. If the dough sticks to the work surface too much, dust the surface with all-purpose flour and keep kneading. If the dough is very dry and hard to work with, wet the surface of the dough with some water and knead until the water is fully mixed in.",
            "Place the dough into the mixing bowl and cover with plastic wrap. It’s OK if the surface of the dough is not super smooth. Let rest for 30 minutes.",
            "Once the dough is rested, gently knead the dough again for 1 to 2 minutes so it’s very smooth. Let the dough rest, covered, for another 10 to 20 minutes to relax it.",
            "Divide the dough into halves. Cover up the half you’re not working with.",
            "Dust the work surface with cornstarch and place one piece of dough on top. Press and roll the dough into a small rectangle shape. If the dough springs back and is very hard to knead, you can cover it up and let it rest another 10 to 20 minutes to relax it.",
            "Then roll the dough with a rolling pin into a very large thin sheet, about 1/8” (3 mm) thick, 18” long and 10” wide.Dust the top of the dough with cornstarch again. Fold the dough up along the long side, twice, into a long roll. Then slice the dough into noodles depending on the width you prefer, 1/8” for thin noodles, 1/4” wide for medium noodles, or 3/4” wide for wide noodles. Use your hands to gently pull each noodle so the length increases by 1/3. Set aside and work on the rest of the noodles in the same way.",
            "Lightly dust all the noodles with cornstarch and fluff the noodles to coat evenly.",
            "Now you can boil the noodles and serve them directly. If not used immediately, store the noodles in a sealed bag or container in the fridge for up to a day, or in the freezer for up to 3 months. You don’t need to thaw the noodles before boiling.",
            "To boil the noodles, bring a large pot of water to a boil. Boil the noodles for 2 minutes or so, or until fully cooked through (the cooking time depends on the thickness of the noodles you make).",
        ]
    ),
    "Egg Fried Rice": RecipeDetail(
        ingredients: [
            "2 tablespoons peanut oil ((or vegetable oil))",
            "4 eggs (, beaten )",
            "3 cups cooked white rice ((day-old rice works best))",
            "1/2 teaspoon salt ((or to taste, and a pinch of chicken bouillon if preferred))",
            "4 green onions (, sliced)",
            "1 teaspoon toasted sesame oil ((Optional))",
        ],
        steps: [
            "Add oil to a large skillet and heat over medium-high heat until smoking. Pour in the beaten eggs. Wait until the bottom of the eggs is set. Lightly scramble the eggs until mostly set but some parts are still runny.",
            "Add the rice on top of the runny egg. Use your spatula to chop the rice to separate it into small pieces, so some of the rice is coated with egg. Keep stirring and chopping the rice until the rice is well separated.",
            "Sprinkle with salt and add the green onion. Keep cooking and stir occasionally, until the rice turns slightly golden and crispy, 2 to 3 minutes. Taste the rice. Adjust seasoning by adding more salt (or a touch of chicken bouillon or MSG), if needed. You can leave the rice in the pan for a couple more minutes after turning off the stove, so the rice gets even crispier.",
            "(Optional) If you used a neutral oil like vegetable oil, add toasted sesame oil after turning off the heat. Stir to mix again.",
            "Transfer everything to a plate and serve hot as a side dish or a light main dish.",
        ]
    ),
    "Garlic Green Beans": RecipeDetail(
        ingredients: [
            "1 lb green beans (, tough ends removed)",
            "3 to 4 tablespoons peanut oil ((or vegetable))",
            "6 cloves garlic (, minced)",
            "1 thumb minced ginger",
            "1 tablespoon Shaoxing wine ((or dry sherry, or chicken broth))",
            "1 teaspoon soy sauce",
            "1/2 teaspoon salt",
            "Chinese chili flakes ((for garnish) (Optional))",
        ],
        steps: [
            "Thoroughly pat the green beans dry with paper towels to prevent oil splatter.",
            "Heat 3 tablespoons of oil in a large skillet over medium-high heat until hot. Turn to medium heat and add the green beans. Toss to coat well with the oil. Spread out the green beans as much as possible with minimal overlap and sprinkle with the salt. Let cook without touching for 2 to 3 minutes, until the bottom starts to blister and turn golden. Remove any green beans that have blistered and charred on one side and transfer them to a big plate. Keep cooking the rest of the green beans, flipping occasionally and taking out the ones that are blistered. The whole process should take about 6 to 8 minutes.",
            "If your pan looks dry, add the remaining 1 tablespoon of oil. Otherwise, directly add the garlic and ginger to the pan. Stir and cook for a few minutes to release fragrance. Add back all the cooked green beans and stir to mix a few times.",
            "Pour in the Shaoxing wine and soy sauce and sprinkle with salt. Stir immediately to mix everything well. Taste the green beans. Adjust seasoning by adding more salt or soy sauce, if needed.",
            "Transfer everything to a big plate. Sprinkle with chili flakes, if using. Serve hot as a side dish.",
        ]
    ),
    "Steamed Tofu": RecipeDetail(
        ingredients: [
            "1 block (1 lb / 450 g) soft tofu (, drained and sliced into 1/2” (1 cm) thick pieces)",
            "1 tablespoon light soy sauce",
            "1 tablespoon vegetarian oyster sauce ((or oyster sauce))",
            "1/2 teaspoon sugar",
            "Pinch of salt",
            "2 cloves garlic (, minced)",
            "2 green onions (, thinly sliced)",
            "2 teaspoons grated ginger",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "2 dried chili peppers",
            "1/4 teaspoon ground Sichuan peppercorn ((or black pepper))",
        ],
        steps: [
            "Prepare the steamer by adding 2” (5 cm) water to the pot and heat over medium-high heat until brought to a boil.",
            "Arrange the tofu on a plate that can fit into your steamer with as little overlap as possible. Place the plate onto the steaming rack.",
            "When the water is boiling, add the steaming rack. Steam covered for 6 minutes. Once done, carefully remove the plate from the steamer (*Footnote 1). Let the plate cool off for a few minutes. Then tilt the plate to drain off as much water as you can.",
            "While cooking the tofu, mix the light soy sauce, vegetarian oyster sauce, sugar and salt together in a small bowl.",
            "When the tofu is ready, heat the oil in a small skillet over medium heat until hot but not smoking. Add the chili peppers, garlic, ginger, a small amount of the green onion (*Footnote 2), and Sichuan peppercorns. Stir a few times until the chili peppers turn dark red. Immediately pour the oil with everything evenly over the tofu. Then pour the mixed sauce over the tofu.",
            "Serve warm or at room temperature as an appetizer, or over steamed rice as a main dish.",
        ]
    ),
    "Braised Daikon": RecipeDetail(
        ingredients: [
            "1 tablespoon vegetable oil",
            "2 green onions (, chopped)",
            "1 teaspoon ginger (, minced)",
            "1 pound (450 grams) ground meat ((beef, pork, chicken, or turkey))",
            "2 teaspoons Doubanjiang ((Spicy Fermented Bean Paste))",
            "1 Daikon radish ((about 700 grams / 2 pounds))",
            "2 cups chicken stock ((vegetable stock, or water))",
            "1 tablespoon soy sauce",
            "1 tablespoon Shaoxing wine ((or dry sherry) (Optional))",
            "1 tablespoon sugar",
            "1/8 teaspoon five-spice powder",
            "1/4 teaspoon fine sea salt (or to taste)",
        ],
        steps: [
            "Heat a medium-size dutch oven (or heavy duty pot) over medium heat until hot. Add a tablespoon of oil. Add green onion and ginger. Cook for a minute to release the flavor.",
            "Add ground meat. Cook and stir until surface turns brown.",
            "Add the doubanjiang. Cook and stir until the meat is evenly coated.",
            "Add the radish. Cook and stir to mix well.",
            "Add Shaoxing wine, chicken stock, soy sauce, sugar, and five spice powder. Cook over medium high heat until brought to a boil. Turn to medium low heat. Simmer for 15 to 20 minutes, or until the radish turns tender. Add salt to taste.",
            "Serve with steamed rice or by itself.",
        ]
    ),
    "Home Style Tofu": RecipeDetail(
        ingredients: [
            "1 block (14 oz/396 g) soft or medium firm tofu (, cut into 1 cm thick triangles (Footnote 1))",
            "1 cup vegetable oil (, for deep frying)",
            "4 cloves garlic (, sliced)",
            "1 &quot; (2.5 cm) ginger (, thinly sliced into strips)",
            "3 green onions (, cut into 1&quot; pieces, white and green parts separated)",
            "1 tablespoon doubanjiang",
            "1/2 carrot (, sliced (about 1/3 cup))",
            "1 bell pepper (, cut into 1” diamonds)",
            "1 (8-oz / 226 g) can sliced bamboo shoots (, or 1 bamboo shoot, sliced (about 1/3 cup))",
            "1 teaspoon sesame oil",
            "3 tablespoons light soy sauce ((or soy sauce))",
            "1 tablespoon Chinkiang vinegar",
            "2 teaspoons vegetarian oyster sauce ((or sweet bean paste) (Footnote 2))",
            "1 tablespoon sugar",
            "3 tablespoons water ((or vegetable stock))",
            "1 1/2 teaspoons cornstarch",
            "1 tablespoon water",
        ],
        steps: [
            "Mix the sauce ingredients together in a medium bowl.",
            "Add the slurry ingredients into a small bowl and stir to mix well.",
            "In a high-walled skillet or pot, heat the oil to 375°F (190°C). Carefully add the tofu. Fry until both sides turn golden, about 3 minutes. Flip once or twice to ensure even cooking. Remove the tofu from the oil and transfer it to a big plate.",
            "Pour off all but 1 tablespoon of oil from the pan (alternatively, you can heat 1 tablespoon of oil in another large skillet).",
            "Add the garlic, ginger, green onion (white part), and doubanjiang to the pan. Turn the heat to medium. Stir fry to release the fragrance until the oil turns red, about 2 minutes.",
            "Add the fried tofu, carrots, bell peppers, and bamboo. Stir fry for 30 seconds to 1 minute.",
            "Pour in the sauce. Bring to a boil then reduce to a simmer, gently flipping occasionally. Simmer for 5 minutes.",
            "Add the green onion (green part). Mix the slurry again so the cornstarch is fully dissolved. Pour in the slurry and mix with a spatula until the sauce thickens.",
            "Drizzle in a teaspoon of sesame oil to finish up.",
            "Serve hot over steamed rice as a main dish.",
        ]
    ),
    "Braised Bamboo with Mushrooms": RecipeDetail(
        ingredients: [
            "6 dried shiitake mushrooms",
            "1 whole bamboo shoot ((*Footnote 1))",
            "1 teaspoon salt ((optional))",
            "2 tablespoons oyster sauce",
            "1 teaspoon light soy sauce",
            "1 teaspoon sugar",
            "2 tablespoons vegetable oil ((*Footnote 2))",
            "1 thumb ginger (, sliced)",
            "2 teaspoons Shaoxing wine",
        ],
        steps: [
            "Add the dried shiitake mushrooms to a medium bowl and warm water to cover. Soak for 15 minutes or so, until turning tender. Reserve 1/2 cup mushroom soaking water. Drain, squeeze out water and pat dry. Remove the stem and slice in half.",
            "(Optional) If using a fresh bamboo shoot, remove the tough outer layers by slicing across the shoot once lengthwise so it’s easier to peel, then cut off about 1” from the tip. Peel off and discard the tough outer skins. Then use a pairing knife to shave off any uneven layers, so the surface is more even and smooth. Cut into bite-size pieces. (See my blog post above for the step-by-step cutting pictures.) Bring a big pot of water to a boil. Add salt and bamboo shoot. Cook for 5 minutes. Drain and pat dry. (*Footnote 3)",
            "Mix the oyster sauce, light soy sauce and sugar together in a small bowl.",
            "Heat oil in a wok over medium-high heat until it shimmers. Add the ginger and shiitake mushrooms. Cook and stir for 30 seconds, until lightly charred.",
            "Add the bamboo shoots. Stir and cook for another 2 minutes, until the bamboo is lightly charred.",
            "Pour in the Shaoxing wine to deglaze. Then pour in the reserved mushroom soaking water and the mixed sauce. Cover and braise for 3 to 4 minutes. Then uncover and keep cooking to reduce the sauce, stirring frequently to prevent sticking. Once the sauce has thickened enough to coat the ingredients, turn off the heat and transfer everything to a plate. Serve hot.",
        ]
    ),
    "Braised Winter Melon": RecipeDetail(
        ingredients: [
            "1/2 lb ground chicken",
            "1 tablespoon Shaoxing wine",
            "1/2 teaspoon salt",
            "2 teaspoons cornstarch",
            "1 lb winter melon ((*Footnote 1))",
            "1 tablespoon vegetable oil",
            "2 teaspoons ginger (, minced)",
            "2 scallions (, sliced, white and green parts divided)",
            "1 tablespoon Shaoxing wine",
            "2 cups chicken stock",
            "1 tablespoon light soy sauce",
            "1 teaspoon sugar",
            "1 1/2 tablespoons cornstarch",
            "1 teaspoon toasted sesame oil",
        ],
        steps: [
            "Combine ground chicken, Shaoxing wine, salt and cornstarch in a medium bowl. Marinate for 10 minutes while preparing other ingredients.",
            "Deseed the winter melon using a paring knife to slice off the soft part that’s attached to the seeds. Divide the winter melon into 2 to 3 large pieces so it’s easier to work with. Slice off the skin about 1/4” (1/2 cm), until you no longer see green color on the winter melon flesh. Then slice it into 1/2” (1 cm) thick slices. (See the step-by-step pictures in my blog post on how to cut winter melon.)",
            "Heat oil in a wok or large skillet over medium-high heat until it shimmers. Add ginger and scallion whites. Stir to release fragrance, 30 seconds or so. Add the ground chicken. Cook, breaking into smaller pieces, until the surface turns golden, 2 to 3 minutes.",
            "Add the winter melon. Stir and cook to coat well with oil, 1 minute or so.",
            "Pour in Shaoxing wine to deglaze. Then add the chicken stock, light soy sauce and sugar. Stir to mix well. Bring to a boil, then simmer over medium heat until the winter melon turns tender, 8 minutes or so. (*Footnote 2)",
            "Add the cornstarch and 1 tablespoon water in a small bowl, stir to dissolve completely. Pour into the wok. Turn to medium heat. Cook and stir until the broth thickens. Garnish with sesame oil and scallion greens. Transfer to a serving plate. Serve hot.",
        ]
    ),
    "Winter Melon Soup": RecipeDetail(
        ingredients: [
            "6 oz ground pork",
            "1 tablespoon Shaoxing wine",
            "2 teaspoons light soy sauce",
            "1 teaspoon grated ginger",
            "1/4 teaspoon salt",
            "1 egg white",
            "2 tablespoons water",
            "2 teaspoons cornstarch",
            "1 1/2 to 2 lbs winter melon",
            "4 cups chicken stock ((or homemade pork stock) (*see footnote))",
            "2 slices ginger ((Optional))",
            "1/4 teaspoon salt (, or to taste (use 1/2 teaspoon salt if using homemade unsalted broth))",
            "1/3 cup cilantro (, chopped (For garnish))",
        ],
        steps: [
            "Combine the ground pork, Shaoxing wine, light soy sauce, minced ginger, salt, egg white and water in a medium-sized bowl. Stir with a spatula to mix well. Add the cornstarch. Mix until the ground pork becomes pasty and sticky. Set aside to marinate.",
            "To prepare the winter melon. Chop it into 3 to 4 pieces. Use a knife to slice the rind off and discard it. Cut off the soft inner part and discard it. Slice the winter melon into even 1/2” (1 cm), large bite-size pieces.",
            "Add the broth and ginger (if using) to a medium-sized pot and bring to a boil over medium-high heat. Turn to medium-low heat. Use a spoon to scoop about 1 tablespoon of the ground pork mixture, shape it into a ball, and add it to the soup. Make the meatballs one at a time. After the last meatball is added, cook for 1 minute. Stir the soup gently 2 to 3 times. Immediately transfer all the meatballs to a plate and set aside. The meatballs should be cooked on the outside but still raw inside.",
            "Add the winter melon to the pot. Bring the soup to a boil over high heat. Turn to medium heat and boil until the winter melon is almost cooked through, 6 to 8 minutes. The edges of the winter melon should have turned semi-transparent.",
            "Add the meatballs back into the soup. Bring the soup back to a boil and cook for 1 minute. Turn off the heat, cover, and allow the soup to sit for another 5 minutes. The residual heat will further gently cook the meatballs so they remain super tender and juicy. Add the salt and mix well. Taste the soup and adjust seasoning if needed.",
            "Add cilantro to the soup and serve hot.",
        ]
    ),
    "Winter Melon Stir Fry": RecipeDetail(
        ingredients: [
            "1/2 carrot (, cut into 2x1/2” (6x1 cm) batons (about 4 oz) (Optional) (*Footnote 1))",
            "1 1/2 lbs (680 g) winter melon (, peeled and cut into 2x1/2” (6x1 cm) batons)",
            "1 tablespoon peanut oil",
            "2 tablespoons papery shrimp ((*Footnote 2))",
            "2 cloves garlic (, minced)",
            "1 long green pepper (, sliced (Optional) (*Footnote 3))",
            "1/2 teaspoons mushroom powder ((or chicken powder) (*Footnote 4))",
            "1 teaspoon sugar",
            "1/4 teaspoon salt ((or to taste))",
            "1/2 teaspoon cornstarch",
            "1 teaspoon water",
        ],
        steps: [
            "Combine the cornstarch and water in a small bowl. Stir to mix well and set aside.",
            "Prepare a large skillet and add about 3” (8 cm) of water. Bring to a boil and add a pinch of salt. Add the carrots and boil for 1 minute. Add the winter melon and boil for another 1 to 2 minutes, until slightly softened but not yet translucent. Drain the cooked vegetables and rinse with cold water to stop the cooking. Drain again and set aside in a big plate.",
            "Return the pan to the stove and wipe clean with a paper towel. Add the oil and heat over medium heat until hot. Add the papery shrimp. Stir and cook until the shrimp turn golden, 1 minute or so.",
            "Add the garlic and stir a few times to release the fragrance.",
            "Add the pepper. Cook and stir for 1 minute.",
            "Add the blanched carrot and winter melon, mushroom powder, sugar, and a pinch of salt. Stir and cook until the seasonings are evenly distributed and the winter melon turns tender but is not falling apart, 1 to 2 minutes.",
            "Stir the slurry ingredients again to fully dissolve the cornstarch and pour it over the vegetables. Stir gently until the sauce thickens slightly, 1 minute or so. Carefully taste the winter melon and add more salt, if needed.",
            "Serve hot as a side dish.",
        ]
    ),
    "Napa Cabbage Soup": RecipeDetail(
        ingredients: [
            "2 large slices ginger",
            "3 to 4 green onions (, chopped)",
            "1/4 cup chopped pancetta ((or bacon))",
            "1 cup chicken stock (or 2 cups, if you want the soup to be extra rich) ((Optional))",
            "1/4 cup dried shrimp",
            "1/4 cup dried scallops",
            "3 cups chicken stock ((or pork stock))",
            "1/2 pound (230 grams) ground turkey ((or ground pork))",
            "1/4 cup finely chopped green onion (green part) ((Optional))",
            "1 tablespoon Shaoxing wine ((or dry sherry or Japanese sake))",
            "2 teaspoons soy sauce or tamari for gluten-free",
            "2 teaspoons potato starch",
            "1 teaspoon ginger (, grated)",
            "1 large egg",
            "1/4 teaspoon salt",
            "1 teaspoon sesame oil ((or peanut oil, or vegetable oil))",
            "6 to 8 large napa cabbage leaves (, chopped (generate 6 to 8 cups))",
            "1/2 daikon radish, peeled and chopped (generates 2 cups) ((Optional))",
            "1 batch enoki mushrooms (golden needle mushrooms, tough ends removed and separated)",
            "1/2 (400g / 14-ounces) block soft tofu (, chopped)",
            "Sea salt to taste",
        ],
        steps: [
            "Heat a 3.8-liter (4-quart) pot over medium heat and add the fatty parts of the pancetta. When it starts to sizzle, turn to medium low heat. Stirring occasionally, cook until the fat renders and the pancetta turns golden.",
            "Add the lean parts of the pancetta. Continue cooking and stirring until brown.",
            "Add chicken stock and immediately use a spatula to scrape the brown bits off the bottom of the pot. Add 2 cups water (add 1 cup water, if using 2 cups chicken stock; or 3 cups water + 1 tablespoon oyster sauce or hoisin sauce, if you do not want to use chicken stock), ginger, and green onion. Cook over high heat until boiling. Turn to medium low heat. Cover and boil for 5 minutes.",
            "Rinse dried scallops. Place scallops in a small bowl and add water to cover. Rehydrate for 2 to 3 hours. Drain and tear into small pieces.",
            "Rinse dried shrimp, transfer to a small bowl, and add water to cover. Rehydrate for 30 minutes. Drain and set aside.",
            "Combine the rehydrated scallops and shrimp, ginger, green onion, and 3 cups water in a 3.8-liter (4-quart) pot. Heat over high heat until boiling. Turn to medium heat. Cover and let simmer for 5 minutes.",
            "Combine chicken stock (or pork stock), ginger, and green onion in a 3.8-liter (4-quart) pot. Heat over high heat until boiling. Turn to medium heat. Cover and boil for 5 minutes.",
            "Combine all the ingredients for the meatballs in a large bowl. Stir until all ingredients are just combined and form a slightly runny mixture. Do not over-stir it. Let sit for 5 to 10 minutes.",
            "Rinse and cut veggies while letting the stock simmer.",
            "Add daikon radish into the soup pot. Cover and cook for 5 minutes.",
            "Add the thick parts of the napa cabbage. Cover and cook for 5 minutes.",
            "Add the green parts of the napa cabbage and enoki mushroom into the soup. Cook for 2 to 3 minutes.",
            "You can adjust the seasoning at this point, by adding a bit salt, if needed.",
            "Add soft tofu. Push all the ingredients to one side of the pot, to clear some space for the meatballs. (If you don’t have enough space in the pot, you can take out some of the napa cabbage leaves)",
            "Use a spoon to scoop 1 to 1.5 tablespoons of the meatball mixture and carefully add it into the soup. Repeat this until you’ve made about 15 meatballs.",
            "Cover the pot and simmer until the meatballs are just cooked through, 4 to 5 minutes. Turn off heat immediately and remove the pot from the stove, keeping it covered.",
            "Serve hot as a main or side. To make it a full meal, you can boil some noodles (or mung bean noodles or shirataki noodles) and add them into the soup at the end of cooking. In this case, you might want to add a bit more salt or light soy sauce, to make the broth a bit saltier. This way, it will taste just right with the noodles.",
        ]
    ),
    "Napa Cabbage with Glass Noodles": RecipeDetail(
        ingredients: [
            "4 oz. (100 g) potato noodles",
            "1 1/2 lbs (700 g) napa cabbage ( (about 6 cups chopped))",
            "2 tablespoons soy sauce",
            "1/2 tablespoon dark soy sauce",
            "1 tablespoon oyster sauce ((or Chee Hou Sauce))",
            "1 teaspoon sugar",
            "1 1/2 tablespoons peanut oil ((or vegetable oil))",
            "2 teaspoons Sichuan peppercorns",
            "2 green onions (, chopped)",
            "1 tablespoon ginger (, minced)",
        ],
        steps: [
            "Add the potato noodles into a big bowl and add hot water to cover. Let sit for 10 minutes, or until the noodles turn al dente. Drain the hot water, rinse the noodles with running tap water, drain again, and set aside.",
            "To chop the napa cabbage, halve the head of napa cabbage, then cut it into quarters. Tilt your knife to split the quarters in half again. Then cut the napa cabbage into bite-size pieces (see the step-by-step photos in the blog post).",
            "Mix the sauce ingredients together in a small bowl.",
            "Heat the peanut oil in a large nonstick skillet over medium-high heat. Add the Sichuan peppercorns. Cook and stir until the Sichuan peppercorns turn dark, but are not burned. Remove the Sichuan peppercorns and discard them.",
            "Add the green onions and ginger. Stir for 30 seconds to release the fragrance.",
            "Add the napa cabbage. Let it cook, stirring occasionally, until it’s withered but not soft, 5 minutes or so.",
            "Turn to medium heat. Pour the sauce over the skillet and stir to mix well.",
            "Add the soaked noodles. Stir again. Cover the skillet and let it cook until the napa cabbage turns soft, 2 to 3 minutes.",
            "Uncover the pan. Toss everything again. If there’s too much residual liquid, you can turn to medium-high heat again and cook for another 1 to 2 minutes, to thicken the sauce.",
            "Transfer everything to a plate and serve hot as a side dish.",
        ]
    ),
    "Bok Choy with Oyster Sauce": RecipeDetail(
        ingredients: [
            "1 lb baby bok choy",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "2 dried chili peppers",
            "2 teaspoons ginger (, minced)",
            "1/2 teaspoon sugar",
            "1 tablespoon soy sauce",
            "2 tablespoons oyster sauce",
        ],
        steps: [
            "Cut off the ends of baby bok choy and discard. Separate the larger leaves of baby bok choy. Soak in cold water for 2 minutes, then rinse to remove any dust. Cut the stems into 1/2” pieces and the leaves into 2” pieces. Separate the whites and greens. Halve the cores.",
            "Heat oil in a wok over medium-high heat until smoking. Add chili peppers and ginger. Stir a few times to release fragrance.",
            "Add the baby bok choy whites and turn to high heat. Stir a few times to coat evenly with oil, spread them out and sear until the white part just starts to turn tender, 1 to 2 minutes.",
            "Add the baby bok choy greens and sprinkle with sugar. Stir to mix well. Add the soy sauce and oyster sauce. Stir immediately to mix the ingredients. Cook and stir until the greens are wilted, then transfer everything to a big serving plate. Serve hot as a side dish.",
        ]
    ),
    "Gai Lan with Oyster Sauce": RecipeDetail(
        ingredients: [
            "2 tablespoons oyster sauce",
            "1/2 teaspoon sugar",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "10 oz Chinese broccoli (, tough ends and stem surfaces removed)",
            "1 tablespoon garlic (, minced)",
            "1 teaspoon ginger (, minced)",
        ],
        steps: [
            "Combine the oyster sauce, sugar and 2 tablespoons of water in a small bowl. Mix well and set aside.",
            "Bring a large pot of water to a boil. Add a pinch of salt and a drizzle of oil for vibrant color (Optional). Add the Chinese broccoli and boil over medium heat, until the broccoli is cooked through and the stem part remains crisp, 1 to 2 minutes. Drain broccoli, rinse with cold tap water for a few seconds to stop cooking, then drain again and transfer to a large plate. Spread them out so there’s little overlap. If the Chinese broccoli is very wet, you can use paper towels to pat the surface dry.",
            "Heat a small skillet or a saucepan over medium heat until hot. Add peanut oil, garlic and ginger. Stir a few times until fragrant.",
            "Turn to low heat. Add the oyster sauce mixture and stir immediately. When the sauce becomes fragrant, after 10 to 20 seconds, pour the oyster sauce over the Chinese broccoli. Serve immediately as a side dish.",
        ]
    ),
    "Yu Choy Stir Fry": RecipeDetail(
        ingredients: [
            "1 lb (450 g) yu choy",
            "3 cloves garlic (, coarsely chopped)",
            "1 tablespoon peanut oil ((vegetable oil))",
            "1/4 teaspoon salt ((or to taste))",
        ],
        steps: [
            "Remove the tough ends of the yu choy. Slice the stem into small bite-size pieces, and cut the leaves into large bite-size pieces. Separate the stems and leaves.",
            "Heat oil in a large skillet (or wok) over high heat until hot. Add the garlic. Stir a few times to release fragrance.",
            "Add the yu choy stems. Stir and cook for 30 seconds. Add the leaves. Stir a few times to coat with oil. Sprinkle the salt evenly. Keep stirring until the leaves are just withered and the stems turn tender. Turn to low heat and taste the yu choy carefully. Adjust seasoning by adding more salt, if needed. Transfer everything to a plate and serve hot as a side dish.",
        ]
    ),
    "Lettuce with Oyster Sauce": RecipeDetail(
        ingredients: [
            "3 heads (340 g / 12 oz) romaine lettuce ((*Footnote 1))",
            "2 tablespoons vegetarian oyster sauce ((or regular oyster sauce))",
            "2 teaspoons soy sauce",
            "1 teaspoon sugar",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "5 cloves garlic (, minced)",
        ],
        steps: [
            "Cut the tough ends off the lettuce and halve the lettuce lengthwise. Rinse with cold tap water then drain thoroughly. Prepare a large bowl of water with ice for a water bath.",
            "Bring a medium pot of water to a boil. Add a few drops of vegetable oil and a pinch of salt (*Footnote 2). Add the lettuce leaves and turn off the heat. Stir for about 10 seconds, until the lettuce just starts to soften. Immediately drain and transfer the lettuce to the water bath to stop cooking. Then drain thoroughly again, remove excess water with paper towels, then transfer to a large plate.",
            "Mix the oyster sauce, soy sauce and sugar in a small bowl. Add 1 tablespoon of water and mix well.",
            "Add oil to a small frying pan and heat over medium heat until hot. Add the garlic. Stir and cook for a few seconds to release the fragrance. Pour in the mixed sauce and turn to medium low heat. Simmer and stir for 1 minute, until the sauce is thick and bubbly. If the sauce becomes too dry, add a splash of water and mix well. (*Footnote 3)",
            "Once the sauce is cooked, pour over the plated lettuce. Serve immediately as a side dish.",
        ]
    ),
    "Choy Sum with Garlic": RecipeDetail(
        ingredients: [
            "1/2 lb (225 g) choy sum",
            "2 teaspoons oyster sauce",
            "1 teaspoon light soy sauce",
            "1/8 teaspoon sugar",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "2 cloves garlic (, coarsely chopped)",
        ],
        steps: [
            "Soak the choy sum for a few minutes then wash with running tap water to remove any dirt. Discard any leaves that are withered or yellow. Drain thoroughly.",
            "Heat a big pot of water over medium-high heat until boiling. You can add a teaspoon of oil and a pinch of salt so the choy sum will have a brighter green color (Optional). Add the choy sum, stem side down, so the thicker part cooks longer. Cook the stem for 30 seconds to 1 minute, then submerge the leafy part into the hot water. Cook until the choy sum turns just tender, 1 to 2 minutes, or you can cook it until it reaches your desired texture. Drain the boiling water and rinse the choy sum under running tap water again to stop the cooking. Drain it thoroughly and pat dry with paper towels. Transfer it to a serving plate.",
            "Mix the sauce ingredients together in a small bowl.",
            "Heat the oil in a small saucepan over medium heat until hot. Add the garlic. Stir a few times to release the fragrance, 30 seconds or so.",
            "Pour in the sauce. Cook and stir until the sauce slightly thickens, 30 seconds to 1 minute. Immediately pour the sauce over the plated choy sum. Serve as a side dish.",
        ]
    ),
    "Bok Choy with Tofu Puffs": RecipeDetail(
        ingredients: [
            "1 lb (450 g) bok choy (, chopped to bite size pieces (see the cutting method in the post above))",
            "1 heaping cup (60 grams) tofu puffs (, halved)",
            "2 green onions (, sliced)",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "1 teaspoon sugar",
            "2 tablespoons light soy sauce ((or soy sauce))",
        ],
        steps: [
            "Heat 1 tablespoon of oil in a medium-sized wok or large skillet over high heat until hot. Add scallion and stir a few times until fragrant.",
            "Add bok choy. Stir and cook for 1 to 2 minutes, to coat evenly with oil.",
            "Sprinkle it with sugar and swirl in light soy sauce. Immediately stir a few times to mix well. Add deep fried tofu, then stir again for about 20 seconds.",
            "Cover the wok and lower to medium-low heat. Steam for 30 seconds. Uncover and stir to check the doneness. Cover and cook for another 10 to 20 seconds again, if necessary, until the bok choy is cooked through and slightly caramelized on the edges. Turn off the heat and transfer everything to a serving plate.",
            "Serve hot as a side dish or over steamed rice as a light main dish.",
        ]
    ),
    "Watercress Stir Fry": RecipeDetail(
        ingredients: [
            "1 bunch (1 lb / 450 g) watercress",
            "1 teaspoon oyster sauce ((or vegetarian oyster sauce))",
            "1 teaspoon soy sauce",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "3 cloves garlic (, sliced)",
            "1/8 teaspoon sugar",
            "Salt to taste ((Optional))",
        ],
        steps: [
            "Soak the watercress in cold tap water for 2 to 3 minutes while preparing other ingredients. Then drain thoroughly and set aside.",
            "Mix the oyster sauce and soy sauce together in a small bowl.",
            "Heat oil in a wok or large skillet over medium-high heat until hot. Add the garlic. Stir a few times to release fragrance.",
            "Add the watercress. Stir and cook a few times to mix well with the oil.",
            "Pour in the oyster sauce and soy sauce mixture. Sprinkle evenly with the sugar. Continue to stir as you cook, to mix the seasoning evenly. When the watercress turns tender but is still crisp, transfer everything to a plate. Turn to low heat and taste the sauce. Sprinkle with a small pinch of salt if needed (*Footnote 1). Serve hot as a side dish.",
        ]
    ),
    "Water Spinach Stir Fry": RecipeDetail(
        ingredients: [
            "1 batch water spinach ((*Footnote 1))",
            "1 to 2 tablespoons peanut oil ((*Footnote 2))",
            "2 to 3 Chinese chili peppers (, dried (*Footnote 3))",
            "2 blocks (1 tablespoon) fermented tofu ( (*Footnote 4))",
            "2 teaspoons liquid from the jar of fermented tofu",
            "1/2 teaspoon sugar",
            "3 cloves garlic (, sliced)",
            "6 cloves garlic (, minced and separated)",
            "2 tablespoons Shaoxing wine ((or chicken stock, or vegetable stock))",
            "1/4 teaspoon salt",
        ],
        steps: [
            "Prepare the water spinach by cutting off the tough stems, usually 2 to 3 inches from the bottom end. Discard the leaves that are withered, have brown spots, or have turned yellow. Thoroughly rinse with tap water and transfer to a colander to drain. Separate the stems and leaves with a pair of kitchen scissors. Cut the stems into 1-inch long pieces.",
            "Add the fermented tofu, the liquid from the jar, and the sugar into a small bowl. Use the back of your spoon to mash the tofu and stir it with the rest of the ingredients to make it into a sauce.",
            "Heat the oil in a large skillet (or woover medium-high heat until hot. Break apart the chili peppers and add them into the skillet. Add the garlic. Stir a few times to release the fragrance.",
            "Add the stems of the water spinach to the skillet. Cook and stir for a minute.",
            "Add the leaves of the water spinach. Cook, flipping occasionally using your spatula, until most of the parts are withered.",
            "Pour in the fermented tofu sauce. Stir until the water spinach turns tender and the sauce is evenly mixed. Transfer everything to a plate. Serve hot.",
            "Heat the oil in a large skillet (or woover medium-high heat until hot. Break apart the chili peppers and add them into the skillet. Add half of the garlic. Stir a few times to release the fragrance.",
            "Add the stems of the water spinach to the skillet. Cook and stir for a minute.",
            "Add the leaves of the water spinach. Cook, flipping occasionally using your spatula, a few times. Pour in the Shaoxing wine and sprinkle with salt. Cook and stir until most of the parts are withered.",
            "Add the remaining garlic. Stir a few times to mix well. Transfer everything to a plate. Serve hot.",
        ]
    ),
    "Watercress Wonton Soup": RecipeDetail(
        ingredients: [
            "30 wonton wrappers",
            "1 batch (8 oz. / 225 g) B&amp;W Quality Growers watercress ((or 6 oz. packaged leafy watercress) (*Footnote 1))",
            "1 3/4 teaspoons salt (, separated)",
            "4 oz. (112 g) ground pork",
            "1 teaspoon light soy sauce",
            "1 teaspoon Shaoxing wine ((or dry sherry))",
            "1 teaspoon sesame oil",
            "1/4 teaspoon sugar",
            "1 clove garlic (, grated)",
            "4 cups chicken stock",
            "2 green onions (, chopped)",
            "1 teaspoon light soy sauce ((or soy sauce))",
            "2 cloves garlic (, minced)",
            "2 teaspoons sesame oil (, toasted)",
            "Salt (to taste)",
            "Homemade chili oil ((Optional))",
        ],
        steps: [
            "Rinse the watercress thoroughly to remove any dirt. Remove the tough stems using your hands and discard the stems. Rinse the leafy parts with water again. Transfer to a big bowl. You will get about 6 oz. (170 g) of watercress after removing the stems. (*Footnote 1)",
            "Sprinkle with 1 1/2 teaspoons of salt and mix well with your hand. Let sit for 10 minutes. Once done, use your hands to squeeze the water out of the watercress, as much as you can, then drain it thoroughly and mince it into very small pieces.",
            "Combine the ground pork, light soy sauce, Shaoxing wine, sesame oil, garlic, and 1/4 teaspoon of salt in a big bowl. Stir for 5 minutes until it forms a sticky paste.",
            "Add the drained watercress into the bowl with the pork. Stir to mix well.",
            "Work on the wontons one at a time. Place a wonton wrapper on your palm with a pointed end facing up. Add about 1 teaspoon of filling onto the lower third of the wrapper. Fold the bottom point onto the filling, and roll the filling upward. Use your fingers to press the dough on both sides of the filling, squeezing out as much air as possible. Dip your finger into a bowl of water, wet the wrapper on both sides of the filling, bend the two ends toward the middle so they overlap, then press them together to seal the wonton.",
            "Place the wrapped wontons onto a tray and cover them with plastic wrap or a few layers of wet paper towel to prevent drying out.",
            "Combine the chicken stock, green onions, light soy sauce, and garlic in a pot. Cook until bringing to a boil. Let simmer for at least 5 minutes.",
            "While the wonton soup is cooking, heat another pot of water over medium-high heat until bringing to a boil. Add the number of wontons you plan to serve and make sure the wontons do not crowd the pot (the wontons should form a single layer in the pot without too much overlap). Gently stir to prevent them from sticking to the bottom. Cook until the wontons float on top. Continue boiling for another 1 to 2 minutes, until the filling is just cooked through.",
            "Once the wontons are done, immediately transfer them into serving bowls and pour in the hot broth. Taste a wonton with the broth. Add more salt to the broth, if needed. Drizzle with sesame oil and serve hot.",
            "You can freeze the wrapped uncooked wontons. To freeze the wontons, seal the tray tightly with plastic wrap and store it in the freezer for up to a month.",
            "To cook the frozen wontons, follow the same procedure you would for fresh wontons. You will need to cook the wontons for 1 to 2 minutes longer to cook the filling through.",
        ]
    ),
    "Century Egg Tofu": RecipeDetail(
        ingredients: [
            "1 block (16 oz / 450 g) silken tofu (, cubed)",
            "2 century eggs (, cubed)",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 teaspoon toasted sesame oil",
            "1 green onion (, thinly sliced)",
        ],
        steps: [
            "Add tofu into a big bowl. Top with eggs. Drizzle light soy sauce and sesame oil on top. Garnish with green onion.",
            "Serve cold as an appetizer. To enjoy the dish, use a spoon to get a mixture of everything. You can also drizzle more soy sauce or sprinkle some salt to adjust seasoning as needed.",
        ]
    ),
    "Chrysanthemum Greens Salad": RecipeDetail(
        ingredients: [
            "8 oz (220 g) chrysanthemum greens ((yield about 6 oz / 170 g washed &amp; trimmed))",
            "1 tablespoon Chinkiang vinegar",
            "2 teaspoons soy sauce",
            "1 1/2 teaspoons sugar",
            "1/4 teaspoon salt",
            "1/2 teaspoon sesame oil",
            "1 tablespoon peanut oil",
            "2 cloves garlic (, chopped)",
            "1 ” (2.5 g) ginger (, shredded)",
            "6 dried chilis (, chopped (or 3 thai chilis, deseeded &amp; sliced))",
        ],
        steps: [
            "Thoroughly wash the chrysanthemum greens with running water and let air dry. You can also use a few layers of kitchen paper towels to pat dry. One done, chop them into bite-size pieces and add to a large heat proof bowl.",
            "Combine the sauce ingredients in a small bowl and set aside.",
            "Heat the oil in a small pan over low heat and add the garlic, ginger, and chilis. Fry slowly until the garlic begins to brown lightly.",
            "Pour in sauce and turn off the heat.",
            "Stir the sauce into the oil briefly, then pour over the chrysanthemum leaves. Immediately toss everything with a pair of tongs to evenly mix the sauce. Set aside and let the leaves wilt for about 2 minutes.",
            "Serve immediately as an appetizer.",
        ]
    ),
    "Pork Liver Soup": RecipeDetail(
        ingredients: [
            "8 oz (225 g) pork liver",
            "2 teaspoons Shaoxing wine",
            "1 teaspoon soy sauce",
            "1/4 teaspoon salt",
            "1/4 teaspoon white pepper",
            "2 teaspoons cornstarch",
            "1/2 thumb ginger (, sliced)",
            "3 cups chicken broth",
            "1/2 batch (5 oz / 150 g) spinach",
            "pinch of salt ((or to taste))",
            "1 teaspoon sesame oil",
        ],
        steps: [
            "Place the pork liver in a large bowl. Rinse with cold water a few times, then add cold water to cover completely. Soak for 15 minutes. Drain off and discard the water. Slice the liver into 1/4” (4mm) thick pieces and place in a medium size bowl.",
            "Add the Shaoxing wine, salt, white pepper and cornstarch to the pork liver. Mix well with your hand. Let marinate for 10 minutes while preparing the rest of the ingredients. If you have extra time, marinating the pork liver in the fridge for 1 to 2 hours will yield better flavor.",
            "Bring a pot of water to a boil. Add the spinach, stem side down. Let the stem cook for 30 seconds, then submerge the leaf part as well. Cook for 30 more seconds or so, until al dente. Transfer the spinach to a colander. Run with cold tap water to stop cooking and cool off slightly. Then drain and gently squeeze out excess water. Cut the spinach to large bite-size pieces.",
            "Add the pork liver to the same pot of boiling water. Low boil for 30 seconds. Then drain, rinse with cold tap water to remove any impurities, drain again, and transfer the pork to a bowl.",
            "Add the chicken broth and the ginger to a medium size pot. Cook over medium-high heat until boiling. Add the cooked pork liver and boil for 1 minute, until just cooked through.",
            "Turn off the heat. Add back the cooked spinach, a pinch of salt and sesame oil. Taste the soup and add more salt if needed. Serve hot.",
        ]
    ),
    "Pork Liver Stir Fry": RecipeDetail(
        ingredients: [
            "12 oz (340 g) pork liver (, sliced into 1/4” (1/2 cm) thick pieces (*Footnote 1))",
            "2 teaspoons Shaoxing wine ((or dry sherry))",
            "1/2 teaspoon salt",
            "1 1/2 teaspoons cornstarch ((*Footnote 2))",
            "1/4 cup chicken broth",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "2 tablespoons oyster sauce",
            "1 teaspoon light soy sauce",
            "1 teaspoon dark soy sauce",
            "1 1/2 teaspoons sugar",
            "2 teaspoons cornstarch",
            "1 tablespoon peanut oil",
            "1 tablespoon minced ginger",
            "1/2 onion (, sliced into bite-size pieces)",
            "8 stalks (2 oz / 60 g) garlic chives (, cut to 2” pieces (or 4 green onions))",
        ],
        steps: [
            "Combine the pork liver, Shaoxing wine and salt in a medium-sized bowl. Gently mix well with your hand (*Footnote 2).",
            "Combine all the sauce ingredients in a medium-sized bowl. Stir to mix well.",
            "Bring a medium pot of water to a low boil and add the pork liver. Turn to low heat to make sure that the water does not boil. Cook and stir until the pork just turns a pale pink color, 1 minute or so. Drain the pork thoroughly and transfer the pork to a plate. Discard the boiling water.",
            "Heat 1 tablespoon of oil in a large skillet over medium-high heat until hot. Add the ginger. Stir a few times to release the fragrance.",
            "Add the onion. Stir and cook for 1 minute.",
            "Stir the sauce again until the cornstarch is dissolved completely. Pour it into the pan. Stir and cook until the sauce thickens. Add the pork and garlic chives. Stir and cook until everything is evenly coated with the sauce. Transfer everything to a serving plate. Serve hot over steamed rice as a main dish.",
        ]
    ),
    "Pork Soup with Lily Flower": RecipeDetail(
        ingredients: [
            "8 oz (225 g) pork tenderloin (, thinly sliced)",
            "1 tablespoon Shaoxing wine",
            "1 teaspoon light soy sauce ((or soy sauce))",
            "1 teaspoon sesame oil",
            "1/4 teaspoon salt",
            "1 teaspoon cornstarch",
            "1 cup (1 oz / 30 g) dried lily flower (and its soaking water)",
            "4 cups water ((or chicken broth) (*Footnote 1))",
            "1 clove garlic (, sliced)",
            "1/2 thumb ginger (, sliced)",
            "1 1/2 tablespoons light soy sauce ((or soy sauce))",
            "1/8 teaspoon white pepper",
            "Salt to taste",
            "1 teaspoon sesame oil ((Optional))",
            "Sliced green onion (for garnish (Optional))",
        ],
        steps: [
            "Combine the pork and the rest of the marinating ingredients in a medium sized bowl. Mix well with your hands.",
            "Add the dried lily flowers to a medium bowl and add 1 cup of warm water to cover. Let soak until the lily flowers turn tender, 10 to 15 minutes. Once done, remove the lily flowers and reserve the water. Check the lily flowers and remove any tough ends if needed. Measure the soaking water, and add enough water so you have 5 cups in total. Pour the combined water into a medium pot.",
            "Add the garlic and ginger. Heat over medium-high heat until boiling.",
            "Add the soaked lily flowers, soy sauce and salt and let boil for 2 minutes.",
            "Add the marinated pork and turn to medium-low heat. Use a pair of chopsticks to separate the pork slices immediately. Cook for 2 minutes, or until the pork is just cooked through.",
            "Turn off the heat. Add the white pepper, sesame oil and green onion for garnishing. Stir to mix well. Taste the soup and add more salt to adjust the flavor if needed. Serve the soup hot.",
        ]
    ),
    "Tomato Egg Drop Soup": RecipeDetail(
        ingredients: [
            "1/4 teaspoon white pepper powder",
            "1/4 teaspoon salt ((or to taste))",
            "4 teaspoons cornstarch",
            "2 teaspoons peanut oil ((or vegetable oil))",
            "2 cloves garlic (, minced)",
            "1 slice ginger",
            "4 cups chicken broth",
            "2 medium-sized tomatoes (, chopped into bite-size pieces)",
            "3 green onions (, chopped, white and green parts separated)",
            "3 large eggs (, beaten)",
            "1 teaspoon sesame oil",
        ],
        steps: [
            "To make the slurry: Combine the cornstarch, white pepper, salt, and 2 tablespoons of water in a small bowl. Whisk until cornstarch is completely dissolved.",
            "To make the soup: Heat oil in a small pot over medium heat until hot. Add the garlic and ginger. Cook and stir for 30 seconds to release the fragrance.",
            "Add the tomato and white part of the green onion. Cook until the tomato is blistered, 2 to 3 minutes.",
            "Pour in the chicken broth. Cook over medium-high heat until brought to a boil. Turn to a low heat and let the soup reduce to a simmer.",
            "Stir the slurry again to dissolve the cornstarch. Swirl it into the soup and mix well with a spatula. The soup will thicken up once it reaches a simmer. If you prefer a thicker soup, you can mix more cornstarch with water and add it to the soup, 1 teaspoon of cornstarch with 1 tablespoon of water at a time.",
            "To add the eggs, hold a fork (or two chopsticks slightly apart) across the edge of the egg bowl, and drizzle the egg mixture slowly through the gaps into the soup. Let the eggs set for a few seconds, then stir gently to break up the egg into desired sized pieces.",
            "Drizzle sesame oil and sprinkle with the green part of the green onion. Serve hot.",
        ]
    ),
    "Chinese Corn Soup": RecipeDetail(
        ingredients: [
            "1/2 lb ground chicken ((or ground turkey))",
            "1 teaspoon salt (, divided (or to taste))",
            "2 teaspoons Shaoxing wine ((or dry sherry))",
            "2 tablespoons cornstarch (, divided)",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "1 large slice ginger",
            "4 cups chicken broth",
            "1 cup canned or frozen corn (, drained (*see footnote 1))",
            "1/8 teaspoon turmeric powder ((for color, optional))",
            "1/8 teaspoon white pepper",
            "3 eggs (, beaten)",
            "1 teaspoon sesame oil",
            "1 green onion (, chopped (and extra for garnish))",
        ],
        steps: [
            "Combine the ground chicken, 1/2 teaspoon salt, Shaoxing wine and 1 teaspoon of the cornstarch in a small bowl. Mix well and let marinate while preparing the other ingredients.",
            "Heat the oil in a big pot until warm. Add ground chicken. Let cook as you chop the chicken into smaller pieces. Keep cooking until the chicken is almost cooked through and the surface is lightly browned.",
            "Add chicken stock and ginger. Turn to high heat. Cook until brought to a boil. Skim and discard the foam from the top of the soup. Then add the corn and the remaining 1/2 teaspoon salt. Turn to medium-low heat.",
            "While boiling the soup, combine the remaining cornstarch, turmeric powder, and pepper white pepper with 2 tablespoons of water in a small bowl. Stir to dissolve the cornstarch completely. Swirl the cornstarch starch slurry into the soup. Stir until the soup thickens. Turn to medium-low heat so the soup comes to a low simmer.",
            "Put a spatula (or a fork) against one end of the bowl with the egg in it. Slowly drizzle the egg into the soup in a swirling motion. Let the egg sit for 15 seconds, then stir the soup again to mix everything together. Taste the soup with a small spoon. If the soup is not as thick as you’d like, mix a bit more cornstarch slurry and add it into the soup. Add more salt to adjust seasoning if necessary.",
            "Drizzle with sesame oil and add green onion. Serve hot.",
        ]
    ),
    "Tomato Egg Noodles": RecipeDetail(
        ingredients: [
            "8 oz. (225 g) wheat noodles (, dried (or udon noodles))",
            "1 and 1/2 tablespoons peanut oil ((or vegetable oil))",
            "4 eggs (, beaten)",
            "2 green onions (, chopped)",
            "3 cloves garlic (, chopped (yields about 1 tablespoon))",
            "2 cans (28 oz. / 800 g in total) tomatoes (, diced (or 4 ripe tomatoes, or a mix of both))",
            "1 teaspoon soy sauce",
            "1 teaspoon salt ((or to taste))",
            "1 tablespoon sugar",
            "Homemade nutty sauce (to serve with (Optional))",
        ],
        steps: [
            "Bring a large pot of water to a boil over high heat. Cook the noodles according to the instructions on the package. Once done, run under tap water to cool. Drain and set aside.",
            "Heat 1 tablespoon of oil in a medium-sized non-stick pan over medium-high heat until hot. Add the eggs and let them sit without touching until the bottom side is done, but the top is still raw, about 30 seconds. Stir with a spatula, chopping the egg into bite-sized pieces, until the eggs are just cooked. Transfer the eggs to a plate and set aside.",
            "Add the remaining 1/2 tablespoon oil, green onion, and garlic to the pan. Stir a few times to release the fragrance. Add the tomatoes and/or canned tomato. Stir and cook until the tomatoes turn tender, about 2 minutes. Add the soy sauce and stir to mix well.",
            "Add the cooked eggs, salt, and sugar. Stir everything together to mix well. Taste the sauce. Adjust the seasoning by adding more salt and/or sugar, if needed. Transfer everything to a big plate.",
            "To serve, divide the noodles among the serving bowls. Add a few spoonfuls of the tomato egg sauce. Mix well and enjoy! To spice up the noodles, you can use the nutty sauce from this recipe. The flavors go very well together.",
        ]
    ),
    "Yellow Chive and Egg": RecipeDetail(
        ingredients: [
            "1 small batch (14 oz./400g) Chinese yellow chives",
            "4 large eggs (, beaten)",
            "1 1/2 tablespoon peanut oil ((or vegetable oil))",
            "1/2 teaspoon salt",
        ],
        steps: [
            "Rinse the yellow chives with running tap water. Use your fingers to gently wash them in small batches to remove any dirt. During this process, snip off any withered ends and peel off any parts that do not look fresh and discard them. Once done, drain the chives. Chop about 2 inches from the bottom (the white part is usually tougand discard it. Chop the rest of the chives into 2-inch pieces and set them aside.",
            "Heat 1/2 tablespoon of oil in a large 12” nonstick frying pan over medium-high heat until warm. Add the beaten eggs. Let cook until the bottom sets. Stir them with your spatula and chop them into smaller bits, like you’re cooking scrambled eggs. Once the eggs are just cooked, remove the pan from the stove immediately and transfer the eggs to a plate.",
            "Add the remaining 1 tablespoon oil. When the oil just starts to smoke, add the yellow chives. Quickly stir a few times to coat the chives evenly with oil. When the chives start to turn tender, add back the eggs and sprinkle salt over everything evenly. Stir and cook until the chives turn tender and the volume reduces. Remove the pan from the stove and taste the chives. If the chive are still tough, you can return them to the stove and cook them a bit longer. The chives will start to release water when they turn very tender and it won’t affect the taste. Once done, transfer everything to a plate.",
            "Serve hot immediately over steamed rice.",
        ]
    ),
    "Wood Ear Mushroom Salad": RecipeDetail(
        ingredients: [
            "0.5 oz dried wood ear mushrooms ((yield 2 cups once rehydrated))",
            "2 cloves garlic (, grated)",
            "1 fresno pepper (, sliced (or other chili pepper of your choice) (Optional))",
            "1 tablespoon light soy sauce",
            "1 tablespoon Chinkiang vinegar",
            "1 teaspoon sugar",
            "1/8 teaspoon salt",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "1 teaspoon Sichuan peppercorn",
            "1/4 cup cilantro (, coarsely chopped, for garnish (Optional))",
        ],
        steps: [
            "Combine wood ear mushrooms with 3 cups of warm water in a large bowl. Rehydrate until they soften, 20 minutes or so. Gently rinse the mushrooms with tap water. Remove the tough ends from the mushrooms and tear them into small bite-size pieces.",
            "Bring a pot of water to a boil. Add wood ear mushrooms and cook for 3 to 4 minutes, until turning tender. Drain, rinse the mushrooms with cold water, drain again, and place into a medium bowl. Add the chili pepper (if using).",
            "Combine garlic, light soy sauce, black rice vinegar, sugar, and salt in a small bowl. Stir to mix well.",
            "Heat peanut oil in a small skillet until warm. Add Sichuan peppercorn. Cook until you can smell a strong fragrance, 2 to 3 minutes. Turn off the heat. Remove and discard all the peppercorns with a slotted spoon. Immediately and carefully pour the hot oil into the small bowl with the soy sauce based mixture. Mix well.",
            "Combine the sauce and wood ear mushrooms in a bowl, toss a few times.",
            "Garnish with cilantro and serve as a cold appetizer.",
        ]
    ),
    "Garlic Enoki Mushrooms": RecipeDetail(
        ingredients: [
            "1 bag (7 oz / 200 g) enoki mushrooms (, tough ends removed and torn to thin bunches)",
            "1/4 teaspoon sugar",
            "Pinch of salt",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "6 cloves garlic (, minced)",
            "2 dried Chinese chili peppers (, sliced (or bird’s eye chili peppers))",
            "1 tablespoon light soy sauce",
            "1 green onion (, sliced)",
            "1 teaspoon sesame oil",
        ],
        steps: [
            "Prepare the steamer by heating 2” (5cm) water over medium-high heat until boiling.",
            "Spread the enoki mushrooms on a plate that can fit in your steamer. Sprinkle the mushrooms evenly with the sugar and pinch of salt.",
            "Heat oil in a small frying pan over medium heat until hot. Add the garlic and chili peppers. Stir to mix thoroughly, until the garlic just starts to turn golden. Immediately pour the hot sauce over the mushrooms.",
            "Steam the enoki mushrooms for 6 minutes, or until turning tender. Once done, transfer the plate to your kitchen counter.",
            "Drizzle with light soy sauce and sesame oil. Sprinkle the green onion over it. Serve as an appetizer. Stir gently to mix well before eating.",
        ]
    ),
    "Lotus Root Soup": RecipeDetail(
        ingredients: [
            "6 shiitake mushrooms (, rehydrated (or 2 pieces dried kelp) (*Footnote 1))",
            "1 lb (450 g) pork spare ribs strips (, cut into single or double ribs along the bone (*Footnote 2))",
            "1 lb (450 g) lotus root",
            "1/4 cup raw peanuts",
            "1 thumb ginger (, sliced)",
            "1/4 teaspoon salt ((or to taste) (*Footnote 3))",
            "1 green onion (, sliced (for garnish))",
            "1 tablespoon light soy sauce",
            "1/2 teaspoon Chinkiang vinegar",
            "1/2 teaspoon sugar",
            "1 teaspoon sesame oil",
        ],
        steps: [
            "Place the shiitake mushrooms in a medium-sized bowl and pour boiling water on top to cover by at least 1” (2.5 cm). Press them down to submerge into the water. Rehydrate for 20 minutes, until they turn soft throughout. Once done, drain the mushrooms and set aside.",
            "Add pork spareribs and 10 cups of water into a large pot. Bring to a boil over high heat. Skim the foam from the surface until the soup is clear, 10 minutes or so.",
            "While boiling the ribs, prepare the lotus root. Wash lotus root carefully. Peel the root and remove tough ends. Cut into 2 equal parts lengthwise, then chop into irregular bite size pieces.",
            "Place lotus root into the pot along with the ribs. Add the soaked mushrooms, peanuts, ginger, and the 1/4 teaspoon salt. Bring to a boil over high heat. Cover, turn to medium heat, and low boil for 1.5 to 2 hours, until the ribs almost fall off the bones and the lotus root becomes very tender. Add more salt to taste, if needed. And garnish with the green onions.",
            "You can enjoy the pork ribs by mixing and serving with the dipping sauce. You can also eat the ribs by simply sprinkling some salt over them.",
        ]
    ),
    "Lotus Root Stir Fry": RecipeDetail(
        ingredients: [
            "2 tablespoons dried wood ear mushrooms",
            "1 teaspoon mushroom powder ((or chicken bouillon powder))",
            "1 teaspoon cornstarch",
            "1/4 cup water",
            "1 teaspoon light soy sauce ((or soy sauce))",
            "2 cups lotus root (, sliced (*or 1 small fresh lotus root) (*Footnote 1))",
            "1 small carrot (, sliced)",
            "1/2 cup snow peas",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "3 cloves garlic (, minced)",
            "1 tablespoon minced ginger",
            "1/4 teaspoon salt",
            "1/2 teaspoon toasted sesame oil",
        ],
        steps: [
            "Soak the mushrooms: Add the dried wood ear mushrooms into a small bowl and add 1 cup hot water to cover. Soak for 15 to 20 minutes, until the mushrooms are soft throughout. Drain well. Remove any tough ends if needed, then cut into bite-sized pieces.",
            "Mix the sauce: Combine the mushroom powder, cornstarch and water in a small bowl. Stir to mix well.",
            "Make the stir fry: Add 1/4 cup water to a large skillet. Heat over medium-high heat until boiling. Add the lotus root and carrot. Cover the pan and steam for 1 minute. Then add the snow peas and soaked wood ear mushrooms. Stir a few times. Cover and steam for another 20 seconds. Once done, transfer all the vegetables to a big plate. Wipe the pan with paper towels to remove any water.",
            "Heat the oil in the same pan over medium-high heat until hot. Add the garlic and ginger. Stir a few times to release the fragrance.",
            "Add back all the vegetables. Stir a few times to coat the vegetables with oil. Sprinkle the salt. Stir and cook until the vegetables have softened but are still crisp, 1 to 2 minutes.",
            "Stir the sauce again to fully dissolve the cornstarch, and pour it into the pan. Immediately stir to mix well, until the sauce thickens. Transfer everything to a large serving plate.",
            "Serve hot as a side dish.",
        ]
    ),
    "Beef Shank Noodle Soup": RecipeDetail(
        ingredients: [
            "1 tablespoon peanut oil",
            "1/2 onion (, minced)",
            "1 carrot (, sliced)",
            "1 1/2 cup water",
            "1 cup beef braising liquid from homemade braised beef shank",
            "2 tablespoons ketchup",
            "8 oz (220 g ) fresh wheat noodles, or 5 oz / 140 g dried noodles",
            "4 heads baby bok choy ((or yu choy, spinach, other leafy greens of your choice))",
            "1 cup homemade braised beef shank (, chopped)",
            "Salt (to taste)",
            "1/8 teaspoon white pepper",
            "1 tablespoon Chinese pickled radish ((Optional))",
            "2 tablespoons homemade chili oil ((with chili flakes))",
            "Chopped cilantro ((for garnish))",
        ],
        steps: [
            "Heat oil in a medium-sized pot over medium-high heat until hot. Add the onion and carrot. Cook and stir until the onion turns golden, 3 minutes or so.",
            "Add the water, beef braising liquid, and ketchup. Simmer until the onions turn very soft, 5 to 10 minutes.",
            "Meanwhile, bring a separate pot of water to a boil and cook the noodles according to the package instructions. Once done, rinse the noodles with tap water for a few seconds to stop cooking, then drain and transfer them into two serving bowls.",
            "Add the baby bok choy into the noodle boiling water. Cook for 1 minute or until the desired doneness. Transfer the bok choy onto the noodles.",
            "If the braised beef shank is cold, add it to the broth. Cook for 1 minute or so, to warm it up.",
            "Once the broth is ready, taste it carefully and adjust the flavor by adding a pinch of salt and the white pepper. Transfer it to the noodle bowls. Top with the braised beef shank and pickles (if using). Drizzle with chili oil and garnish with cilantro. Serve hot as a main dish.",
        ]
    ),
    "Honey Sticky Rice Lotus Root": RecipeDetail(
        ingredients: [
            "150 grams (5 ounces) glutinous rice",
            "2 teaspoons white sugar",
            "1 400 grams fresh lotus root ( (*see footnote 1))",
            "100 grams (3.5 ounces) rock sugar ( (or 1/2 cup white sugar))",
            "2 tablespoons brown sugar",
            "4 tablespoons osmanthus syrup ((or honey))",
        ],
        steps: [
            "Add glutinous rice into a small bowl and rinse it 2 to 3 times. Add water to cover rice with 1 centimeter (0.5 inch) excess. Let the rice soak at room temperature for 4 to 5 hours or in the fridge overnight (cover / wrap the bowl if placed in the fridge).",
            "Drain the rice. Add white sugar and mix well.",
            "Wash lotus root carefully. Peel the rind off and discard it. When you cut off the tough ends, be careful not to cut off so much that you reveal the tubes.",
            "Cut about 2 centimeters (1 inch) from one end of the lotus root. Save the small piece that you cut off to use as a lid.",
            "To stuff the lotus root with glutinous rice, add a spoonful of rice onto the cut end and use a chopstick to push the rice into the holes. Use a chopstick to squeeze the stuffed rice and compress it. Carefully fill up all the tubes, including the small ones. (It will take some time. I highly suggest you sit down and play your favorite TV show while doing this.)",
            "Place the small “lid” back to cover the cut end, in exactly the position it originally was (so the glutinous rice will expand into the holes of the “lid” during cooking). Use 6 to 8 toothpicks to seal the “lid”. You should push the toothpicks as far in as you can. The glutinous rice will expand during cooking and the “lid” will fall off or be pushed apart if not sealed carefully.",
            "Add lotus root to a small pot, with 2 cups of water to cover (*see footnote 2). Add rock sugar (or white granular sugar) and brown sugar. Bring to a boil over high heat. Stir during boiling to dissolve the sugar.",
            "Turn to low heat, cover, and boil for 1 hour. Keep the water boiling throughout. Flip the lotus root after 30 minutes and add more water to cover it, if necessary.",
            "Turn to lowest heat to simmer for another 20 minutes. Flip the lotus root 4 to 5 times during cooking.",
            "To serve after cooking, transfer the lotus root to a cutting board and allow it to cool. Cut into evenly thick slices when the root is cool enough to handle.",
            "To serve later, leave the lotus root in the pot until it cools off completely before slicing. If you plan to serve it the next day, place the lotus root in an airtight container and add the sugary water to cover. Store in fridge.",
            "Drizzle osmanthus syrup (or honey) on top of the cut lotus root. Serve warm or cold.",
        ]
    ),
    "Silkie Chicken Soup": RecipeDetail(
        ingredients: [
            "1 (1.5 lbs / 680 g) silkie chicken",
            "1/3 cup dried jujubes ((Optional))",
            "4 dried shiitake mushrooms",
            "1 tablespoon Goji berries",
            "1 small corn on the cob",
            "1 thumb ginger",
            "6 cups water",
        ],
        steps: [
            "Combine everything in a small dutch oven that’s just large enough to hold the chicken. Add water to cover the chicken. It’s OK if some of the chicken is above the water.",
            "Cook over medium-high heat until bringing to a boil. Turn to medium low heat. Skim the surface with a fine sieve to remove the brown bits, for 10 minutes or so, until the chicken broth is clear. Simmer covered for at least 1.5 hours, up to 2 to 2.5 hours, until the chicken turns very tender and almost falls off the bones.",
            "All the ingredients in the soup are edible. But for a clear broth, you could remove the chicken and drain the soup before serving.",
            "The chicken meat will be quite tasty as well. I prefer to serve it with some homemade dipping sauce.",
        ]
    ),
    "Herbal Chicken Soup": RecipeDetail(
        ingredients: [
            "1.5 to 2 kilograms (3 to 4 pounds) bone-in skin-on thigh ((or whole chicken) (*Footnote))",
            "1 thumb ginger (, sliced)",
            "4 green onions",
            "1/4 cup goji berries (Gou Qi Zi)",
            "10 dried longan (Long Yan Rou)",
            "10 pieces Chinese wild yam (Huai Shan)",
            "5 dried dates (Hong Zhao)",
            "5 pieces codonopsis (Dang shen)",
            "4 pieces astragalus (Huang Qi)",
            "Chopped cilantro or green onion for garnish",
            "Salt and pepper",
            "Cooked noodles for noodle soup ((Optional))",
            "4 to 6 cups vegetables such as baby spinach, broccoli, and / or mushrooms ((Optional))",
        ],
        steps: [
            "Add chicken into a medium size pot. Add 6 to 8 cups water, until just covering the chicken. Bringing the water to a simmer over medium-high heat and turn to medium-low heat immediately. Simmer for 30 minutes. Skim off the brown foam from top of the soup and discard.",
            "Add ginger and green onion. Rinse the herbal mix under tap water and add to the soup. Simmer for at least 1 hour for a milder soup, or up to 3 hours for a darker and richer soup.",
            "Add chicken, ginger, green onion, and herbal mix into a slow cooker and 6 cups water to cover. Cook on low for 6 to 10 hours or on high for 2 to 4 hours, depending on the richness of the herbal flavors you prefer.",
            "Add chicken, ginger, green onion, herbal mix and 6 cups water in a pressure cooker. Cook at high pressure for 30 minutes. If using an Instant Pot, choose manual, and set timer to 30 minutes. If using a stovetop pressure cooker, cook over medium high heat until high pressure is reached. Turn to medium low heat. Continue to cook 30 minutes.",
            "Skim chicken fat from top of the soup and discard. Filter the soup with a fine mesh to remove the herbs. From the herb mix, the red dates, goji berries, and Chinese yam are all edible. You can either serve them with the soup or discard them with the rest of the herbs.",
            "At the end of cooking, remove chicken from the pot and transfer to a plate to cool, so you can begin to shred it.",
            "(Optional) Add vegetables into the soup and simmer until the vegetables are just cooked through.",
            "(Optional) You can add cooked noodles to make the dish more substantial.",
            "Garnish with chopped cilantro or green onion and serve hot.",
            "Check this post to learn more ways to cook with leftover chicken.",
        ]
    ),
    "Braised Chicken Feet": RecipeDetail(
        ingredients: [
            "1.5 lbs (680 g) chicken feet",
            "1 piece red bean curd plus 1 teaspoon juice ((Optional but highly recommended))",
            "3 green onions (, halved crosswise)",
            "1/2 thumb ginger (, sliced)",
            "2 tablespoons Shaoxing wine",
            "3 tablespoons light soy sauce",
            "2 tablespoons dark soy sauce",
            "1 teaspoon sugar ((or 1 heaping teaspoon rock sugar))",
            "2 dried chili peppers",
            "2 bay leaves",
            "1 cinnamon stick",
            "1 star anise",
            "1/2 teaspoon Sichuan peppercorns ((Optional) (*Footnote 1))",
        ],
        steps: [
            "Wash the chicken feet thoroughly. Clip off the chicken nails using a pair of kitchen shears. Transfer the chicken feet into a large pot and add water to cover.",
            "Heat the pot over medium-high heat until the water is boiling. Boil for 5 minutes. Skim and discard the brown foam from top. Then drain and discard the boiling water. Rinse the chicken feet with cold running water and drain again. Transfer the chicken feet to a wok (or the same large pot if not using a wok) and add water to cover, about 8 cups.",
            "Add the red bean curd and its juice to a small bowl and 2 tablespoons of water. Smash the bean curd to blend well with the water.",
            "Add the remaining spices and seasonings, and the dissolved red bean curd with all the liquid. Heat the pot over medium-high heat until boiling.",
            "Turn to medium heat. Keep a low boil with cover for 30 minutes. Move onto the next step if you prefer a chewy texture. If you prefer a tender texture (like I did in this recipe), uncover the pan and keep it boiling for another 30 minutes or so.",
            "To reduce the broth, turn to high heat and uncover the pan. Cook, stirring occasionally, until the sauce is slightly thickened and can thinly coat the chicken, 20 minutes or so. You need to watch the pan towards the end and stir more frequently to prevent it from sticking. During this process, you can also remove and discard the aromatics and spices by fishing them out, so the dish has a clean look when serving.",
            "Turn off the heat and transfer everything to a plate. The sauce is full of gelatin and will keep thickening as it cools.",
            "Serve hot or at room temperature as an appetizer.",
        ]
    ),
    "Chestnut Braised Chicken": RecipeDetail(
        ingredients: [
            "8 dried shiitake mushrooms",
            "1.5 lbs (680 g) bone-in chicken leg quarters (, cut into four bite-sized pieces (*Footnote 2))",
            "3 tablespoons light soy sauce",
            "12 chestnuts (, fresh, frozen, canned, or vacuum packed (*Footnote 1))",
            "2 tablespoons peanut oil ((vegetable oil, or lard))",
            "3 green onions (, two chopped into 2” (5 cm) pieces and one finely chopped)",
            "3 cloves garlic (, smashed)",
            "2 pieces ginger",
            "3 tablespoons Shaoxing wine ((or dry sherry))",
            "1 tablespoon dark soy sauce",
            "1/2 teaspoon kosher salt",
            "2 tablespoons rock sugar ((or 1 tablespoon regular sugar))",
            "1 star anise pod",
            "1 piece (3” / 7.5cm) cinnamon stick",
            "1 teaspoon Sichuan peppercorns ((optional))",
            "1 teaspoon sesame oil ((optional))",
        ],
        steps: [
            "Place the shiitake mushrooms in a small bowl and add 1/2 cup warm water. Let soak until the mushrooms turn soft throughout. Once done, gently rub the mushrooms to remove any dust on the surface. Squeeze the excess water from the mushrooms and reserve the soaking liquid.",
            "Add the cut chicken pieces and the light soy sauce in a big bowl. Toss to mix well and set aside.",
            "Bring a small pot of water to a boil over high heat. For fresh chestnuts, slice off their bases, boil for 3 to 5 minutes. Once done, transfer the chestnuts using a slotted spoon to a bowl. Taking care not to burn yourself, rub until the skins fall off and a pale yellow nut is revealed. Dry thoroughly. If using peeled frozen chestnuts, boil according to the package instructions (mine said 10 mins, but yours may be less).",
            "In a medium-sized dutch oven or wok, add the oil and heat over medium heat until hot. Add the chestnuts. Cook, stirring occasionally, until lightly browned. Transfer to a plate.",
            "Add the green onion, garlic, ginger and soaked mushrooms. Cook until lightly browned. Transfer everything to the plate with the chestnuts.",
            "Add the chicken pieces without overlapping (you might need to cook them in two batches). Let cook until the bottom side is lightly browned, and then flip to brown the other side. (*Footnote 3)",
            "Pour 1 1/2 cups water into the pan. Use your spatula to scrape off the browned bits from the bottom. Add the 1/2 cup of the reserved mushroom soaking liquid, but be careful not to add the residual bits on the bottom of the bowl.",
            "Add the Shaoxing wine, dark soy sauce, kosher salt, rock sugar, star anise pod, Sichuan peppercorns, and cinnamon stick. Add back the cooked chestnuts with the aromatics. The liquid should cover most of the chicken. If not, you can add a bit more water.",
            "Cook over medium-high heat until bringing the broth to a low boil. Then adjust the heat so the broth remains at a low boil (*Footnote ). Cook uncovered for 25 minutes, or until the chicken turns very tender. Over the final 10 minutes of cooking, keep an eye on the chicken and stir carefully a few times.",
            "Once the cooking is done, the broth should be reduced to able to coat the chicken with a thin layer. And it will thicken a bit more once it has cooled a bit. If there’s too much broth left but the chicken has already turned very tender, you should transfer the chicken to a serving bowl and keep reducing the broth over high heat, until it thickens. If the chicken is not too tender, you can reduce the sauce while keeping the chicken in the pot.",
            "Once done, drizzle sesame oil over the chicken if using. Sprinkle chopped green onions for garnish.",
            "Serve hot over steamed rice as a main course.",
        ]
    ),
    "Braised Chicken with Mushroom": RecipeDetail(
        ingredients: [
            "10 medium (total 35 g) dried shiitake mushrooms",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "2 to 3 lbs (1 to 1.4 kg) bone-in chicken (, chopped to large bite size pieces (*Footnote 1))",
            "4 green onions (, white part uncut, green part thinly sliced for garnish)",
            "1 thumb ginger (, sliced)",
            "1 whole star anise",
            "2 tablespoons Shaoxing wine",
            "2 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "1 teaspoon rock sugar ((or regular sugar))",
            "3/4 teaspoon salt",
        ],
        steps: [
            "Place dried shiitake mushrooms in a medium-sized bowl and add warm water to cover. Rehydrate mushrooms until soft, 20 minutes or so. Set aside. Reserve the soaking water once done.",
            "Heat the oil in a large wok or dutch oven over medium-high heat until hot. Add the chicken pieces without overlapping. Cook until both sides are browned, 2 to 3 minutes per side. You might need to cook in batches. Transfer the chicken to a large plate once browned.",
            "Your pan should still have some oil left. If not, add 1 tablespoon of oil. Add the star anise green onion (white part) and ginger. Stir and cook over medium heat until the edges of the aromatics are lightly charred, 1 to 2 minutes.",
            "Add back the browned chicken. Add 1 cup of the mushroom soaking water. Then add cold water until it can mostly cover the chicken, 5 cups or so. Add the Shaoxing wine, light and dark soy sauce, rock sugar, and salt. Cook over medium-high heat until brought to a boil. Skim and discard any brown foam from the top.",
            "Add the rehydrated shiitake mushrooms. Then cover the pan and turn to medium heat. Keep the liquid at a low boil until the chicken turns tender, 30 minutes or so. Check the chicken after 15 minutes, scooping the chicken from the bottom to prevent it from sticking.",
            "Taste a small piece of chicken and some sauce, adding salt if necessary. If you want to serve the chicken by itself, the chicken should taste slightly under seasoned now, because the saltiness will increase once the sauce is reduced. If you want to serve the chicken over steamed rice, add a bit of salt until it tastes just right. In this case, I added 1/4 teaspoon of salt to get a slightly salty dish in the end.",
            "Once the chicken turns tender, turn to high heat and boil uncovered. (*Footnote 2) Use a spatula to scoop the chicken from the bottom constantly, until the sauce is thick enough to thinly coat the chicken, 5 to 10 minutes. Pay a lot of attention during this step, since the sauce reduces very fast towards the end and might burn the bottom. The sauce will thicken up a bit more once cooled.",
            "Once done, sprinkle with the reserved green onion to garnish. Transfer chicken to a large bowl. Serve hot as a main dish or over rice.",
            "Store the leftover chicken in an airtight container in the fridge for up to 1 week or in the freezer for up to 2 months.",
        ]
    ),
    "Mom’s Best Braised Duck Leg": RecipeDetail(
        ingredients: [
            "2 kilograms (4.5 pounds) duck legs with thigh",
            "30 grams (1.4 ounces) scallions (, chopped)",
            "20 grams (3/4 ounces) ginger (, sliced)",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "1 teaspoon Sichuan peppercorn",
            "4 tablespoons Shaoxing wine",
            "2 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "1 tablespoon sugar",
            "1/2 teaspoon salt",
        ],
        steps: [
            "Separate the thigh from the drumsticks. Continue chopping each into 4 to 5 parts.(*see footnote)",
            "In a large pot, add duck and enough water to cover. Bring to a boil over medium high heat. Turn to medium heat and boil for 3 minutes. During boiling, use a ladle to skim any foam from the surface, and discard it. Transfer the duck legs to a large colander and drain them. Discard boiling water.",
            "Bring 4 cups water to a boil and set aside.",
            "Heat a wok (or a large dutch oven) over medium high heat until hot. Add oil and swirl to coat the bottom of wok. Turn to low heat. Add Sichuan peppercorn and fry until fragrant, about 1 minute. Use a ladle to scoop out peppercorns and discard them. Add scallion and ginger and stir a few times until fragrant. Turn back to medium high heat. Carefully add duck legs back into the wok and stir immediately. Stir until duck is slightly browned on the outside, about 5 minutes.",
            "Add boiled water to cover the duck legs. Add shaoxing wine, light soy sauce, dark soy sauce and sugar. After bringing to a boil, turn to low heat and simmer, covered, for 30 minutes. Add salt and stir well. If the broth has reduced and no longer covers the duck, add more boiling water (about 1 cup). Simmer for another 30 minutes, covered. During simmering, check on the duck every 15 minutes. Use a spatula to scoop the duck from bottom to prevent burning. Add more water if needed.",
            "The duck should turn very soft after 1 hour. The broth should be reduced to a thick sauce, just enough to coat the duck. If the sauce is still too thin, turn to medium heat and boil uncovered to thicken the sauce. Stir the duck constantly during the process.",
            "Serve the duck leg warm over steamed rice or noodles. You can store duck leg in the fridge for up to 1 week or in the freezer for up to 1 month.",
        ]
    ),
    "Beef Stew with Tendon": RecipeDetail(
        ingredients: [
            "2.4 kilograms (5 pounds) beef plate (, cut into bite-size cubes)",
            "0.8 kilograms (1.5 pounds) beef tendon (, cut into bite-size cubes)",
            "4 tablespoons Shaoxing wine",
            "6 chili peppers (, dried)",
            "1 and 1/2 thumbnail ginger (, divided into 3 thick slices, slightly smashed with a knife)",
            "15 centimeters (6 inches) scallion (, chopped (2 centimeters /1 inches in length))",
            "4 bay leaves",
            "2 teaspoons whole black peppercorns",
            "2 tablespoons curry powder",
            "1 tablespoon sugar",
            "4 tablespoons tomato paste",
            "1 tablespoon dark soy sauce",
            "2 tablespoons light soy sauce",
            "4 teaspoons salt",
        ],
        steps: [
            "Place beef tendon in a pressure cooker and add water to cover beef completely. Place on high heat until rated pressure has been reached. Turn to lowest heat. Simmer at rated pressure for 30 minutes. Turn off heat and allow the pressure to release naturally.",
            "While simmering the beef tendon, prepare beef plate. Add beef plate into a large pot and add water to cover the meat. Bring to a boil over high heat. Turn to medium-low heat and keep a gentle boil going for 10 to 15 minutes. While boiling, skim the foam from the top of the broth and discard it. Turn off heat. Use a colander to transfer beef to a wok (or a large dutch oven). Let the soup sit about 10 minutes, then pour the soup into the wok until it covers the beef completely. (There may be some clotted blood on the bottom of pot. Try to avoid pouring it into wok.) Save the rest of the soup in the pot and set it aside for later use.",
            "Heat the wok over medium heat. Add Shaoxing wine, chili pepper, ginger, scallion, bay leaves and black pepper (* see footnote) into wok and simmer, covered, for about 40 minutes. The beef tendon should be ready at that point.",
            "Transfer beef tendon from the pressure cooker to the wok, and discard the broth.",
            "Add curry powder, sugar and tomato paste into wok and mix well. Simmer, covered, for about 30 minutes, until beef starts to become more tender.",
            "Add dark soy sauce, light soy sauce and salt into the wok. Mix well and simmer, covered, for one hour to one hour and a half (simmer time varies depending on the cut of beef). While simmering, stir the beef several times. Scoop the beef from the bottom with a spatula, to avoid burning it on the bottom of the pot.",
            "After 20 minutes, watch the beef more closely and adjust the seasoning. If the liquid is becoming thick, but the beef is still tough, add more broth (from step 2), half a cup at a time. The liquid should be able to cover half of the beef. However, do not add too much water at the end of simmering, when beef is already soft.",
            "When simmering has finished, adjust the seasoning again. The beef should be very tender and the soup quite thick. If the soup is not thick enough, boil uncovered over medium heat. Stand near the wok and stir constantly until soup thickens.",
            "Serve warm with steamed rice.",
            "The beef stew will stay good in an airtight container in the fridge for up to a week, or in the freezer for up to a month.",
            "To store the beef stew for your lunchbox or dinner during the next two weeks, place stew in a small bowl (2 to 4 servings per bowl) and set aside. After the stew has cooled down to room temperature, cover with plastic wrap and place in refrigerator, until stew has congealed and can easily be easily taken from the bowl. Store the blocks of stew in individual ziplock bags in the freezer.",
            "To make a one-dish meal, you could add beans, potato, tomato, carrot or broccoli into the stew and boil them together, until the vegetables are cooked through.",
        ]
    ),
    "Mom’s Best Lamb Dumplings": RecipeDetail(
        ingredients: [
            "500 grams (1 pound) ground lamb leg",
            "4 tablespoons Shaoxing wine",
            "4 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "10 grams (1 tablespoon) ginger (, minced)",
            "1/4 teaspoon Sichuan peppercorn powder",
            "1/4 teaspoon salt ((Optional) (*see footnote 1))",
            "80 grams zucchini",
            "200 grams carrot",
            "80 grams (1 cup) green onion (, chopped)",
            "80 pieces homemade dumplings wrappers",
        ],
        steps: [
            "Combine ground lamb meat, Shaoxing wine, light soy sauce, and dark soy sauce in a large bowl. Mix well until the mixture becomes a sticky paste. Add ginger. Sprinkle evenly with Sichuan peppercorn powder and salt (if you’re using it). Mix thoroughly. Add peanut oil and mix well. Cover with plastic wrap and set aside (or in the fridge if you’re not planning to make dumplings within an hour).",
            "(option) If you are making your own dumpling wrappers, mix the ground lamb with the seasonings first, and set aside at room temperature for up to 1 hour (or in the fridge for up to a day). Do not add any vegetables to the meat at this point, because the veggies will be dehydrated by the salt, and the filling will become watery.",
            "Right before you wrap the dumplings, prepare the vegetables. To mince the carrot and zucchini, you can use a mandoline to slice them into strips first, then chop them into small bits. You can also use a food processor to mince them.",
            "Cook carrot. Heat 1 tablespoon oil in a wok (or a nonstick skillet) over medium high heat until warm. Add carrot, stir, and saute until cooked through, 2 to 3 minutes. Transfer to a plate.",
            "When you’re ready to start wrapping dumplings, add green onion, zucchini, and carrot into the ground lamb. Mix well.",
            "{If you are using fresh homemade wrappers} Scoop about 1 tablespoon (or slightly less) of the dumpling filling and place it in the center of the wrapper. Hold the dumpling with one hand and start sealing the edges with the other hand (refer to the video or this post to see detailed information on how to fold a dumpling).",
            "{If you are using pre-made wrappers from the store} Scoop about 2 teaspoons (or 1 tablespoon, depending on the size of the wrapper) of the lamb filling and place it in the center of the wrapper. Gently press the mixture into a round shape, so it will be easier to wrap. Wet your finger or a pair of chopsticks with water and gently brush water onto the edge of the wrapper. Fold the wrapper into a half moon shape. (*see footnote 2)",
            "If you have trouble sealing the dumplings, reduce the amount of filling until you can seal it easily.",
            "Place the dumplings on the working surface, one finger’s width apart. Work with the rest of the wrappers in the same manner.",
            "You should wrap the dumplings in small batches, 20 to 25 at a time. After the dumplings are wrapped, cook or freeze them within 30 minutes. Otherwise, the dumplings will start to lose moisture. For more information on cooking frozen dumplings, refer to this post.",
            "Bring a large pot of water to a boil.",
            "Carefully add dumplings into the water, one at a time. Use a big ladle to stir the water gently and continuously, until the water starts to boil again, so the dumplings won’t stick to the bottom, for about 1 minute. Adjust the heat so the water is at boiling point, but isn’t bubbling too fiercely.",
            "When the dumplings float to the surface, continue boiling until the dumplings are filled with air and swollen, and the dough starts to become transparent, about 1 minutes. Immediately transfer all the dumplings to a plate.",
            "Be careful, the dumplings cook quickly and you should always stand beside the pot throughout the boiling process. When the dumplings are cooked, they will start to fall apart within seconds, so transfer them as soon as possible.",
            "Heat a tablespoon of oil in a nonstick skillet over medium high heat. When oil is hot, place potstickers in the skillet, pleat side up.",
            "Swirl 2 tablespoons water in the skillet, cover immediately, and turn the heat to medium. Cook covered until the water is evaporated and potstickers are cooked through, about 3 minutes.",
            "Remove the cover and flip one potsticker to see whether the bottom side is charred. If not, turn to medium high heat and cook until the bottom side turns golden brown.",
            "Transfer the potstickers to a plate.",
            "Option 1: Serve with Chinese black vinegar and a few ginger slices.",
            "Option 2: Serve with Chinese black vinegar and a few drops fresh Chili oil.",
            "If you plan to store dumplings or won't serve them immediately, always freeze them uncooked. It won’t affect the texture or flavor of the dumplings.",
            "Dust the bottom of a big airtight box with a thin layer of flour. Place the dumplings, one finger’s width apart. Store in the freezer for up to 2 months.",
        ]
    ),
    "Braised Pork Ribs": RecipeDetail(
        ingredients: [
            "1 slab pork ribs (about 1.8 kg / 4 lbs)",
            "2 &quot; ginger (, sliced)",
            "4 green onion (, halved lengthwise)",
            "1 whole nutmeg ((or 1 teaspoon nutmeg powder))",
            "2 star anise pods",
            "5 cloves",
            "1/4 cup Shaoxing wine ((or dry sherry))",
            "3 tablespoons light soy sauce",
            "1 tablespoon dark soy sauce",
            "2 tablespoons granulated sugar",
            "2 teaspoons salt",
            "2 pieces red fermented bean curd ((Optional))",
            "2 tablespoons cornstarch",
            "2 red potatoes (, chopped (or waxy potatoes))",
            "3 carrots (, chopped)",
            "1/2 lb green beans",
        ],
        steps: [
            "Add pork ribs to a large pot and add cold water to cover. Bring to a boil over medium high heat, then turn to medium heat. Boil for 5 minutes while skimming the foam off the top with a spoon.",
            "Add the ginger, green onion, nutmeg, star anise, cloves, and cooking wine. Turn to low heat. Cover and simmer for 40 minutes. Stir occasionally.",
            "Add light soy sauce, dark soy sauce, sugar, and salt. Add the red fermented bean curd into a small bowl and add a few spoonfuls of hot broth from the pot. Smash with the back of a spoon until the bean curd dissolves. Pour back into the pot. Simmer uncovered for another 40 to 50 minutes, until pork turns tender but is not quite falling of the bone.",
            "(Optional) Add the vegetables. Continue simmering for 15 minutes, until the vegetables turn tender.",
            "Add cornstarch and 1/3 cup water into a small bowl. Whisk well until the cornstarch dissolves completely. Slowly add half of the slurry into the pot. Stir to mix well. Add more slurry and stir if you want to thicken the sauce more. Note, you might not need to add all the cornstarch slurry. (*Footnote 2)",
            "Serve pork ribs with steamed white rice or noodles. Enjoy!",
            "Store the pork ribs in an airtight container in the fridge for up to 1 week, or in the freezer for up to 1 month.",
        ]
    ),
    "Pearl Balls": RecipeDetail(
        ingredients: [
            "1 cup glutinous rice",
            "2 tablespoons Chinese dried shrimp ((optional))",
            "1 lb ground pork ((*Footnote 1))",
            "2 eggs",
            "2 tablespoons light soy sauce",
            "1 tablespoon Shaoxing wine",
            "2 teaspoons ginger (, grated)",
            "4 green onions (, thinly sliced)",
            "1 teaspoon sugar",
            "1 teaspoon salt",
            "1/4 teaspoon white pepper powder",
            "1/4 teaspoon nutmeg powder",
            "2 tablespoons cornstarch",
            "1/2 cup panko breadcrumbs",
            "1 tablespoon toasted sesame oil",
        ],
        steps: [
            "Add glutinous rice and dried shrimp into separate bowls. Add cold water to cover. Let soak for at least 4 hours. (*Footnote 2)",
            "Drain glutinous rice and dried shrimp. Place the glutinous rice onto a medium plate with rim or a large bowl. Finely mince the rehydrated dried shrimp.",
            "Combine pork, eggs, dried shrimp, light soy sauce, Shaoxing wine, ginger, green onion, sugar, salt, white pepper, and nutmeg in a large bowl. Stir in one direction, in a circular motion until it’s sticky. Add cornstarch and panko breadcrumbs. Stir to mix well. Pour in the sesame oil. Stir again to combine.",
            "Line your steamer with parchment paper with holes cut in it, or a few layers of wet cheesecloth.",
            "Scoop out about 2 tablespoons of meat paste (you can use a cookie scoop), shape it into a ball, and roll it in the glutinous rice, until the surface is completely coated with rice. Gently press with your hand so that the rice sticks to it. Place meatballs onto the lined steamer. Make the rest of the meatballs using the same method, spaced 1” (2.5 cm) apart.",
            "Add 2” (5 cm) water to a steamer and bring it to a boil.",
            "Steam the meatballs for 15 minutes, or until cooked through (*Footnote 3). Serve as a main dish with or without rice (*Footnote 4).",
        ]
    ),
    "Liang Fen": RecipeDetail(
        ingredients: [
            "1/2 cup (120 g) mung bean starch",
            "3 cups water (, divided)",
            "2 tablespoons soy sauce",
            "1 tablespoon Chinkiang vinegar",
            "1/4 teaspoon salt",
            "1 tablespoon sugar",
            "3 cloves garlic (, sliced)",
            "2 tablespoons homemade chili oil (, including the oil and the chili flakes, or to taste)",
            "homemade black bean sauce (*Footnote 1) ((Optional))",
            "Chopped cilantro and/or green onions (, for garnish)",
            "A handful of shredded cucumber ((Optional))",
        ],
        steps: [
            "Add 2 1/2 cups of water to a medium-sized pot and bring it to a boil over medium-high heat. Then turn the heat down to a simmer.",
            "In a small bowl, combine the mung bean starch and 1/2 cup of water. Stir until the starch is fully dissolved.",
            "Prepare a rectangular or square baking dish that can hold at least 4 cups of water but is small enough, so the mixture is at least 1” (2.5 cm) thick. (*Footnote 2)",
            "Slowly pour the mung bean mixture into the simmering water, while stirring gently with a ladle or a whisk. Continue to stir until the mixture in the pot starts to thicken and small bubbles start to form. It should start turning somewhat translucent. Simmer for another 6 to 8 minutes while stirring, until the mixture thickens further, like a thick sauce texture. Carefully pour the mixture into the prepared baking dish.",
            "Let cool at room temperature until solidified. It takes about 2 hours if you use a shallower dish, but up to 3 or 4 hours if using a deeper dish. Once congealed, you can store the jelly covered in the fridge for up to 3 days.",
            "Combine all the sauce ingredients in a medium-sized bowl, stir to mix well.",
            "Place a large cutting board over the baking dish and flip it. Jiggle the dish slightly so the jelly falls onto the cutting board. Slice the jelly into 1/2” (1 cm) by 2 1/2” (5 cm) sticks, or any bite-size shapes you prefer.",
            "Transfer the sliced mung bean curd into serving bowls, drizzle with a few spoonfuls of the sauce, and serve chilled or at room temperature.",
        ]
    ),
    "Dan Huang Su": RecipeDetail(
        ingredients: [
            "70 g all-purpose flour",
            "20 g low-gluten flour ((pastry or cake flour))",
            "12 g (1 tablespoon) powdered sugar",
            "1/8 teaspoon salt",
            "35 g unsalted butter (, softened)",
            "40 ml ice water",
            "110 g low-gluten flour ((pastry or cake flour))",
            "55 g shortening",
            "16 salted duck yolks ((*Footnote 1))",
            "400 g homemade red bean paste",
            "2 to 3 egg yolks",
            "Black sesame seeds",
        ],
        steps: [
            "Sift the water dough flours, sugar, and salt into the bowl of a stand mixer. Add the butter and ice water. Mix with a spatula until a rough dough forms. Place the bowl in the mixer with the dough hook attachment. Drape a piece of the dough over the hook. Turn the mixer to setting 4 and knead until smooth and elastic, about 10 minutes. Depending on the size of your mixer, it may be necessary to stop the kneading occasionally and lift the dough over the hook (*Footnote 3). To test the dough, stretch it into a thin semi transparent sheet and it should hold well. Knead in the mixer for a bit longer, if needed. Once done, cover the dough and rest for 10 minutes.",
            "Combine the low-gluten flour and shortening in a medium-sized bowl. Mix and press it together using your hands, until dough shapes. Further shape and knead it on a working surface until uniform and smooth. Cover and rest for 5 minutes.",
            "Divide your choice of filling paste into 25g balls. Flatten each ball into a 2.5”(6.5 cm) disc and place a yolk in the center. Gently press the paste around the yolk to cover the yolk completely. Try to press out any air bubbles and prevent from damaging the yolk. Once the yolk is fully covered, roll it between your hands to smooth it out until it forms a smooth ball.",
            "Divide the water dough into 16 even pieces, 10 g per piece. Work on one dough at a time, use your hands to pull the dough towards the center, until it forms a ball. Pinch to seal the end and set aside. Always cover the dough with plastic wrap.",
            "Divide the oil dough into 16 even pieces, 10 g per piece. Form each piece into dough balls using your hands and cover them.",
            "Flatten a ball of water dough with your palm and spread it with your fingers so that the center is thicker than the edges, about 2.5” (6.5 cm) wide. Place a ball of oil dough in the center. Lift the edges of the water dough over the oil dough to wrap it and pinch at the top to seal it. Set it aside and cover it. Repeat with all pieces of dough.",
            "Preheat the oven to 350°F (176°C).",
            "Take a formed ball, sealed-side down, and flatten it with your palm. Gently roll it into a 5” (12.5 cm) long strip. Flip it over so it’s seam-side up. Starting from the short side, roll it into a thick jelly roll. Turn the roll 90° and flatten it with your hand. Again roll it into a 5”(12.5 cm) strip and then into a jelly roll. Cover and set aside. Repeat with the remaining balls.",
            "Beginning with the first roll you made, take a roll and press into the middle so the swirled ends are pressed out. Then fold the swirled ends into the center and press them down so that a flat disc is formed. Roll this disc out so that it is 5” (12.5 cm) in diameter. Place the filling in the center. Lift and stretch the dough over the paste ball to cover completely, and pinch to seal. Roll between your palms to smooth it out. Repeat with all the dough and cover all the dough pieces with plastic wrap as you do so. (*Footnote 5)",
            "Line a baking tray with parchment paper. Place the pastries on it, at least 1” (2.5) apart.",
            "Lightly beat the yolk. Brush a thin layer of the egg wash onto the tops of the pastries. Wait 5 minutes and brush with a second layer of yolk.",
            "Wet your fingertip with water and dip it into the sesame seeds so the seeds stick to your finger. Tap the top of each pastry to decorate.",
            "Bake at 350°F (176°C) for 15 to 20 minutes, until the egg wash turns golden and the pastries are cooked through and flaky. Once done, remove from the baking sheet from the oven and let cool for 15 minutes before serving.",
            "After completely cooling, you can store the baked mooncakes in an airtight container at room temperature for up to 4 days, in the fridge up to 2 weeks, or in the freezer for 3 months.",
        ]
    ),
    "Da La Pi": RecipeDetail(
        ingredients: [
            "2 eggs (, beaten)",
            "1 teaspoon cornstarch",
            "2 tablespoons water",
            "Pinch of salt",
            "Pinch of sugar",
            "Oil spray (for cooking)",
            "1/4 cup Chinese sesame paste ((or unsalted natural peanut butter) (*Footnote 1))",
            "2 tablespoons warm water ((or more))",
            "2 tablespoons light soy sauce",
            "2 tablespoons Chinkiang vinegar",
            "1 tablespoon maple syrup ((or sugar))",
            "2 teaspoons sesame oil",
            "1 clove garlic (, grated)",
            "1 teaspoon wasabi",
            "1/4 teaspoon salt",
            "7 oz (200 g) fresh potato noodles ((or 3.5 oz / 100 g dried potato noodles))",
            "1 small carrot (, sliced to thin strips)",
            "1/2 English cucumber (, sliced to thin strips)",
            "1 cup purple cabbage (, thinly sliced)",
            "1/3 cup cilantro (, chopped)",
        ],
        steps: [
            "If using dried noodles that require soaking, soak the noodles according to package instructions. (*Footnote 2)",
            "Crack the eggs into a medium-sized bowl and beat until even and smooth. Add the cornstarch and water into a smaller bowl, stir to mix well until the cornstarch is dissolved, and pour it into the beaten eggs. Add the salt and sugar. Stir to mix well.",
            "Spray (or drizzle) a small amount of oil onto a large nonstick skillet and use paper towels to wipe the oil so the skillet is very thinly coated. Heat over medium heat for 20 seconds. Pour in the beaten egg mixture and immediately swirl the skillet so the egg spreads out into a thin, round layer. Cook until the eggs are mostly set, 1 to 2 minutes. Turn off the heat. Slowly use a spatula to loosen the egg and fold it over a few times, then transfer to a cutting board.",
            "Wait until the eggs are cool enough to handle. Slice it into thin strips about 1/4 (1/2 cm) wide.",
            "Add the sesame paste into a medium-sized bowl. Slowly add warm water and whisk with a spoon, until it forms a smooth paste.",
            "Add the rest of the sauce ingredients. Stir to mix well. If the sauce is still too thick, almost like a dipping sauce, add 1 or 2 more tablespoons of water and mix again, until it reaches a salad dressing consistency.",
            "Cook the soaked potato noodles according to package directions. Taste a noodle before draining, to make sure it’s fully cooked through. Once done, drain well and rinse with cold tap water to stop cooking. Drain again and transfer the noodles to a medium-sized bowl. Toss with half of the sauce, then transfer to the center of a big plate.",
            "Place the cucumber, carrot, purple cabbage and sliced eggs around the noodles. Garnish with cilantro and serve with the rest of the sauce on the side.",
            "Toss everything together with the rest of the sauce. Serve at room temperature as an appetizer.",
        ]
    ),
    "Buddha’s Delight": RecipeDetail(
        ingredients: [
            "25 g (1/2 cup) dried lily flowers",
            "25 g (8 medium) dried shiitake mushrooms",
            "10 g (2 tablespoons) dried wood ear mushrooms",
            "40 g (1 small bundle) mung bean vermicelli noodles ((yield about 1 cup once rehydrated), or other types of vermicelli noodles)",
            "2 tablespoons light soy sauce",
            "1 tablespoon vegetarian oyster sauce ((or regular oyster sauce))",
            "1 tablespoon dark soy sauce",
            "1 teaspoon sugar",
            "1/4 teaspoon salt",
            "1 cup soaking water from the lily flower and mushroom ((*Footnote 2))",
            "1 teaspoon sesame oil",
            "1 teaspoon cornstarch",
            "1 tablespoon water",
            "2 tablespoons peanut oil ((or vegetable oil))",
            "4 green onion (, chopped)",
            "1 tablespoon minced ginger",
            "1 carrot (, sliced)",
            "10 pieces deep fried tofu puffs (, halved)",
            "4 heads baby bok choy (, quartered)",
            "230 g (4 cups) napa cabbage (, chopped)",
            "1/2 cup bamboo shoots (, sliced)",
        ],
        steps: [
            "Prepare the dried lily flowers, shiitake mushrooms and wood ear mushrooms: Place each ingredient in a separate medium-sized bowl and pour boiling water on top to cover by at least 1” (2.5 cm). Press the ingredients down to submerge into the water. Rehydrate for 20 minutes, until they turn soft throughout.",
            "After the lily flowers turn soft, remove the tough ends if needed (*Footnote 1). If the lily flowers are very long, cut them in half lengthwise. Drain and set aside. Measure out 3/4 cup of the soaking water for later use.",
            "For the shiitake mushrooms, gently squeeze the water from the mushrooms, then slice into halves. Measure out 1/4 cup of the soaking water and pour into the same bowl with the lily flower rehydrating water.",
            "For the wood ear, mushrooms, once rehydrated, cut into small bite-sized pieces.",
            "Place the vermicelli noodles in a medium-sized bowl and add boiling water to cover. Let sit for 3 to 5 minutes (or according to the package instructions), until the noodles turn al-dente. Drain and set aside.",
            "Combine the sauce ingredients in a medium-sized bowl, stir to mix well and set aside.",
            "Mix the ingredients in a small bowl and set aside.",
            "Heat the oil in a large skillet (at least 13 inches) or a large dutch oven over medium-high heat. When oil turns hot but not smoking hot, add ginger and green onion. Stir a few times until fragrant.",
            "Add the carrot, lily flowers, and dried shiitake mushrooms. Stir and cook for 1 minute.",
            "Add bamboo shoots and wood ear mushrooms. Stir and cook for 1 minute.",
            "Add fried tofu and pour in the sauce. Add the napa cabbage and bok choy. Cover and cook over medium heat for 3 to 5 minutes, until the vegetables are cooked through. Uncover and stir in between, to mix the vegetables with the sauce.",
            "Add bean thread noodles and let them soak in the liquid. Stir and cook for another 30 seconds. Stir the cornstarch slurry again to dissolve completely and pour into the pan. Stir until the sauce thickens. Transfer everything to a large platter. Serve hot as a main dish.",
        ]
    ),
    "Bean Sprout Salad": RecipeDetail(
        ingredients: [
            "1 teaspoon salt",
            "12 oz (340 g) bean sprouts",
            "1 anaheim pepper (, or half a red pepper, or 1 Asian long red pepper (*Footnote 1))",
            "2 green onions (, sliced)",
            "4 cloves garlic (, grated (*Footnote 2))",
            "1 tablespoon soy sauce",
            "2 teaspoon Chinkiang vinegar",
            "1/2 teaspoon sugar",
            "1/4 teaspoon ground Sichuan peppercorn ((*Footnote 2))",
            "2 tablespoons peanut oil",
            "1 teaspoon toasted sesame oil ((or homemade chili oil))",
        ],
        steps: [
            "Bring a medium-sized pot of water to a boil. Add the salt and stir to dissolve completely. Add the bean sprouts. Cook for 40 seconds, or until al dente. Immediately drain and transfer the bean sprouts to a colander. Rinse with cold tap water to stop cooking. Once cooled completely, drain thoroughly, then pat dry with paper towels. Transfer to a big bowl.",
            "Add the sliced pepper, green onion, and garlic to the bowl with the bean sprouts. Do not stir. Make sure the garlic is on the very top of the bowl.",
            "Add the soy sauce, Chinkiang vinegar, sugar and Sichuan peppercorns.",
            "Heat the peanut oil over medium heat until hot. Immediately drizzle the oil into the bowl, directly over the garlic and Sichuan peppercorns. You should see the ingredients sizzle in the hot oil.",
            "Mix everything together and pour in the sesame oil (or chili oil, if you prefer a spicy dish). Mix again and serve as an appetizer.",
        ]
    ),
    "Marinated Eggs": RecipeDetail(
        ingredients: [
            "4 large eggs",
            "1/4 cup light soy sauce ((or soy sauce))",
            "1 tablespoon rice vinegar",
            "1 tablespoon sugar",
            "1/8 teaspoon five spice powder",
            "1 cup water ((*Footnote 1))",
        ],
        steps: [
            "Combine the soy sauce, rice vinegar, sugar and five spice powder in a small bowl. Heat in the microwave until hot, 30 seconds or so. Mix well to dissolve the sugar and the five spice.",
            "Prepare a pot that is large enough to hold all the eggs without overlapping them. Add enough water to cover the eggs. Heat over medium-high heat until boiling.",
            "Transfer the eggs to a ladle or a colander. Slowly lower the eggs into the water to prevent them from cracking. Adjust the heat so the water maintains a slow boil. Let the eggs boil for 1 minute, then use a ladle or a pair of chopsticks to rotate each egg, to make the yolks more centered (Optional).",
            "Cook for 6 minutes for runny yolks, 8 minutes for semi-firm, or 11 minutes for hard boiled.",
            "Once done, drain the hot water immediately and run cold water over the eggs. While the eggs are still hot, quickly crack the eggs inside of the cold water (it makes peeling much easier). Cover the eggs with cold water and let cool enough to handle by hand. Then peel the eggs.",
            "Transfer the cooked eggs into a zip lock bag and pour in the cooled marinade. Add 1/2 cup water if you plan to use the eggs in a couple of hours the same day (Footnote 1). Use 1 cup water instead, if you plan to marinate the eggs overnight (highly recommended, for better flavor). The eggs can be refrigerated in the marinade for up to 3 days.",
        ]
    ),
    "Oxtail Soup": RecipeDetail(
        ingredients: [
            "2 kg (4 to 5 lbs) oxtail (, separated at joints)",
            "8 cups beef stock ((or water) (*Footnote 1))",
            "2 tablespoons olive oil",
            "1 big onion (, coarsely chopped)",
            "4 carrots (, chopped)",
            "1 thumb ginger (, sliced)",
            "4 Yukon gold potatoes (, chopped)",
            "28 oz (800 g) tomato (, diced)",
            "2 tablespoons tomato paste",
            "3 bay leaves",
            "1/4 head cabbage (, chopped)",
            "2 teaspoons sugar",
            "1 teaspoon coarse sea salt",
            "1/2 teaspoon coarse black pepper",
            "Heavy cream (sour cream, or plain Greek yogurt for garnish)",
        ],
        steps: [
            "Add oxtail and water (or beef stock) in a big pot. Cook over medium-high heat and bring to a boil. Turn to medium-low heat. Simmer for 20 to 30 minutes. Skim any brown foam from the top of liquid.",
            "Transfer oxtail to a high pressure cooker or Instant Pot using a pair of tongs. Transfer all the broth into the same pot. Cover and lock the lid. Turn on high pressure and set timer to 35 minutes. Once cooked, let it release pressure naturally.",
            "The oxtail might leave a brown residue on the inside of the big pot you used to boil it. Wash the pot thoroughly before using in the following steps.",
            "Remove the oxtail from the pot and transfer onto a large plate. Transfer the broth into an oil separator to remove extra fat. Alternatively you can let the broth sit for 10 minutes and skim the fat from the top with a ladle.",
            "(Optional) To serve the oxtail without bones, let the oxtail cool until it’s possible to handle. Remove the meat from the bones and break the meat into bite size chunks with your fingers.",
            "While waiting the oxtail to cool, heat the big pot (from step 1) with olive oil over medium heat. Add onion and carrot. Sprinkle with a pinch of salt. Cook and stir until the onion softens, 10 to 15 minutes.",
            "Transfer the beef broth and beef meat back to the big pot. Add ginger, potatoes, cabbage, canned tomato, tomato paste, bay leaves, sugar, salt and black pepper. Simmer for another 30 to 40 minutes (*Footnote 2), until the potato and cabbage become tender. Adjust seasoning by adding more salt, if necessary.",
            "Transfer the soup into serving bowls, garnish with heavy cream or Greek yogurt and serve warm as a main.",
        ]
    ),
    "Oyster Omelet": RecipeDetail(
        ingredients: [
            "1/2 cup chicken broth",
            "1/4 cup ketchup",
            "1 tablespoon light soy sauce",
            "1 tablespoon rice vinegar",
            "1 tablespoon sugar",
            "2 teaspoons cornstarch",
            "1/2 lb (225 g) small shucked oysters",
            "2 teaspoons cornstarch",
            "2 tablespoons peanut oil ((or vegetable oil, divided) (*Footnote 2))",
            "2 teaspoons potato starch",
            "3 eggs",
            "1/4 teaspoon salt",
            "1/4 teaspoon white pepper",
            "4 green onion (, minced)",
        ],
        steps: [
            "Whisk together the sauce ingredients in a saucepan over medium-low heat. Simmer until the sauce thickens.",
            "Add the oysters into a colander and sprinkle evenly with cornstarch. Rub the oysters gently with the cornstarch, then use cold running water to rinse them off. This helps to clean the oysters from any shell fragments and debris. Drain thoroughly and gently pat dry with paper towels.",
            "Heat 1/2 tablespoon oil in a 9” skillet over medium heat until hot but not smoking hot. Add the oysters. Let cook until the bottom has turned white, 30 seconds or so. Flip to cook the other side until it just turns white. Drain off the liquid and transfer the oysters onto a plate to cool off slightly.",
            "Mix the potato starch with 1 tablespoon of water in a small bowl until fully dissolved.",
            "Beat the eggs in a large bowl with salt and white pepper. Add the potato starch slurry. Mix until fully dissolved. Add the green onion and cooled-off oysters. Mix again.",
            "Add the remaining 1 1/2 tablespoons of oil into the same skillet and heat over medium-high heat until hot. Pour in the egg batter and turn to medium heat. Cook until the bottom turns golden. Carefully flip the omelet. Keep cooking until the bottom has set and the inside has cooked. Transfer to a large serving plate. Serve hot along with the sauce as an appetizer or main dish.",
        ]
    ),
    "Smashed Cucumber Salad": RecipeDetail(
        ingredients: [
            "1 English cucumbers (about 11 oz / 300 g) (, tough skin removed)",
            "3 cloves garlic (, crushed and minced)",
            "1 tablespoon Chinkiang vinegar ((or rice vinegar))",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 teaspoon sugar",
            "1/2 teaspoon salt",
            "1/2 teaspoon sesame oil",
            "2 teaspoons Homemade chili oil ((or store-bought chili oil), or to taste (Optional))",
            "1 tablespoon Lao Gan Ma Chili Crisp (, or to taste (Optional))",
        ],
        steps: [
            "Dry the cucumber with a paper towel. Place the cucumber on a large cutting board and carefully use a cleaver to crush it. If you don&#x27;t own a cleaver, a meat pounder will work as well. Then cut it into bite-size pieces and place them into a bowl.",
            "Add the garlic on top of the cucumber.",
            "Combine the vinegar, soy sauce, sugar, salt and sesame oil in a small bowl and mix well.",
            "Right before serving, pour the sauce mixture over the cucumber and mix well. (Do not add the sauce beforehand. It will cause the cucumber to lose water, and the sauce will be diluted.",
            "(Optional) To give the salad an extra kick, you can drizzle some chili oil or add a spoonful of chili crisp. It makes the dish addictively good.",
        ]
    ),
    "Okra Salad": RecipeDetail(
        ingredients: [
            "8 oz (225 g) okra",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "1 tablespoon vegetarian oyster sauce ((or regular oyster sauce))",
            "2 teaspoons Chinkiang vinegar",
            "1 teaspoon toasted sesame oil",
            "1/2 teaspoon sugar",
            "1 cloves garlic (, finely minced)",
            "1 tablespoon ginger (, finely minced)",
            "1 bird eye chili pepper (, sliced for garnish (Optional))",
            "2 teaspoons light soy sauce ((or soy sauce))",
            "1/2 teaspoons green Sichuan pepper oil ((or more to taste))",
        ],
        steps: [
            "Bring a medium pot of water to a boil. Add 1 teaspoon vegetable oil and a pinch of salt, so the okra will have a vibrant color once blanched (Optional). Boil the okra until just turning tender, 1 minute for al dente or 2 minutes for a more tender texture. Drain, rinse with cold tap water or use an ice bath to stop cooking, drain again and pat dry thoroughly with paper towels. Cut off the tough end and the stem off the okra and discard them (Optional, Footnote 2). Then transfer the okra to a bowl or tall plate.",
            "Add the rest of the “Dressing 1” ingredients in a small bowl and stir to mix well. Pour over the okra. Serve as a cold appetizer.",
            "Directly pour the light soy sauce and green Sichuan pepper oil over the okra and serve.",
        ]
    ),
    "Spinach Salad with Peanuts": RecipeDetail(
        ingredients: [
            "1/2 lb (225 g) spinach (, tough ends removed and rinsed thoroughly)",
            "1 tablespoon Chinkiang vinegar",
            "1 teaspoon light soy sauce ((or soy sauce))",
            "1 teaspoon sugar",
            "1/4 teaspoon salt",
            "2 teaspoons ginger (, minced)",
            "1/4 scant cup salted roasted peanuts (, coarsely chopped)",
        ],
        steps: [
            "Bring a large pot of water to a boil. Add spinach and cook over medium heat until cooked through, about 1 minute. Drain, quickly rise with cold tap water, then drain again. Squeeze extra water out of the spinach with both hands. Chop spinach into pieces about 3” (8 cm) in length and transfer a serving bowl.",
            "Combine black vinegar, light soy sauce, sugar, salt, and ginger in a small bowl, mix well.",
            "Right before serving, top the spinach with peanuts and drizzle with the vinegar sauce. Serve immediately as a cold appetizer.",
        ]
    ),
    "Celery and Peanut Salad": RecipeDetail(
        ingredients: [
            "1 cup raw skin-on peanuts ((*Footnote 1))",
            "2 green onions (, cut into 2” (5 cm) long pieces)",
            "2 slices ginger (, sliced)",
            "1 clove garlic (, smashed)",
            "1 teaspoon Sichuan peppercorns",
            "2 bay leaves",
            "1 whole star anise",
            "1 cinnamon stick",
            "1 teaspoon salt",
            "1/4 carrot (, diced)",
            "1/4 cup Chinese celery (, sliced)",
            "1 teaspoon soy sauce",
            "1/4 teaspoon sugar",
            "1/2 teaspoon sesame oil ((or chili oil))",
        ],
        steps: [
            "Add the peanuts into a medium-sized pot with 4 cups of water. Heat over medium heat until it comes to a boil. Add the rest of the braising ingredients. Simmer for 30 minutes. Once done, discard the braising spices. Drain and transfer the peanuts to a bowl and set aside to cool.",
            "Bring a small pot of water to a boil. Add the carrot. Cook until just starting to turn tender, 1 minutes or so. Add the celery to the same pot of water. Boil for 30 seconds, or until just turning tender. Drain and run the veggies with cold tap water to stop the cooking. Transfer to the same bowl with the peanuts.",
            "Add the soy sauce and sugar. Mix well. Drizzle with sesame oil and serve at room temperature.",
        ]
    ),
    "Celtuce Leaves Salad": RecipeDetail(
        ingredients: [
            "1 small batch celtuce leaves (, cut into bite size pieces (yields about 4 cups))",
            "Toasted sesame seeds ((for garnish) (Optional))",
            "2 tablespoons Chinese sesame paste ((or unsweetened natural peanut butter, or tahini))",
            "2 tablespoons Chinkiang vinegar ((or rice vinegar))",
            "1 tablespoon light soy sauce ((or soy sauce))",
            "2 teaspoons maple syrup ((or sugar))",
            "2 teaspoons homemade chili oil ((Optional))",
            "1 clove garlic (, grated)",
        ],
        steps: [
            "To prepare the celtuce leaves, tear the leaves off the stem and rinse them thoroughly with cold tap water to remove any dirt. Once done, drain well and set aside to dry. If the leaves are still wet when you prepare the salad, pat them dry with paper towels. Cut the celtuce leaves into bite-sized pieces and place them on a serving plate.",
            "Mix the sauce ingredients in a small bowl and stir until smooth. Pour half of the sauce onto the celtuce.",
            "Serve the celtuce with the rest of the sauce. Drizzle more sauce if needed.",
        ]
    ),
    "Scallion Tofu Salad": RecipeDetail(
        ingredients: [
            "1 block (325 grams / 12 ounces) silken tofu",
            "1/4 teaspoon sea salt ((or to taste))",
            "1/2 cup green onion (, chopped (green part))",
            "2 teaspoons Chinese sesame oil",
        ],
        steps: [
            "Carefully transfer the tofu from the package to a medium-size plate.",
            "Sprinkle sea salt over tofu and top with green onion and a drizzle of sesame oil. Use a knife to slice tofu into strips, then gently mix it with a pair of chopsticks.",
            "Serve immediately.",
        ]
    ),
    "Enoki Mushroom Salad": RecipeDetail(
        ingredients: [
            "1 stalk enoki mushrooms (, tough ends removed)",
            "2 persian cucumbers (, julienned (or 4” of English cucumber))",
            "1/4 red pepper (, julienned (Optional, or use chili pepper for heat))",
            "1 tablespoon light soy sauce",
            "1 teaspoon Chinkiang vinegar ((or rice vinegar))",
            "1 teaspoon sugar",
            "1/8 teaspoon salt",
            "1 clove garlic (, minced)",
            "1/2 teaspoon sesame oil",
        ],
        steps: [
            "Bring a medium-sized pot of water to a boil. Add golden needle mushrooms and cook for 20 to 30 seconds, until the mushrooms are just cooked through. Immediately drain the mushrooms in a colander and run cold tap water over them to stop cooking. Drain thoroughly, pat dry with paper towels, and transfer to a medium-sized bowl. Add the cucumber, and red pepper.",
            "Mix light soy sauce, vinegar, sugar, salt, garlic, and sesame oil together in a small bowl.",
            "Right before serving (*footnote 1), pour sauce over the salad, add the toasted sesame seeds, and mix well. Serve at room temperature as a side or an appetizer.",
        ]
    ),
    "Tiger Salad": RecipeDetail(
        ingredients: [
            "1 cup cilantro (, thick stems removed and chopped into 1”(2.5 cm) pieces)",
            "1 english cucumber (, sliced to thin strips)",
            "1 to 2 anaheim chilis (, thinly sliced (or other long green chilis, depending on desired spice level))",
            "2 green onions (, thinly sliced in a diagonal)",
            "1 1/2 tablespoons rice vinegar",
            "1 1/2 teaspoons sesame oil",
            "1/2 teaspoon soy sauce",
            "2 teaspoons sugar",
            "1/2 teaspoon salt",
        ],
        steps: [
            "Combine all the salad ingredients in a large bowl.",
            "Add all the dressing ingredients over the salad then toss to coat well.",
        ]
    ),
    "Pickled Cabbage": RecipeDetail(
        ingredients: [
            "1 1/2 cups rice vinegar",
            "1/2 cup water",
            "3/4 cup sugar",
            "1 teaspoon salt",
            "3 cloves garlic (, smashed)",
            "4 red chili peppers (more if desired (Optional))",
            "1 teaspoon Sichuan peppercorns ((Optional))",
            "1 lbs (450 g) cabbage ((about half of a small head of cabbage))",
            "1 large carrot (, peeled)",
            "2 tablespoons salt",
        ],
        steps: [
            "Combine the rice vinegar, water, sugar, salt, and chili peppers in a small saucepan. Heat over medium heat until it reaches a simmer. Cook, stirring occasionally, for 5 minutes, until the sugar is dissolved. Use a clean spoon to taste the pickling liquid to see if it has the desired spice level. You can simmer it for a bit longer if you want the liquid to taste spicier. Once done, set aside and allow to cool.",
            "Meanwhile, prepare the veggies. Cut out the cabbage core and discard it. Tear the leaves into bite-size pieces. Cut the carrot into 1/4” (1/2 cm) thick half-moon shaped slices.",
            "Combine the cabbage, carrots, and 2 tablespoons of salt in a big bowl. Toss it with your hands so the veggies are coated with salt. Let sit at room temperature for 30 minutes, up to 1 hour (no more than an hour).",
            "Drain and discard the salted water released by the veggies. Rinse the veggies with tap water twice. Drain thoroughly, and squeeze out the excess water from the veggies. Transfer them into a large container (or a jar).",
            "Add the crushed garlic and Sichuan peppercorns (if using) into the same container.",
            "Add the cooled pickling liquid. Press the veggies so they are submerged in the liquid. It is fine if a small fraction of the veggies are poking out from the liquid (because the veggies will shrink over time and become submerged). Seal the container and allow to pickle for 3 days in the fridge.",
            "The pickles will start to taste good after 1 day, but the sourness will come through at day 3. Make sure to use clean chopsticks (or flatware) to pick out the pickles every time you serve them. They will stay good in the fridge for 2 to 3 weeks.",
        ]
    ),
    "Pickled Cucumber": RecipeDetail(
        ingredients: [
            "1 to 1 1/2 lbs (450 g to 680 g) persian cucumbers (, cut into spears (or kirby, or English cucumber) (*Footnote 1))",
            "1 teaspoon kosher ((or sea salt))",
            "2 cloves garlic (, lightly crushed)",
            "1/4 teaspoon sichuan peppercorns",
            "2 dried chilis",
            "1/2 cup distilled white vinegar",
            "1 cup water",
            "2 teaspoons soy sauce",
            "1 tablespoon sugar",
        ],
        steps: [
            "Add cucumber into a big bowl. Sprinkle salt over the sliced cucumbers and gently toss them with your hands so the cucumbers are evenly coated. Rest for 30 minutes to an hour, tossing them occasionally.",
            "Once the cucumbers are done resting, drain off the liquid that has collected in the bottom of the container and gently rinse the cucumbers with cold water to remove the excess salt. Place the rinsed cucumbers and garlic cloves into a heat-proof, sealable container or mason jars. Make sure to arrange the cucumbers to be packed together, without too much excess space between them.",
            "Heat the sichuan peppercorns and dried chilis over medium-low heat in a small pot. Toss the spices until fragrant, around 1 minute.",
            "Once the spices are fragrant add the vinegar, water, soy sauce, and sugar. Bring to a boil.",
            "Pour the hot brine over the cucumbers until they are completely covered.",
            "Allow the pickles to cool to room temperature and seal the container.",
            "Let the cucumbers pickle overnight in the fridge and enjoy!",
        ]
    ),
    "Pickled Peppers (Pao Jiao)": RecipeDetail(
        ingredients: [
            "8 to 10 jalapenos (, quartered and deseeded, or sliced and deseeded (*Footnote 1))",
            "1 clove garlic (, lightly crushed)",
            "3 slices ginger",
            "2 teaspoons Baijiu ((or vodka))",
            "1 teaspoon sugar",
            "3/4 teaspoons salt",
            "1/3 cup Chinese white rice vinegar ((or regular rice vinegar, or distilled vinegar))",
            "1/4 cup water",
        ],
        steps: [
            "Place the jalapenos, garlic, and ginger in a heat proof 16-oz (473 ml) jar or a container, they should be well packed together. Sprinkle over the salt, sugar, and pour in baijiu.",
            "Combine the water and rice vinegar in a small pot and bring to a boil. Pour over the jalapenos.",
            "Cover the pickles and allow them to cool. Seal and refrigerate for 24 to 48 hours before serving. The pickles should be able to stay well for at least a month in the refrigerator. Always use a clean pair of chopsticks to serve them, to prevent contamination.",
        ]
    ),
    "Red Bean Zongzi": RecipeDetail(
        ingredients: [
            "20 to 30 sheets dried or fresh bamboo leaves ((or reed or banana leaves) (*see footnote))",
            "2 cups (400 grams) glutinous rice",
            "1 cup homemade red bean paste ((or a packaged one from a Chinese market))",
            "Cotton twine or narrow stalks to tie the zongzi",
        ],
        steps: [
            "Rinse glutinous rice with water 2 to 3 times. Add glutinous rice into a big bowl and water to cover. Let soak overnight.",
            "Bring a large pot of water to a boil. Add bamboo leaves and boil for 5 to 8 minutes, until the leaves turn soft but are still green in color. Transfer the bamboo leaves to a plate.",
            "Heat a large pot of water to just under boiling. Turn off heat. Dip bamboo leaves in the hot water and let them soak for 1 to 2 minutes, until soft.",
            "Place the bamboo leaves, cotton twine, red bean paste, glutinous rice (do not discard the water), and two spoons on the working surface.",
            "If the bamboo leaves are less than 8 cm (3 inches) wide, use two at a time. Otherwise, you can use one leaf. Overlap the leaves by 50% to 60% if using more than one. Fold the leaves with both hands to shape them like a funnel, without leaving an opening at the bottom.",
            "Hold the funnel with one hand. Start adding glutinous rice into it with a spoon with the other hand, until halfway filled. You should add water with the rice, so the rice fills the leaf nicely while the water drips away from the bottom. Scoop about 1 tablespoon of red bean paste (or more if the zongzi size is bigger) and place it on the rice. Continue to fill the funnel with rice, until almost level with the edge. Pat the rice a bit so the top is flat. You don’t need to compress the rice too hard, otherwise the rice will be squeezed into the red bean paste.",
            "Continue to hold the funnel with the same hand. Use the other hand to fold the longer side of the leaf as a lid to cover the rice. Continue to fold the longer side of the leaf, until it wraps the funnel. Hold the zongzi with one hand and use the other hand to tie it up with the cotton twine. The finished zongzi should have edges that are 8 to 10 centimeters (3 to 4 inches) long. Work on the rest of zongzi using the same method. (refer to the video for how to tie zongzi)",
            "Place the zongzi in a large pot and add water until it almost covers the zongzi. Place a heavy plate on top to keep the zongzi in the water while cooking. Cover the pot and bring to a boil over high heat. Turn to low (or lowest) heat and let the water continue boiling. Keep covered and simmer for 3 hours.",
            "Transfer one zongzi to a plate to cool off until you can handle it. Untie and slice it in half to make sure it’s cooked through (if the zongzi is very large, it might require more cooking time, up to 4 hours). Transfer all the zongzi to a plate to cool off.",
            "Untie the zongzi right before serving and discard the leaves. Serve warm or cold with honey or sugar. Dip the zongzi in honey or sugar while eating.",
            "To store zongzi, place in a plastic bags after cooling off and seal the bag. Store in fridge up to 3 days or in freezer up to 2 months.",
            "To serve leftover zongzi. Let thaw completely (if frozen). Steam or gently boil in a pot of water until warm. Or you can place the zongzi on the kitchen counter until they return to room temperature, then serve cold. I personally prefer warm zongzi, because they have a better texture than the cold one.",
        ]
    ),
    "Savory Pork Zongzi": RecipeDetail(
        ingredients: [
            "24 to 36 dried bamboo leaves ((Footnote 1))",
            "24 2 ft (60 cm) twine",
            "3 cups (600 g) short grain sweet rice (, washed (Footnote 2))",
            "1 teaspoon sugar",
            "1 tablespoon soy sauce",
            "1 tablespoon dark soy sauce",
            "1 tablespoon oyster sauce",
            "12 oz (350 g) fatty pork (pork belly, chop, or loin with fat attached) (, cut into 2” (5cm) chunks (Footnote 3))",
            "1 tablespoon Shaoxing wine ((or dry sherry))",
            "2 teaspoons soy sauce",
            "1 teaspoon dark soy sauce",
            "2 teaspoons sugar",
            "1 teaspoon salt",
            "1/2 teaspoon five spice powder",
            "2 teaspoons grated ginger",
            "2 green onions (, sliced diagonally)",
            "3/4 cup (150 g) shelled mung beans (, washed)",
            "12 dried shiitake mushrooms",
            "6 salted duck egg yolks (, halved)",
        ],
        steps: [
            "Soak the bamboo leaves, sweet rice, and mung beans separately in water overnight.",
            "Combine all the pork ingredients and allow to marinate overnight.",
            "(Optional- to sanitize the bamboo leaves, remove them from the soaking liquid and add them to a pot with fresh water. Bring it to a boil and cook the leaves for 5 minutes.) Drain the leaves and wipe them each down on both sides. Cut off an inch from the base and an inch from the tip.",
            "Place the shiitake mushrooms in a medium-sized bowl and add hot water to cover. Soak for 15 to 20 minutes, or until the mushrooms are soft throughout. Drain the mushrooms, squeeze out the excess water, and slice them into quarters.",
            "Drain the rice and transfer it to a big bowl. Add the seasonings to the rice and mix until evenly coated.",
            "Drain the mung beans and transfer them to a medium-sized bowl.",
            "To wrap the zongzi (see the process photos above for the steps)",
            "Take two leaves, making sure they do not have any holes or tears. Use a pair of kitchen scissors to cut off 1” (2.5 cm) from both ends. Face the smooth sides towards yourself (this is the side that will contain the filling), with the wider base sides facing away from each other, then overlap the leaves to make 1 long strip. There should be 3-4” (8-10 cm) of individual leaf sticking out beyond the overlap on each side. A third of the way along the strip, pinch the side opposite from you and fold it into a cone shape, with the leaf sticking out from one end. Hold the cone using one hand and begin to add the filling with your other hand.",
            "Add 2-3 tablespoons of rice to the bottom and press it up against the sides to create a small well. Add a piece of pork (make sure every piece added has a chunk of fat), half a yolk, two quarters a shiitake, and 1 to 2 tablespoons of mung beans. Add 2 to 3 tablespoons of rice over everything. Gently press and smooth as you do. There should be a 1/4” (1/2 cm) lip around the rice.",
            "Take the open side of the zongzi between your thumb and index finger and fold the sides inwards, covering the rice. Fold the long leaves over the open area, tightening between your thumb and index finger to create a pointed triangular shape. Then flip the zongzi over and wrap the leaves around tightly to seal it. Wrap the zongzi in a piece of twine, making sure it is cinching any area where the leaf might come loose, and tie it off. For extra security, you can use another piece of twine to wrap the zongzi again, crosswise.",
            "Cook on the stovetop: Bring a large pot of water to boil and add the zongzi. Return the pot to a low simmer and cook covered for 3 hours (4 if the zongzi are very large).",
            "Cook in an Instant Pot: Add the zongzi to an Instant Pot and water to cover. Close the lid and make sure the valve is sealed. Choose “Manual” at “High Pressure” and set a timer for 1 hour. Once done, let the Instant Pot release the pressure naturally.",
            "Drain the zongzi from the water and serve hot.",
            "Store cooked and wrapped zongzi in an airtight container or Ziplock bag in the fridge for 5 days or in the freezer for up to 6 months. To reheat, thaw the zongzi completely in the fridge overnight. Boil the zongzi in water until heated through, 15 to 20 minutes. You can heat up the unwrapped zongzi in a microwave as well.",
        ]
    ),
    "Traditional Mooncake": RecipeDetail(
        ingredients: [
            "140 g (1 1/3 cups) black sesame seeds (, toasted)",
            "80 g (2/3 cup) fine white sugar",
            "60 g (4 tablespoons) butter",
            "150 g (1 cup) white beans (, well drained)",
            "1 tablespoon maltose ((Optional))",
            "9 salted duck egg yolks (, halved (*footnote 1))",
            "140 g golden syrup",
            "4 g (3/8 teaspoon) kansui",
            "50 g vegetable oil",
            "1/8 teaspoon salt",
            "200 g cake flour",
            "1 egg yolk",
            "1 teaspoons milk ((or water))",
            "50g mooncake mold",
            "Scale ((*Footnote 2))",
            "Pastry brush",
        ],
        steps: [
            "Add the black sesame seeds into a food processor. Blend until the sesame seeds start to seep oil and thicken, about 2 minutes. Use a spatula to thoroughly scrape the paste from the walls and bottom of the food processor. Blend again until it forms a fine paste, 1 to 2 minutes. Scrape the paste from the walls and bottom.",
            "Add sugar and white beans. Blend again until everything is fully mixed. If the paste is too thick to blend, you can add a very small amount of water. Transfer the paste to a bowl.",
            "Heat half of the butter in a medium-sized skillet over medium heat until melted. Add the bean paste. Cook and stir until the butter is fully absorbed. Add the rest of the butter and cook until fully absorbed. Add the maltose if using. Cook and stir until the paste becomes quite dry and able to hold its own shape, 3 to 4 minutes. Transfer the sesame paste to a plate and spread it out. Let cool completely. You can store the sesame paste in the fridge to make it easier to handle later.",
            "Combine golden syrup, kansui, vegetable oil and salt in a large bowl. Mix with a spatula until emulsified.",
            "Add cake flour into the bowl. Gently fold the dough with a motion of scraping from bottom to top, like you are folding a cake dough. Do not stir the dough in a circular motion. It will toughen the dough.",
            "When the flour is fully combined, shape the dough into a ball with your hands. The dough should be soft and a bit sticky but still hold its shape. Seal with plastic wrap. Let rest for 2 hours.",
            "Once it has cooled off, divide the sesame paste into 30-gram portions if not using duck egg yolks. Or add half a duck egg yolk and some sesame paste onto a scale, so that it weighs 30 grams in total. Shape the sesame paste into a ball, then press the center to form a disk. Place the egg yolk in the center. Wrap the sesame paste around the yolk until fully covered, then shape it into a small ball. Place it onto a tray,",
            "Once you have shaped all the mooncake fillings, cover them with plastic wrap and place them in the freezer. Wait until the balls harden so they’re easier to handle, 30 minutes or so. (*Footnote 3)",
            "Once the mooncake dough is rested, scoop and measure 20g dough pieces. Shape each dough piece into a ball using your hands. Then place them onto a large tray. Cover the tray with plastic wrap to prevent the dough from drying out.",
            "Preheat oven to 400°F (200°C). Line a baking sheet with parchment.",
            "Place a dough piece onto your palm and use your thumb to flatten the dough from the center, until it forms a round disk that is thinner in the center and thicker on the outside. Place the black sesame filling in the center. Carefully wrap the dough around the filling. Spread the dough until it seals the filling in completely. The dough should be very soft but not sticky, and easy to shape, like soft clay. (*Footnote 4) If you find the dough too thick in some spots, pull off the dough and smooth the surface. It doesn't matter if the dough is so thin that it reveals the color of the filling. Roll the dough between your hands until the dough forms a smooth ball.",
            "Slide the plastic pattern disc into the mooncake mold, pattern side down. Twist the handle to lock the pattern disc so it’s secure.",
            "Dust both hands and the mooncake dough with a bit of cake flour, so it’s easy to release from the mold. Carefully place the mooncake into the mold.",
            "Place the mold on a clean working surface and firmly press the handle until you cannot move it any further. Hold the handle down for at least 5 seconds so the pattern sticks. Then release the mold from the table and push the handle to release the mooncake onto the lined baking sheet. Work on the rest of the mooncakes and place them onto the tray, about 1” (1.5 cm) apart. Spray a very small amount of water onto the mooncakes to prevent the dough from cracking. Bake for 5 minutes until the patterns are set. The edges of the mooncakes should turn pale golden.",
            "Meanwhile, make the egg wash by beating the egg yolk with milk (or water) in a small bowl.",
            "Remove the mooncakes from the oven. Brush a thin layer of egg wash onto the surface of the mooncakes. Only brush the top surfaces, not the vertical (side) surfaces. Try to only brush it onto the arched pattern, and not the recessed concave area. If you accidentally brush too much egg wash and it fills in the pattern, use a small brush to clean the gaps and remove the excess egg wash.",
            "Place the mooncakes back in the oven and lower the oven temperature to 350°F (176°C). Continue baking until the egg wash turns golden brown, 12 to 15 minutes.",
            "Let mooncakes cool on the tray for 20 minutes before removing (*footnote 5). Then transfer to a plate to cool completely.",
            "Once cooled completely, store the mooncakes in an airtight container. The mooncakes can be served after 24 hours, and they will look and taste better after 2 days. (Footnote 6)",
            "Store the mooncakes in an airtight container in a cool dark area for up to 1 week, or in the fridge for 2 to 3 weeks, or in the freezer for up to 2 months. If stored in the fridge, let the mooncakes return to room temperature before serving. Thaw frozen mooncakes in the fridge overnight before serving.",
        ]
    ),
    "Tang Yuan": RecipeDetail(
        ingredients: [
            "1/2 cup shelled peanut",
            "1/2 cup original peanut butter (, unsweetened)",
            "1 cup caster sugar",
            "1/4 cup (4 tablespoons) butter (, softened (or lard in room temperature, or melt coconut oil for a vegetarian option) (*footnote 1))",
            "2 cups (250 grams) glutinous rice flour ((*footnote 2))",
            "1 cup warm water",
        ],
        steps: [
            "Spread peanuts in a pan and heat over medium heat on stove. When the pan turns warm, turn to medium low heat. Shake the pan occasionally for even cooking. Toast until the peanuts turn golden but not darkly browned. Alternatively, you can roast the peanuts in 350 F oven for 8 to 15 minutes, or until the surface turns golden. Shake the pan occasionally during baking.",
            "Ground the peanuts in batches by using a coffee grinder, in a mini food processor, or by using a mortar and pestle until finely grounded, but not into powder. You can leave the pieces a bit larger if you want a chewy texture. Transfer to a bowl. Add peanut butter, sugar and coconut oil. Stir to mix well. Transfer to fridge to harden for about 30 minutes or longer, until it’s possible to scoop out the filling and shape it. If you leave the filling in the fridge for a longer time, it will harden even more and might be a bit difficult to shape. If this is the case, place the filling in room temperature for 5 minutes to let it soften a bit before shaping.",
            "Use a small spoon to scoop about 1 teaspoon to 1 and 1/2 teaspoon of filling. Shape it quickly into a ball, and place on a small tray or in a container.",
            "Transfer the peanut butter balls into the freezer while making the dough.",
            "Add glutinous rice flour in a big bowl. Slowly add warm water and whisk with a pair of chopsticks (or a spatula). When the water is fully absorbed, use your hands to press and work it into a dough. If the dough is too sticky, add more glutinous rice flour, 1 tablespoon at a time, and keep kneading the dough. Unlike wheat flour dough, rice flour dough does not require a lot of kneading, so it is done once the dough is shaped. Transfer the dough to a big bowl and cover with plastic wrap or a clean wet towel, to prevent it from drying out.",
            "Divide the dough into 4 equal pieces. Shape each piece into a round ball. Work on one dough ball at a time and return the three dough balls back into the large bowl, then cover with plastic wrap.",
            "Roll the dough ball into a long even strip. Cut to 8 pieces. Roll into small balls.",
            "Work on the dough balls one by one. Flatten the dough into a round disk that has a dent in the center. Place the filling in the center of the dough. Seal the filling carefully by wrapping and spreading the dough. When you cannot see the filling anymore, roll the dough into a round ball by using both hands.",
            "If you find the dumpling is too difficult to seal, knead the rest dough balls back together into one big dough ball again, cut into 5 pieces to 6 pieces and try again. It is very important to wrap and seal the dough tightly, so the dumplings won’t fall apart during cooking.",
            "The filling will become soft if placed in room temperature for too long and become very difficult to wrap, especially if you’re using coconut oil. I suggest you to take out a few filling balls at a time to work with, and store the rest in the freezer.",
            "Work on the rest of the dough balls using the same method.",
            "Now you can cook the rice balls or freeze them for later.",
            "Bring a pot of water to a boil. Carefully add the number of rice balls you plan to serve. Cook and stir occasionally until the rice balls float on top and the skins look translucent.",
            "Immediately transfer the rice balls to small serving bowls with just enough boiling water to cover them. We usually eat the rice balls with some boiling water. If it’s not sweet enough for you, add a few drops of honey or osmanthus syrup into the boiling water to sweeten it.",
            "Place leftover filling in a ziplock bag, squeeze out as much as air as possible, and seal. Store in the fridge for 1 week or in the freezer for up to 3 months.",
            "To store the raw tang yuan, place them on a tray, 1 finger apart, and cover with a plastic wrap. Freeze until completely frozen. Transfer to a ziplock bag or airtight container, store in the freezer for 2 to 3 months.",
            "Note, you should always cook the amount of tang yuan you plan to serve and eat them while they’re warm, soon after cooking. Always store the extra tang yuan in the raw form in freezer.",
        ]
    ),
    "Snow Skin Mooncake": RecipeDetail(
        ingredients: [
            "40 grams (6 tablespoons) cornstarch",
            "5 grams (2 teaspoons) all-purpose flour",
            "112 grams (1/2 cup) granulated sugar",
            "5 large egg yolks",
            "480 grams (2 cups) whole milk",
            "30 grams (2 tablespoons) butter",
            "1/2 teaspoon vanilla extract",
            "120 grams (1 cup) glutinous rice flour",
            "120 grams (1 cup) rice flour",
            "120 grams (1 cup) cornstarch (, and extra for coating the mooncakes)",
            "100 grams (3/4 cup) confectioners sugar",
            "350 grams (1 1/2 cup) whole milk",
            "55 grams (1/3 cup) vegetable oil",
            "1/2 teaspoon vanilla extract",
            "A 50-gram Mooncake mold",
        ],
        steps: [
            "Mix the cornstarch, all-purpose flour, and half of the sugar together in a small bowl.",
            "Place the egg yolks in a large bowl. Stir a few times to mix the yolks.",
            "Add the milk and the remaining half of the sugar into a small saucepan. Heat over medium heat. Stir occasionally to dissolve the sugar completely. Cook until it reaches about 120°F/ 49°C (no more than 150°F / 65°C). You might see a few bubbles here and there. If the milk starts foaming, it’s too hot.",
            "While the milk starts to get warm, add the dry ingredients (from step 1) into the bowl with the egg yolks. Whisk until it forms an even paste. Do not add the dry ingredients too early, because the sugar will change the texture of the eggs.",
            "Add the warm milk into the egg yolk mixture, about 1/4 cup at a time. Whisk constantly until the milk is fully incorporated into the paste. Continue to add more milk a 1/4 cup at a time and keep stirring, until it forms a thin, smooth mixture and all the milk is added.",
            "Return the mixture back into the pot (the one you used to heat the milk). Heat over medium heat and stir constantly while scraping the bottom (to prevent from burning), until the mixture thickens. Keep cooking and stirring, until it starts to bubble. Stop your spatula for a moment to make sure that the custard is boiling. Keep stirring and boiling for one full minute. This is important so the custard will be able to thicken after chilling.",
            "Remove the pot from the stove. Add the butter and vanilla extract. Stir to mix well.",
            "Line a large deep plate with plastic wrap. Place a large mesh strainer on top.",
            "Pour the custard into the lined plate over the strainer to smooth out the texture. Use a spatula to press the strainer if any lumps remain.",
            "Cover the custard with plastic wrap. Press the wrap against the custard, so it won’t form a skin once it’s chilled.",
            "Chill the custard in the fridge until it’s cooled completely, 2 hours or so. Or in the freezer for 30 mins.",
            "Prepare a large bowl that can fit into your steamer. Place a large strainer on top.",
            "In another medium-sized bowl, add the glutinous rice flour, rice flour, and cornstarch. Mix well with a fork.",
            "Line a large mesh strainer over the bowl and sift the confectioner's sugar through it. Use your fingers or a spoon to press the sugar through if any lumps exist.",
            "Add the milk, oil, and vanilla extract into a small bowl. Stir to mix well.",
            "Use your fork to form a hole in the middle of the flour. Add 2 to 3 tablespoons of the milk mixture at a time. Stir until the liquid is incorporated into the flour completely. Repeat the process until it forms a very runny batter.",
            "Pour the mixture into the large bowl (you prepared in step 1) over the strainer. Press the lumps using a spoon. Once strained, the mixture will thicken a little bit.",
            "Prepare a steamer by pouring 1 inch (2.5 cm) of water into the steamer pot. Cover and heat over medium-high heat until boiling. Place the bowl with the batter into the steamer rack. Place the rack over the boiling pot. Cover and steam until the batter is cooked completely, 25 to 30 minutes. After 25 minutes, examine the dough by inserting a spoon into the middle. The spoon should come out clean, and the dough should feel very stiff.",
            "Once done, remove the lid, and transfer the steaming rack with the bowl onto your kitchen counter to cool off for a few minutes.",
            "Fold a kitchen towel a few times and place it on your working surface. Remove the bowl with the dough wearing oven mitts, and transfer the bowl onto the towel.",
            "Scrape the dough from the bowl and knead it using a spoon, until it forms a dough ball, 5 minutes or so.",
            "Transfer the dough onto a clean surface. Note, do not add any flour onto the surface or dust your hands with it. Knead the dough using your hands until it’s smooth, 5 minutes or so. The dough will soften once done.",
            "Form the dough into balls - Measure 25 grams of dough (about 1 round tablespoon) and use your hands to roll it into a ball. Place the dough balls into a container and cover. Chill in the fridge until the custard is ready to use.",
            "You can keep the dough and the custard filling refrigerated for a couple of hours, up to overnight, until ready to assemble. The dough will become a bit stiff if you chill it overnight. If you want the freshest taste, you should assemble the mooncakes the same day you make the dough and filling.",
            "Once the custard is fully chilled, use a spatula to mix the custard again to even out the texture. This step will soften the custard a bit, but make it easier to scoop and shape.",
            "Form the custard into balls - Measure 25 grams of filling (about 1 round tablespoon) and use your hands to press and roll, until it forms a ball. I highly recommend wearing disposable gloves to help with this process, so the custard doesn’t stick to your hands.",
            "Transfer the filling balls into a plate and wrap it. Chill for another 30 minutes.",
            "Place the dough ball on a clean working surface. Use a rolling pin to roll it into an even, thin, round disc that is about 4” (9 to 10 cm) in diameter. Carefully remove it from the surface onto your palm.",
            "Place a custard ball in the center of the wrapper. Use your other hand to gather the wrapper onto the top of the custard filling. The dough sheet will start to form pleats and create a thicker layer. Try to pinch the extra dough together using your fingers, and pinch off the dough. The process will keep the mooncake skin even and thin, to create a better mouthfeel. Once done, place the mooncake onto a plate, pleated-side-down. Loosely cover it with plastic wrap to prevent them from drying out. Repeat the process to wrap the rest of the mooncakes.",
            "Install the pattern plate into the mooncake mold, with the pattern side facing downward. If you’re using the round shape, you can twist the lever of the mold so the pattern plate will snap onto the lever. It’s not required but it makes the process a bit easier.",
            "Dust the mooncake with a very thin layer of cornstarch. (*Footnote 1)",
            "Carefully place the wrapped mooncake balls into the mold, smooth surface against the pattern plate.",
            "Place the mold onto a clean, flat surface. Gently press the lever until the dough is against your table surface. Hold it for at least 30 seconds. It will help the pattern to form. Once done, push the lever to release the mooncake. Repeat the process to mold all the mooncakes.",
            "The mooncakes are ready to eat!",
            "Transfer the mooncakes into an airtight container. Store them in the fridge for 3 to 4 days. To enjoy the mooncakes with a better texture, transfer them to your kitchen counter and wait for them to return to room temperature. You can eat the chilled mooncakes, but the skin will be a bit stiff.",
            "Note, do not freeze the mooncakes. This will change the texture of the custard and make it very grainy.",
        ]
    ),
    "Fa Gao": RecipeDetail(
        ingredients: [
            "50 g (1/3 cup) brown sugar",
            "1/2 cup (120 ml) water",
            "1 tablespoon white sugar ((*Footnote 1))",
            "160 g (1 cup) all-purpose flour",
            "4 g (1 teaspoon) instant yeast",
            "1 egg",
            "16 jujubes (, pitted, 10 halved, and the remaining 6 chopped)",
        ],
        steps: [
            "Add the brown sugar, white sugar, and water into a small bowl. Microwave to heat up for 30 seconds. Stir to dissolve completely. Let the water cool off while preparing the rest of the ingredients.",
            "Sift the flour into a medium-sized bowl. Add the yeast and stir to mix well.",
            "Once the mixture of sugar water cools to skin temperature, pour it into the flour. Add the egg. Stir everything together to mix well until it forms a smooth batter, but do not over mix. Run the batter through a colander into a big bowl, pressing down any remaining bits that are not mixed evenly. Add the chopped jujubes. Stir again to mix well.",
            "Grease a 6” cake pan with a thin layer of oil. Pour in the batter. Shake the pan to smooth out the batter. Arrange the halved jujubes on top. Let rise in a warm spot until the size doubles, 1 hour or so.",
            "Prepare a steamer by adding 2” (5 cm) water into the pot. Heat covered over medium-high heat until boiling. Place the cake pan onto the steamer rack, and place the rack over the steamer. Steam for 30 minutes over medium-high heat. Then turn off the heat and let it rest for 5 minutes (do not remove the cover).",
            "Once done, transfer the cake pan onto a rack to cool off slightly. Then turn it upside down to remove the cake. Once it’s cooled enough to handle by hand, or to room temperature, slice it into wedges and serve.",
        ]
    ),
    "Pumpkin Mochi Cake": RecipeDetail(
        ingredients: [
            "1 can (15 oz) pumpkin puree ((or 25 oz (700 g) pumpkin))",
            "2 cups (250 g) glutinous rice flour",
            "1/2 cup bread crumbs",
            "Oil spray ((or oil for frying))",
            "2/3 cup red bean paste",
        ],
        steps: [
            "(Optional) If making pumpkin puree from uncooked pumpkin - Cut the pumpkin into large bite-size pieces. Fill a steamer with water and bring to a boil. Place pumpkin on a steaming rack, skin side down. Cover pot and bring to a boil over medium-high heat. Turn to low heat and steam until the pumpkin can easily be pierced with a fork, about 15 minutes. Transfer pumpkin to a plate to cool. Scoop the pumpkin flesh from the skin and add it into a large bowl. Smash into paste.",
            "Slowly blend glutinous rice flour into pumpkin paste, about 2 tablespoons at a time. Whisk with a pair of chopsticks (or a fork), until flour is fully incorporated. Add more flour and keep mixing, until the flour becomes difficult to blend. Dust both hands with rice flour. Knead the dough together with one hand until it forms a consistent and soft dough. The dough should be easily picked up by hand and should stick to the bottom of the bowl a bit. Pick up the dough and use both hands to press and knead the dough for another 5 minutes to blend the rice flour in well. The surface of the dough should be smooth and you shouldn't notice any stray flour on or inside the dough.",
            "Put bread crumbs in a tall plate or a bowl and set aside.",
            "To prepare the filling, scoop 2 teaspoons of red bean paste and shape it into a small ball using your hands. Repeat until you’ve made 16 red bean filling balls.",
            "Divide the dough into 4 equal parts, then divide each of those parts into 4 small pieces (about 41 g per dough piece). Shape each small piece into a dough ball with both hands.",
            "To make pumpkin buns: Hold a dough ball in one hand and use the other hand to press it into a flat, round shape, about 2” (5 cm) in diameter. Place the red bean paste in the center. Wrap the dough around the filling and pinch the edges together to seal the filling, forming a ball again. Gently press the ball until it is shaped like a mini pancake, about 1/2” (1 cm) thick.",
            "Place the buns in the bread crumbs, pressing gently so the bread crumbs coat the surface. Flip to coat the other side. Process the rest of the dough in the same manner to make 15 pumpkin cakes.",
            "If using stovetop: Heat 1/2” (1 cm) oil in a medium-sized skillet over medium-high heat until hot. Cook in batches by placing a few pumpkin cakes into the skillet. Fry over medium-low heat for 2 minutes, until the bottom side turns golden brown. Flip the buns and fry the other side over lowest heat for another 2 minutes. Check the bottom side of the buns after 1 minute. If the color has already turned brown, turn to low heat, and allow to sit for another minute. Transfer to a plate to cool.",
            "If using an air fryer: Preheat the air fryer for 10 minutes at 350°F (176°C). Line the air fryer basket with parchment paper. Place the pumpkin cakes into the basket without overlapping and leave a bit of space in between. Spray the top of the cakes with a generous amount of oil. Cook for 6 minutes, until the top becomes golden. Take out the basket, flip, and spray with oil. Air fry for another 4 minutes until the top becomes golden crispy, and the pumpkin cakes have slightly ballooned.",
            "Let the pumpkin cakes cool slightly before serving. Serve hot or at room temperature. Store in an airtight container in the fridge for up to 3 days or in the freezer for 3 months. Thaw the cakes before reheating. You can reheat the cake in a 300°F (150°C) air fryer or oven until the cake is warm throughout. You can also reheat them on the stove top by adding a bit of oil into the pan, covering the pan, and reheating over low heat.",
        ]
    ),
    "Black Sesame Tang Yuan": RecipeDetail(
        ingredients: [
            "60 g (1/2 cup) toasted black sesame seeds",
            "50 g (1/4 cup) brown sugar ((or regular sugar))",
            "85 g (6 tablespoons) unsalted butter (, softened)",
            "200 g (1 1/2 cup) glutinous rice flour (, and extra for dusting)",
            "200 ml (2/3 cup + 1 tablespoon) warm water (100°F / 40°C)",
        ],
        steps: [
            "Combine the black sesame seeds and sugar in a food processor. Blend until the sesame seeds are finely ground.",
            "Add the softened butter to the food processor. Pulse until the butter is evenly blended. Transfer the mixture onto a plate. Use a spatula to press the filling into a thin layer so it hardens faster. Cover the plate and refrigerate or freeze until the butter is solidified enough to handle, a minimum of 30 minutes in the fridge or 15 minutes in the freezer.",
            "To make the sweet rice ball filling, scoop out about 1/2 tablespoon of the filling (7 g). Use your palms to roll the filling until it forms a round ball. Keep working to make the filling balls. If the butter becomes too soft, transfer it back to the fridge to solidify it. Once done, place the plate of black sesame balls back in the fridge or freezer (*Footnote 1).",
            "Add the glutinous rice flour to a medium-sized bowl and pour in the water. Mix until a dough forms. Sprinkle some flour onto a working surface and dust your hands with it. Transfer the dough onto the working surface. Use your hands to knead the dough a few times until it’s smooth and soft.(*Footnote 2) Return the dough to the bowl and cover with plastic wrap when not using.",
            "Take about 1 scant tablespoon (16 g) of the dough. Use your palms to shape the dough into a round ball. Then use your thumb to press the center of the dough so it forms a small bowl shape. Place the black sesame ball in the center of the dough. Use your thumb to press the filling, while using your other hand to slowly smooth and stretch the dough over the filling. When the dough fully covers the filling, pinch the dough together to seal it. Then roll the rice ball between your hands so it’s perfectly round. Then place it onto a tray and work on the rest of the rice balls.",
            "Once you’ve shaped the rice balls, you can freeze them and cook them later. Or you can cook them immediately.",
            "Bring a medium-sized pot of water to a boil over medium-high heat. Add the rice balls according to the number of servings you want to make (*Footnote 3). Stir gently to prevent them from sticking to the pot. Cook until the water comes to a boil again, then turn to medium heat. Once the rice balls have risen to the top, keep boiling for another 2 minutes. Then transfer the rice balls along with some boiling water to the serving bowls. The boiling water should just cover the rice balls. Serve hot and enjoy!",
        ]
    ),
    "Sesame Balls": RecipeDetail(
        ingredients: [
            "1 1/2 cup glutinous rice flour",
            "3/4 cup water",
            "1/2 cup sugar",
            "1/2 teaspoon salt",
            "Vegetable oil (, for deep frying (about 8 cups))",
            "12 heaping teaspoons red bean paste ((or lotus seed paste) (*Footnote 1))",
            "1/3 cup sesame seeds ((raw, or toasted and hulled) (*Footnote 2))",
        ],
        steps: [
            "Weigh 140g of glutinous rice flour in a heatproof bowl, and weigh the other 50g in a separate small bowl.",
            "Add the water, sugar and salt to a small saucepan and bring to a simmer. Stir until the sugar is fully dissolved to make a syrup.",
            "Slowly add the syrup gradually to the heatproof bowl with the glutinous rice, while mixing with a spatula, until the mixture becomes a smooth paste without any clumps.",
            "Gradually add the remaining 50g (1/4 cup) glutinous rice flour in three parts, stirring until a cohesive dough is formed. If the dough continues sticking to the bowl, add an additional 10g (about 1 tablespoon) of glutinous rice flour. If it becomes crumbly, add 10g (2 teaspoons) of water.",
            "Add 1 teaspoon of oil to the dough. Knead it with your hands to incorporate. The dough should become uniform and ductile, and should not stick to the bowl.",
            "Once the dough is completed, wrap it in plastic wrap and rest in the fridge for 30 minutes.",
            "While the dough rests, weigh out the red bean paste into twelve 16g balls (approximately 1 heaping teaspoon) (*Footnote 3). After weighing, roll each red bean paste portion into a ball by rolling between the palms of your hands. Place the red bean paste balls on a tray, and put it in the freezer (this makes the wrapping much easier and mess-free).",
            "Once the dough has finished resting, transfer it to a clean working surface lightly dusted with glutinous rice flour. Roll the dough into a uniform tube. Cut the dough into 12 equal pieces that weigh approximately 32g each.",
            "Roll each dough section into a ball with the palms of your hands, and cover with a moistened towel to prevent it from drying out.",
            "To form the sesame balls, gently flatten a dough ball, forming a dimple in the middle. Place a chilled Red Bean Paste ball inside the dimple. Gently hold the dough ball in your dominant hand, delicately tuck the Red Bean Paste into the dough, while cupping the edge of the dough with your other hand. Continue tucking and cupping the edge of the dough, turning the dough section as you go, until the dough covers the chilled red bean paste ball. Press the edges of the dough together to completely seal the ball (*Footnote 4). Then roll the ball gently in your palms to round it out. Repeat this process with the remaining dough balls. Cover the formed balls with a wet towel to prevent them from drying out.",
            "Place the sesame seeds in a small bowl. Wet both of your hands. Roll each ball to moisten the exterior, then place it into the bowl with sesame seeds. Gently shake the bowl in a circular motion to coat the ball evenly with sesame seeds. Place the sesame ball onto a tray. Repeat with the rest of the balls.",
            "Prepare a sheet pan lined with a wire rack. Heat the oil to 300°F (150°C) in a medium-sized pot, and place half the sesame balls into the hot oil. To prevent the bottoms of the sesame balls from sticking to the pot and burning, gently stir them with a ladle or slotted spoon.",
            "Continue frying the balls for 15 minutes, while maintaining the oil temperature at 275°F (135°C) to 290°F (143°C). If the oil exceeds 300°F (150°C), turn off the heat and let the oil temperature come back down.(*Footnote 5)",
            "The sesame balls should begin to float to the top and puff up after the first few minutes. Stir them occasionally to ensure that the balls become evenly crispy.",
            "After 15 minutes the balls should be a light golden brown, and the sesame seeds should be only lightly toasted. If the sesame balls look pale, slightly raise the temperature to 320-330°F (160-165°C) and continue frying for a few minutes, until the sesame balls turn light golden brown (*Footnote 6). Once the ideal color has been achieved, remove the balls from the oil, and allow them to cool on the sheet pan lined with a wire rack. Repeat the frying process with the second batch of balls.",
            "Let the sesame balls cool off for 10 to 15 minutes before serving. Serve them warm or at room temperature.",
        ]
    ),
    "Black Sesame Soup": RecipeDetail(
        ingredients: [
            "2 tablespoons (30 g) glutinous rice",
            "1/2 cup (75 g) toasted black sesame seeds ((*See Footnote 1))",
            "4 tablespoons brown sugar ((or to taste) (*See Footnote 2))",
        ],
        steps: [
            "Soak the glutinous rice for 4 hours at room temperature or overnight in the fridge.",
            "Add the sesame seeds to a large skillet. Shake the pan so the seeds are spread out in a thin layer. Toast over medium heat until you can smell the fragrance, 2 to 3 minutes. (*Footnote 3)",
            "Drain the soaked glutinous rice and transfer it to a blender, along with the toasted sesame seeds and 2 cups of water. Blend until it forms a very smooth soup, 1 minute in a Vitamix, or up to 3 minutes in a blender.",
            "Transfer the mixture to a medium-sized saucepan. Add 3 cups of water. Heat over medium heat until boiling. Stir constantly during the whole process to prevent the bottom from sticking (*Footnote 4). When the soup starts to boil, turn to medium-low heat and add the sugar. Stir to melt the sugar and taste the soup. Adjust the seasoning by adding more sugar, if needed. The soup is ready to serve now. If you want the soup to be thicker, simmer it over low heat until it reaches desired consistency.",
            "Enjoy the soup hot, warm, or at room temperature.",
            "Store the leftover soup in an airtight container in the fridge for up to 3 days or in the freezer for 2 months. The soup might separate in the fridge. Stir and reheat it in the microwave before serving.",
        ]
    ),
    "Mango Sago": RecipeDetail(
        ingredients: [
            "1/4 cup small tapioca pearls (sago)",
            "6 Ataulfo mangos ((or 3 Tommy Atkins mango))",
            "1/4 cup water",
            "1/4 cup sugar",
            "Pinch of salt",
            "1 cup coconut milk",
        ],
        steps: [
            "Bring 3 cups of water to a boil. Add the tapioca pearls. Boil, stir occasionally, until pearls turn transparent with a small white spot in the middle of each, 12 minutes or so. If the white dot is still quite large, boil for an additional 1 to 2 minutes. (*Footnote 1)",
            "Immediately strain the cooked tapioca pearls with a fine sieve and rinse them with tap water to stop the cooking. Submerge the sieve with the cooked tapioca into a bowl of tap water to prevent the pearls from drying out. Set aside.",
            "Heat 1/4 cup water in the microwave until hot. Add the sugar and salt. Stir until fully dissolved to make a simple syrup.",
            "Dice two mangos and reserve it for the topping (refer to the pictures in my blog post above to see how I cut the mangos). Pit the rest of the mangos and transfer to a blender. Add2 tablespoons of the syrup. Add the coconut milk. Blend until it forms a smooth texture. Taste it, and adjust the taste by adding more sugar if needed, and mix in a bit water if the mixture is too thick. (*Footnote 2)",
            "Add half of the mango pieces (I use the ones with imperfect shapes), about 2 cups, into a blender. Mix at the highest speed until it forms a smooth paste.",
            "To assemble, add the mango puree into two small bowls, divide and add the tapioca pearls into each serving bowl, stir to mix, then top with more mango pieces for garnish. Enjoy at room temperature or cool off in the fridge before serving.",
        ]
    ),
    "Red Bean Soup": RecipeDetail(
        ingredients: [
            "1 cup dried red beans (azuki beans)",
            "2 to 4 tablespoons rock sugar ((or granulated sugar))",
            "Pinch of salt",
            "2 cups sliced sticky rice cakes ((Optional))",
        ],
        steps: [
            "Rinse the beans with tap water and drain. Add the red beans into a big bowl along with 3 cups of water. Soak the beans overnight. (*Footnote 1)",
            "Drain the beans and transfer them to a medium-sized pot. Add 8 cups of tap water. Heat over medium heat and stir occasionally to prevent the beans from sticking to the pan. When the water start to boil, turn to low heat. Simmer, covered, until the beans turn tender and start to fall apart, about 1 hour. Remove from heat.",
            "(Optional) If you like a creamy soup, use an immersion blender to blend the beans until it reaches your desired consistency. Normally, the soup is quite coarse and still contains bits of red beans. Or you can blend the soup until smooth if you prefer.",
            "Add the salt. Add the sugar, 1 tablespoon at a time, and stir to mix well. Taste the soup until it reaches the desired sweetness. I usually use 2 tablespoons for a mild sweet taste for a regular dessert or afternoon snack. But I would ramp up the sugar to 4 tablespoons if I’m planning serve the dish at a dinner party.",
            "(Optional) Add the rice cakes if using, turn the stove back to medium-low heat. Heat the rice cakes until just tender, 5 to 8 minutes, depending on the type and shape of the rice cakes you use.",
            "At this stage, you can add a small amount of water to adjust the texture of the soup, if needed.",
            "Once done, serve the soup hot or cold as a dessert. You can store the leftover soup in an airtight container in the fridge for 3 to 4 days.",
        ]
    ),
    "Douhua (Tofu Pudding)": RecipeDetail(
        ingredients: [
            "1 2/3 cups homemade soy milk ((or store-bought soy milk), cold or room temperature (*Footnote 1))",
            "1/2 teaspoon gypsum ((*Footnote 2))",
            "Pinch of salt and/or sugar ((Optional, *Footnote 3))",
            "1/2 cup brown sugar",
            "1/2 cup water",
            "1/2 ” ginger (, sliced)",
        ],
        steps: [
            "Prepare a heatproof bowl or container that can hold at least 2 cups of water and will fit into your steamer. Add the gypsum, salt/sugar if using, and a small amount of soy milk to the bowl. Mix until fully dissolved. Then slowly pour in the rest of the soy milk and stir constantly to mix in the gypsum. Cover with plastic wrap.",
            "Add water to your steamer and bring it to a full boil. Add the bowl with the soy milk mixture, cover the steamer, and steam for 10 minutes over high heat.",
            "Once done, remove the steamer from the stove. Uncover carefully to let the steam out, and poke a few holes in the plastic with a fork to release condensation while the tofu cools.",
            "Once the steam is mostly released, remove the plastic wrap and serve the douhua warm or cold. (Footnote 4)",
            "Add the brown sugar, water and ginger to a small pot. Heat over medium heat until bringing to a boil. Turn to medium-low heat to reduce to a simmer, then cook for another 5 minutes.",
            "Pour over tofu pudding and enjoy!",
        ]
    ),
    "Walnut Cookies": RecipeDetail(
        ingredients: [
            "150 g (1 1/2 cups) roasted unsalted walnuts ((*Footnote 1))",
            "280 g (2 cups) all-purpose flour",
            "1/2 teaspoon baking soda",
            "1/2 teaspoon baking powder",
            "15 g (2 tablespoons) cornstarch",
            "1/2 teaspoon fine sea salt ((or 1 teaspoon kosher salt))",
            "175 g (1 1/2 sticks) unsalted butter, room temperature",
            "90 g (1/2 cup) sugar",
            "1 egg",
            "1 egg",
            "1 tablespoon water",
            "1 egg",
            "Splash of heavy cream",
            "Chopped walnuts and / or raw sugar (for garnish)",
        ],
        steps: [
            "Toast the walnuts on the stovetop or in the oven, until very fragrant. If you have a food processor, pulse the walnuts until mostly turned to fine pieces but with corn sized pieces here and there. Without a food processor, place the walnuts into a large ziploc bag and hit it with a rolling pin, until finely crushed with larger pieces here and there.",
            "In a medium bowl, whisk together flour, baking soda, baking powder, cornstarch, and salt. Add walnuts and whisk to combine.",
            "Add butter and sugar into the bowl of a stand mixer. Attach the whisk to the stand mixer. Turn to medium speed (speed 4 to 6) for about 5 minutes, scraping down sides of bowl halfway through, until the butter lightens in color and the sugar is mostly dissolved. If you don’t have a mixer, you can hand whisk to cream the butter as well.",
            "Add the egg into the mixing bowl. Mix until incorporated. Scrape down the sides of the bowl.",
            "Add the dry ingredients from step 2. Mix at low-medium speed until the dough just comes together and no dry spots remain, no more than 30 seconds.",
            "Transfer the dough out onto the counter or a clean working surface. Divide into 4 equal pieces. Pull a sheet of plastic wrap from the dispenser, leaving the end attached. Put one piece of dough onto the plastic wrap and shape into a log using your hands, rolling back and forth until the log is an even 1” (2.5 cm) in diameter. Rip plastic wrap and roll dough log with plastic to seal. Place the dough into a tray. Repeat with 3 remaining pieces of dough. Refrigerate the dough pieces until solid, at least 2 hours or overnight.",
            "Preheat the oven to 350°F (177°C). Line a baking sheet with parchment paper.",
            "(Optional) To make the cookies with the raw sugar edges - Brush egg wash #1 onto each dough log. Sprinkle the raw sugar onto a large cutting board. Gently roll the brushed dough log back and forth over the sugar until fully covered.",
            "Slice off both ends, then slice each dough into 1/4” (6mm) rounds and place onto the lined baking sheet, with the space of one cookie dough in between. You will need to bake in batches.",
            "To garnish the top, brush cookies lightly with egg wash. For a lighter colored surface, use egg wash #1. For a bright yellow color, use egg wash #2. Top with a sprinkle of raw sugar, or a big piece of walnut, or a few small pieces of chopped walnut. (*Footnote 2)",
            "Bake at 350°F (177°C) for 120 to 15 minutes, rotating pan halfway through, until golden brown on edges and fragrant. Let the walnut cookies cool off a few minutes, then carefully move to a rack or plate to cool completely before serving.",
            "Once cooled completely, store the cookies in a ziplock bag at room temperature for a week, or in the freezer for up to 3 months.",
        ]
    ),
    "Peanut Brittle": RecipeDetail(
        ingredients: [
            "150 g (1 cup) peanuts (, unsalted)",
            "50 g (1/3 cup) quinoa",
            "50 g (1/2 cup) sesame (, roasted)",
            "200 g (1 scant cup) sugar",
            "30 g (2 tablespoons) butter",
            "50 g (2 tablespoons) honey",
            "6 g (1 teaspoon) salt",
        ],
        steps: [
            "If using raw peanuts, roast the peanuts in the oven at 350° until fragrant and lightly golden, around 15 to 20 minutes. Shake the peanuts 1 to 2 times during roasting for even cooking. Skip this step if using roasted peanuts.",
            "While the peanuts are toasting, heat a heavy duty medium-sized pot (stainless steel or cast iron, footnote 1) over medium-high heat until hot. Add the quinoa. Stir constantly until quinoa pops and puffs up slightly, 1 minute or so. Remove from heat and immediately transfer the quinoa to a plate to prevent it from overcooking.",
            "Prepare a small sheet pan and place it on a heat-proof surface. Line the sheet pan with parchment paper.",
            "Add butter, honey, sugar, and salt into a medium-sized saucepan. Stir frequently with rubber spatula over medium heat until mixture is bubbling and darkens to medium brown. At this point, stir in peanuts, puffed quinoa, and the sesame seeds all at once and mix to combine so everything is coated.",
            "Continue cooking another 2 to 5 minutes until the mixture reaches a dark amber color. It should register 300 to 310°F (148 to 154°C) on an instant thermometer.",
            "Immediately remove the pan from heat and pour the peanut mixture onto the lined sheet pan you prepared earlier. Place a piece of parchment over the mixture and use a rolling pin to roll out the mixture into a 1/2” (1-cm) thick piece while it’s still hot.",
            "Remove the top piece of parchment paper and let the brittle cool off completely. Then cut the brittle to your desired size.",
            "Serve the brittle as a snack or dessert. Once it has cooled completely, you can store the brittle in an airtight container at room temperature for 3 to 4 days.",
        ]
    ),
    "Black Rice Coconut Pudding": RecipeDetail(
        ingredients: [
            "1 cup (7 ounces / 200 g) black rice",
            "2 cups water",
            "3 tablespoons sugar",
            "1/8 teaspoon salt",
            "2 cans (18 oz / 540 ml) coconut milk",
            "4 tablespoons sugar ((or syrup))",
            "20 ice cubes ((about 1 1/2 cup))",
            "4 mangos (, cubed (*Footnote 2))",
        ],
        steps: [
            "Rinse and drain the black rice. If you prefer a stickier texture, add water to cover the rice and soak for 1 hour at room temperature, or overnight in the fridge. Drain well.",
            "Add the rice to a small saucepan with 2 cups of water. Cook over medium heat until it boils. Reduce to medium-low heat. Cover the pot. Cook covered for 35 minutes. Do not uncover the lid during cooking. Once done, turn off the heat and let the rice rest, covered, for 10 minutes.",
            "Sprinkle the sugar and salt onto the rice while it is still hot. Fluff the rice and mix until the sugar has mixed in and dissolved. Taste the rice. You can add more sugar, if needed, and mix again. Set aside to cool.",
            "Combine coconut milk, ice cubes and sugar in a food processor or blender. Mix until the ice is chopped into small pieces but not melted completely.",
            "Add about 1/2 cup rice and 1/2 cup coconut milk into small serving bowls. Divide the mango evenly among the bowls. Serve immediately. (*Footnote 3)",
        ]
    ),
    "Almond Tofu": RecipeDetail(
        ingredients: [
            "2 cups unsweetened original almond milk",
            "0.5 oz (14 g) gelatin sheet or powder ((or 0.1-oz/3-g agar strips for vegetarian diet))",
            "5 tablespoons sugar (, divided)",
            "1 teaspoon almond extract",
            "2 cups strawberries",
        ],
        steps: [
            "(1) Bring 1 cup almond milk to a boil. Turn off heat and add the gelatin. Stir until dissolved completely.",
            "(2) Add 4 tablespoons sugar and the almond extract. Stir until dissolved.",
            "(3) Add the remaining 1 cup almond milk and stir to mix well. Pour the mixture through a fine sieve into a 8”x8” (20x20cm) baking pan. Place in the fridge until set, 1 hour or so.",
            "(4) Meanwhile, prepare the strawberries. Quarter the strawberries and mix them with the remaining 1 tablespoon sugar. Cover with plastic wrap and transfer to the fridge to macerate.",
            "(5) When ready to serve, run a knife around the edge of the pudding to loosen it, then cut it into 1/2-inch (1 cm) squares. Use a rubber spatula to release the pudding and transfer it into serving bowls. Add the strawberries along with the macerating liquid. Enjoy!",
        ]
    ),
    "Lu Rou Fan": RecipeDetail(
        ingredients: [
            "8 dried shiitake mushrooms",
            "1 lb (450 g) pork belly (skin-on) (, cut into thin strips)",
            "2 teaspoons Shaoxing wine ((or dry sherry))",
            "1 teaspoon dark soy sauce",
            "1 large shallot (, sliced into 1/4” rounds)",
            "2 cloves garlic (, sliced)",
            "1/2 cup vegetable oil",
            "2 tablespoons Shaoxing wine ((or dry sherry))",
            "2 tablespoons soy sauce",
            "1 tablespoon dark soy sauce",
            "1 tablespoon rock sugar ((or white sugar))",
            "2 star anise pods",
            "1 cinnamon stick",
            "4 hard boiled eggs",
            "Green veggies of your choice (, blanched)",
            "Homemade pickled shallot ((or other pickles) (*Footnote 1))",
            "Steamed rice",
        ],
        steps: [
            "Add the dried shiitake mushrooms into a small bowl and pour in 1 cup of boiling water. Rehydrate for at least 20 minutes, or until the mushrooms turn tender throughout. Once rehydrated, remove the shiitakes from their soaking liquid, squeezing out the extra water. Slice them into 3/4”(1 cm) strips. Reserve the soaking liquid.",
            "Cut the pork belly into thin slices, about 1/4”(1/2 cm) thick. Then cut into thin strips, about 1/4” (1/2 cm) thick. Transfer the pork belly into a medium-sized bowl. Add the Shaoxing wine and dark soy sauce. Mix well. Let marinate for 20 to 30 minutes.",
            "(Skip this step if using pre-fried shallots) While the pork is marinating, heat a 9” cast iron pan (or heavy-bottomed pan) over medium-low heat and add the 1/2 cup oil. Once the oil has reached around 200 to 250°F (93 to 120°C), add the shallots. Fry for around 5 minutes, then add the garlic. Fry for another 10 minutes, or until the shallots and garlic turn golden and crispy. (*Footnote 2) If some of the bits brown faster, fish them out using a slotted spoon, to prevent overcooking. Once done cooking, strain everything from the oil and set aside. Pour the oil from the pan into a heat-proof bowl, leaving a thin layer of oil in the pan. (You can save the aromatic oil to use in other recipes)",
            "Return the oiled pan to medium heat and add the marinated pork belly. Stir fry until the meat is lightly browned, about 5 minutes.",
            "Pour in the shaoxing wine and scrape the pan with a spatula to release any brown bits. Add the soy sauce, dark soy sauce, sugar, star anise, cinnamon stick, crispy shallots, and shiitake mushrooms. Stir fry for 30 seconds, until everything is mixed together and well coated.",
            "Add the cup of mushroom soaking liquid (being careful not to add the sediment at the bottom) and 1 cup of water.",
            "Bring to a boil over medium-high heat then reduce to low heat. Simmer until the meat is tender and the liquid is reduced to a thin sauce, about 1 hour 30 minutes. Depending on your stove, the braising time might vary a lot. Check on the pork at the 1-hour mark, and stop cooking if the pork has turned tender and the sauce thickened.",
            "Once the meat is set to a simmer, boil 4 eggs by bringing a pot of water to a boil, then adding the eggs to cook for 10 minutes. Run the cooked eggs under cold water to stop the cooking. Peel the eggs and add them to the braising pork during the last 30 minutes of braising.",
            "Once the pork turns tender and the sauce has thickened, remove the pot from the heat. Serve over steamed rice with blanched veggies of your choice and pickled shallots (or other pickles you prefer).",
        ]
    ),
    "Gua Bao": RecipeDetail(
        ingredients: [
            "1 lb pork belly ((*Footnote 1))",
            "1 tablespoon peanut oil ((or vegetable oil))",
            "4 cloves garlic (, smashed)",
            "2 green onions (, knotted)",
            "3 slices ginger",
            "1 star anise",
            "1 cinnamon sticks",
            "6 dried Chinese chili peppers",
            "3 tablespoons Shaoxing wine ((or dry sherry))",
            "2 tablespoons light soy sauce ((or soy sauce))",
            "1 tablespoon dark soy sauce ((or soy sauce))",
            "1 tablespoon brown sugar ((or regular sugar))",
            "1/2 teaspoon white pepper",
            "3 cups water",
            "5 to 10 homemade steamed bao buns ((or store-bought buns) (*Footnote 5))",
            "Homemade pickled shallots ((or Chinese pickled mustard greens) (*Footnote 6))",
            "1/4 cup peanuts (, crushed)",
            "1/4 cup cilantro (, chopped)",
        ],
        steps: [
            "(Optional) If you’re making my Gua Bao Bun recipe, cook the pork during the first rise of the dough. Shape the steamed buns while the pork is cooking. Then steam the buns after the pork belly is cooked.",
            "Heat a large skillet (*Footnote 2) over medium-high heat and add the oil. Once the oil is hot add the pork belly. Cook on both sides until the edges just turn golden, then transfer to a plate.",
            "Add the garlic, green onions, and ginger to the same skillet. Stir to release the fragrance, about 1 minute. Add the star anise, cinnamon, and chilis. Stir and cook for another 30 seconds.",
            "Pour in the shaoxing wine, scraping the bottom of the pan with a wooden spatula to release the brown bits. Then add the light soy sauce, dark soy sauce, and sugar. Stir to mix well.",
            "Add the browned pork back back to the pan, flipping once to coat the pork with the seasonings. Add the white pepper and water. Bring to a boil, then reduce to a simmer. Braise, covered, for 1 to 1.5 hours, flipping occasionally, until the pork turns tender but not to a degree that it falls apart.",
            "Once the pork is done, remove the pork from the pan and place it onto a big plate. Cover with plastic wrap to prevent from drying out.",
            "Add a mesh strainer over a tall cup (or an oil separator), strain the braising liquid and discard all the solid spices. Use a ladle or big spoon to skim the fat off the top and discard (*Footnote 3). Once you’ve removed most of the oil, return the liquid to the pan. Cook over medium-high heat and let the broth reduce until thickened, 10 minutes or so. (*Footnote 4)",
            "Slice the pork belly into 2.5” (6 cm) pieces and add it to the reduced sauce. Flip a few times to coat the pork, then transfer the pork to a serving plate with the remaining sauce on the side in a small bowl.",
            "Take a bun and add 2 to 3 slices of pork, some pickled shallots, a sprinkle of crushed peanuts, and a few sprigs of cilantro. Drizzle some extra sauce over the filling.",
        ]
    ),
    "Hainanese Chicken Rice": RecipeDetail(
        ingredients: [
            "2.5 to 3 lbs (1.1 to 1.4 kg) whole chicken (*Footnote 1)",
            "1 thumb ginger (, sliced)",
            "3 green onions (, cut into 6 cm (2.5 inch) long pieces)",
            "1 tablespoon sea salt",
            "1 tablespoon sesame oil",
            "2 tablespoons homemade sweet soy sauce ((or store-bought type) (Optional))",
            "chopped cilantro for garnish ((Optional))",
            "2 tablespoons butter and/or chicken fat from the chicken",
            "3 green onions (, chopped)",
            "1 tablespoon minced ginger",
            "3 cloves garlic (, minced)",
            "2 cups (480 ml / 16 oz) jasmine rice, rinsed and drained",
            "3 cups chicken broth from boiling the chicken",
            "3 fresh Thai chili peppers (, chopped (seed the peppers for a less spicy sauce))",
            "1/4 red bell pepper (, seeded and chopped)",
            "1/4 small white onion (, chopped)",
            "2 tablespoons minced ginger",
            "2 cloves garlic (, chopped)",
            "1/2 teaspoon salt",
            "1/3 cup lime juice or lemon juice",
            "1 tablespoon light soy sauce",
            "1 tablespoon Chinkiang vinegar",
            "1 tablespoon thinly sliced ginger",
            "1 teaspoon sugar",
            "1 teaspoon sesame oil",
        ],
        steps: [
            "Remove the neck and innards from the chicken cavity and either reserve them for making stock or gravy or discard them. Remove the chicken fat from the cavity and set it aside for making the rice.",
            "Place the whole chicken breast-side-up in a 5-quart pot or one that’s deep and wide enough to hold the chicken. Add water until it covers the chicken (about 8 cups of water in my case). Bring the water to a boil over medium-high heat. Gently move the chicken with a spatula so it does not stick to the bottom. Skim the foam with a fine mesh strainer until the soup becomes clear, 5 minutes or so.",
            "Turn to medium-low heat. Add the ginger, green onion, and salt. Carefully flip the chicken using a spatula and a pair of tongs. Simmer for 10 minutes. Flip the chicken again so the breast side is up. Continue to simmer until the chicken is just cooked through, 15 to 20 minutes, depending on the size of your chicken. Test the doneness by poking the joint between the thigh and the body with a paring knife. The chicken is cooked if the juice comes out clear. Or you can use a thermometer inserted into the same joint. It should register 165 degrees F (74 C).",
            "Prepare a large ice bath when the chicken is almost done.",
            "When the chicken is done, immediately remove it from the pot and plunge it into the ice bath to cool. This process will tighten the chicken skin and stop the cooking process to keep the meat tender. Once the chicken is mostly cooled, 3 to 4 minutes, drain and pat it dry with paper towels. Transfer to a cutting board to air dry.",
            "Strain and save the chicken broth for cooking the rice and making chicken soup.",
            "While the chicken is cooling, prepare the rice. Heat the reserved chicken fat in a non-stick skillet over medium heat. Cook and stir occasionally, until the oil renders. You should have about 2 tablespoons of oil in your pan. If there isn’t enough chicken fat, add some butter to the pan (I used 1 tablespoon of butter).",
            "Add the ginger, garlic, and green onion to the skillet. Cook and stir until fragrant, 1 minute or so. Add the rice and continue stirring until the rice turns pale yellow, 3 to 4 minutes. Turn to medium-low heat. Transfer 3 cups of chicken broth from the big pot you used to cook the chicken to the rice skillet. Cook, covered, for 12 minutes. Then remove the pan from the stove. Let rest, covered for another 10 minutes. Fluff the rice with a spatula. Taste the rice. Add a bit more salt, if needed, and mix well.",
            "While cooking the rice, prepare the chicken and the sauce(s). Separate the chicken into legs, breasts, and wings.",
            "Prepare chili dipping sauce: add all the ingredients into a mini-food processor or the chopping container included with your immersion blender. Chop everything into a coarse paste.",
            "There are two ways to prepare the chicken for serving. You can rub either sesame oil or sweet soy sauce onto the skin. Read more about the two options in the blog post above. Once done, slice the chicken breast into bite-sized pieces. Transfer to a big plate and garnish with cilantro, if using.&nbsp;",
            "Before you serve, you may want to reheat the chicken broth. Garnish the hot soup with cilantro and green onion. Serve the soup with the rice and chicken. Enjoy!",
        ]
    ),
    "Pineapple Cake": RecipeDetail(
        ingredients: [
            "1 large fresh ripe pineapple (, peeled and cored (700g / 24 oz once cut))",
            "200 g (1 cup) sugar",
            "1/4 teaspoon salt",
            "80 g (1/3 cup) butter",
            "230 g (2 1/2 cups + 2 tablespoons) all-purpose flour",
            "40 g (1/4 cup) sugar",
            "25 g (3 tablespoons) powdered milk",
            "1 teaspoon baking powder",
            "100 g (1 stick minus 2 teaspoons) butter (, cubed and chilled)",
            "1 egg (, plus 1 egg yolk)",
        ],
        steps: [
            "Dice pineapple into fine pieces. Place it in a large strainer over a large bowl for 10 to 15 mins. Let sit until most of the residual liquid is released. Drain and discard the liquid, and transfer the pineapple into a large saute pan. Add sugar and salt. Cook over medium heat. The pineapple will release a lot of liquid at first. Continue to simmer, stirring occasionally to avoid sticking, until all liquid evaporates completely and the pineapple pieces start to feel sticky. Add butter and stir to melt. Transfer everything to a medium-sized bowl. Let cool slightly. Then cover the top of the pineapple with plastic wrap. Let cool in the fridge completely before using.",
            "In a food processor (ideally) or by hand, add the flour, sugar, powdered milk and baking powder. Stir to combine.",
            "Add the butter. Pulse or cut by hand until crumbly.",
            "Add the egg and yolk. Mix until the dough just starts to come together. Transfer the dough onto a clean work surface. Form it into a rough square shape. Wrap in plastic and chill at least 30 mins, or up to overnight.",
            "Cut a large sheet of aluminum foil, about 2.5 feet (76 cm) in length. Fold in half 2 times, to form a thicker sheet that has 4 layers (so the pan will be sturdy enough to hold the pineapple cake). Place an actual loaf pan upside down (*Footnote 1). Press the folded foil over the bottom of the loaf pan to crease, shaping the foil like the loaf pan. Then remove the foil and fold at the creases, to create 4 sides that are about 1/2” (5 cm) high.",
            "You can repeat this to create 2 foil pans so you can bake both pineapple cakes at the same time (highly recommended). Or you can bake one cake at a time by only using one pan (this will take a lot longer because each pineapple cake needs time to cool off before removing the foil).",
            "Once the dough is fully chilled, cut the dough into 4 equal pieces.",
            "Place the dough between two large pieces of parchment paper. Roll out the dough until very thin and slightly larger than the foil pan, aiming to keep the shape of a rectangle.",
            "Lift the top piece of parchment to release the dough. Carefully flip the dough sheet over, and remove the parchment paper from the other side. Carefully transfer rolled dough to the foil pan. Press the dough to fit the pan. The dough should come up on all sides. Trim the edge of the dough by pressing off any overhang with your fingers. You can patch up any tears with excess dough.",
            "Fill the fitted dough sheet with half of the cooled pineapple filling. The filling should go almost all the way up to the top edge of the pan, with a little space left for the other dough sheet. Press lightly to smooth out the filling and form an even layer.",
            "Repeat the rolling process with the next piece of dough using the same method from step 2. Place the rolled dough over top to seal in pineapple filling, trimming off any excess dough. Gently press the dough edges to seal the filling completely.",
            "Preheat the oven to 325°F (163°C). Transfer the pineapple cake foil pans onto a sheet pan. Bake on the middle level for 20 to 25 minutes, until the top turns light golden. Let the pineapple cakes cool off completely. Then you can fold down the edges of the foil pans and place the pineapple cake on a cutting board. To cut the pineapple cake, slice lengthwise down the center. Then slice into thirds crosswise, then slice each third in half to make 12 pieces in total.",
        ]
    ),
    "Taiwanese Beef Noodles": RecipeDetail(
        ingredients: [
            "2 to 3 lbs beef shank ((*Footnote 1))",
            "2 tablespoons vegetable oil",
            "4 scallions (, halved)",
            "1 onion (, quartered)",
            "1 carrot (, chopped roughly)",
            "6 cloves garlic",
            "1 thumb ginger (, sliced)",
            "2 tomatoes (, chopped roughly)",
            "3 ” daikon (, chopped roughly)",
            "2 tablespoons doubanjiang",
            "1/2 cup Shaoxing wine",
            "1/2 cup soy sauce",
            "2 tablespoons tomato paste",
            "2 heaping spoons rock sugar ((or 2 packed tablespoons brown sugar))",
            "2 star anise pods",
            "1 teaspoon fennel seeds",
            "1 teaspoon Sichuan peppercorns",
            "1 cinnamon stick",
            "1/2 teaspoon salt ((or to taste) (*Footnote 2))",
            "8 oz pickled mustard greens (, drained, rinsed, and diced into 1/4” pieces)",
            "3 garlic cloves (, minced)",
            "2 Thai birdseye chilis",
            "1 tablespoon vegetable oil",
            "2 tablespoons sugar",
            "1.3 to 2 lbs fresh wheat noodles",
            "Baby bok choy (, halved or quartered depending on the size (or other greens))",
            "Scallions (, sliced)",
        ],
        steps: [
            "Add the beef shank into a large pot and add enough cold water to cover. Cook over high heat, stirring occasionally to prevent the bottom from sticking. After the water is boiling, cook for 5 minutes. Drain the beef and discard the broth. Rinse any brown foam from the beef with tap water if needed.",
            "In a dutch oven (or the same big pot you just used), add 2 tablespoons of oil and heat over medium heat until the oil is shimmering. Add the scallion, onion, carrot, garlic and ginger. Stir and cook for 4 to 5 minutes.",
            "Add the doubanjiang. Stir to coat everything well, 1 to 2 minutes.",
            "Pour in the Shaoxing wine. Scrape any browned bits off the bottom of the pot.",
            "Add back the blanched beef and pour in 8 cups of water. Add the tomato, daikon, soy sauce, tomato paste, rock sugar, star anise, fennel seeds, Sichuan peppercorns, and cinnamon sticks. Cook over medium-high heat until it comes to a boil. Lower the heat to medium-low. Cover and simmer for 2 hours, until the beef turns tender. Taste the broth and adjust seasoning by adding salt, if needed.",
            "Once the soup is done, transfer the beef pieces to a big plate to cool. Use a spider to remove and discard the solid ingredients from the soup. You can use a colander to strain the soup further for a clear broth. (*Footnote 5) At this point, you can store the broth and the beef for future use.",
            "While the broth is simmering, prepare the pickled greens. Add the oil into a medium pan and heat over medium-high heat until shimmering. Add the garlic and chilis. Stir and cook for 30 seconds to release fragrance.",
            "Add the pickled mustard greens. Stir and cook until any excess liquid has evaporated, about 2 minutes. Add the sugar. Cook and stir until the sugar has dissolved, 2 minutes or so. Transfer everything to a small bowl and set aside.",
            "Warm 1 to 1 1/2 cup of soup for each bowl (the amount of soup depends on the size of the noodle bowl). After boiling, cover and turn to low heat to keep warm.",
            "When it’s possible to handle the beef with your hands, slice the beef into 1/2” (1 cm) thick pieces against the grain. Add the sliced beef to the hot soup to bring it up to serving temperature.",
            "Heat a pot of water over high heat to bring to a boil. Add 3 to 4 pieces of bok choy per bowl to the water and blanch for a minute, or to desired doneness. Transfer to a plate using a slotted spoon. Quickly rinse with cold tap water to stop cooking, drain, and set aside.",
            "Cook the noodles according to package instructions in the same pot. Drain and rinse with cold tap water briefly to stop cooking. Drain again.",
            "To each serving bowl, add the noodles, pour in the soup, top with the sliced beef, mustard greens, and bok choy. Sprinkle with scallion slices to garnish. Serve immediately as a main dish.",
        ]
    ),
    "Taiwanese Fried Chicken": RecipeDetail(
        ingredients: [
            "1 lb boneless skinless chicken thighs ((or breasts))",
            "2 tablespoons light soy sauce",
            "1 tablespoons Shaoxing wine",
            "1 tablespoons sugar",
            "1 ” ginger (, grated)",
            "3 cloves garlic (, grated)",
            "1 teaspoon white pepper",
            "1 teaspoon five spice",
            "1 teaspoon salt",
            "1/4 teaspoon Chinese chili flakes",
            "1/4 teaspoon paprika",
            "1/4 teaspoon five spice",
            "1/4 teaspoon white pepper",
            "1/4 teaspoon garlic powder",
            "2 pints peanut oil ((for frying) (*Footnote 1))",
            "3 eggs",
            "1/4 cup cornstarch",
            "1 cup chunky sweet potato starch ((or panko breadcrumbs) (*Footnote 2))",
            "Lemon wedges",
            "Mayonnaise",
        ],
        steps: [
            "Pound the chicken: Work on one at a time, place a piece of chicken on a cutting board and cover with plastic wrap. Using a meat tenderizer or the back of a heavy knife, pound the meat until it is 1/3” (8 mm) thick and even throughout. If using chicken breast and the piece is thick, slice the breast horizontally into two thin pieces before pounding.",
            "Marinate the chicken: Mix all the marinade ingredients together in a medium bowl. Place the beaten chicken thighs into a plate or tray and pour the marinade over them. Gently mix and rub so the marinade covers the meat evenly. Cover with plastic wrap and refrigerate for at least 3 hours, preferably overnight.",
            "Set up cooking station: Beat the eggs in a wide bowl with the cornstarch until the cornstarch is mostly dissolved. It’s OK if small clumps remain. Place the sweet potato starch in a large bowl. Prepare a tray or plate for the breaded chicken, and a tray lined with a wire rack for the fried chicken.",
            "Prepare the spice mix: Combine all the spice mix ingredients in a small bowl.",
            "Bread the chicken: Work on one piece at a time, pick up a chicken piece to drain excess marinade, transfer into the egg mixture to coat well. Shake off excess egg mixture, then place onto the sweet potato starch. Coat both sides. Place onto the prepared tray.",
            "Fry the chicken: Heat the oil over medium-high heat to 365°F (185°C) in a wok or large pan with high sides. Carefully lower a breaded chicken into the oil. Fry for 2 minutes. Then carefully flip with a pair of tongs and fry for an additional two minutes. The chicken should be a light golden and cooked all the way through. Transfer onto the lined tray to drain off excess oil. Fry the rest of the chicken.",
            "Coat with the spice mix: While the fried chicken is still hot, sprinkle the spice mix evenly over both sides of the chicken.",
            "Serve immediately as a main dish. The chicken is tasty by itself, but some lemon wedges and a squeeze of mayo add a nice touch.",
        ]
    ),
]

